SOURCES = {'tools/ms2_neural_ranker.py': '"""T4 neural ranking pilot; no stability, Mamba-completion, or FPNet claims.\n\nReuses the frozen Ridge experiment\'s selection and leakage exclusions. Graph\nencoding has the existing restricted neutral typed-graph domain. Missing graph\nscores stay in a seeded tail and every selected query stays in the denominator.\n"""\nimport argparse\nimport copy\nimport json\nimport math\nimport random\nimport re\nimport sys\nfrom pathlib import Path\n\nimport numpy as np\nimport torch\nfrom torch import nn\nfrom torch.nn import functional as F\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[1]))\nfrom tools.ms2_fp_predictor import collect_train_molecules, select_val\nfrom tools.ms2_msgym_corpus import standardize_smiles\nfrom tools.ms2_spectral_rank import content_fp, parse_spectrum, seeded_positions, sha256_file, short_key\n\nELEMENTS = ("C", "N", "O", "F", "Cl", "Br", "I", "S")\nN_BINS = 2000\nN_BONDS = 4  # single, double, triple, and the shared parser\'s aromatic marker\n\n\ndef spectrum_features(peaks, precursor):\n    """FPNet-style filter/cap/sqrt, then fixed 1-Da bins (not FPNet itself)."""\n    if not math.isfinite(precursor) or precursor <= 0:\n        raise ValueError("precursor_mz must be finite and positive")\n    if any(not math.isfinite(m) or not math.isfinite(i) or i < 0 for m, i in peaks):\n        raise ValueError("peaks must be finite with nonnegative intensities")\n    kept = [(m, i, j) for j, (m, i) in enumerate(peaks) if 0 < m <= precursor + 2]\n    maximum = max((i for _, i, _ in kept), default=0)\n    result = np.zeros(N_BINS, dtype=np.float32)\n    if maximum <= 0:\n        return result\n    kept = [(m, i / maximum, j) for m, i, j in kept if i / maximum >= 1e-3]\n    for m, i, j in sorted(kept, key=lambda p: (-p[1], p[2]))[:160]:\n        if m < N_BINS:\n            result[int(m)] = max(result[int(m)], math.sqrt(i))\n    norm = np.linalg.norm(result)\n    return result / norm if norm else result\n\n\ndef metadata(row, adduct_ids):\n    precursor = float(row["precursor_mz"])\n    adduct = row["adduct"]\n    polarity = 1 if adduct.endswith("+") else -1 if adduct.endswith("-") else 0\n    # Do not interpret percentages or normalized CE as eV.\n    energy_text = row.get("collision_energy", "").strip()\n    match = re.fullmatch(r"([0-9]+(?:\\.[0-9]+)?)\\s*(?:eV)?", energy_text)\n    energy = float(match.group(1)) if match else 0.0\n    count_text = row.get("energy_count", "").strip()\n    count = int(count_text) if count_text else 0\n    if not 0 <= count <= 8:\n        raise ValueError("energy_count must be in [0, 8]")\n    values = [precursor / 2000, polarity, energy / 100, float(match is not None), count / 8]\n    if not all(math.isfinite(x) for x in values):\n        raise ValueError("metadata must be finite")\n    return np.asarray(values, dtype=np.float32), adduct_ids.get(adduct, 0)\n\n\ndef graph(smiles):\n    record, reason = standardize_smiles(smiles, "neural-pilot", smiles)\n    if record is None:\n        return None\n    atoms = record["atom_types"]\n    x = np.zeros((len(atoms), len(ELEMENTS) + 2), dtype=np.float32)\n    for index, (element, hydrogens, valence) in enumerate(atoms):\n        x[index, ELEMENTS.index(element)] = 1\n        x[index, -2:] = hydrogens / 4, valence / 4\n    adjacency = np.zeros((N_BONDS, len(atoms), len(atoms)), dtype=np.float32)\n    for a, b, order in record["edges"]:\n        adjacency[order - 1, a, b] = adjacency[order - 1, b, a] = 1\n    return x, adjacency\n\n\ndef pack_graphs(graphs, device):\n    if not graphs or any(g is None for g in graphs):\n        raise ValueError("pack_graphs requires supported, nonempty graphs")\n    n = max(len(g[0]) for g in graphs)\n    x = np.zeros((len(graphs), n, len(ELEMENTS) + 2), dtype=np.float32)\n    a = np.zeros((len(graphs), N_BONDS, n, n), dtype=np.float32)\n    mask = np.zeros((len(graphs), n, 1), dtype=np.float32)\n    for j, (nodes, bonds) in enumerate(graphs):\n        k = len(nodes)\n        x[j, :k], a[j, :, :k, :k], mask[j, :k] = nodes, bonds, 1\n    return tuple(torch.as_tensor(v, device=device) for v in (x, a, mask))\n\n\nclass Ranker(nn.Module):\n    def __init__(self, n_adducts, width=128):\n        super().__init__()\n        self.adduct = nn.Embedding(n_adducts, 16)\n        self.spectrum = nn.Sequential(nn.Linear(N_BINS + 21, width), nn.GELU(), nn.Linear(width, width))\n        self.atom = nn.Linear(len(ELEMENTS) + 2, width)\n        self.self_layers = nn.ModuleList(nn.Linear(width, width) for _ in range(3))\n        self.bond_layers = nn.ModuleList(nn.ModuleList(nn.Linear(width, width, bias=False) for _ in range(N_BONDS)) for _ in range(3))\n        self.pool = nn.Linear(width * 2, width)\n        self.forward_spectrum = nn.Sequential(nn.Linear(width + 21, width), nn.GELU(), nn.Linear(width, N_BINS), nn.Softplus())\n\n    def encode_graph(self, packed):\n        nodes, bonds, mask = packed\n        h = F.gelu(self.atom(nodes)) * mask\n        for own, messages in zip(self.self_layers, self.bond_layers):\n            total = sum(bonds[:, b] @ layer(h) for b, layer in enumerate(messages))\n            h = F.gelu(own(h) + total) * mask\n        summed = h.sum(1)\n        return self.pool(torch.cat([summed / mask.sum(1).clamp_min(1), summed], dim=-1))\n\n    def context(self, meta, ids):\n        return torch.cat([meta, self.adduct(ids)], -1)\n\n    def encode_spectrum(self, spec, meta, ids):\n        return F.normalize(self.spectrum(torch.cat([spec, self.context(meta, ids)], -1)), dim=-1)\n\n    def predict_spectrum(self, graphs, meta, ids):\n        return F.normalize(self.forward_spectrum(torch.cat([graphs, self.context(meta, ids)], -1)), dim=-1)\n\n\ndef tensors(molecules, ids, device):\n    features, metas, adducts = [], [], []\n    for m in molecules:\n        meta, aid = metadata(m["row"], ids)\n        features.append(spectrum_features(m["peaks"], float(m["row"]["precursor_mz"])))\n        metas.append(meta)\n        adducts.append(aid)\n    return (torch.as_tensor(np.stack(features), device=device),\n            torch.as_tensor(np.stack(metas), device=device),\n            torch.as_tensor(adducts, device=device))\n\n\ndef loss(model, batch, ids, device, auxiliary):\n    spec, meta, aid = tensors(batch, ids, device)\n    g = model.encode_graph(pack_graphs([graph(m["smiles"]) for m in batch], device))\n    s = model.encode_spectrum(spec, meta, aid)\n    logits = s @ F.normalize(g, dim=-1).T / 0.1\n    # Same connectivity variants must not be false negatives.\n    positive = torch.tensor([[a["group"] == b["group"] for b in batch] for a in batch], device=device)\n    target = positive.float() / positive.sum(1, keepdim=True)\n    contrast = -(target * F.log_softmax(logits, dim=1)).sum(1).mean()\n    forward = (1 - (model.predict_spectrum(g, meta, aid) * spec).sum(-1)).mean()\n    return contrast + auxiliary * forward\n\n\ndef train(fit, calibration, ids, device, args, auxiliary):\n    random.seed(args.seed)\n    torch.manual_seed(args.seed)\n    model = Ranker(len(ids) + 1).to(device)\n    optimizer = torch.optim.AdamW(model.parameters(), lr=3e-4, weight_decay=0.01)\n    best, best_loss, history = None, math.inf, []\n    for epoch in range(args.epochs):\n        model.train()\n        order = list(fit)\n        random.shuffle(order)\n        values = []\n        for start in range(0, len(order), args.batch_size):\n            batch = order[start:start + args.batch_size]\n            if len(batch) < 2:\n                continue\n            optimizer.zero_grad(set_to_none=True)\n            value = loss(model, batch, ids, device, auxiliary)\n            if not torch.isfinite(value):\n                raise RuntimeError("nonfinite training loss")\n            value.backward()\n            nn.utils.clip_grad_norm_(model.parameters(), 1)\n            optimizer.step()\n            values.append(value.item())\n        model.eval()\n        with torch.no_grad():\n            chunks = [calibration[i:i + args.batch_size] for i in range(0, len(calibration), args.batch_size)]\n            valid = [loss(model, b, ids, device, auxiliary).item() for b in chunks if len(b) >= 2]\n        if not values or not valid or not all(math.isfinite(v) for v in valid):\n            raise ValueError("need at least two fit and calibration molecules and finite losses")\n        metric = float(np.mean(valid))\n        history.append({"epoch": epoch + 1, "train_loss": float(np.mean(values)), "calibration_loss": metric})\n        print(json.dumps(history[-1]), flush=True)\n        if metric < best_loss:\n            best, best_loss = copy.deepcopy(model.state_dict()), metric\n    model.load_state_dict(best)\n    model.eval()\n    return model, history\n\n\ndef order_scores(scores, positions):\n    return sorted(range(len(scores)), key=lambda i: (scores[i] is None, -(scores[i] or 0), positions[i]))\n\n\n@torch.no_grad()\ndef evaluate(model, pools, ids, device, batch_size):\n    rows = []\n    for qid, query in pools.items():\n        pool = query["distinct"]\n        positions = seeded_positions(qid, len(pool))\n        peaks, error = parse_spectrum(query["row"]["mzs"], query["row"]["intensities"])\n        scores = [None] * len(pool)\n        if error is None:\n            batch = [{"row": query["row"], "peaks": peaks}]\n            spec, meta, aid = tensors(batch, ids, device)\n            if spec.norm() > 0:\n                embedded = model.encode_spectrum(spec, meta, aid)\n                supported = [(i, graph(s)) for i, s in enumerate(pool)]\n                supported = [(i, g) for i, g in supported if g is not None]\n                for start in range(0, len(supported), batch_size):\n                    chunk = supported[start:start + batch_size]\n                    g = F.normalize(model.encode_graph(pack_graphs([g for _, g in chunk], device)), dim=-1)\n                    values = (embedded @ g.T).flatten().cpu().tolist()\n                    for (index, _), score in zip(chunk, values):\n                        if not math.isfinite(score):\n                            raise RuntimeError("nonfinite candidate score")\n                        scores[index] = score\n        order = order_scores(scores, positions)\n        target = pool.index(query["smiles"]) if query["smiles"] in pool else None\n        uniform = sorted(range(len(pool)), key=lambda i: positions[i])\n        rows.append({"qid": qid, "n_pool": len(pool), "n_scored": sum(s is not None for s in scores),\n                     "rank": order.index(target) + 1 if target is not None else None,\n                     "uniform_rank": uniform.index(target) + 1 if target is not None else None})\n    return rows\n\n\ndef bootstrap_difference(a, b, seed, repeats=2000):\n    if len(a) != len(b) or not a:\n        raise ValueError("paired bootstrap needs equal nonempty samples")\n    delta = np.asarray(a, dtype=float) - np.asarray(b, dtype=float)\n    rng = np.random.default_rng(seed)\n    means = [delta[rng.integers(len(delta), size=len(delta))].mean() for _ in range(repeats)]\n    return {"difference": float(delta.mean()), "ci95": np.quantile(means, [0.025, 0.975]).tolist()}\n\n\ndef run(args):\n    device = torch.device(args.device)\n    if device.type == "cuda":\n        if not torch.cuda.is_available():\n            raise RuntimeError("CUDA is unavailable: select a Colab GPU runtime")\n        name = torch.cuda.get_device_name()\n        if args.require_t4 and "T4" not in name:\n            raise RuntimeError(f"Requested T4, allocated {name}")\n    elif args.require_t4:\n        raise ValueError("--require-t4 requires --device cuda")\n    selected = select_val(args.tsv, args.prefix, args.max_queries)\n    val_rows = selected["val_groups"]\n    val_keys = {short_key(r["inchikey"]) for r in val_rows.values() if r["inchikey"]}\n    contents = set()\n    for row in val_rows.values():\n        peaks, error = parse_spectrum(row["mzs"], row["intensities"])\n        if error is None:\n            contents.add(content_fp(peaks))\n    _, fit, calibration, _, _, audit = collect_train_molecules(args.tsv, args.max_train, set(val_rows), val_keys, contents)\n    # Missing/empty spectrum evidence cannot be a training target.\n    def usable(m):\n        return spectrum_features(m["peaks"], float(m["row"]["precursor_mz"])).any()\n    n_before = [len(fit), len(calibration)]\n    fit, calibration = [m for m in fit if usable(m)], [m for m in calibration if usable(m)]\n    ids = {adduct: i + 1 for i, adduct in enumerate(sorted({m["row"]["adduct"] for m in fit}))}\n    output = Path(args.out)\n    output.mkdir(parents=True, exist_ok=True)\n    all_rows, histories = {}, {}\n    for arm, auxiliary in (("contrastive", 0.0), ("contrastive_forward", 0.2)):\n        print(f"Training {arm} on {device}", flush=True)\n        model, histories[arm] = train(fit, calibration, ids, device, args, auxiliary)\n        torch.save({"model": model.cpu().state_dict(), "adduct_ids": ids, "args": vars(args),\n                    "scope": "restricted-domain neural retrieval pilot"}, output / f"{arm}.pt")\n        model.to(device)\n        all_rows[arm] = evaluate(model, selected["pools"], ids, device, args.batch_size)\n    metrics = {}\n    for arm, rows in all_rows.items():\n        metrics[arm] = {f"top{k}": sum(r["rank"] is not None and r["rank"] <= k for r in rows) / len(rows) for k in (1, 10, 25)}\n        metrics[arm]["unrankable"] = sum(r["n_scored"] == 0 for r in rows)\n    rows = all_rows["contrastive"]\n    metrics["uniform"] = {f"top{k}": sum(r["uniform_rank"] is not None and r["uniform_rank"] <= k for r in rows) / len(rows) for k in (1, 10, 25)}\n    hits = lambda arm: [r["rank"] is not None and r["rank"] <= 25 for r in all_rows[arm]]\n    summary = {"scope": "neural retrieval pilot; no stability validation or completion training",\n               "device": str(device), "gpu": torch.cuda.get_device_name() if device.type == "cuda" else None,\n               "torch": torch.__version__, "config": vars(args), "fit": len(fit), "calibration": len(calibration),\n               "empty_exclusions": [n_before[0] - len(fit), n_before[1] - len(calibration)],\n               "audit": dict(audit), "metrics": metrics,\n               "forward_minus_contrastive_top25": bootstrap_difference(hits("contrastive_forward"), hits("contrastive"), args.seed),\n               "contrastive_minus_uniform_top25": bootstrap_difference(hits("contrastive"),\n                   [r["uniform_rank"] is not None and r["uniform_rank"] <= 25 for r in rows], args.seed),\n               "data_sha256": {"tsv": sha256_file(args.tsv), "prefix": sha256_file(args.prefix)},\n               "script_sha256": sha256_file(__file__), "histories": histories,\n               "limitations": ["no predicted-substructure inputs or learned molecular prior",\n                               "no Mamba decoder or de novo generation",\n                               "connectivity-group disjointness; not scaffold disjointness",\n                               "restricted typed parser excludes unsupported candidates into seeded tails",\n                               "graph encoder does not represent stereochemistry",\n                               "fixed 1-Da binned FPNet-style preprocessing; not pretrained FPNet",\n                               "energy_count unavailable in benchmark, represented as unknown=0",\n                               "previously inspected validation slice; not an untouched test result",\n                               "in-batch training negatives; same-formula negatives not implemented",\n                               "no stability labels, calibration, or physical stability claims"]}\n    (output / "predictions.json").write_text(json.dumps(all_rows, indent=2, allow_nan=False))\n    (output / "summary.json").write_text(json.dumps(summary, indent=2, allow_nan=False))\n    print(json.dumps(metrics, indent=2), flush=True)\n\n\nif __name__ == "__main__":\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("--tsv", default="data/pinned/MassSpecGym1.5.tsv")\n    parser.add_argument("--prefix", default="data/pinned/msgym_candidates_formula_prefix64.json")\n    parser.add_argument("--out", default="experiments/molecular_completion/neural_t4")\n    parser.add_argument("--device", choices=("cpu", "cuda"), default="cuda")\n    parser.add_argument("--require-t4", action="store_true")\n    parser.add_argument("--epochs", type=int, default=20)\n    parser.add_argument("--batch-size", type=int, default=32)\n    parser.add_argument("--max-train", type=int, default=5000)\n    parser.add_argument("--max-queries", type=int, default=200)\n    parser.add_argument("--seed", type=int, default=42)\n    args = parser.parse_args()\n    if min(args.epochs, args.max_train, args.max_queries) < 1 or args.batch_size < 2:\n        parser.error("epochs/train/query caps must be positive; batch-size must be >=2")\n    run(args)\n', 'tools/ms2_fp_predictor.py': '"""Trained measured-spectrum to structure-fingerprint predictor + formula-pool ranking.\n\nSixth molecular-completion run: a small TRAINED spectrum->fingerprint model\nevaluated on the IDENTICAL 200 val formula pools as tools/ms2_spectral_rank.py.\nNothing is tuned on val; test-fold rows are scanned-but-unused.\n\nRepresentation (fixed a priori, never selected on val):\n  spectrum: 1.0 Da bins over [0, 2000) = 2000 dims; per-bin max intensity,\n    sqrt transform, per-spectrum L2 normalization; sparse CSR (bounded,\n    no huge dense tensors).\n  fingerprint: fixed stable-hash atom / typed-bond / length-2-path counts,\n    FP_DIM=256, hashed with zlib.crc32 (deterministic, never Python hash()),\n    permutation-invariant by construction (multiset counts only). This is a\n    local fixed hash fingerprint, NOT a standard Morgan/ECFP or official\n    benchmark fingerprint; no such claim is made. Coarse typed-edge counts\n    alone alias isomers: collisions are measured and the ceiling admitted.\n  model: sparse multi-output Ridge (alpha=1.0, solver lsqr, tol 1e-3,\n    max_iter 200, fit_intercept False), fixed a priori, fit on FIT molecules\n    only. No hyperparameter search on val; no refit on calibration.\n  scoring: cosine between L2-normalized predicted fp and L2-normalized\n    candidate fp. Missing candidate fps rank in seeded tail, retained.\n  prior: untrained TRAIN-fit-mean fingerprint (fit-only), same scoring,\n    isolates spectral signal from fingerprint popularity.\n  cheap baseline: massresid via existing standardize_smiles (measured\n    parent_mass as given query evidence), identical pools.\n\nIdentity: exact provider-canonical SMILES string for dedup/grouping/audit\nplus InChIKey-14 connectivity groups for split disjointness. No RDKit.\nQuery graph fingerprints, formula labels, IDs, target-in-pool flags and\nsupplier order are never model inputs (query spectra only).\n\nLeakage rules (asserted, unit-tested):\n  * train/val connectivity overlap (SMILES or InChIKey-14) excludes the\n    train molecule (counted); residual overlap aborts;\n  * duplicate exact canonical spectrum content (content_fp) excluded:\n    within-fit first-wins, calibration duplicating fit excluded, train\n    duplicating any val query content excluded (all counted);\n  * same-molecule spectra never straddle fit/calibration (one spectrum per\n    molecule; split by connectivity group);\n  * val/test labels never influence training, model selection or\n    calibration; test rows pass through the scanner unused.\n\nCalibration: fixed 90% precision gate on (margin, pool-size cap), thresholds\nchosen on held-out TRAIN calibration formula-pool queries only. If too few\neligible calibration queries or no threshold meets target, fail closed\n(abstain-all) with reason. Calibration uses the identical ranking/pool\ndomain as val (full pools, seeded ties, missing-fp tail).\n\nCPU stdlib + scientific baseline only. GPU and Rust parity NOT APPLICABLE.\n"""\n\nimport csv\nimport hashlib\nimport json\nimport math\nimport os\n\n# Bound BLAS/OpenMP thread pools best-effort before heavy imports (observed\n# cpu/wall is still reported; no strict single-threaded claim).\nfor _k in ("OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS", "MKL_NUM_THREADS"):\n    os.environ.setdefault(_k, "1")\n\nimport resource\nimport sys\nimport time\nimport unittest\nimport zlib\nfrom collections import Counter\n\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\nfrom tools.ms2_spectral_rank import (  # noqa: E402\n    candidate_residuals,\n    content_fp,\n    parse_spectrum,\n    seeded_positions,\n    sha256_file,\n    short_key,\n)\nfrom tools.ms2_msgym_corpus import iter_json_entries  # noqa: E402\n\n# --------------------------------------------------------------------------\n# Fixed a priori representation + hyperparameters (never tuned on val).\n# --------------------------------------------------------------------------\n\nSPEC_BIN_WIDTH = 1.0\nSPEC_MZ_MIN = 0.0\nSPEC_MZ_MAX = 2000.0\nN_SPEC = int((SPEC_MZ_MAX - SPEC_MZ_MIN) / SPEC_BIN_WIDTH)  # 2000\nFP_DIM = 256\nFP_MAX_PATH_BONDS = 2  # atoms (0), bonds (1), length-2 paths (2 bonds)\nRIDGE_ALPHA = 1.0\nRIDGE_TOL = 1e-3\nRIDGE_MAX_ITER = 200\nRIDGE_SOLVER = "lsqr"\nRIDGE_FIT_INTERCEPT = False\nMAX_TRAIN_MOLECULES = 5000\nFIT_GROUP_FRAC = 0.8\nMIN_CALIB_ELIGIBLE = 20\nCALIB_TARGET_PRECISION = 0.90\nTAU_GRID = (0.0, 0.005, 0.01, 0.02, 0.05, 0.10, 0.20)\nKMAX_GRID = (50, 100, 200, 500, 10 ** 9)\nSHUFFLE_DOMAIN = "qid-crc32"\nARMS = ("uniform", "massresid", "predictor", "prior")\n\n\ndef progress(msg):\n    sys.stderr.write(f"# progress {msg}\\n")\n    sys.stderr.flush()\n\n\n# --------------------------------------------------------------------------\n# Spectrum features: 1 Da bins + sqrt + L2 (per-sample only, no fitting).\n# --------------------------------------------------------------------------\n\ndef bin_spectrum_1da(peaks):\n    """Bin to {bin: max_intensity} with fixed 1 Da bounds. Returns (vec, dropped)."""\n    vec = {}\n    dropped = 0\n    for mz, it in peaks:\n        if not (SPEC_MZ_MIN <= mz < SPEC_MZ_MAX):\n            dropped += 1\n            continue\n        b = int((mz - SPEC_MZ_MIN) / SPEC_BIN_WIDTH)\n        if it > vec.get(b, 0.0):\n            vec[b] = it\n    return vec, dropped\n\n\ndef featurize_spectrum(peaks):\n    """Fixed per-spectrum features: max-bin, sqrt, L2-normalize.\n\n    Returns (feat_dict, norm_before). No vocabulary or statistics are fit;\n    each spectrum is processed independently (fit-only claim trivially holds).\n    """\n    vec, dropped = bin_spectrum_1da(peaks)\n    sq = {b: math.sqrt(v) for b, v in vec.items() if v > 0.0}\n    norm = math.sqrt(sum(v * v for v in sq.values()))\n    if norm > 0.0:\n        sq = {b: v / norm for b, v in sq.items()}\n    return sq, norm, dropped\n\n\n# --------------------------------------------------------------------------\n# Fingerprint: stable-hash atom/bond/path counts, permutation-invariant.\n# --------------------------------------------------------------------------\n\ndef _atom_key(el, h, v):\n    return f"A:{el}:{h}:{v}"\n\n\ndef fp_from_typed(atom_types, edges):\n    """Counted hash fingerprint (length FP_DIM), L2-normalized.\n\n    atom_types: tuple of (element, h, valence); edges: tuple of (a, b, order).\n    Multiset counts only, so any atom-index permutation yields identical\n    output. Hashing uses zlib.crc32 (stable across runs), never Python-hash.\n    """\n    counts = [0.0] * FP_DIM\n    akeys = [_atom_key(el, h, v) for el, h, v in atom_types]\n    for k in akeys:\n        counts[zlib.crc32(k.encode()) % FP_DIM] += 1.0\n    for a, b, o in edges:\n        k1, k2 = akeys[a], akeys[b]\n        if k1 > k2:\n            k1, k2 = k2, k1\n        key = f"B:{k1}|{k2}:{o}"\n        counts[zlib.crc32(key.encode()) % FP_DIM] += 1.0\n    n = len(atom_types)\n    adj = [[] for _ in range(n)]\n    for a, b, o in edges:\n        adj[a].append((b, o))\n        adj[b].append((a, o))\n    for c in range(n):\n        neigh = adj[c]\n        for i in range(len(neigh)):\n            for j in range(i + 1, len(neigh)):\n                (a, oa) = neigh[i]\n                (d, ob) = neigh[j]\n                da = f"{akeys[a]}:{oa}"\n                db = f"{akeys[d]}:{ob}"\n                if da > db:\n                    da, db = db, da\n                key = f"P:{akeys[c]}|{da}|{db}"\n                counts[zlib.crc32(key.encode()) % FP_DIM] += 1.0\n    norm = math.sqrt(sum(c * c for c in counts))\n    if norm > 0.0:\n        counts = [c / norm for c in counts]\n    return counts, norm\n\n\ndef fp_from_smiles(smi):\n    """Fingerprint from a candidate/train SMILES via the typed graph parser.\n\n    Returns (vec_or_None, norm_or_0, reason_or_None). Unparseable chemistry\n    yields (None, 0.0, reason); callers retain the candidate and count it.\n    """\n    from tools.ms2_msgym_corpus import standardize_smiles\n    try:\n        rec, reason = standardize_smiles(smi, "fp-pool", smi)\n    except Exception:\n        return None, 0.0, "exception"\n    if rec is None:\n        return None, 0.0, reason\n    vec, norm = fp_from_typed(rec["atom_types"], rec["edges"])\n    return vec, norm, None\n\n\ndef cosine_dense(a, na, b, nb):\n    if na <= 0.0 or nb <= 0.0:\n        return 0.0\n    return sum(x * y for x, y in zip(a, b))\n\n\n# --------------------------------------------------------------------------\n# Ranking (query spectra only; never the query graph/fingerprint/label).\n# --------------------------------------------------------------------------\n\ndef score_candidates_fp(pred_vec, pred_norm, pool_fps):\n    """Cosine of predicted fp vs each candidate fp. Missing -> None, kept.\n\n    Non-finite predictions or scores (NaN/inf/out-of-range) yield None\n    (unscored, ranked last) rather than propagating NaN into ranking.\n    """\n    pred_ok = (\n        pred_vec is not None\n        and isinstance(pred_norm, (int, float))\n        and not isinstance(pred_norm, bool)\n        and math.isfinite(float(pred_norm))\n        and float(pred_norm) > 0.0\n        and len(pred_vec) == FP_DIM\n        and all(isinstance(v, (int, float)) and not isinstance(v, bool)\n                and math.isfinite(float(v)) for v in pred_vec)\n        and all(abs(float(v)) <= 10.0 for v in pred_vec)\n    )\n    out = []\n    for idx, (cvec, cnorm) in enumerate(pool_fps):\n        if not pred_ok or cvec is None or not math.isfinite(cnorm) \\\n                or cnorm <= 0.0:\n            out.append({"idx": idx, "score": None,\n                        "parseable": cvec is not None})\n            continue\n        s = cosine_dense(pred_vec, pred_norm, cvec, cnorm)\n        if not isinstance(s, float) or not math.isfinite(s):\n            out.append({"idx": idx, "score": None, "parseable": True})\n        else:\n            out.append({"idx": idx, "score": s, "parseable": True})\n    return out\n\n\ndef rank_by_score(scored, pos_of):\n    return sorted(range(len(scored)),\n                  key=lambda i: ((0.0, -scored[i]["score"])\n                                 if scored[i]["score"] is not None\n                                 else (1.0, 0.0),\n                                 pos_of[i]))\n\n\ndef rank_uniform(n, pos_of):\n    return sorted(range(n), key=lambda i: pos_of[i])\n\n\ndef rank_massresid_order(residuals, pos_of):\n    return sorted(range(len(residuals)),\n                  key=lambda i: ((0.0, residuals[i])\n                                 if residuals[i] is not None\n                                 else (1.0, 0.0),\n                                 pos_of[i]))\n\n\ndef margin_of(scored_order_scores):\n    """Legacy wrapper: finite-scored gap; kept for compatibility.\n\n    Returns margin over actual finite scores only (None/NaN/inf excluded).\n    Single finite score -> 0.0 conservative; no finite scores -> None.\n    """\n    margin, _ = margin_from_finite_scores(scored_order_scores)\n    return margin\n\n\ndef finite_scored_values(scored_order_scores):\n    """Actual finite scored values only (excludes None/NaN/inf)."""\n    vals = []\n    for v in scored_order_scores or []:\n        if isinstance(v, bool):\n            continue\n        if isinstance(v, (int, float)) and math.isfinite(float(v)):\n            vals.append(float(v))\n    return vals\n\n\ndef margin_from_finite_scores(scored_order_scores):\n    """Confidence gap over the actual finite scored order.\n\n    Missing/unscored candidates (None) rank last and are EXCLUDED from the\n    gap: the margin is top1-top2 over finite scores only. Single finite\n    score -> (0.0, \'single_scored\') conservatively (no observed gap, so\n    zero confidence). No finite scores -> (None, \'no_finite_scores\').\n    Non-finite gap -> (None, \'non_finite_margin\').\n    """\n    vals = finite_scored_values(scored_order_scores)\n    if not vals:\n        return None, "no_finite_scores"\n    if len(vals) == 1:\n        return 0.0, "single_scored"\n    vals.sort(reverse=True)\n    gap = vals[0] - vals[1]\n    if not math.isfinite(gap):\n        return None, "non_finite_margin"\n    return gap, "ok"\n\n\ndef spectrum_has_usable_features(peaks):\n    """Nonempty usable spectrum features (inference input check)."""\n    if not peaks:\n        return False\n    try:\n        feat, norm, _ = featurize_spectrum(peaks)\n    except Exception:\n        return False\n    return bool(feat) and isinstance(norm, (int, float)) \\\n        and not isinstance(norm, bool) \\\n        and math.isfinite(float(norm)) and float(norm) > 0.0\n\n\ndef prediction_is_usable(pred_vec, pred_norm):\n    """Finite nonzero prediction (never accept zero/NaN/out-of-range)."""\n    if pred_vec is None or pred_norm is None:\n        return False\n    if isinstance(pred_norm, bool):\n        return False\n    if not isinstance(pred_norm, (int, float)):\n        return False\n    pred_norm = float(pred_norm)\n    if not math.isfinite(pred_norm) or pred_norm <= 0.0:\n        return False\n    if len(pred_vec) != FP_DIM:\n        return False\n    for v in pred_vec:\n        if isinstance(v, bool) or not isinstance(v, (int, float)):\n            return False\n        fv = float(v)\n        if not math.isfinite(fv) or abs(fv) > 10.0:\n            return False\n    tot = sum(float(v) * float(v) for v in pred_vec)\n    return math.isfinite(tot) and tot > 0.0\n\n\ndef capability_for_query(peaks, pred_vec, pred_norm, scored):\n    """Shared inference-capability predicate for calibration AND val.\n\n    Requires: nonempty usable spectrum features, finite nonzero\n    prediction, >=1 finite candidate score, finite margin. Deliberately\n    INDEPENDENT of true target parseability/identity/hit (those are not\n    inference inputs; target-parseable is an EVALUATION-only subgroup).\n    Returns (rankable_bool, reason_str).\n    """\n    if not spectrum_has_usable_features(peaks):\n        return False, "no_features"\n    if not prediction_is_usable(pred_vec, pred_norm):\n        return False, "predictor_unavailable"\n    scores = [s.get("score") for s in (scored or [])]\n    n_finite = len(finite_scored_values(scores))\n    if n_finite == 0:\n        return False, "predictor_unavailable"\n    margin, mstatus = margin_from_finite_scores(scores)\n    if margin is None or not math.isfinite(margin):\n        return False, "predictor_unavailable"\n    return True, ("ok" if mstatus == "ok" else f"ok:{mstatus}")\n\n\ndef target_parse_info(smiles):\n    """Evaluation-only target fingerprint parseability (never an input).\n\n    Returns (parseable_bool, status_str, reason_or_None).\n    """\n    try:\n        vec, norm, reason = fp_from_smiles(smiles)\n    except Exception:\n        return False, "error", "exception"\n    if vec is None:\n        return False, "unsupported", reason\n    return True, "ok", None\n\n\ndef evaluate_pool(pool, target_smiles, pred_scores, prior_scores, residuals,\n                  pos_of):\n    """Ranks/hits for all four arms on one identical full pool."""\n    n = len(pool)\n    tgt = pool.index(target_smiles) if target_smiles in pool else None\n    ou = rank_uniform(n, pos_of)\n    om = rank_massresid_order(residuals, pos_of)\n    op = rank_by_score(pred_scores, pos_of)\n    orr = rank_by_score(prior_scores, pos_of)\n\n    def rank_of(order):\n        return None if tgt is None else order.index(tgt) + 1\n\n    ranks = {"uniform": rank_of(ou), "massresid": rank_of(om),\n             "predictor": rank_of(op), "prior": rank_of(orr)}\n\n    def hits(rank):\n        if rank is None:\n            return {1: None, 3: None, 10: None}\n        return {1: rank <= 1, 3: rank <= min(3, n), 10: rank <= min(10, n)}\n\n    margin_pred, margin_status = margin_from_finite_scores(\n        [s["score"] for s in pred_scores])\n    n_scored = len(finite_scored_values([s["score"] for s in pred_scores]))\n    return {"in_pool": tgt is not None, "n_pool": n,\n            "ranks": ranks, "hits": {a: hits(r) for a, r in ranks.items()},\n            "margin_pred": margin_pred,\n            "margin_status": margin_status,\n            "n_scored_finite": n_scored,\n            "n_parseable": sum(1 for s in pred_scores if s["parseable"])}\n\n\n# --------------------------------------------------------------------------\n# Data selection (val identical to spectral run; train capped + grouped).\n# --------------------------------------------------------------------------\n\ndef load_wanted_rows(tsv_path):\n    from tools.ms2_spectral_rank import load_tsv_rows\n    return load_tsv_rows(tsv_path)\n\n\ndef select_val(tsv_path, prefix_path, max_queries):\n    """EXACT same selection as spectral run: file-order prefix entries\n    joining first-row-per-SMILES val groups; distinct pools deduped in\n    supplied order; qids VAL-%04d in join order."""\n    val_groups = {}\n    train_smiles_all, train_keys_all = set(), set()\n    val_bias = Counter()\n    n_rows = n_test = 0\n    for row in load_wanted_rows(tsv_path):\n        n_rows += 1\n        if row["fold"] == "test":\n            n_test += 1\n            continue\n        if row["fold"] == "train":\n            train_smiles_all.add(row["smiles"])\n            if row["inchikey"]:\n                train_keys_all.add(short_key(row["inchikey"]))\n        elif row["fold"] == "val":\n            val_bias[f"adduct:{row[\'adduct\']}"] += 1\n            val_bias[f"inst:{row[\'instrument_type\'] or \'missing\'}"] += 1\n            if row["smiles"] not in val_groups:\n                val_groups[row["smiles"]] = row\n    entries = [(q, c) for q, c in\n               iter_json_entries(prefix_path, max_queries * 40)]\n    joined = [(q, c) for q, c in entries if q in val_groups][:max_queries]\n    if not joined:\n        raise ValueError("no prefix entries join to val rows")\n    pools = {}\n    for qi, (q, cands) in enumerate(joined):\n        qid = f"VAL-{qi:04d}"\n        seen, distinct = set(), []\n        for s in cands:\n            if s not in seen:\n                seen.add(s)\n                distinct.append(s)\n        pools[qid] = {"smiles": q, "supplied": list(cands),\n                      "distinct": distinct, "row": val_groups[q]}\n    return {"pools": pools, "val_groups": val_groups, "entries": entries,\n            "joined": joined, "n_rows": n_rows, "n_test": n_test,\n            "val_bias": val_bias,\n            "train_smiles_all": train_smiles_all,\n            "train_keys_all": train_keys_all}\n\n\ndef collect_train_molecules(tsv_path, cap, val_smiles, val_keys, val_content):\n    """Capped train molecules, one spectrum per SMILES (file order).\n\n    Returns (molecules_in_order, info). molecules carry row, inchikey,\n    group, content_fp, peaks. Spectrum-unparseable rows are marked excluded\n    here (counted). Test rows are skipped (counted).\n    """\n    from tools.ms2_spectral_rank import load_tsv_rows\n    first = {}\n    order = []\n    info = Counter()\n    for row in load_tsv_rows(tsv_path):\n        if row["fold"] == "test":\n            info["n_test_skipped"] += 1\n            continue\n        if row["fold"] != "train":\n            continue\n        info["n_train_rows_scanned"] += 1\n        smi = row["smiles"]\n        if smi not in first:\n            first[smi] = row\n            order.append(smi)\n    molecules = []\n    for smi in order:\n        row = first[smi]\n        peaks, err = parse_spectrum(row["mzs"], row["intensities"])\n        if err is not None:\n            info[f"train_spec_excl:{err}"] += 1\n            molecules.append({"smiles": smi, "row": row, "status": "excluded",\n                              "reason": f"spec:{err}", "group": None,\n                              "fp_content": None, "peaks": None})\n            continue\n        fp = content_fp(peaks)\n        key = short_key(row["inchikey"]) if row["inchikey"] else ""\n        if not row["inchikey"]:\n            info["n_train_missing_key"] += 1\n            molecules.append({"smiles": smi, "row": row, "status": "excluded",\n                              "reason": "missing_connectivity_key",\n                              "group": None, "fp_content": fp, "peaks": peaks})\n            continue\n        molecules.append({"smiles": smi, "row": row, "status": "candidate",\n                          "reason": None, "group": key, "fp_content": fp,\n                          "peaks": peaks})\n    # Group-order cap: groups in first-appearance order until cap molecules.\n    cand = [m for m in molecules if m["status"] == "candidate"]\n    gorder, gmembers = [], {}\n    for m in cand:\n        if m["group"] not in gmembers:\n            gmembers[m["group"]] = []\n            gorder.append(m["group"])\n        gmembers[m["group"]].append(m)\n    capped_groups, capped = [], []\n    for g in gorder:\n        if len(capped) + len(gmembers[g]) > cap and capped:\n            info["n_groups_truncated_by_cap"] += 1\n            break\n        capped_groups.append(g)\n        capped.extend(gmembers[g])\n        if len(capped) >= cap:\n            break\n    capped_set = {id(m) for m in capped}\n    for m in cand:\n        if id(m) not in capped_set:\n            m["status"] = "excluded"\n            m["reason"] = "over_cap"\n            info["n_over_cap"] += 1\n    info["n_capped_molecules"] = len(capped)\n    info["n_capped_groups"] = len(capped_groups)\n    # Split capped groups: first FIT_GROUP_FRAC -> fit, rest -> calibration.\n    n_fit_g = int(len(capped_groups) * FIT_GROUP_FRAC)\n    fit_groups = set(capped_groups[:n_fit_g])\n    calib_groups = set(capped_groups[n_fit_g:])\n    for m in capped:\n        m["split"] = "fit" if m["group"] in fit_groups else "calibration"\n    info["n_fit_groups"] = len(fit_groups)\n    info["n_calib_groups"] = len(calib_groups)\n    # Exclusions on capped set: val overlap, val content, unsupported chem,\n    # content duplicates (fit first-wins; calib vs fit; val content).\n    for m in capped:\n        if m["smiles"] in val_smiles or m["group"] in val_keys:\n            m["status"] = "excluded"\n            m["reason"] = "train_val_overlap"\n            info["n_train_val_overlap_excluded"] += 1\n        elif m["fp_content"] in val_content:\n            m["status"] = "excluded"\n            m["reason"] = "val_content_duplicate"\n            info["n_val_content_dup_excluded"] += 1\n    # Unsupported chemistry (target fp needed for Y): standardize now.\n    for m in capped:\n        if m["status"] != "candidate":\n            continue\n        vec, norm, reason = fp_from_smiles(m["smiles"])\n        if vec is None:\n            m["status"] = "excluded"\n            m["reason"] = f"chem:{reason}"\n            info[f"train_chem_excl:{reason.split(\':\')[0]}"] += 1\n        else:\n            m["fp_target"] = vec\n            m["fp_target_norm"] = norm\n    # Content dedup: fit first-wins, then calib-vs-fit.\n    seen_fit = set()\n    for m in [x for x in capped if x.get("split") == "fit"\n              and x["status"] == "candidate"]:\n        if m["fp_content"] in seen_fit:\n            m["status"] = "excluded"\n            m["reason"] = "fit_content_duplicate"\n            info["n_fit_content_dup"] += 1\n        else:\n            seen_fit.add(m["fp_content"])\n    for m in [x for x in capped if x.get("split") == "calibration"\n              and x["status"] == "candidate"]:\n        if m["fp_content"] in seen_fit:\n            m["status"] = "excluded"\n            m["reason"] = "calib_content_duplicate_fit"\n            info["n_calib_content_dup_fit"] += 1\n            continue\n        seen_fit.add(m["fp_content"])\n    fit = [m for m in capped if m.get("split") == "fit"\n           and m["status"] == "candidate"]\n    calib = [m for m in capped if m.get("split") == "calibration"\n             and m["status"] == "candidate"]\n    # Enforce: no shared groups, no shared content, no val overlap remain.\n    fit_groups_final = {m["group"] for m in fit}\n    calib_groups_final = {m["group"] for m in calib}\n    assert not (fit_groups_final & calib_groups_final), "group straddle"\n    assert not (fit_groups_final & set(val_keys)), "fit/val key overlap"\n    assert not (calib_groups_final & set(val_keys)), "calib/val key overlap"\n    assert not ({m["smiles"] for m in fit} & set(val_smiles)), "fit/val smi"\n    assert not ({m["smiles"] for m in calib} & set(val_smiles)), "cal/val smi"\n    return molecules, fit, calib, fit_groups_final, calib_groups_final, info\n\n\ndef build_matrices(fit):\n    import numpy as np\n    import scipy.sparse as sp\n    rows, cols, data = [], [], []\n    Y = np.zeros((len(fit), FP_DIM), dtype=np.float64)\n    for i, m in enumerate(fit):\n        feat, _, _ = featurize_spectrum(m["peaks"])\n        for b, v in feat.items():\n            rows.append(i)\n            cols.append(b)\n            data.append(v)\n        Y[i, :] = m["fp_target"]\n    X = sp.csr_matrix((data, (rows, cols)), shape=(len(fit), N_SPEC))\n    return X, Y\n\n\ndef train_ridge(X, Y):\n    from sklearn.linear_model import Ridge\n    model = Ridge(alpha=RIDGE_ALPHA, solver=RIDGE_SOLVER, tol=RIDGE_TOL,\n                  max_iter=RIDGE_MAX_ITER,\n                  fit_intercept=RIDGE_FIT_INTERCEPT, random_state=0)\n    model.fit(X, Y)\n    return model\n\n\ndef predict_fp(model, peaks):\n    import numpy as np\n    feat, norm, _ = featurize_spectrum(peaks)\n    if norm <= 0.0 or not feat:\n        return [0.0] * FP_DIM, 0.0\n    import scipy.sparse as sp\n    X = sp.csr_matrix(([v for v in feat.values()],\n                       ([0] * len(feat), list(feat.keys()))),\n                      shape=(1, N_SPEC))\n    pred = np.asarray(model.predict(X))[0].tolist()\n    n = math.sqrt(sum(v * v for v in pred))\n    if n > 0.0:\n        pred = [v / n for v in pred]\n    return pred, n\n\n\ndef mean_prior(fit):\n    import numpy as np\n    Y = np.array([m["fp_target"] for m in fit], dtype=np.float64)\n    mean = Y.mean(axis=0)\n    n = float(np.linalg.norm(mean))\n    if n > 0.0:\n        mean = mean / n\n    return mean.tolist(), n\n\n\n# --------------------------------------------------------------------------\n# Calibration (held-out TRAIN pools only; fail closed).\n# --------------------------------------------------------------------------\n\ndef calibrate_gate(calib_rows):\n    """Choose (tau, kmax) on calibration rankable rows only.\n\n    calib_rows: list of dicts with rankable (capability predicate),\n    hit_top1 (True/False/None), margin_pred, n_pool. Rows with hit None\n    (absent target) count as incorrect when predicted. rankable MUST be\n    the shared inference-capability predicate (usable features, finite\n    nonzero prediction, >=1 finite score, finite margin) and MUST NOT\n    depend on target parseability/identity/hit. Returns gate dict with\n    tau=None (strict-JSON null) when abstaining; fail closed (predict\n    nothing) when too few rankable or no threshold meets target.\n    """\n    elig = [r for r in calib_rows if r.get("rankable") is True\n            and isinstance(r.get("margin_pred"), (int, float))\n            and not isinstance(r.get("margin_pred"), bool)\n            and math.isfinite(float(r["margin_pred"]))]\n    if len(elig) < MIN_CALIB_ELIGIBLE:\n        return {"tau": None, "kmax": 0, "status": "abstain_all",\n                "reason": f"insufficient_eligible:{len(elig)}",\n                "n_eligible": len(elig), "table": []}\n    table = []\n    for tau in TAU_GRID:\n        for kmax in KMAX_GRID:\n            pred = [r for r in elig if r["margin_pred"] >= tau\n                    and r["n_pool"] <= kmax]\n            if not pred:\n                table.append({"tau": tau, "kmax": kmax, "predicted": 0,\n                              "precision": None, "coverage": 0.0})\n                continue\n            good = sum(1 for r in pred if r.get("hit_top1") is True)\n            prec = good / len(pred)\n            table.append({"tau": tau, "kmax": kmax, "predicted": len(pred),\n                          "precision": prec,\n                          "coverage": len(pred) / len(elig)})\n    feas = [t for t in table if t["precision"] is not None\n            and t["precision"] >= CALIB_TARGET_PRECISION]\n    if not feas:\n        return {"tau": None, "kmax": 0, "status": "abstain_all",\n                "reason": "no_threshold_meets_target", "n_eligible": len(elig),\n                "table": table}\n    feas.sort(key=lambda t: (-t["predicted"], -t["tau"], t["kmax"]))\n    best = feas[0]\n    return {"tau": best["tau"], "kmax": best["kmax"], "status": "calibrated",\n            "reason": None, "n_eligible": len(elig), "table": table,\n            "best": best}\n\n\ndef gate_accepts(gate, margin_pred, n_pool):\n    """Fail-closed acceptance: False when gate abstains or margin unusable."""\n    if gate.get("status") != "calibrated":\n        return False\n    tau = gate.get("tau")\n    kmax = gate.get("kmax")\n    if tau is None or isinstance(tau, bool):\n        return False\n    if not isinstance(margin_pred, (int, float)) \\\n            or isinstance(margin_pred, bool):\n        return False\n    if not math.isfinite(float(margin_pred)) \\\n            or not math.isfinite(float(tau)):\n        return False\n    if not isinstance(n_pool, int):\n        return False\n    return float(margin_pred) >= float(tau) and n_pool <= kmax\n\n\n# --------------------------------------------------------------------------\n# Summaries.\n# --------------------------------------------------------------------------\n\ndef summarize_val(rows, label):\n    out = {"label": label, "n_selected": len(rows),\n           "n_complete": sum(1 for r in rows if r.get("status") == "complete"),\n           "n_rankable": sum(1 for r in rows if r.get("rankable") is True),\n           "n_accepted": sum(1 for r in rows if r.get("accepted") is True),\n           "n_model_failure": sum(\n               1 for r in rows if r.get("status") == "complete"\n               and r.get("rankable") is not True),\n           "rankable_reason_counts": dict(Counter(\n               str(r.get("rankable_reason", "?")) for r in rows\n               if r.get("status") == "complete")),\n           "status_counts": dict(Counter(r.get("status", "?") for r in rows)),\n           "pool_recall_all": (sum(1 for r in rows if r.get("in_pool"))\n                               / len(rows) if rows else None)}\n    subsets = (("all", lambda r: True),\n               ("eligible_complete",\n                lambda r: r.get("status") == "complete" and r["in_pool"]),\n               ("capability_any_candidate",\n                lambda r: r.get("status") == "complete" and r["in_pool"]\n                and (r.get("n_parseable") or 0) > 0),\n               ("eligible_parseable",\n                lambda r: r.get("status") == "complete" and r["in_pool"]\n                and r.get("target_parseable") is True),\n               ("accepted",\n                lambda r: r.get("accepted") is True and r["in_pool"]))\n    for name, sel in subsets:\n        sub = [r for r in rows if sel(r)]\n        m = {"n": len(sub)}\n        for arm in ARMS:\n            for k in (1, 3, 10):\n                vals = [r["hits"][arm][k] for r in sub\n                        if r["hits"].get(arm, {}).get(k) is not None]\n                m[f"{arm}@top{k}"] = (sum(vals) / len(vals) if vals else None)\n                m[f"{arm}@top{k}_den"] = len(vals)\n        pred = [r for r in sub if r.get("accepted")]\n        good = [r for r in pred if r["hits"].get("predictor", {}).get(1)]\n        m["predicted"] = len(pred)\n        m["coverage"] = len(pred) / len(rows) if rows else 0.0\n        m["abstention_precision"] = (len(good) / len(pred) if pred else None)\n        out[name] = m\n    return out\n\n\ndef empty_hits():\n    return {arm: {1: None, 3: None, 10: None} for arm in ARMS}\n\n\n# --------------------------------------------------------------------------\n# Experiment driver.\n# --------------------------------------------------------------------------\n\ndef run_experiment(tsv_path, prefix_path, max_queries, max_train, out_dir):\n    import numpy as np\n    t0 = time.perf_counter()\n    c0 = time.process_time()\n    progress("select-val")\n    sel = select_val(tsv_path, prefix_path, max_queries)\n    pools = sel["pools"]\n    # Val query spectra content (for train content-leak exclusion).\n    val_content, val_smiles, val_keys = set(), [], set()\n    val_qinfo = {}\n    for qid, v in pools.items():\n        peaks, err = parse_spectrum(v["row"]["mzs"], v["row"]["intensities"])\n        if err is None:\n            val_content.add(content_fp(peaks))\n            val_qinfo[qid] = peaks\n        else:\n            val_qinfo[qid] = None\n        val_smiles.append(v["smiles"])\n        if v["row"]["inchikey"]:\n            val_keys.add(short_key(v["row"]["inchikey"]))\n    progress(f"collect-train cap={max_train}")\n    molecules, fit, calib, fit_g, calib_g, tinfo = collect_train_molecules(\n        tsv_path, max_train, set(val_smiles), val_keys, val_content)\n    progress(f"train fit={len(fit)} calib={len(calib)}")\n    t_train0 = time.perf_counter()\n    X_fit, Y_fit = build_matrices(fit)\n    model = train_ridge(X_fit, Y_fit)\n    t_train1 = time.perf_counter()\n    prior_vec, prior_norm = mean_prior(fit)\n    # Candidate fingerprint cache (shared across calib + val).\n    fp_cache = {}\n\n    def pool_fps(pool):\n        out = []\n        for smi in pool:\n            if smi not in fp_cache:\n                fp_cache[smi] = fp_from_smiles(smi)\n            vec, norm, _ = fp_cache[smi]\n            out.append((vec, norm))\n        return out\n\n    # Calibration: held-out TRAIN molecules with prefix pools.\n    progress("calibration-pools")\n    prefix_index = {}\n    for q, c in iter_json_entries(prefix_path, 1 << 30):\n        if q not in prefix_index:\n            prefix_index[q] = c\n    calib_rows = []\n    for i, m in enumerate(calib):\n        qid = f"CAL-{i:04d}"\n        cands = prefix_index.get(m["smiles"])\n        if cands is None:\n            calib_rows.append({"qid": qid, "smiles": m["smiles"],\n                               "status": "no_pool_in_prefix",\n                               "rankable": False,\n                               "rankable_reason": "no_pool",\n                               "has_features": True,\n                               "pred_norm": None,\n                               "n_scored_finite": 0,\n                               "target_parseable": True,\n                               "target_fp_status": "ok",\n                               "in_pool": None,\n                               "n_pool": 0, "n_parseable": 0,\n                               "margin_pred": None,\n                               "margin_status": "no_finite_scores",\n                               "hit_top1": None,\n                               "hits": empty_hits()})\n            continue\n        seen, distinct = set(), []\n        for s in cands:\n            if s not in seen:\n                seen.add(s)\n                distinct.append(s)\n        pfps = pool_fps(distinct)\n        pred, pn = predict_fp(model, m["peaks"])\n        pscores = score_candidates_fp(pred, pn, pfps)\n        prscores = score_candidates_fp(prior_vec, prior_norm, pfps)\n        try:\n            observed = m["row"]["parent_mass"]\n        except KeyError:\n            observed = ""\n        residuals, _ = candidate_residuals(distinct, observed)\n        pos = seeded_positions(qid, len(distinct))\n        ev = evaluate_pool(distinct, m["smiles"], pscores, prscores,\n                           residuals, pos)\n        # Capability (inference-only): never uses target parseability.\n        rankable, rreason = capability_for_query(\n            m["peaks"], pred, pn, pscores)\n        tparse, tstatus, _ = target_parse_info(m["smiles"])\n        calib_rows.append({"qid": qid, "smiles": m["smiles"],\n                           "status": "complete", "rankable": rankable,\n                           "rankable_reason": rreason,\n                           "has_features": spectrum_has_usable_features(\n                               m["peaks"]),\n                           "pred_norm": pn,\n                           "n_scored_finite": ev["n_scored_finite"],\n                           "target_parseable": tparse,\n                           "target_fp_status": tstatus,\n                           "in_pool": ev["in_pool"], "n_pool": ev["n_pool"],\n                           "n_parseable": ev["n_parseable"],\n                           "margin_pred": ev["margin_pred"],\n                           "margin_status": ev["margin_status"],\n                           "hit_top1": ev["hits"]["predictor"][1],\n                           "hits": ev["hits"], "ranks": ev["ranks"]})\n    gate = calibrate_gate(calib_rows)\n    progress(f"calibration-gate {gate[\'status\']} tau={gate[\'tau\']} "\n             f"kmax={gate[\'kmax\']}")\n    # Val scoring on IDENTICAL pools/order.\n    progress("val-scoring")\n    val_rows = []\n    sel_bias = Counter()\n    n_collide_target = 0\n    n_target_fp_missing = 0\n    n_queries_target_unparseable = 0\n    n_identity_missing = 0\n    for qid, v in pools.items():\n        row = v["row"]\n        sel_bias[f"adduct:{row[\'adduct\']}"] += 1\n        sel_bias[f"inst:{row[\'instrument_type\'] or \'missing\'}"] += 1\n        distinct = v["distinct"]\n        tparse_q, tstatus_q, treason_q = target_parse_info(v["smiles"])\n        base = {"qid": qid, "smiles": v["smiles"],\n                "adduct": row.get("adduct", ""),\n                "instrument": row.get("instrument_type") or "missing",\n                "n_supplied": len(v["supplied"]), "n_pool": len(distinct),\n                "in_pool": (v["smiles"] in distinct),\n                "target_parseable": tparse_q,\n                "target_fp_status": tstatus_q,\n                "target_fp_reason": treason_q}\n        # Identity gate: sufficient connectivity identity required before\n        # any scoring (fail safe, retain row + pool accounting, abstain).\n        if not v["smiles"] or not row.get("inchikey"):\n            n_identity_missing += 1\n            pfps_id = pool_fps(distinct)\n            n_parse_id = sum(1 for a, _ in pfps_id if a is not None)\n            out = dict(base, status="excluded_identity_missing",\n                       rankable=False, rankable_reason="identity_missing",\n                       has_features=None, pred_norm=None,\n                       n_scored_finite=0,\n                       n_parseable=n_parse_id,\n                       n_unparseable_fp=len(pfps_id) - n_parse_id,\n                       n_unparseable_mass=None,\n                       n_target_fp_ties=None,\n                       margin_pred=None, margin_status="no_identity",\n                       predicted=False, accepted=False,\n                       rank_uniform=None, rank_massresid=None,\n                       rank_predictor=None, rank_prior=None,\n                       hits=empty_hits())\n            val_rows.append(out)\n            continue\n        peaks = val_qinfo[qid]\n        if peaks is None:\n            _, err = parse_spectrum(row["mzs"], row["intensities"])\n            # Spectrum-free ranks still computable (documented).\n            pos = seeded_positions(qid, len(distinct))\n            residuals, n_bad = candidate_residuals(distinct,\n                                                   row["parent_mass"])\n            tgt = distinct.index(v["smiles"]) if v["smiles"] in distinct \\\n                else None\n            out = dict(base, status=f"query_parse_excl:{err}",\n                       rankable=False, rankable_reason="no_features",\n                       has_features=False, pred_norm=0.0,\n                       n_scored_finite=0,\n                       predicted=False,\n                       accepted=False, margin_pred=None,\n                       margin_status="no_finite_scores",\n                       hits=empty_hits(),\n                       rank_uniform=None, rank_massresid=None,\n                       rank_predictor=None, rank_prior=None)\n            if tgt is not None:\n                ou = rank_uniform(len(distinct), pos)\n                om = rank_massresid_order(residuals, pos)\n                out["rank_uniform"] = ou.index(tgt) + 1\n                out["rank_massresid"] = om.index(tgt) + 1\n                n = len(distinct)\n                for arm, rk in (("uniform", out["rank_uniform"]),\n                                ("massresid", out["rank_massresid"])):\n                    out["hits"][arm] = {\n                        1: rk <= 1, 3: rk <= min(3, n), 10: rk <= min(10, n)}\n            out["n_unparseable_mass"] = n_bad\n            pfps0 = pool_fps(distinct)\n            out["n_parseable"] = sum(1 for a, _ in pfps0 if a is not None)\n            out["n_unparseable_fp"] = len(pfps0) - out["n_parseable"]\n            out["n_target_fp_ties"] = None\n            if tparse_q:\n                try:\n                    tvec0, _, _ = fp_from_smiles(v["smiles"])\n                    out["n_target_fp_ties"] = sum(\n                        1 for a, _ in pfps0\n                        if a is not None and list(a) == list(tvec0))\n                except Exception:\n                    out["n_target_fp_ties"] = None\n            val_rows.append(out)\n            continue\n        pfps = pool_fps(distinct)\n        n_parse = sum(1 for a, _ in pfps if a is not None)\n        pred, pn = predict_fp(model, peaks)\n        pscores = score_candidates_fp(pred, pn, pfps)\n        prscores = score_candidates_fp(prior_vec, prior_norm, pfps)\n        residuals, n_bad = candidate_residuals(distinct, row["parent_mass"])\n        pos = seeded_positions(qid, len(distinct))\n        ev = evaluate_pool(distinct, v["smiles"], pscores, prscores,\n                           residuals, pos)\n        rankable, rreason = capability_for_query(peaks, pred, pn, pscores)\n        # Collision stats: target fp vs pool fps (representational ceiling).\n        tvec, _, treason = fp_from_smiles(v["smiles"])\n        if tvec is None:\n            n_queries_target_unparseable += 1\n            n_tied = None\n        else:\n            n_tied = sum(1 for a, an in pfps\n                         if a is not None and list(a) == list(tvec))\n            if n_tied is None:\n                n_target_fp_missing += 1\n            elif n_tied > 1:\n                n_collide_target += 1\n        accepted = bool(rankable and gate_accepts(\n            gate, ev["margin_pred"], ev["n_pool"]))\n        out = dict(base, status="complete",\n                   rankable=rankable, rankable_reason=rreason,\n                   has_features=spectrum_has_usable_features(peaks),\n                   pred_norm=pn,\n                   n_scored_finite=ev["n_scored_finite"],\n                   n_parseable=n_parse,\n                   n_unparseable_fp=len(pfps) - n_parse,\n                   n_unparseable_mass=n_bad,\n                   margin_pred=ev["margin_pred"],\n                   margin_status=ev["margin_status"],\n                   predicted=bool(rankable), accepted=accepted,\n                   n_target_fp_ties=n_tied,\n                   rank_uniform=ev["ranks"]["uniform"],\n                   rank_massresid=ev["ranks"]["massresid"],\n                   rank_predictor=ev["ranks"]["predictor"],\n                   rank_prior=ev["ranks"]["prior"],\n                   hits=ev["hits"])\n        val_rows.append(out)\n    metrics = summarize_val(val_rows, "val_formula_pool")\n    calib_metrics = {"n_calib_molecules": len(calib),\n                     "n_calib_rows": len(calib_rows),\n                     "n_rankable": sum(1 for r in calib_rows\n                                       if r.get("rankable") is True),\n                     "gate": {k: v for k, v in gate.items()\n                              if k != "table"},\n                     "gate_table": gate.get("table", [])}\n    pins = {"tsv": tsv_path, "prefix": prefix_path,\n            "tsv_sha256": sha256_file(tsv_path),\n            "prefix_sha256": sha256_file(prefix_path),\n            "tsv_bytes": os.path.getsize(tsv_path),\n            "prefix_bytes": os.path.getsize(prefix_path),\n            "code_sha256": sha256_file(os.path.abspath(__file__))}\n    os.makedirs(out_dir, exist_ok=True)\n    rows_path = os.path.join(out_dir, "predictor_rows.csv")\n    calib_path = os.path.join(out_dir, "calibration_rows.csv")\n    fit_path = os.path.join(out_dir, "train_fit_rows.csv")\n    sum_path = os.path.join(out_dir, "predictor_summary.json")\n    model_path = os.path.join(out_dir, "predictor_model.npz")\n\n    def flatten(rows):\n        flat = []\n        for r in rows:\n            f = dict(r)\n            h = f.pop("hits", {})\n            for arm in ARMS:\n                for k in (1, 3, 10):\n                    v = (h.get(arm, {}).get(k) if h else None)\n                    f[f"hit_{arm}_top{k}"] = v\n            flat.append(f)\n        return flat\n\n    for path, rows in ((rows_path, val_rows), (calib_path, calib_rows)):\n        flat = flatten(rows)\n        cols = sorted({c for f in flat for c in f})\n        with open(path, "w", encoding="utf-8", newline="") as handle:\n            writer = csv.DictWriter(handle, fieldnames=cols)\n            writer.writeheader()\n            for f in flat:\n                writer.writerow({c: f.get(c) for c in cols})\n    with open(fit_path, "w", encoding="utf-8", newline="") as handle:\n        writer = csv.DictWriter(handle, fieldnames=[\n            "smiles", "split", "status", "reason", "group", "adduct",\n            "instrument"])\n        writer.writeheader()\n        for m in molecules:\n            if m.get("split") not in ("fit", "calibration") and \\\n                    m["status"] == "excluded" and m.get("split") is None:\n                continue\n            if m.get("split") not in ("fit", "calibration"):\n                continue\n            writer.writerow({"smiles": m["smiles"], "split": m.get("split"),\n                             "status": m["status"], "reason": m["reason"],\n                             "group": m["group"],\n                             "adduct": m["row"].get("adduct", ""),\n                             "instrument": m["row"].get("instrument_type",\n                                                        "") or "missing"})\n    np.savez(model_path, coef_=np.asarray(model.coef_),\n             intercept_=np.asarray(model.intercept_\n                                  if hasattr(model, "intercept_") else 0.0),\n             mean_prior=np.asarray(prior_vec),\n             alpha=np.asarray([RIDGE_ALPHA]))\n    # Environment versions AFTER all heavy imports/writes; no torch import\n    # (torch is not used by this experiment; importing it only inflates\n    # RSS, so it is deliberately not imported).\n    import sklearn\n    import scipy\n    import numpy as _np\n    env = {"python": sys.version.split()[0],\n           "numpy": _np.__version__, "scipy": scipy.__version__,\n           "sklearn": sklearn.__version__,\n           "torch": "not_imported_by_design"}\n    # Truthful resource scope: captured AFTER env imports + all CSV/model\n    # writes, BEFORE summary serialization. Declared scope covers the whole\n    # run including hashing and output writes; only the summary-JSON write\n    # itself falls outside (ms-scale, documented).\n    wall = time.perf_counter() - t0\n    cpu = time.process_time() - c0\n    peak_kb = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss\n    try:\n        n_cpu = os.cpu_count() or 1\n    except Exception:\n        n_cpu = 1\n    cpu_ratio = (cpu / wall) if wall > 0 else None\n    summary = {\n        "representation": {\n            "spectrum": f"{SPEC_BIN_WIDTH} Da bins over "\n                        f"[{SPEC_MZ_MIN},{SPEC_MZ_MAX}) = {N_SPEC} dims; "\n                        "per-bin max, sqrt, per-spectrum L2; sparse CSR",\n            "fingerprint": f"stable-hash atom/typed-bond/length-2-path "\n                           f"counts, dim={FP_DIM}, crc32, L2-normalized; "\n                           "local hash only, NOT Morgan/ECFP",\n            "model": f"Ridge alpha={RIDGE_ALPHA} solver={RIDGE_SOLVER} "\n                     f"tol={RIDGE_TOL} max_iter={RIDGE_MAX_ITER} "\n                     f"fit_intercept={RIDGE_FIT_INTERCEPT} (fixed a priori)",\n            "scoring": "cosine pred-fp vs candidate-fp; missing fps tail "\n                       "(seeded), retained",\n            "prior": "untrained fit-mean fingerprint, same scoring",\n            "shuffle": SHUFFLE_DOMAIN,\n            "selection": "val: file-order prefix entries joining fold rows; "\n                         "first row per SMILES (identical to spectral run); "\n                         f"train: first {max_train} distinct SMILES molecules "\n                         "group-capped, 80/20 group split fit/calibration",\n            "fixed_a_priori": True,\n        },\n        "caps": {"max_train_molecules": max_train,\n                 "max_queries": max_queries,\n                 "fp_dim": FP_DIM, "n_spec": N_SPEC,\n                 "fit_group_frac": FIT_GROUP_FRAC,\n                 "min_calib_eligible": MIN_CALIB_ELIGIBLE,\n                 "target_precision": CALIB_TARGET_PRECISION},\n        "pins": pins,\n        "provenance": {"downloads_bytes": 0, "api_calls": 0,\n                       "test_fold": "scanned-but-unused (never fit/score)"},\n        "params": {"max_queries": max_queries, "max_train": max_train},\n        "train": {"info": dict(tinfo), "n_fit": len(fit),\n                  "n_calib": len(calib),\n                  "fit_groups_hash": hashlib.sha256(\n                      "".join(sorted(fit_g)).encode()).hexdigest()[:16],\n                  "calib_groups_hash": hashlib.sha256(\n                      "".join(sorted(calib_g)).encode()).hexdigest()[:16],\n                  "train_time_s": t_train1 - t_train0,\n                  "X_nnz": int(X_fit.nnz), "X_shape": list(X_fit.shape)},\n        "calibration": calib_metrics,\n        "val": {k: v for k, v in\n                {"metrics": metrics,\n                 "n_tsv_rows": sel["n_rows"],\n                 "n_test_skipped": sel["n_test"],\n                 "n_entries_scanned": len(sel["entries"]),\n                 "n_joined": len(sel["joined"]),\n                 "val_bias": dict(sel["val_bias"]),\n                 "selected_bias": dict(sel_bias),\n                 "n_target_fp_collisions": n_collide_target,\n                 "n_target_unparseable": n_queries_target_unparseable,\n                 "n_identity_missing": n_identity_missing}.items()},\n        "cost": {"wall_s": wall, "cpu_s": cpu,\n                 "cpu_wall_ratio": cpu_ratio,\n                 "n_cpu_observed": n_cpu,\n                 "peak_rss_kb": peak_kb,\n                 "thread_env": {k: os.environ.get(k) for k in (\n                     "OMP_NUM_THREADS", "OPENBLAS_NUM_THREADS",\n                     "MKL_NUM_THREADS")},\n                 "note": "timer captured AFTER env imports and all row "\n                         "CSV + checkpoint writes, BEFORE summary-JSON "\n                         "serialization (declared scope: full experiment "\n                         "incl. TSV scans, Ridge fit, fingerprinting, "\n                         "sha256, CSV/model writes; only the summary-JSON "\n                         "write itself falls outside, ms-scale). "\n                         "BLAS/OpenMP pools bounded best-effort to 1 via "\n                         "env at start; observed cpu/wall reported, no "\n                         "strict single-threaded claim"},\n        "env": env,\n        "outputs": {"rows": rows_path, "calibration_rows": calib_path,\n                    "fit_rows": fit_path, "model": model_path,\n                    "summary": sum_path,\n                    "rows_bytes": os.path.getsize(rows_path),\n                    "calibration_bytes": os.path.getsize(calib_path),\n                    "fit_bytes": os.path.getsize(fit_path),\n                    "model_bytes": os.path.getsize(model_path)},\n    }\n    # Strict JSON: tau None (null) when abstaining; allow_nan=False so any\n    # Infinity/NaN fails loudly instead of writing nonstandard JSON.\n    text = json.dumps(summary, indent=2, default=str, allow_nan=False)\n    with open(sum_path, "w", encoding="utf-8") as handle:\n        handle.write(text + "\\n")\n    summary["outputs"]["summary_bytes"] = os.path.getsize(sum_path)\n    # Re-serialize file content WITH summary_bytes so the saved JSON (not\n    # just stdout) carries final timings + byte accounting; keep sizes\n    # consistent with a second pass if digit width changed.\n    text2 = json.dumps(summary, indent=2, default=str, allow_nan=False)\n    with open(sum_path, "w", encoding="utf-8") as handle:\n        handle.write(text2 + "\\n")\n    summary["outputs"]["summary_bytes"] = os.path.getsize(sum_path)\n    sys.stdout.write(text2 + "\\n")\n    return summary\n\n\ndef main(argv):\n    import argparse\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--tsv", default="data/pinned/MassSpecGym1.5.tsv")\n    ap.add_argument("--prefix",\n                    default="data/pinned/msgym_candidates_formula_prefix64.json")\n    ap.add_argument("--max-queries", type=int, default=200)\n    ap.add_argument("--max-train", type=int, default=5000)\n    ap.add_argument("--out-dir",\n                    default="experiments/molecular_completion/20261003_predictor")\n    args = ap.parse_args(argv)\n    run_experiment(args.tsv, args.prefix, args.max_queries, args.max_train,\n                   args.out_dir)\n\n\n# --------------------------------------------------------------------------\n# Tests (eight required themes).\n# --------------------------------------------------------------------------\n\nclass FingerprintTests(unittest.TestCase):\n    def test_deterministic(self):\n        from tools.ms2_msgym_corpus import smiles_to_typed\n        at, ed = smiles_to_typed("CCO")\n        self.assertIsNotNone(at)\n        v1, n1 = fp_from_typed(at, ed)\n        v2, n2 = fp_from_typed(at, ed)\n        self.assertEqual(v1, v2)\n        self.assertAlmostEqual(n1, n2)\n\n    def test_permutation_invariant(self):\n        at = (("C", 3, 4), ("C", 2, 4), ("O", 1, 2))\n        ed = ((0, 1, 1), (1, 2, 1))\n        pat = (("O", 1, 2), ("C", 2, 4), ("C", 3, 4))\n        ped = ((2, 1, 1), (1, 0, 1))\n        v1, _ = fp_from_typed(at, ed)\n        v2, _ = fp_from_typed(pat, ped)\n        self.assertEqual(v1, v2)\n\n    def test_structural_distinction(self):\n        from tools.ms2_msgym_corpus import smiles_to_typed\n        at1, ed1 = smiles_to_typed("CCC")\n        at2, ed2 = smiles_to_typed("CCO")\n        v1, _ = fp_from_typed(at1, ed1)\n        v2, _ = fp_from_typed(at2, ed2)\n        self.assertNotEqual(v1, v2)\n\n    def test_no_python_hash(self):\n        import inspect\n        import re\n        src = inspect.getsource(fp_from_typed)\n        self.assertIsNone(re.search(r"(?<![\\w.])hash\\s*\\(", src))\n        self.assertIn("crc32", src)\n\n\nclass LeakageTests(unittest.TestCase):\n    def test_no_query_structure_input(self):\n        # Prediction path (scores from spectra + candidate fps) must never\n        # read query identity/target structures. Evaluation (evaluate_pool)\n        # legitimately uses the target SMILES string only to compute ranks\n        # on fixed pools -- it never computes scores from it (no fp_from /\n        # standardize call inside).\n        import inspect\n        for fn in (score_candidates_fp, predict_fp):\n            src = inspect.getsource(fn)\n            self.assertNotIn("is_target", src)\n            self.assertNotIn("target_smiles", src)\n            self.assertNotIn("target_fp", src)\n        ev_src = inspect.getsource(evaluate_pool)\n        self.assertNotIn("fp_from", ev_src)\n        self.assertNotIn("standardize", ev_src)\n\n    def test_group_split_no_straddle(self):\n        # Two SMILES sharing one InChIKey group must land on one side.\n        groups = {"g1": ["A", "B"], "g2": ["C"]}\n        order = ["g1", "g2"]\n        n_fit = int(len(order) * FIT_GROUP_FRAC)\n        fit_g = set(order[:n_fit]) if n_fit else set(order[:1])\n        # With 2 groups 80% -> 1 fit group; g1 members stay together.\n        self.assertTrue("g1" in fit_g or "g1" not in fit_g)\n        self.assertFalse(fit_g & (set(order) - fit_g))\n\n    def test_val_overlap_rejected(self):\n        val = {"CCO"}\n        valk = {"KEY1"}\n        m = {"smiles": "CCO", "group": "KEY1"}\n        self.assertTrue(m["smiles"] in val or m["group"] in valk)\n\n\nclass MissingFpTests(unittest.TestCase):\n    def test_missing_tail_retained(self):\n        pred = [1.0] + [0.0] * (FP_DIM - 1)\n        pool = [([1.0] + [0.0] * (FP_DIM - 1), 1.0), (None, 0.0),\n                ([0.0, 1.0] + [0.0] * (FP_DIM - 2), 1.0)]\n        sc = score_candidates_fp(pred, 1.0, pool)\n        pos = seeded_positions("Q", 3)\n        order = rank_by_score(sc, pos)\n        self.assertEqual(len(order), 3)\n        self.assertEqual(set(order), {0, 1, 2})\n        self.assertNotEqual(order[-1], 0)\n\n    def test_absent_target_none(self):\n        pool = ["A", "B"]\n        sc = [{"idx": 0, "score": 0.9, "parseable": True},\n              {"idx": 1, "score": 0.1, "parseable": True}]\n        pos = seeded_positions("Q", 2)\n        ev = evaluate_pool(pool, "ZZZ", sc, sc, [0.1, 0.2], pos)\n        self.assertFalse(ev["in_pool"])\n        self.assertIsNone(ev["ranks"]["predictor"])\n        self.assertIsNone(ev["hits"]["predictor"][1])\n\n\nclass TiePriorTests(unittest.TestCase):\n    def test_seeded_ties(self):\n        sc = [{"idx": 0, "score": 0.5, "parseable": True},\n              {"idx": 1, "score": 0.5, "parseable": True}]\n        o1 = rank_by_score(sc, seeded_positions("Q1", 2))\n        o2 = rank_by_score(sc, seeded_positions("Q1", 2))\n        self.assertEqual(o1, o2)\n\n    def test_prior_is_fit_mean(self):\n        fit = [{"fp_target": [1.0, 0.0]}, {"fp_target": [0.0, 1.0]}]\n        import numpy as np\n        Y = np.array([m["fp_target"] for m in fit])\n        mean = Y.mean(axis=0)\n        self.assertAlmostEqual(mean[0], 0.5)\n        self.assertAlmostEqual(mean[1], 0.5)\n\n\nclass CalibrationTests(unittest.TestCase):\n    def test_fail_closed_no_threshold(self):\n        rows = [{"rankable": True, "hit_top1": False, "margin_pred": 0.0,\n                 "n_pool": 10} for _ in range(MIN_CALIB_ELIGIBLE)]\n        g = calibrate_gate(rows)\n        self.assertEqual(g["status"], "abstain_all")\n        self.assertEqual(g["kmax"], 0)\n        self.assertIsNone(g["tau"])\n\n    def test_fail_closed_insufficient(self):\n        rows = [{"rankable": True, "hit_top1": True, "margin_pred": 0.5,\n                 "n_pool": 10}]\n        g = calibrate_gate(rows)\n        self.assertEqual(g["status"], "abstain_all")\n        self.assertIsNone(g["tau"])\n\n    def test_strict_json_gate(self):\n        rows = [{"rankable": True, "hit_top1": False, "margin_pred": 0.0,\n                 "n_pool": 10} for _ in range(MIN_CALIB_ELIGIBLE)]\n        g = calibrate_gate(rows)\n        text = json.dumps({"gate": {k: v for k, v in g.items()\n                                    if k != "table"}},\n                          allow_nan=False)\n        self.assertNotIn("Infinity", text)\n        self.assertNotIn("NaN", text)\n\n        def _fail(_s):\n            raise ValueError("nonstandard JSON constant")\n        parsed = json.loads(text, parse_constant=_fail)\n        self.assertIsNone(parsed["gate"]["tau"])\n        self.assertEqual(parsed["gate"]["status"], "abstain_all")\n\n\nclass FitOnlyTests(unittest.TestCase):\n    def test_featurize_needs_no_fit(self):\n        # Per-sample transform only: single-arg signature, no fitted\n        # globals, deterministic on repeated calls.\n        import inspect\n        sig = list(inspect.signature(featurize_spectrum).parameters)\n        self.assertEqual(sig, ["peaks"])\n        self.assertIsNone(globals().get("_SPEC_VOCAB"))\n        self.assertIsNone(globals().get("_FITTED_MEAN"))\n        v1, n1, _ = featurize_spectrum([(100.5, 1.0), (1500.2, 4.0)])\n        v2, n2, _ = featurize_spectrum([(100.5, 1.0), (1500.2, 4.0)])\n        self.assertEqual(v1, v2)\n        self.assertEqual(n1, n2)\n        import math as _m\n        self.assertAlmostEqual(_m.sqrt(sum(x * x for x in v1.values())), 1.0)\n\n    def test_bin_bounds(self):\n        vec, dropped = bin_spectrum_1da([(0.0, 1.0), (1999.9, 1.0),\n                                         (2000.0, 1.0), (5000.0, 1.0)])\n        self.assertEqual(dropped, 2)\n        self.assertEqual(len(vec), 2)\n        self.assertLess(max(vec), N_SPEC)\n\n\nclass TargetParseableTests(unittest.TestCase):\n    def test_unsupported_target_despite_parseable_candidates(self):\n        # Target with unsupported chemistry alongside parseable others:\n        # capability(any-candidate) includes it, true eligible excludes it.\n        rows = [\n            {"status": "complete", "in_pool": True, "n_parseable": 3,\n             "target_parseable": False, "accepted": False,\n             "hits": {a: {1: False, 3: False, 10: False} for a in ARMS}},\n            {"status": "complete", "in_pool": True, "n_parseable": 3,\n             "target_parseable": True, "accepted": False,\n             "hits": {a: {1: True, 3: True, 10: True} for a in ARMS}},\n        ]\n        m = summarize_val(rows, "t")\n        self.assertEqual(m["capability_any_candidate"]["n"], 2)\n        self.assertEqual(m["eligible_parseable"]["n"], 1)\n        # All arms compared on the exact true-eligible subgroup.\n        for arm in ARMS:\n            self.assertEqual(m["eligible_parseable"][f"{arm}@top1_den"], 1)\n        self.assertEqual(m["eligible_parseable"]["predictor@top1"], 1.0)\n\n    def test_target_parse_info_marks_unsupported(self):\n        parseable, status, _ = target_parse_info("CCO")\n        self.assertTrue(parseable)\n        self.assertEqual(status, "ok")\n        # Unsupported element (parser domain exclusion) is evaluation-only.\n        parseable2, status2, reason2 = target_parse_info("[Si]C")\n        if not parseable2:\n            self.assertEqual(status2, "unsupported")\n            self.assertIsNotNone(reason2)\n\n\nclass IdentityMissingTests(unittest.TestCase):\n    def test_missing_val_key_retained_no_shrink(self):\n        import tempfile\n        from tools.ms2_spectral_rank import WANTED_COLUMNS\n        header = "\\t".join(WANTED_COLUMNS)\n        trows = [\n            ["V0", "100.0", "1.0", "CCO", "", "C2H6O", "C2H7O",\n             "46.0", "47.0", "[M+H]+", "QTOF", "20", "val"],\n            ["V1", "150.0", "1.0", "CCC", "J" * 27, "C3H8", "C3H9",\n             "44.0", "45.0", "[M+H]+", "QTOF", "20", "val"],\n            ["G2", "200.0", "1.0", "CCN", "A" * 27, "C2H7N", "C2H8N",\n             "45.0", "46.0", "[M+H]+", "QTOF", "20", "train"],\n            ["G3", "300.0", "1.0", "CCCC", "B" * 27, "C4H10", "C4H11",\n             "58.0", "59.0", "[M+H]+", "QTOF", "20", "train"],\n        ]\n        with tempfile.NamedTemporaryFile("w", suffix=".tsv",\n                                         delete=False) as h:\n            h.write(header + "\\n")\n            for r in trows:\n                h.write("\\t".join(r) + "\\n")\n            tsv = h.name\n        with tempfile.NamedTemporaryFile("w", suffix=".json",\n                                         delete=False) as h:\n            json.dump({"CCO": ["CCO", "CCC"], "CCC": ["CCC", "CCO"]}, h)\n            prefix = h.name\n        outdir = tempfile.mkdtemp()\n        try:\n            s = run_experiment(tsv, prefix, 2, 10, outdir)\n            import csv as _csv\n            with open(os.path.join(outdir, "predictor_rows.csv")) as fh:\n                rows = list(_csv.DictReader(fh))\n        finally:\n            os.unlink(tsv)\n            os.unlink(prefix)\n        # No output shrinking: both queries retained.\n        self.assertEqual(s["val"]["metrics"]["n_selected"], 2)\n        self.assertEqual(len(rows), 2)\n        by_q = {r["qid"]: r for r in rows}\n        self.assertIn("excluded_identity_missing",\n                      by_q["VAL-0000"]["status"])\n        # Pool accounting retained, abstain, no predictor result.\n        self.assertTrue(int(by_q["VAL-0000"]["n_pool"]) > 0)\n        self.assertEqual(by_q["VAL-0000"]["accepted"], "False")\n        self.assertEqual(by_q["VAL-0000"]["rank_predictor"], "")\n        self.assertEqual(s["val"]["n_identity_missing"], 1)\n\n\nclass CapabilityTests(unittest.TestCase):\n    def _scored(self, scores):\n        return [{"idx": i, "score": s, "parseable": s is not None}\n                for i, s in enumerate(scores)]\n\n    def test_zero_norm_never_rankable(self):\n        peaks = [(100.5, 1.0)]\n        pred = [0.0] * FP_DIM\n        ok, reason = capability_for_query(peaks, pred, 0.0,\n                                          self._scored([0.5, 0.2]))\n        self.assertFalse(ok)\n        self.assertEqual(reason, "predictor_unavailable")\n        # Even a tau=0 gate must not accept.\n        g = {"status": "calibrated", "tau": 0.0, "kmax": 10 ** 9}\n        self.assertFalse(gate_accepts(g, None, 5))\n\n    def test_all_missing_never_rankable(self):\n        peaks = [(100.5, 1.0)]\n        pred = [1.0] + [0.0] * (FP_DIM - 1)\n        ok, _ = capability_for_query(peaks, pred, 1.0,\n                                     self._scored([None, None]))\n        self.assertFalse(ok)\n\n    def test_out_of_range_nan_never_accepted(self):\n        peaks = [(100.5, 1.0)]\n        bad = [float("nan")] + [0.0] * (FP_DIM - 1)\n        ok, _ = capability_for_query(peaks, bad, 1.0,\n                                     self._scored([0.5, 0.2]))\n        self.assertFalse(ok)\n        huge = [100.0] + [0.0] * (FP_DIM - 1)\n        ok2, _ = capability_for_query(peaks, huge, 100.0,\n                                      self._scored([0.5, 0.2]))\n        self.assertFalse(ok2)\n        inf_pred = [float("inf")] + [0.0] * (FP_DIM - 1)\n        sc = score_candidates_fp(inf_pred, float("inf"),\n                                 [([1.0] + [0.0] * (FP_DIM - 1), 1.0)])\n        self.assertIsNone(sc[0]["score"])\n\n    def test_no_features_excluded(self):\n        ok, reason = capability_for_query([], [1.0] + [0.0] * (FP_DIM - 1),\n                                          1.0, self._scored([0.5]))\n        self.assertFalse(ok)\n        self.assertEqual(reason, "no_features")\n\n    def test_targetfp_independent_gate(self):\n        # Same inference inputs -> same rankability regardless of target.\n        peaks = [(100.5, 1.0)]\n        pred = [1.0] + [0.0] * (FP_DIM - 1)\n        scored = self._scored([0.6, 0.2])\n        ok1, _ = capability_for_query(peaks, pred, 1.0, scored)\n        self.assertTrue(ok1)\n        # rankability does not consult target_parseable: prove by source.\n        import inspect\n        src = inspect.getsource(capability_for_query)\n        self.assertNotIn("target_parseable", src)\n        self.assertNotIn("target_fp", src)\n        self.assertNotIn("in_pool", src)\n        self.assertNotIn("hit_top1", src)\n        # Evaluation subgroup differs while capability is identical.\n        rows = [\n            {"status": "complete", "in_pool": True, "n_parseable": 2,\n             "target_parseable": True, "rankable": ok1, "accepted": False,\n             "hits": {a: {1: True, 3: True, 10: True} for a in ARMS}},\n            {"status": "complete", "in_pool": True, "n_parseable": 2,\n             "target_parseable": False, "rankable": ok1, "accepted": False,\n             "hits": {a: {1: False, 3: False, 10: False} for a in ARMS}},\n        ]\n        m = summarize_val(rows, "t")\n        self.assertEqual(m["capability_any_candidate"]["n"], 2)\n        self.assertEqual(m["eligible_parseable"]["n"], 1)\n\n\nclass MarginTests(unittest.TestCase):\n    def test_negative_scores_gap(self):\n        # Ridge cosine is signed: finite gap is .3, not .1 under old\n        # missing-as-zero logic.\n        margin, status = margin_from_finite_scores([-0.1, -0.4, None])\n        self.assertEqual(status, "ok")\n        self.assertAlmostEqual(margin, 0.3)\n\n    def test_single_usable_score_conservative(self):\n        margin, status = margin_from_finite_scores([0.7, None, None])\n        self.assertEqual(status, "single_scored")\n        self.assertEqual(margin, 0.0)\n\n    def test_no_finite_scores_none(self):\n        margin, status = margin_from_finite_scores([None, None])\n        self.assertIsNone(margin)\n        margin2, _ = margin_from_finite_scores(\n            [float("nan"), float("inf")])\n        self.assertIsNone(margin2)\n\n    def test_evaluate_pool_uses_finite_margin(self):\n        pool = ["A", "B", "C"]\n        sc = [{"idx": 0, "score": -0.1, "parseable": True},\n              {"idx": 1, "score": -0.4, "parseable": True},\n              {"idx": 2, "score": None, "parseable": False}]\n        pos = seeded_positions("Q", 3)\n        ev = evaluate_pool(pool, "A", sc, sc, [1.0, 2.0, 3.0], pos)\n        self.assertAlmostEqual(ev["margin_pred"], 0.3)\n        self.assertEqual(ev["margin_status"], "ok")\n        self.assertEqual(ev["n_scored_finite"], 2)\n\n\nclass ResourceStrictJsonTests(unittest.TestCase):\n    def test_no_torch_import_in_source(self):\n        import inspect\n        src = inspect.getsource(run_experiment)\n        self.assertNotIn("import torch", src)\n\n    def test_strict_json_roundtrip(self):\n        g = {"tau": None, "kmax": 0, "status": "abstain_all",\n             "reason": "t", "n_eligible": 3, "table": []}\n        text = json.dumps({"gate": g}, allow_nan=False)\n        self.assertNotIn("Infinity", text)\n\n        def _fail(_s):\n            raise ValueError("bad constant")\n        parsed = json.loads(text, parse_constant=_fail)\n        self.assertIsNone(parsed["gate"]["tau"])\n\n\nclass IntegrationTests(unittest.TestCase):\n    def test_malformed_queries_first_and_later(self):\n        import tempfile\n        from tools.ms2_spectral_rank import WANTED_COLUMNS\n        header = "\\t".join(WANTED_COLUMNS)\n        trows = [\n            ["BAD1", "bad_mz", "bad_it", "CCO", "K" * 27, "C2H6O", "C2H7O",\n             "46.0", "47.0", "[M+H]+", "QTOF", "20", "val"],\n            ["G1", "100.0", "1.0", "CCC", "J" * 27, "C3H8", "C3H9",\n             "44.0", "45.0", "[M+H]+", "QTOF", "20", "val"],\n            ["G2", "200.0", "1.0", "CCN", "A" * 27, "C2H7N", "C2H8N",\n             "45.0", "46.0", "[M+H]+", "QTOF", "20", "train"],\n            ["G3", "300.0", "1.0", "CCCC", "B" * 27, "C4H10", "C4H11",\n             "58.0", "59.0", "[M+H]+", "QTOF", "20", "train"],\n            ["G4", "400.0", "1.0", "CCOC", "C" * 27, "C3H8O", "C3H9O",\n             "60.0", "61.0", "[M+H]+", "QTOF", "20", "train"],\n        ]\n        with tempfile.NamedTemporaryFile("w", suffix=".tsv",\n                                         delete=False) as h:\n            h.write(header + "\\n")\n            for r in trows:\n                h.write("\\t".join(r) + "\\n")\n            tsv = h.name\n        with tempfile.NamedTemporaryFile("w", suffix=".json",\n                                         delete=False) as h:\n            json.dump({"CCO": ["CCO", "CCC"], "CCC": ["CCC", "CCO"]}, h)\n            prefix = h.name\n        outdir = tempfile.mkdtemp()\n        try:\n            s = run_experiment(tsv, prefix, 2, 10, outdir)\n        finally:\n            os.unlink(tsv)\n            os.unlink(prefix)\n        self.assertEqual(s["val"]["metrics"]["n_selected"], 2)\n        self.assertTrue(os.path.exists(os.path.join(outdir, "predictor_rows.csv")))\n        self.assertTrue(os.path.exists(os.path.join(outdir, "predictor_model.npz")))\n\n\nif __name__ == "__main__":\n    main(sys.argv[1:])\n', 'tools/ms2_msgym_corpus.py': '"""Real-corpus ingestion for the database-first retrieval harness.\n\nExtends tools/ms2_database_retrieval.py (imported, not modified) with:\n\n- a restricted, stdlib-only SMILES parser that accepts a documented subset\n  and rejects everything else with an explicit reason (aromaticity,\n  charges, non-domain elements, bracket anomalies, syntax errors). Rejected\n  inputs are a measured denominator, never silently reinterpreted;\n- a Hill-formula parser used to cross-check the graph-derived composition;\n- an incremental scanner for the large MassSpecGym candidate JSONs so a\n  capped prefix download yields complete per-query entries;\n- a pinned, capped MassSpecGym val-fold driver that joins supplied\n  candidate pools to measured-spectrum metadata and runs the same four\n  staged filters as the synthetic harness.\n\nRun:   python3 tools/ms2_msgym_corpus.py --prefix data/pinned/msgym_candidates_formula_prefix.json \\\\\n           --tsv data/pinned/MassSpecGym1.5.tsv --max-queries 150\nTest:  python3 -m unittest tools.ms2_msgym_corpus\n\nScope notes (see docs/MOLECULAR_COMPLETION_DATABASE_EXPERIMENTS.md):\n- Target-parent reconstruction only. Peak masses do not identify fragment\n  connectivity, so no fragment-graph claims are made.\n- Whole-target requests: the precursor measurement is redundant with the\n  target evidence, so the stage-4 precursor arm is reported not_evaluated.\n- Aromatic records are outside the current closed-molecule typed-graph\n  domain (no kekulization is performed; silent kekulization would invent\n  bond orders). They are counted as exclusions.\n- Top-k is reported only when the target is present in the supplied pool.\n"""\nfrom __future__ import annotations\n\nimport csv\nimport hashlib\nimport json\nimport os\nimport sys\nimport time\nimport unittest\nfrom collections import Counter\n\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\nfrom tools.ms2_database_retrieval import (\n    DOMAIN_ELEMENTS,\n    DatabaseIndex,\n    WorkCounters,\n    edge_fingerprint,\n    formula_key,\n    formula_of,\n    joint_contains,\n    mass_verdict,\n    neutral_mass,\n    rank_baselines,\n    run_query,\n    standardize_record,\n    contains_exact,\n)\n\nVALENCE = {"C": 4, "N": 3, "O": 2, "F": 1, "Cl": 1, "Br": 1, "I": 1, "S": 2}\nAROMATIC_VALENCE = {"C": 3, "N": 3, "O": 2, "S": 2}\nDOMAIN_SET = {"C", "N", "O", "F", "Cl", "Br", "I", "S"}\nAROMATIC_ATOMS = set("cnops")\nORGANIC_ATOMS = {\n    "B", "C", "N", "O", "P", "S", "F", "Cl", "Br", "I",\n}\n\n\nclass SmilesUnsupported(Exception):\n    def __init__(self, reason):\n        super().__init__(reason)\n        self.reason = reason\n\n\ndef _read_atom(smi, i):\n    """Parse one atom token at position i. Returns (atom_dict, next_i)."""\n    n = len(smi)\n    c = smi[i]\n    if c == "[":\n        j = smi.index("]", i)\n        body = smi[i + 1:j]\n        # Strip stereochemistry markers (connectivity identity only).\n        body = body.replace("@", "")\n        k = 0\n        while k < len(body) and not body[k].isalpha():\n            k += 1\n        # A leading number is an isotope label ([13C], [2H]): normalize-and-\n        # forget would silently compute the unlabeled mass, so reject.\n        if any(ch.isdigit() for ch in body[:k]):\n            raise SmilesUnsupported("unsupported_isotope")\n        aromatic = False\n        if k < len(body) and body[k].islower():\n            aromatic = True\n            elem = body[k].upper()\n            k += 1\n        elif k < len(body) and body[k].isupper():\n            elem = body[k]\n            k += 1\n            if k < len(body) and body[k].islower():\n                elem += body[k]\n                k += 1\n        else:\n            raise SmilesUnsupported(f"bracket_feature:{body!r}")\n        rest = body[k:]\n        hydrogens = 0\n        charge = 0\n        p = 0\n        while p < len(rest):\n            if rest[p] == "H":\n                p += 1\n                num = ""\n                while p < len(rest) and rest[p].isdigit():\n                    num += rest[p]\n                    p += 1\n                hydrogens = int(num) if num else 1\n            elif rest[p] in "+-":\n                sign = 1 if rest[p] == "+" else -1\n                p += 1\n                num = ""\n                while p < len(rest) and rest[p].isdigit():\n                    num += rest[p]\n                    p += 1\n                charge += sign * (int(num) if num else 1)\n            else:\n                raise SmilesUnsupported(f"bracket_feature:{rest!r}")\n        return ({"element": elem, "aromatic": aromatic, "bracket": True,\n                 "hydrogens": hydrogens, "charge": charge,\n                 "valence": AROMATIC_VALENCE.get(elem, VALENCE.get(elem, 0)) if aromatic\n                 else VALENCE.get(elem, 0)}, j + 1)\n    if c.islower():\n        return ({"element": c.upper(), "aromatic": True, "bracket": False,\n                 "hydrogens": 0, "charge": 0,\n                 "valence": AROMATIC_VALENCE.get(c.upper(), 0)}, i + 1)\n    if c.isupper():\n        if c in ("Cl",) or (c == "C" and i + 1 < n and smi[i + 1] == "l"):\n            return ({"element": "Cl", "aromatic": False, "bracket": False,\n                     "hydrogens": 0, "charge": 0, "valence": 1}, i + 2)\n        if c == "B" and i + 1 < n and smi[i + 1] == "r":\n            return ({"element": "Br", "aromatic": False, "bracket": False,\n                     "hydrogens": 0, "charge": 0, "valence": 1}, i + 2)\n        if c == "I":\n            return ({"element": "I", "aromatic": False, "bracket": False,\n                     "hydrogens": 0, "charge": 0, "valence": 1}, i + 1)\n        if c == "S":\n            return ({"element": "S", "aromatic": False, "bracket": False,\n                     "hydrogens": 0, "charge": 0, "valence": 2}, i + 1)\n        return ({"element": c, "aromatic": False, "bracket": False,\n                 "hydrogens": 0, "charge": 0,\n                 "valence": VALENCE.get(c, 0)}, i + 1)\n    raise SmilesUnsupported(f"unexpected_char:{c!r}")\n\n\ndef parse_smiles(smi):\n    """Parse SMILES into (atoms, bonds).\n\n    atoms: list of dicts with element/aromatic/bracket/hydrogens/charge/\n    valence. bonds: list of (a, b, order) with order in (1, 2, 3, 4 =\n    aromatic). Raises SmilesUnsupported for anything outside the subset.\n    """\n    from tools.ms2_database_retrieval import AROM_ORDER\n    if not smi:\n        raise SmilesUnsupported("empty_smiles")\n    if "." in smi:\n        raise SmilesUnsupported("disconnected_or_salt")\n    atoms, bonds = [], []\n    stack = []\n    ring = {}\n    prev = None\n    pending_bond = None\n    i, n = 0, len(smi)\n\n    def add_bond(a, b, order):\n        if a is None or b is None:\n            raise SmilesUnsupported("dangling_bond")\n        bonds.append((a, b, order))\n\n    def close_ring(num, order):\n        # Default ring-bond order resolves at close time, when both endpoint\n        # aromaticity flags are known (fixes aromatic closures).\n        if num in ring:\n            other, stored = ring.pop(num)\n            if order is not None:\n                resolved = order\n            elif stored is not None:\n                resolved = stored\n            elif atoms[prev]["aromatic"] and atoms[other]["aromatic"]:\n                resolved = AROM_ORDER\n            else:\n                resolved = 1\n            add_bond(prev, other, resolved)\n        else:\n            ring[num] = (prev, order)\n\n    while i < n:\n        c = smi[i]\n        if c == "(":\n            stack.append((prev, pending_bond))\n            pending_bond = None\n            i += 1\n        elif c == ")":\n            if not stack:\n                raise SmilesUnsupported("unbalanced_paren")\n            prev, pending_bond = stack.pop()\n            i += 1\n        elif c in "-=#:/\\\\":\n            if c == "=":\n                pending_bond = 2\n            elif c == "#":\n                pending_bond = 3\n            elif c == ":":\n                pending_bond = AROM_ORDER\n            else:\n                pending_bond = 1\n            i += 1\n        elif c == "%":\n            digits = smi[i + 1:i + 3]\n            if len(digits) != 2 or not digits.isdigit():\n                raise SmilesUnsupported("bad_ring_closure")\n            num = int(digits)\n            order = pending_bond\n            pending_bond = None\n            close_ring(num, order)\n            i += 3\n        elif c.isdigit():\n            num = int(c)\n            order = pending_bond\n            pending_bond = None\n            close_ring(num, order)\n            i += 1\n        else:\n            atom, i = _read_atom(smi, i)\n            idx = len(atoms)\n            atoms.append(atom)\n            if prev is not None:\n                if pending_bond is not None:\n                    order = pending_bond\n                elif atom["aromatic"] and atoms[prev]["aromatic"]:\n                    order = AROM_ORDER\n                else:\n                    order = 1\n                add_bond(prev, idx, order)\n            pending_bond = None\n            prev = idx\n    if stack:\n        raise SmilesUnsupported("unbalanced_paren")\n    if ring:\n        raise SmilesUnsupported("unclosed_ring")\n    if not atoms:\n        raise SmilesUnsupported("empty_smiles")\n    return atoms, bonds\n\n\ndef _aromatic_type(el, bracket_h, n_arom, n_other, vsum, std_valence,\n                   has_exo_multiple):\n    """Resolve (h, valence) for an aromatic atom or raise SmilesUnsupported.\n\n    bracket_h: stated H count, or None for bare atoms. Bare `n` with two\n    aromatic-only connections follows the RDKit convention (pyridine,\n    H=0); this is sound for RDKit-canonical corpora and recorded as a\n    corpus dependence. Anything structurally ambiguous is rejected, not\n    guessed.\n\n    Atoms with an exocyclic multiple bond (e.g. a pyrone carbonyl carbon,\n    which RDKit still flags aromatic) cannot use aromatic valence 3: they\n    fall back to aliphatic typing with the standard valence, which the\n    uniform residual rule then validates. `vsum` uses ORDER_VALUE and\n    `std_valence` is the aliphatic valence (C4 N3 O2 S2).\n    """\n    total = n_arom + n_other\n    if has_exo_multiple and bracket_h is None and el in ("C", "N", "O", "S"):\n        h = std_valence - vsum\n        if h < 0:\n            raise SmilesUnsupported("hypervalent")\n        return h, std_valence\n    if el == "C":\n        if bracket_h is not None:\n            if bracket_h != 3 - total:\n                raise SmilesUnsupported("bracket_valence")\n            return bracket_h, 3\n        if total < 2:\n            raise SmilesUnsupported("ambiguous_aromatic")\n        h = 3 - total\n        if h < 0:\n            raise SmilesUnsupported("hypervalent")\n        return h, 3\n    if el == "N":\n        if bracket_h is not None:\n            return bracket_h, 3 if bracket_h > 0 else 2\n        if n_arom == 2 and n_other == 0:\n            return 0, 2\n        if n_arom >= 2 and total == 3:\n            return 0, 3\n        raise SmilesUnsupported("ambiguous_aromatic")\n    if el in ("O", "S"):\n        if bracket_h is not None:\n            return bracket_h, 2\n        if total == 2:\n            return 0, 2\n        raise SmilesUnsupported("ambiguous_aromatic")\n    raise SmilesUnsupported(f"ambiguous_aromatic:{el}")\n\n\ndef typed_from_parsed(atoms, bonds):\n    """Shared typed-graph builder for SMILES and SDF front ends.\n\n    atoms: list of dicts with element/aromatic/bracket/hydrogens/charge/\n    valence. bonds: list of (a, b, order) with order in (1, 2, 3, 4).\n    Returns (atom_types, edges) or (None, exclusion_reason). Hydrogens are\n    parent-relative counts derived here, never invented downstream.\n    Valence sums use ORDER_VALUE (aromatic code counts one unit).\n    """\n    from tools.ms2_database_retrieval import AROM_ORDER, ORDER_VALUE\n\n    for a, b, o in bonds:\n        if o == AROM_ORDER:\n            # Aromatic bonds need aromatic-flagged endpoints (SMILES\n            # lowercase). V2000 molfiles carry no such flags, so SDF bond\n            # type 4 stays rejected; likewise explicit \':\' on aliphatics.\n            if not (atoms[a]["aromatic"] and atoms[b]["aromatic"]):\n                return None, "aromatic_bond"\n            continue\n        if o not in (1, 2, 3):\n            return None, f"unsupported_bond_type:{o}"\n    for a in atoms:\n        if a["charge"] != 0:\n            return None, "unsupported_charge"\n        if a["element"] not in DOMAIN_SET:\n            return None, f"unsupported_element:{a[\'element\']}"\n    n = len(atoms)\n    vsum = [0] * n\n    narom = [0] * n\n    nother = [0] * n\n    exomult = [False] * n\n    for a, b, o in bonds:\n        try:\n            value = ORDER_VALUE[o]\n        except KeyError:\n            return None, f"unsupported_bond_type:{o}"\n        vsum[a] += value\n        vsum[b] += value\n        if o == AROM_ORDER:\n            narom[a] += 1\n            narom[b] += 1\n        else:\n            nother[a] += 1\n            nother[b] += 1\n            if value >= 2:\n                exomult[a] = True\n                exomult[b] = True\n    typed = []\n    try:\n        for idx, a in enumerate(atoms):\n            el = a["element"]\n            if a["aromatic"]:\n                h, val = _aromatic_type(\n                    el, a["hydrogens"] if a["bracket"] else None,\n                    narom[idx], nother[idx], vsum[idx],\n                    VALENCE.get(el, 0), exomult[idx])\n            elif a["bracket"]:\n                h = a["hydrogens"]\n                val = a["valence"]\n                if vsum[idx] + h != val:\n                    raise SmilesUnsupported("bracket_valence")\n            else:\n                val = a["valence"]\n                h = val - vsum[idx]\n                if h < 0:\n                    raise SmilesUnsupported("hypervalent")\n            typed.append((el, h, val))\n    except SmilesUnsupported as exc:\n        return None, exc.reason\n    edges = tuple((a, b, o) for a, b, o in bonds)\n    return tuple(typed), edges\n\n\ndef smiles_to_typed(smi):\n    """Convert SMILES to (atom_types, edges) or return (None, reason)."""\n    try:\n        atoms, bonds = parse_smiles(smi)\n    except SmilesUnsupported as exc:\n        return None, exc.reason\n    except (ValueError, IndexError) as exc:\n        return None, f"syntax_error:{exc}"\n    return typed_from_parsed(atoms, bonds)\n\n\ndef parse_formula(text):\n    """Parse a Hill formula string (e.g. C16H17NO4) into a counts dict."""\n    import re\n\n    counts = {e: 0 for e in DOMAIN_ELEMENTS}\n    for el, num in re.findall(r"([A-Z][a-z]?)(\\d*)", text):\n        if el == "H":\n            counts["H"] += int(num) if num else 1\n        elif el in counts:\n            counts[el] += int(num) if num else 1\n        else:\n            counts[el] = counts.get(el, 0) + (int(num) if num else 1)\n    return counts\n\n\ndef standardize_smiles(smi, source, mid, expected_formula=None):\n    """Parse + standardize one SMILES. Returns (record, exclusion_reason)."""\n    typed, result = smiles_to_typed(smi)\n    if typed is None:\n        return None, result\n    edges = result\n    raw = {"id": mid, "source": source, "family": "msgym",\n           "atom_types": typed, "edges": edges, "charge": 0,\n           "original": {"smiles": smi}}\n    record, reason = standardize_record(raw)\n    if record is None:\n        return None, reason\n    if expected_formula is not None:\n        if formula_key(record["formula"]) != formula_key(expected_formula):\n            return None, "formula_mismatch"\n    return record, None\n\n\n# --------------------------------------------------------------------------\n# Incremental candidate-JSON scanner (capped prefix -> complete entries).\n# --------------------------------------------------------------------------\n\ndef iter_json_entries(path, max_entries):\n    """Yield (query_smiles, candidates) for complete entries in file order.\n\n    The file is a single large JSON object mapping query SMILES to arrays\n    of candidate SMILES. Only complete entries are returned; a trailing\n    partial entry from a Range-request prefix is dropped.\n    """\n    with open(path, "r", encoding="utf-8") as handle:\n        text = handle.read()\n    entries = []\n    i, n = 0, len(text)\n    try:\n        while len(entries) < max_entries and i < n:\n            # Find next string token (object key).\n            while i < n and text[i] != \'"\':\n                if text[i] == "}":\n                    return iter(entries)\n                i += 1\n            if i >= n:\n                break\n            key, i = _scan_string(text, i)\n            while i < n and text[i] in " \\t\\r\\n":\n                i += 1\n            if i >= n or text[i] != ":":\n                break\n            i += 1\n            while i < n and text[i] in " \\t\\r\\n":\n                i += 1\n            if i >= n or text[i] != "[":\n                break\n            value_text, i = _scan_array(text, i)\n            try:\n                candidates = json.loads(value_text)\n                query = json.loads(key)\n            except json.JSONDecodeError:\n                continue\n            entries.append((query, candidates))\n    except SmilesUnsupported:\n        pass  # truncated prefix (key or array): keep complete entries only\n    return iter(entries)\n\n\ndef _scan_string(text, i):\n    assert text[i] == \'"\'\n    j = i + 1\n    n = len(text)\n    while j < n:\n        c = text[j]\n        if c == "\\\\":\n            j += 2\n            continue\n        if c == \'"\':\n            return text[i:j + 1], j + 1\n        j += 1\n    raise SmilesUnsupported("truncated_string")\n\n\ndef _scan_array(text, i):\n    assert text[i] == "["\n    depth = 0\n    j = i\n    n = len(text)\n    in_str = False\n    while j < n:\n        c = text[j]\n        if in_str:\n            if c == "\\\\":\n                j += 2\n                continue\n            if c == \'"\':\n                in_str = False\n        else:\n            if c == \'"\':\n                in_str = True\n            elif c == "[":\n                depth += 1\n            elif c == "]":\n                depth -= 1\n                if depth == 0:\n                    return text[i:j + 1], j + 1\n        j += 1\n    raise SmilesUnsupported("truncated_array")\n\n\n# --------------------------------------------------------------------------\n# TSV loading (val fold, capped, deduplicated by structure string).\n# --------------------------------------------------------------------------\n\nWANTED_COLUMNS = ("identifier", "smiles", "inchikey", "formula",\n                  "precursor_formula", "parent_mass", "precursor_mz",\n                  "adduct", "instrument_type", "collision_energy", "fold")\n\n\ndef load_tsv_rows(path):\n    with open(path, "r", encoding="utf-8") as handle:\n        reader = csv.DictReader(handle, delimiter="\\t")\n        missing = [c for c in WANTED_COLUMNS if c not in (reader.fieldnames or [])]\n        if missing:\n            raise ValueError(f"TSV missing columns: {missing}")\n        for row in reader:\n            yield {c: row[c] for c in WANTED_COLUMNS}\n\n\ndef index_val_by_smiles(path):\n    """Map smiles -> list of val-fold rows (dedup key: raw SMILES string)."""\n    groups = {}\n    n_rows = 0\n    for row in load_tsv_rows(path):\n        n_rows += 1\n        if row["fold"] != "val":\n            continue\n        groups.setdefault(row["smiles"], []).append(row)\n    return groups, n_rows\n\n\n# --------------------------------------------------------------------------\n# Query construction from a true structure (synthetic open subgraphs).\n# --------------------------------------------------------------------------\n\ndef extract_patterns(atom_types, edges):\n    """Single-atom, single-bond, and first overlapping bond-pair patterns."""\n    if not edges:\n        return ((atom_types[0],), ()), None\n    a, b, o = edges[0]\n    single = (((atom_types[a], atom_types[b])), ((0, 1, o),))\n    pair = None\n    for c, d, p in edges[1:]:\n        if len({a, b, c, d}) == 3:\n            at = [atom_types[a], atom_types[b]]\n            third = c if c not in (a, b) else d\n            at.append(atom_types[third])\n            # Re-index: keep shared atom first for a compact pattern.\n            shared = a if a in (c, d) else b\n            others = [x for x in (a, b) if x != shared] + [third]\n            order = {tuple(sorted((x, y))): q for x, y, q in edges}\n            mapping = {shared: 0, others[0]: 1, others[1]: 2}\n            pe = tuple(sorted(\n                (mapping[x], mapping[y], q)\n                for (x, y), q in order.items()\n                if x in (shared,) + tuple(others) and y in (shared,) + tuple(others)\n                and {x, y} <= {shared, others[0], others[1]}\n                and ((x == shared and y in others) or (y == shared and x in others))))\n            pair = ((tuple([atom_types[shared]] + [atom_types[x] for x in others])), pe)\n            break\n    return single, pair\n\n\ndef run_msgym_experiment(prefix_path, tsv_path, max_queries, candidate_cap=None):\n    """Capped val-fold run over supplied formula candidate pools."""\n    t0 = time.perf_counter()\n    c0 = time.process_time()\n    val_groups, n_tsv_rows = index_val_by_smiles(tsv_path)\n    entries = [(q, c) for q, c in iter_json_entries(prefix_path, max_queries * 20)]\n    # File-order slice: first entries that join to a val row.\n    joined = [(q, c) for q, c in entries if q in val_groups][:max_queries]\n    pool_stats = Counter()\n    target_stats = Counter()\n    queries = []  # (name, target_record, patterns_list, row)\n    for qi, (qsmiles, cands) in enumerate(joined):\n        row = val_groups[qsmiles][0]\n        try:\n            expected = parse_formula(row["formula"])\n        except Exception:\n            target_stats["formula_unparseable"] += 1\n            continue\n        target, reason = standardize_smiles(\n            qsmiles, "msgym-val", f"MSGYM-Q{qi:04d}", expected)\n        if target is None:\n            target_stats[reason.split(":")[0]] += 1\n            continue\n        target_stats["in_domain"] += 1\n        # Mass agreement: graph-derived theoretical neutral mass vs the\n        # provider\'s parent_mass, which is MEASURED (precursor m/z minus\n        # proton mass; sub-ppm Orbitrap errors observed). Agreement within\n        # 10 ppm validates the parser\'s H-count logic against an independent\n        # column; the separate formula cross-check already passed.\n        try:\n            from decimal import Decimal\n\n            observed_mu = int(Decimal(row["parent_mass"]) * 1_000_000)\n            ppm = abs(observed_mu - target["mass"]) / target["mass"] * 1e6\n        except Exception:\n            ppm = None\n        mass_ok = ppm is not None and ppm <= 10.0\n        pool_stats["mass_agree" if mass_ok else "mass_mismatch"] += 1\n        pool = []\n        capped = cands if candidate_cap is None else cands[:candidate_cap]\n        for ci, csmiles in enumerate(capped):\n            pool_stats["n_supplied"] += 1\n            rec, rreason = standardize_smiles(\n                csmiles, "msgym-pool", f"MSGYM-Q{qi:04d}-C{ci:04d}")\n            if rec is None:\n                pool_stats[f"pool_excl:{rreason.split(\':\')[0]}"] += 1\n                continue\n            pool_stats["pool_in_domain"] += 1\n            pool.append(rec)\n        single, pair = extract_patterns(target["atom_types"], target["edges"])\n        pats_mass_only = []\n        pats_single = [single] if single else []\n        pats_two = [single, pair] if pair else pats_single\n        queries.append((f"MSGYM-Q{qi:04d}", target, pool, row,\n                        pats_mass_only, pats_single, pats_two))\n    rows = []\n    import sys as _sys\n\n    for qi, (name, target, pool, row, p0, p1, p2) in enumerate(queries):\n        # Supplied pools are used verbatim; the target is never injected.\n        sub = DatabaseIndex(pool)\n        qsmiles = row["smiles"]\n        # Pool membership by exact (RDKit-canonical) SMILES string. This is\n        # exact up to the provider\'s canonicalization; the fingerprint-based\n        # flag below is a weaker upper bound (collisions possible).\n        strict_in_pool = any(\n            r["original"].get("smiles") == qsmiles for r in pool)\n        loose_in_pool = strict_in_pool or any(\n            formula_key(r["formula"]) == formula_key(target["formula"])\n            and edge_fingerprint(r["atom_types"], r["edges"])\n            == edge_fingerprint(target["atom_types"], target["edges"])\n            for r in pool)\n        try:\n            from decimal import Decimal\n\n            obs_mu = int(Decimal(row["parent_mass"]) * 1_000_000)\n            ppm_err = abs(obs_mu - target["mass"]) / target["mass"] * 1e6\n        except Exception:\n            ppm_err = None\n        for qname, pats in (("mass_only", p0), ("single_bond", p1),\n                            ("bonded_pair", p2)):\n            # Bonded patterns only: single-atom patterns are combinatorially\n            # promiscuous on drug-sized targets; their behavior is covered by\n            # the synthetic harness. 100k embedding nodes per arm, then an\n            # explicit search_budget_exhausted status (never a silent cut).\n            counters = WorkCounters(limit=100_000)\n            res = run_query(sub, target, pats, "unknown", None,\n                            counters=counters)\n            present = {stage: any(\n                r["original"].get("smiles") == qsmiles for r in res[stage])\n                for stage in ("s1", "s2", "s3")}\n            # Rank the surviving pool; the target-equivalent member (by\n            # string) is the top-k reference. Absent target => keys gated.\n            tgt_rid = next(\n                (r["id"] for r in res["s3"]\n                 if r["original"].get("smiles") == qsmiles), "__absent__")\n            rank, _ = rank_baselines(res["s3"], tgt_rid, sub)\n            rows.append({\n                "query": f"{name}:{qname}", "target": target["id"],\n                "in_supplied_pool": strict_in_pool,\n                "in_pool_loose_fp": loose_in_pool,\n                "recall_s1": present["s1"], "recall_s2": present["s2"],\n                "recall_s3": present["s3"],\n                "n_supplied": len(pool),\n                "n_s1": len(res["s1"]), "n_s2": len(res["s2"]),\n                "n_s3": len(res["s3"]),\n                "zero_status": res["zero_status"],\n                "top1_uniform": rank.get("uniform@1"),\n                "top1_fingerprint": rank.get("fingerprint@1"),\n                "top3_fingerprint": rank.get("fingerprint@3"),\n                "heavy": target["heavy"],\n                "n_pool": len(pool),\n                "adduct": row["adduct"],\n                "instrument": row["instrument_type"],\n                "ppm_err": round(ppm_err, 3) if ppm_err is not None else None,\n                "truncated": res["truncated"],\n                "embedding_nodes": counters.embedding_nodes,\n            })\n        if (qi + 1) % 5 == 0 or qi + 1 == len(queries):\n            _sys.stderr.write(f"# progress {qi + 1}/{len(queries)}\\n")\n            _sys.stderr.flush()\n    wall = time.perf_counter() - t0\n    cpu = time.process_time() - c0\n    return {\n        "rows": rows,\n        "n_tsv_rows": n_tsv_rows,\n        "n_val_structures": len(val_groups),\n        "n_entries_scanned": len(entries),\n        "n_queries": len(queries),\n        "pool_stats": dict(pool_stats),\n        "target_stats": dict(target_stats),\n        "wall_s": wall,\n        "cpu_s": cpu,\n    }\n\n\ndef main(argv):\n    import argparse\n\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--prefix", required=True)\n    ap.add_argument("--tsv", required=True)\n    ap.add_argument("--max-queries", type=int, default=150)\n    ap.add_argument("--out", default="")\n    args = ap.parse_args(argv)\n    result = run_msgym_experiment(args.prefix, args.tsv, args.max_queries)\n    if args.out:\n        with open(args.out, "w", encoding="utf-8") as handle:\n            writer = csv.DictWriter(handle, fieldnames=sorted(result["rows"][0].keys()))\n            writer.writeheader()\n            writer.writerows(result["rows"])\n    summary = {k: v for k, v in result.items() if k != "rows"}\n    sys.stdout.write(json.dumps(summary, indent=2, default=str) + "\\n")\n    for r in result["rows"][:10]:\n        sys.stderr.write(str(r) + "\\n")\n\n\n# --------------------------------------------------------------------------\n# Tests.\n# --------------------------------------------------------------------------\n\nclass SmilesTests(unittest.TestCase):\n    def test_ethanol(self):\n        typed, edges = smiles_to_typed("CCO")\n        f = formula_of(typed)\n        self.assertEqual((f["C"], f["H"], f["O"]), (2, 6, 1))\n        rec, reason = standardize_record({"id": "t", "atom_types": typed,\n                                          "edges": edges, "charge": 0})\n        self.assertIsNotNone(rec, reason)\n\n    def test_branch_and_double_bond(self):\n        typed, _ = smiles_to_typed("CC(=O)O")\n        self.assertEqual(formula_of(typed)["H"], 4)  # acetic acid C2H4O2\n\n    def test_ring_closure(self):\n        typed, edges = smiles_to_typed("C1CCOC1")  # tetrahydrofuran\n        self.assertEqual(len(typed), 5)\n        self.assertEqual(len(edges), 5)\n\n    def test_percent_ring(self):\n        typed, _ = smiles_to_typed("C%10CCCCC%10")  # cyclohexane via %10\n        self.assertEqual(len(typed), 6)\n\n    def test_benzene_aromatic(self):\n        typed, edges = smiles_to_typed("c1ccccc1")\n        self.assertEqual(formula_of(typed)["H"], 6)  # C6H6\n        self.assertTrue(all(o == 4 for _, _, o in edges))\n        rec, reason = standardize_record({"id": "t", "atom_types": typed,\n                                          "edges": edges, "charge": 0})\n        self.assertIsNotNone(rec, reason)\n\n    def test_pyridine_pyrrole_thiophene(self):\n        for smi, h, n in (("n1ccccc1", 5, 1), ("c1cc[nH]c1", 5, 1),\n                          ("c1ccsc1", 4, 0)):\n            typed, _ = smiles_to_typed(smi)\n            f = formula_of(typed)\n            self.assertEqual((f["H"], f["N"]), (h, n), smi)\n\n    def test_aromatic_chloride(self):\n        typed, _ = smiles_to_typed("Clc1ccccc1")\n        self.assertEqual(formula_of(typed),\n                         {"C": 6, "H": 5, "N": 0, "O": 0, "F": 0,\n                          "S": 0, "Cl": 1, "Br": 0, "I": 0})\n\n    def test_sulfone_hypervalent(self):\n        _, reason = smiles_to_typed("CCS(=O)(=O)C")\n        self.assertEqual(reason, "hypervalent")\n\n    def test_bare_n_ambiguous(self):\n        _, reason = smiles_to_typed("nC")\n        self.assertEqual(reason, "ambiguous_aromatic")\n\n    def test_pyrone_carbonyl_fallback(self):\n        # RDKit flags pyrone carbonyl carbons aromatic; with an exocyclic\n        # double bond they take aliphatic typing (uniform residual rule).\n        rec, reason = standardize_smiles(\n            "O=c1oc2ccccc2c(O)c1C", "t", "T", parse_formula("C10H8O3"))\n        self.assertIsNotNone(rec, reason)\n        self.assertEqual(rec["formula"]["H"], 8)\n\n    def test_aromatic_kekule_boundary(self):\n        # Representation boundary (documented): aromatic-order patterns do\n        # not match kekule-ordered targets and vice versa, even for the\n        # same molecule. Within one canonical corpus this never triggers.\n        from tools.ms2_database_retrieval import contains_exact\n\n        kt, ke = smiles_to_typed("C1=CC=CC=C1")\n        at, ae = smiles_to_typed("c1ccccc1")\n        apat = ((at[0], at[1]), ((0, 1, ae[0][2]),))\n        self.assertFalse(contains_exact(kt, ke, *apat))\n        self.assertTrue(contains_exact(at, ae, *apat))\n\n    def test_charge_excluded(self):\n        _, reason = smiles_to_typed("CC[N+](=O)[O-]")\n        self.assertEqual(reason, "unsupported_charge")\n\n    def test_halogen_alkyl_now_supported(self):\n        # Monovalent halogens joined the domain; silicon stays out.\n        typed, _ = smiles_to_typed("CCCl")\n        self.assertEqual(formula_of(typed)["Cl"], 1)\n        _, reason = smiles_to_typed("CC[Si]")\n        self.assertEqual(reason, "unsupported_element:Si")\n\n    def test_disconnected_excluded(self):\n        _, reason = smiles_to_typed("CC.[Na+]")\n        self.assertEqual(reason, "disconnected_or_salt")\n\n    def test_bracket_stereo_ok(self):\n        typed, _ = smiles_to_typed("C[C@H](N)O")\n        self.assertEqual(formula_of(typed)["H"], 7)  # C2H7NO\n\n    def test_kekule_benzene_accepted_as_domain(self):\n        typed, edges = smiles_to_typed("C1=CC=CC=C1")\n        rec, reason = standardize_record({"id": "t", "atom_types": typed,\n                                          "edges": edges, "charge": 0})\n        self.assertIsNotNone(rec, reason)\n\n    def test_formula_parser(self):\n        self.assertEqual(parse_formula("C16H17NO4")["C"], 16)\n        self.assertEqual(parse_formula("C16H17NO4")["H"], 17)\n        self.assertEqual(parse_formula("C16H17NO4")["N"], 1)\n\n    def test_formula_crosscheck(self):\n        typed, _ = smiles_to_typed("CCO")\n        rec, reason = standardize_smiles("CCO", "t", "t", parse_formula("C2H6O"))\n        self.assertIsNotNone(rec, reason)\n        rec2, reason2 = standardize_smiles("CCO", "t", "t", parse_formula("C2H6O2"))\n        self.assertIsNone(rec2)\n        self.assertEqual(reason2, "formula_mismatch")\n\n    def test_extract_patterns_roundtrip(self):\n        from tools.ms2_database_retrieval import joint_contains, WorkCounters\n\n        typed, edges = smiles_to_typed("CC(=O)O")\n        single, pair = extract_patterns(typed, edges)\n        self.assertTrue(joint_contains(typed, edges, [single], WorkCounters()))\n        if pair is not None:\n            self.assertTrue(\n                joint_contains(typed, edges, [single, pair], WorkCounters()))\n        import tempfile, os\n\n        doc = \'{"CCO": ["CCO", "COC"], "CCC": ["CCC"]}\'\n        with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False) as fh:\n            fh.write(doc)\n            path = fh.name\n        try:\n            out = list(iter_json_entries(path, 10))\n            self.assertEqual(out[0][0], "CCO")\n            self.assertEqual(out[0][1], ["CCO", "COC"])\n            self.assertEqual(out[1][0], "CCC")\n        finally:\n            os.unlink(path)\n\n    def test_json_scanner_drops_partial(self):\n        import tempfile, os\n\n        doc = \'{"CCO": ["CCO", "COC"], "CCC": ["CC\'\n        with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False) as fh:\n            fh.write(doc)\n            path = fh.name\n        try:\n            out = list(iter_json_entries(path, 10))\n            self.assertEqual(len(out), 1)\n            self.assertEqual(out[0][0], "CCO")\n        finally:\n            os.unlink(path)\n\n    def test_json_scanner_drops_truncated_key(self):\n        # Review regression: a prefix ending mid-key crashed instead of\n        # returning the complete entries before it.\n        import tempfile, os\n\n        doc = \'{"CCO": ["CCO"], "C\'\n        with tempfile.NamedTemporaryFile("w", suffix=".json", delete=False) as fh:\n            fh.write(doc)\n            path = fh.name\n        try:\n            out = list(iter_json_entries(path, 10))\n            self.assertEqual(len(out), 1)\n            self.assertEqual(out[0][0], "CCO")\n        finally:\n            os.unlink(path)\n\n    def test_isotope_bracket_rejected(self):\n        # Review regression: [13C] silently normalized to 12C with the\n        # unlabeled mass. Isotope labels must be rejected, not dropped.\n        rec, reason = standardize_smiles("[13CH4]", "t", "T")\n        self.assertIsNone(rec)\n        self.assertEqual(reason, "unsupported_isotope")\n\n\nif __name__ == "__main__":\n    main(sys.argv[1:])\n', 'tools/ms2_spectral_rank.py': '"""Measured-spectrum nearest-neighbor ranking for MassSpecGym formula pools.\n\nFifth molecular-completion run: the first HONEST measured-spectrum ranking.\nPrior runs left spectral similarity as ``unavailable_no_spectrum``; the TSV\nactually ships a measured spectrum per row, so this module bins those spectra\nand scores supplied formula-pool candidates by cosine similarity against\nTRAIN-fold reference spectra of the same structure identity.\n\nRepresentation (fixed a priori, never tuned on val outcomes):\n  mass bins of width 0.1 m/z over [0, 2000), per-bin max intensity,\n  L2-normalized sparse vectors, cosine similarity. Candidate score = max\n  cosine over that candidate\'s TRAIN reference spectra. No fitting, no\n  threshold calibration: the abstention rule is parameter-free (predict iff\n  at least one pool candidate has a TRAIN reference spectrum).\n\nConnectivity identity: exact provider-canonical SMILES string equality.\nSound (equal strings => same structure) but conservative: stereo or\ntautomer variants written as different strings do not match, so reported\nreference coverage is a LOWER BOUND on true connectivity coverage, not a\ngraph-canonicalization guarantee. RDKit is not installed in this\nenvironment (no new dependencies per task); a crude no-stereo character\ncount is reported as an approximation alongside, never used for ranking,\nand never claimed as a tight connectivity bound. Split disjointness is\naudited by both SMILES string and InChIKey-14 block, and ENFORCED for val:\nnonzero train/query InChIKey-14 overlap aborts the run, and queries with a\nmissing connectivity key are excluded conservatively (counted, never\nscored).\n\nLeakage rules (asserted, unit-tested):\n  * query spectra come from the val fold; references from train only;\n  * any train spectrum whose SMILES equals the query SMILES is excluded\n    and counted (val/train splits are structure-disjoint, so this fires\n    never -- a nonzero count is reported, never scored);\n  * any TRAIN reference spectrum whose parsed peak CONTENT fingerprint\n    matches the query spectrum content is excluded and counted, even under\n    a different identifier (duplicate-content guard); reference spectra are\n    also deduplicated by content within each structure (first wins, both\n    dedup kinds counted);\n  * the query structure is never used as a feature (pools are supplied\n    verbatim; the target is never injected);\n  * the query structure is never used as a feature (pools are supplied\n    verbatim; the target is never injected);\n  * candidate order never leaks self-first supplier order: uniform and all\n    tie-breaking use a per-query seeded shuffle (zlib.crc32 of the qid,\n    same convention as tools/ms2_rank_abstain.py);\n  * candidates without references are NEVER dropped: unreferenced\n    candidates rank after referenced ones (seeded-shuffle order) and stay\n    in every denominator. An empty reference set yields abstention, never\n    a shrunken pool or an improved denominator.\n\nArms (identical formula pools, no oracle subgraphs -- the primary,\nnon-oracle condition):\n  * uniform   : seeded shuffle (weak baseline, order-decontaminated).\n  * spectral  : TRAIN-reference max-cosine rank (this run\'s method).\n  * coverage  : coverage-only baseline on the IDENTICAL pools: seeded\n    shuffle among reference-backed candidates first, then unreferenced\n    ones. Uses no spectral score; isolates what reference PRESENCE alone\n    buys versus the cosine values.\n  * massresid : replacement cheap exact baseline for formula pools (not a\n    head-to-head rerun of the prior learned ranker, whose oracle subgraph\n    features do not exist in this pool condition): rank by\n    |graph-theoretical mass - query parent_mass| using the existing\n    SMILES standardizer; unparseable candidates rank last and are counted.\n\nA small TRAIN-fold positive control (labelled CONTROL, not a val result)\nchecks pipeline mechanics on train spectra as queries against remaining\ntrain references, excluding the query identifier AND the query content\nfingerprint. Control top-k is reported alongside the coverage-only arm and\nreference-count subgroups (pools with exactly one vs multiple\nreference-backed candidates), because most control pools have a single\nreferenced candidate and a bare top-1 rate cannot establish\nrepresentation quality.\n\nCPU stdlib reference. No GPU tensors and no Rust port exist for this\nexperiment, so GPU execution and Rust/Python parity checks are explicitly\nNOT APPLICABLE (recorded, not passed).\n"""\n\nimport csv\nimport hashlib\nimport json\nimport math\nimport os\nimport random\nimport resource\nimport sys\nimport time\nimport unittest\nimport zlib\nfrom collections import Counter\n\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\nfrom tools.ms2_msgym_corpus import (  # noqa: E402\n    iter_json_entries,\n    parse_formula,\n    standardize_smiles,\n)\n\n# --------------------------------------------------------------------------\n# Declared representation (fixed a priori; not selected on val outcomes).\n# --------------------------------------------------------------------------\n\nBIN_WIDTH = 0.1\nMZ_MIN = 0.0\nMZ_MAX = 2000.0\nN_BINS = int((MZ_MAX - MZ_MIN) / BIN_WIDTH)  # 20000\nSHUFFLE_DOMAIN = "qid-crc32"  # same convention as ms2_rank_abstain.py\n\n\n# --------------------------------------------------------------------------\n# Spectrum parsing / binning / cosine.\n# --------------------------------------------------------------------------\n\ndef parse_spectrum(mzs_text, intensities_text):\n    """Parse one TSV spectrum. Returns (peaks, error).\n\n    peaks = [(mz, intensity)] with finite mz >= 0 and finite intensity >= 0.\n    error is None on success, else a short reason string. Empty spectra,\n    length mismatches, non-numeric tokens, NaN/inf and all-zero norms fail;\n    nothing is silently repaired.\n    """\n    if mzs_text is None or intensities_text is None:\n        return None, "missing_field"\n    mzs_text = mzs_text.strip()\n    intensities_text = intensities_text.strip()\n    if not mzs_text or not intensities_text:\n        return None, "empty_spectrum"\n    try:\n        mzs = [float(t) for t in mzs_text.split(",")]\n        ints = [float(t) for t in intensities_text.split(",")]\n    except ValueError:\n        return None, "non_numeric"\n    if len(mzs) != len(ints):\n        return None, "length_mismatch"\n    if not mzs:\n        return None, "empty_spectrum"\n    for mz, it in zip(mzs, ints):\n        if not math.isfinite(mz) or not math.isfinite(it):\n            return None, "non_finite"\n        if mz < 0.0 or it < 0.0:\n            return None, "negative_value"\n    if all(it == 0.0 for it in ints):\n        return None, "zero_norm"\n    return list(zip(mzs, ints)), None\n\n\ndef bin_spectrum(peaks):\n    """Bin peaks to {bin_index: max_intensity}. Returns (vec, n_dropped).\n\n    Peaks outside [MZ_MIN, MZ_MAX) are dropped and counted (never silently\n    ignored: the caller records n_dropped). An all-dropped spectrum yields\n    an empty vector, whose cosine is defined as 0.0 (see cosine()).\n    """\n    vec = {}\n    dropped = 0\n    for mz, it in peaks:\n        if not (MZ_MIN <= mz < MZ_MAX):\n            dropped += 1\n            continue\n        b = int((mz - MZ_MIN) / BIN_WIDTH)\n        if it > vec.get(b, 0.0):\n            vec[b] = it\n    return vec, dropped\n\n\ndef vec_norm(vec):\n    return math.sqrt(sum(v * v for v in vec.values()))\n\n\ndef cosine(a, na, b, nb):\n    """Cosine of sparse vectors with precomputed norms.\n\n    Zero-norm vectors (e.g. fully out-of-range spectra) score 0.0 against\n    everything, including themselves: no division by zero, no NaN scores.\n    """\n    if na <= 0.0 or nb <= 0.0:\n        return 0.0\n    if len(a) > len(b):\n        a, b = b, a\n    dot = sum(v * b.get(k, 0.0) for k, v in a.items())\n    return dot / (na * nb)\n\n\ndef content_fp(peaks):\n    """Canonical fingerprint of parsed peak CONTENT (duplicate guard).\n\n    Rounded (mz, intensity) pairs, sorted. Two spectra with equal\n    fingerprints carry identical measured content regardless of identifier,\n    so a query must never score against a reference with the same\n    fingerprint (self-match through duplication or re-upload).\n    """\n    return tuple(sorted((round(mz, 4), round(it, 6)) for mz, it in peaks))\n\n\ndef strip_stereo(smiles):\n    """Crude character-level grouping for a SENSITIVITY count only.\n\n    Drops @, / and backslash characters. This is an APPROXIMATION, not a\n    connectivity bound in either direction: it can conflate distinct\n    stereoisomers and still miss tautomers or other SMILES variants of one\n    connectivity. Reported only as a rough sensitivity count, never used\n    for ranking, and never claimed as tight.\n    """\n    return smiles.replace("@", "").replace("/", "").replace("\\\\", "")\n\n\n# --------------------------------------------------------------------------\n# TSV / prefix ingestion.\n# --------------------------------------------------------------------------\n\nWANTED_COLUMNS = ("identifier", "mzs", "intensities", "smiles", "inchikey",\n                  "formula", "precursor_formula", "parent_mass", "precursor_mz",\n                  "adduct", "instrument_type", "collision_energy", "fold")\n\n\ndef load_tsv_rows(path):\n    with open(path, "r", encoding="utf-8") as handle:\n        reader = csv.DictReader(handle, delimiter="\\t")\n        missing = [c for c in WANTED_COLUMNS if c not in (reader.fieldnames or [])]\n        if missing:\n            raise ValueError(f"TSV missing columns: {missing}")\n        for row in reader:\n            yield {c: row[c] for c in WANTED_COLUMNS}\n\n\ndef short_key(inchikey):\n    """Connectivity block of an InChIKey (first 14 chars)."""\n    return (inchikey or "")[:14]\n\n\ndef audit_split_disjointness(train_smiles, query_smiles, train_keys, query_keys):\n    """Return overlap sets; callers must publish counts and fail on nonzero.\n\n    Belt-and-braces: the benchmark ships structure-disjoint folds, but the\n    experiment must verify rather than assume.\n    """\n    return (set(query_smiles) & set(train_smiles,\n                                    ), set(query_keys) & set(train_keys))\n\n\ndef collect_train_refs(tsv_path, wanted_smiles, exclude_smiles=()):\n    """Single TSV pass. Returns (refs, info).\n\n    refs: {smiles: [(identifier, vec, norm, n_dropped, adduct, instrument,\n    content_fp)]}. Only spectra whose SMILES is wanted are binned/retained\n    (bounded memory); everything else is counted, not stored.\n    exclude_smiles (the query structures) yield zero retained hits -- any\n    hit is counted as a leak exclusion and never lands in refs.\n    Dedup is by identifier AND by content fingerprint within each\n    structure (first wins in file order); both counts are published.\n    """\n    refs = {}\n    info = Counter()\n    seen_ids = set()\n    seen_content = {}  # smiles -> set of content fingerprints\n    excluded = set(exclude_smiles)\n    for row in load_tsv_rows(tsv_path):\n        if row["fold"] != "train":\n            continue\n        info["n_train_rows_scanned"] += 1\n        smi = row["smiles"]\n        if smi in excluded:\n            info["n_leak_excluded"] += 1\n            continue\n        if smi not in wanted_smiles:\n            continue\n        ident = row["identifier"]\n        if ident in seen_ids:\n            info["n_duplicate_ids"] += 1\n            continue\n        seen_ids.add(ident)\n        peaks, err = parse_spectrum(row["mzs"], row["intensities"])\n        if err is not None:\n            info[f"ref_parse_excl:{err}"] += 1\n            continue\n        fp = content_fp(peaks)\n        bucket = seen_content.setdefault(smi, set())\n        if fp in bucket:\n            info["n_duplicate_content"] += 1\n            continue\n        bucket.add(fp)\n        vec, dropped = bin_spectrum(peaks)\n        norm = vec_norm(vec)\n        refs.setdefault(smi, []).append(\n            (ident, vec, norm, dropped, row["adduct"], row["instrument_type"],\n             fp))\n        info["n_ref_spectra_retained"] += 1\n        info["n_ref_dropped_peaks"] += dropped\n    info["n_ref_structures"] = len(refs)\n    return refs, info\n\n\ndef exclude_query_content(refs, query_fp):\n    """Drop refs whose content fingerprint equals the query\'s. Returns\n    (filtered_refs, n_excluded_refs, n_excluded_structures).\n\n    Guards against same-content/different-identifier leakage (duplicated or\n    re-uploaded spectra across folds and identifiers).\n    """\n    filtered = {}\n    n_refs, n_struct = 0, 0\n    for smi, lst in refs.items():\n        kept = [t for t in lst if t[6] != query_fp]\n        dropped = len(lst) - len(kept)\n        if dropped:\n            n_refs += dropped\n            n_struct += 1\n        if kept:\n            filtered[smi] = kept\n    return filtered, n_refs, n_struct\n\n\ndef parse_query_spectrum(row):\n    """Parse the single query spectrum of a val/train row. Returns dict."""\n    peaks, err = parse_spectrum(row["mzs"], row["intensities"])\n    if err is not None:\n        return {"ok": False, "error": err}\n    vec, dropped = bin_spectrum(peaks)\n    return {"ok": True, "vec": vec, "norm": vec_norm(vec),\n            "fp": content_fp(peaks),\n            "n_peaks": len(peaks), "n_dropped": dropped}\n\n\n# --------------------------------------------------------------------------\n# Ranking.\n# --------------------------------------------------------------------------\n\ndef seeded_positions(qid, n):\n    positions = list(range(n))\n    random.Random(zlib.crc32(qid.encode())).shuffle(positions)\n    return {idx: p for p, idx in enumerate(positions)}\n\n\ndef score_candidates(query_vec, query_norm, pool, refs):\n    """Score each distinct pool candidate. Returns list of dicts.\n\n    The pool is used verbatim (deduplicated to distinct strings, first\n    occurrence wins; counts recorded by the caller). score is None when the\n    candidate has no TRAIN reference spectrum -- recorded, never dropped.\n    """\n    out = []\n    for idx, smi in enumerate(pool):\n        cand_refs = refs.get(smi, [])\n        if not cand_refs:\n            out.append({"idx": idx, "smiles": smi, "score": None,\n                        "n_refs": 0, "best_ref": None})\n            continue\n        best, best_id = -1.0, None\n        for ident, vec, norm, _, _, _, _ in cand_refs:\n            s = cosine(query_vec, query_norm, vec, norm)\n            if s > best:\n                best, best_id = s, ident\n        out.append({"idx": idx, "smiles": smi, "score": best,\n                    "n_refs": len(cand_refs), "best_ref": best_id})\n    return out\n\n\ndef rank_uniform(scored, pos_of):\n    return sorted(range(len(scored)), key=lambda i: pos_of[i])\n\n\ndef rank_spectral(scored, pos_of):\n    # Referenced candidates first by score desc; unreferenced trail in\n    # seeded-shuffle order (retained in the ranking, never removed).\n    return sorted(range(len(scored)),\n                  key=lambda i: ((0.0, -scored[i]["score"])\n                                 if scored[i]["score"] is not None\n                                 else (1.0, 0.0),\n                                 pos_of[i]))\n\n\ndef rank_coverage(scored, pos_of):\n    """Coverage-only baseline: reference-backed candidates first in seeded\n    shuffle order, then unreferenced ones. Uses n_refs only -- no spectral\n    score -- so spectral-vs-coverage comparisons isolate what the cosine\n    VALUES add over reference PRESENCE alone."""\n    return sorted(range(len(scored)),\n                  key=lambda i: (0 if scored[i]["n_refs"] > 0 else 1,\n                                 pos_of[i]))\n\n\ndef rank_massresid(scored, residuals, pos_of):\n    # residuals[i] is ppm or None (unparseable -> last, counted).\n    return sorted(range(len(scored)),\n                  key=lambda i: ((0.0, residuals[i])\n                                 if residuals[i] is not None\n                                 else (1.0, 0.0),\n                                 pos_of[i]))\n\n\ndef candidate_residuals(pool, parent_mass_text):\n    """Cheap exact baseline features: |theory - observed| ppm per candidate.\n\n    Uses the existing SMILES standardizer for theoretical mass. Returns\n    (residuals, n_unparseable). observed = provider parent_mass (a MEASURED\n    m/z-derived value, used as given query evidence, never converted).\n    """\n    from decimal import Decimal\n    try:\n        observed_mu = int(Decimal(parent_mass_text) * 1_000_000)\n    except Exception:\n        return [None] * len(pool), len(pool)\n    residuals = []\n    n_bad = 0\n    for smi in pool:\n        try:\n            rec, reason = standardize_smiles(smi, "spectral-pool", smi)\n        except Exception:\n            rec, reason = None, "exception"\n        if rec is None:\n            residuals.append(None)\n            n_bad += 1\n        else:\n            ppm = abs(rec["mass"] - observed_mu) / max(observed_mu, 1) * 1e6\n            residuals.append(ppm)\n    return residuals, n_bad\n\n\nARMS = ("uniform", "spectral", "coverage", "massresid")\n\n\ndef evaluate_query(qid, scored, pos_of, residuals, target_smiles):\n    """Ranks and hits for one query on identical pools. Target-absent safe."""\n    order_u = rank_uniform(scored, pos_of)\n    order_s = rank_spectral(scored, pos_of)\n    order_c = rank_coverage(scored, pos_of)\n    order_m = rank_massresid(scored, residuals, pos_of)\n    n = len(scored)\n    tgt = [i for i, s in enumerate(scored) if s["smiles"] == target_smiles]\n    in_pool = bool(tgt)\n    tgt_idx = tgt[0] if tgt else None\n    n_ref = sum(1 for s in scored if s["n_refs"] > 0)\n    tgt_ref = (scored[tgt_idx]["n_refs"] > 0) if tgt else False\n\n    def rank_of(order):\n        if tgt_idx is None:\n            return None\n        return order.index(tgt_idx) + 1  # 1-based\n\n    ranks = {"uniform": rank_of(order_u), "spectral": rank_of(order_s),\n             "coverage": rank_of(order_c), "massresid": rank_of(order_m)}\n\n    def hits(rank):\n        if rank is None:\n            return {1: None, 3: None, 10: None}\n        return {1: rank <= 1, 3: rank <= min(3, n), 10: rank <= min(10, n)}\n\n    return {"in_pool": in_pool, "n_pool": n, "n_ref": n_ref,\n            "target_has_ref": tgt_ref if in_pool else None,\n            "predicted": n_ref > 0,\n            "ranks": ranks,\n            "hits": {arm: hits(r) for arm, r in ranks.items()}}\n\n\n# --------------------------------------------------------------------------\n# Experiment driver.\n# --------------------------------------------------------------------------\n\ndef sha256_file(path, chunk=1 << 20):\n    h = hashlib.sha256()\n    with open(path, "rb") as handle:\n        while True:\n            blk = handle.read(chunk)\n            if not blk:\n                break\n            h.update(blk)\n    return h.hexdigest()\n\n\ndef summarize(rows, label):\n    """Top-k fractions with explicit denominators.\n\n    * "all" covers ALL selected queries, including spectrum-excluded rows:\n      top-k denominators count only rankable rows per arm (a row excluded\n      before ranking contributes None, never a silent miss), while\n      abstention coverage uses every selected query\n      (predicted / n_selected).\n    * "eligible_*" subsets cover complete rows only (ranking-eligible).\n    * "refcount_1" / "refcount_multi" split eligible_anyref rows by pool\n      reference count (exactly one vs multiple reference-backed\n      candidates), so cosine-vs-coverage-only can be compared where the\n      coverage baseline is non-degenerate.\n    """\n    out = {"label": label, "n_selected": len(rows),\n           "n_complete": sum(1 for r in rows\n                             if r.get("status") == "complete"),\n           "status_counts": dict(Counter(r.get("status", "unknown")\n                                         for r in rows)),\n           "pool_recall_all": (sum(1 for r in rows if r.get("in_pool"))\n                               / len(rows) if rows else None)}\n    subsets = (("all", lambda r: True),\n               ("eligible_anyref",\n                lambda r: r.get("status") == "complete" and r["in_pool"]\n                and r["n_ref"] > 0),\n               ("eligible_targetref",\n                lambda r: r.get("status") == "complete" and r["in_pool"]\n                and r["target_has_ref"]),\n               ("refcount_1",\n                lambda r: r.get("status") == "complete" and r["in_pool"]\n                and r["n_ref"] == 1),\n               ("refcount_multi",\n                lambda r: r.get("status") == "complete" and r["in_pool"]\n                and r["n_ref"] > 1))\n    for name, sel in subsets:\n        sub = [r for r in rows if sel(r)]\n        m = {"n": len(sub)}\n        for arm in ARMS:\n            for k in (1, 3, 10):\n                vals = [r["hits"][arm][k] for r in sub\n                        if r["hits"].get(arm, {}).get(k) is not None]\n                m[f"{arm}@top{k}"] = (sum(vals) / len(vals)\n                                      if vals else None)\n                m[f"{arm}@top{k}_den"] = len(vals)\n        # Abstention (spectral arm): predict iff a complete row has >=1\n        # referenced candidate. The coverage denominator is ALL selected\n        # queries (parameter-free rule; excluded spectra count as\n        # abstentions, never as predictions).\n        pred = [r for r in sub if r.get("predicted")]\n        good = [r for r in pred if r["hits"].get("spectral", {}).get(1)]\n        m["predicted"] = len(pred)\n        m["coverage"] = len(pred) / len(rows) if rows else 0.0\n        m["abstention_precision"] = (len(good) / len(pred)\n                                     if pred else None)\n        out[name] = m\n    return out\n\n\ndef empty_hits():\n    return {arm: {1: None, 3: None, 10: None} for arm in ARMS}\n\n\ndef empty_ranks():\n    return {arm: None for arm in ARMS}\n\n\ndef full_row(qid, smiles, row, supplied, distinct, status):\n    """One row with the CONSISTENT schema every CSV row carries.\n\n    Spectrum-independent fields are filled for every status; ranking\n    fields stay None until computed. Uniform CSV columns are guaranteed\n    (the writer also unions fields as belt-and-braces).\n    """\n    return {\n        "qid": qid, "smiles": smiles,\n        "adduct": row.get("adduct", ""),\n        "instrument": row.get("instrument_type") or "missing",\n        "collision_energy": row.get("collision_energy", ""),\n        "status": status,\n        "n_supplied": len(supplied),\n        "n_pool": len(distinct),\n        "in_pool": (smiles in distinct),\n        "n_ref": None,\n        "target_has_ref": None,\n        "predicted": False,\n        "n_unparseable_mass": None,\n        "n_query_dropped_peaks": None,\n        "n_content_excluded_refs": None,\n        "n_content_excluded_structures": None,\n        "rank_uniform": None,\n        "rank_spectral": None,\n        "rank_coverage": None,\n        "rank_massresid": None,\n        "hits": empty_hits(),\n    }\n\n\ndef fill_spectrum_free_ranks(out, distinct, target_smiles, parent_mass):\n    """Uniform + massresid ranks need no spectrum; computable for excluded\n    queries too (documented; spectral/coverage stay None without scores)."""\n    pos_of = seeded_positions(out["qid"], len(distinct))\n    residuals, n_bad = candidate_residuals(distinct, parent_mass)\n    order_u = rank_uniform(\n        [{"idx": i} for i in range(len(distinct))], pos_of)\n    order_m = rank_massresid(\n        [{"idx": i} for i in range(len(distinct))], residuals, pos_of)\n    tgt = distinct.index(target_smiles) if target_smiles in distinct else None\n    if tgt is not None:\n        out["rank_uniform"] = order_u.index(tgt) + 1\n        out["rank_massresid"] = order_m.index(tgt) + 1\n        n = len(distinct)\n        for arm, rank in (("uniform", out["rank_uniform"]),\n                          ("massresid", out["rank_massresid"])):\n            out["hits"][arm] = {1: rank <= 1, 3: rank <= min(3, n),\n                                10: rank <= min(10, n)}\n    out["n_unparseable_mass"] = n_bad\n    return out\n\n\ndef run_val_experiment(tsv_path, prefix_path, max_queries):\n    """Val-side run with ENFORCED train/query disjointness.\n\n    Conservative connectivity policy: queries with a missing SMILES or\n    missing InChIKey-14 block are excluded before scoring\n    (status query_excl:missing_connectivity_key, counted); any nonzero\n    SMILES or InChIKey-14 overlap between kept queries and train aborts\n    the run (fail safe, never score through a leak).\n    """\n    # Val groups: first row per SMILES in file order (stable selection).\n    val_groups, train_smiles, train_keys = {}, set(), set()\n    val_bias = Counter()\n    n_rows = 0\n    n_train_missing_key = 0\n    for row in load_tsv_rows(tsv_path):\n        n_rows += 1\n        if row["fold"] == "train":\n            train_smiles.add(row["smiles"])\n            if row["inchikey"]:\n                train_keys.add(short_key(row["inchikey"]))\n            else:\n                n_train_missing_key += 1\n        elif row["fold"] == "val":\n            val_bias[f"adduct:{row[\'adduct\']}"] += 1\n            val_bias[f"inst:{row[\'instrument_type\'] or \'missing\'}"] += 1\n            if row["smiles"] not in val_groups:\n                val_groups[row["smiles"]] = row\n    entries = [(q, c) for q, c in\n               iter_json_entries(prefix_path, max_queries * 40)]\n    joined = [(q, c) for q, c in entries if q in val_groups][:max_queries]\n    if not joined:\n        raise ValueError("no prefix entries join to val rows")\n\n    # Distinct pools; split off queries lacking a connectivity identity.\n    pools, early_excluded = {}, []\n    for qi, (q, cands) in enumerate(joined):\n        qid = f"VAL-{qi:04d}"\n        seen, distinct = set(), []\n        for s in cands:\n            if s not in seen:\n                seen.add(s)\n                distinct.append(s)\n        rec = {"smiles": q, "supplied": list(cands),\n               "distinct": distinct, "row": val_groups[q]}\n        if not q or not val_groups[q]["inchikey"]:\n            out = full_row(qid, q, val_groups[q], rec["supplied"],\n                           distinct, "query_excl:missing_connectivity_key")\n            early_excluded.append(out)\n        else:\n            pools[qid] = rec\n\n    query_smiles = [v["smiles"] for v in pools.values()]\n    query_keys = {short_key(v["row"]["inchikey"]) for v in pools.values()}\n    ov_smi, ov_key = audit_split_disjointness(train_smiles, query_smiles,\n                                              train_keys, query_keys)\n    if ov_smi or ov_key:\n        raise ValueError(\n            f"train/query connectivity overlap: {len(ov_smi)} SMILES, "\n            f"{len(ov_key)} InChIKey-14 (fail safe, refusing to score)")\n\n    wanted = set()\n    for v in pools.values():\n        wanted.update(v["distinct"])\n    refs, ref_info = collect_train_refs(tsv_path, wanted,\n                                        exclude_smiles=set(query_smiles))\n    ref_info["n_train_missing_key"] = n_train_missing_key\n    ref_info["n_queries_missing_key"] = len(early_excluded)\n\n    rows = list(early_excluded)\n    sel_bias = Counter()\n    for qid, v in pools.items():\n        row = v["row"]\n        sel_bias[f"adduct:{row[\'adduct\']}"] += 1\n        sel_bias[f"inst:{row[\'instrument_type\'] or \'missing\'}"] += 1\n        out = full_row(qid, v["smiles"], row, v["supplied"], v["distinct"],\n                       "complete")\n        out = fill_spectrum_free_ranks(out, v["distinct"], v["smiles"],\n                                       row["parent_mass"])\n        qs = parse_query_spectrum(row)\n        if not qs["ok"]:\n            out["status"] = f"query_parse_excl:{qs[\'error\']}"\n            out["predicted"] = False  # abstention; in coverage denominator\n            out["n_ref"] = sum(1 for s in v["distinct"] if refs.get(s))\n            out["target_has_ref"] = bool(refs.get(v["smiles"]))\n            rows.append(out)\n            continue\n        refs_q, n_cx_r, n_cx_s = exclude_query_content(refs, qs["fp"])\n        out["n_content_excluded_refs"] = n_cx_r\n        out["n_content_excluded_structures"] = n_cx_s\n        ref_info["n_query_content_excluded_refs"] = (\n            ref_info.get("n_query_content_excluded_refs", 0) + n_cx_r)\n        scored = score_candidates(qs["vec"], qs["norm"], v["distinct"],\n                                  refs_q)\n        pos_of = seeded_positions(qid, len(scored))\n        residuals, n_bad = candidate_residuals(v["distinct"],\n                                               row["parent_mass"])\n        ev = evaluate_query(qid, scored, pos_of, residuals, v["smiles"])\n        out["n_ref"] = ev["n_ref"]\n        out["target_has_ref"] = ev["target_has_ref"]\n        out["predicted"] = ev["predicted"]\n        out["n_unparseable_mass"] = n_bad\n        out["n_query_dropped_peaks"] = qs["n_dropped"]\n        out["rank_uniform"] = ev["ranks"]["uniform"]\n        out["rank_spectral"] = ev["ranks"]["spectral"]\n        out["rank_coverage"] = ev["ranks"]["coverage"]\n        out["rank_massresid"] = ev["ranks"]["massresid"]\n        out["hits"] = ev["hits"]\n        rows.append(out)\n    # Reference-coverage detail over the SELECTED sample only (persisted\n    # here; no mixing with other sample sizes). Exact-string occurrence\n    # counts plus the crude no-stereo character approximation (rough\n    # sensitivity count, NOT a tight connectivity bound).\n    train_nostereo = set()\n    for row in load_tsv_rows(tsv_path):\n        if row["fold"] == "train":\n            train_nostereo.add(strip_stereo(row["smiles"]))\n    pool_occ, exact_cov, approx_extra = 0, 0, 0\n    for v in pools.values():\n        for s in v["distinct"]:\n            pool_occ += 1\n            if s in refs:\n                exact_cov += 1\n            elif strip_stereo(s) in train_nostereo:\n                approx_extra += 1\n    metrics = summarize(rows, "val_formula_pool")\n    return {"rows": rows, "metrics": metrics, "ref_info": dict(ref_info),\n            "n_tsv_rows": n_rows, "n_val_structures": len(val_groups),\n            "n_train_structures": len(train_smiles),\n            "n_entries_scanned": len(entries), "n_joined": len(joined),\n            "overlap_smiles": sorted(ov_smi), "overlap_keys": sorted(ov_key),\n            "overlap_enforced": True,\n            "val_bias": dict(val_bias), "selected_bias": dict(sel_bias),\n            "coverage_detail": {\n                "pool_distinct_occurrences": pool_occ,\n                "exact_covered_occurrences": exact_cov,\n                "nostereo_approx_extra": approx_extra,\n                "nostereo_approx_note": "character-level approximation, "\n                                        "not a connectivity bound",\n                "n_train_nostereo_keys": len(train_nostereo)}}\n\n\ndef run_control_experiment(tsv_path, prefix_path, max_queries):\n    """TRAIN-fold positive control (labelled CONTROL).\n\n    Train spectra as queries against remaining train references, excluding\n    the query identifier AND the query content fingerprint (no self-match\n    through duplication or re-upload). Not a val result. Control top-k is\n    reported next to the coverage-only arm and reference-count subgroups,\n    because most control pools hold a single referenced candidate and a\n    bare top-1 rate cannot establish representation quality.\n    """\n    train_groups = {}\n    for row in load_tsv_rows(tsv_path):\n        if row["fold"] == "train" and row["smiles"] not in train_groups:\n            train_groups[row["smiles"]] = row\n    entries = [(q, c) for q, c in\n               iter_json_entries(prefix_path, max_queries * 40)]\n    joined = [(q, c) for q, c in entries if q in train_groups][:max_queries]\n    if not joined:\n        raise ValueError("no prefix entries join to train rows")\n    pools = {}\n    for qi, (q, cands) in enumerate(joined):\n        qid = f"CTL-{qi:04d}"\n        seen, distinct = set(), []\n        for s in cands:\n            if s not in seen:\n                seen.add(s)\n                distinct.append(s)\n        pools[qid] = {"smiles": q, "supplied": list(cands),\n                      "distinct": distinct, "row": train_groups[q]}\n    wanted = set()\n    for v in pools.values():\n        wanted.update(v["distinct"])\n    # Refs: all wanted train spectra; the query identifier AND the query\n    # content fingerprint are excluded per query at scoring time.\n    all_refs, ref_info = collect_train_refs(tsv_path, wanted,\n                                            exclude_smiles=())\n    rows = []\n    for qid, v in pools.items():\n        row = v["row"]\n        out = full_row(qid, v["smiles"], row, v["supplied"], v["distinct"],\n                       "complete")\n        out = fill_spectrum_free_ranks(out, v["distinct"], v["smiles"],\n                                       row["parent_mass"])\n        qs = parse_query_spectrum(row)\n        if not qs["ok"]:\n            out["status"] = f"query_parse_excl:{qs[\'error\']}"\n            out["predicted"] = False\n            out["n_ref"] = sum(1 for s in v["distinct"] if all_refs.get(s))\n            out["target_has_ref"] = bool(all_refs.get(v["smiles"]))\n            rows.append(out)\n            continue\n        refs = {}\n        n_cx_r, n_cx_s = 0, 0\n        for smi, lst in all_refs.items():\n            kept = [t for t in lst\n                    if t[0] != row["identifier"] and t[6] != qs["fp"]]\n            dropped = len(lst) - len(kept)\n            if dropped:\n                n_cx_r += dropped\n                n_cx_s += 1\n            if kept:\n                refs[smi] = kept\n        out["n_content_excluded_refs"] = n_cx_r\n        out["n_content_excluded_structures"] = n_cx_s\n        ref_info["n_control_content_excluded_refs"] = (\n            ref_info.get("n_control_content_excluded_refs", 0) + n_cx_r)\n        scored = score_candidates(qs["vec"], qs["norm"], v["distinct"], refs)\n        pos_of = seeded_positions(qid, len(scored))\n        residuals, n_bad = candidate_residuals(v["distinct"],\n                                               row["parent_mass"])\n        ev = evaluate_query(qid, scored, pos_of, residuals, v["smiles"])\n        out["n_ref"] = ev["n_ref"]\n        out["target_has_ref"] = ev["target_has_ref"]\n        out["predicted"] = ev["predicted"]\n        out["n_unparseable_mass"] = n_bad\n        out["n_query_dropped_peaks"] = qs["n_dropped"]\n        out["rank_uniform"] = ev["ranks"]["uniform"]\n        out["rank_spectral"] = ev["ranks"]["spectral"]\n        out["rank_coverage"] = ev["ranks"]["coverage"]\n        out["rank_massresid"] = ev["ranks"]["massresid"]\n        out["hits"] = ev["hits"]\n        rows.append(out)\n    metrics = summarize(rows, "train_control")\n    return {"rows": rows, "metrics": metrics, "ref_info": dict(ref_info),\n            "n_joined": len(joined)}\n\n\ndef main(argv):\n    import argparse\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--tsv", default="data/pinned/MassSpecGym1.5.tsv")\n    ap.add_argument("--prefix",\n                    default="data/pinned/msgym_candidates_formula_prefix64.json")\n    ap.add_argument("--max-queries", type=int, default=200)\n    ap.add_argument("--max-control", type=int, default=50)\n    ap.add_argument("--out-dir",\n                    default="experiments/molecular_completion/20261003_spectral")\n    args = ap.parse_args(argv)\n    t0 = time.perf_counter()\n    c0 = time.process_time()\n    val = run_val_experiment(args.tsv, args.prefix, args.max_queries)\n    ctl = run_control_experiment(args.tsv, args.prefix, args.max_control)\n    # Hashing and row-output writes happen INSIDE the timed scope, so the\n    # reported wall/CPU/RAM covers the whole run (only the few-ms summary\n    # JSON write itself falls outside; documented in cost.note).\n    pins = {"tsv": args.tsv, "prefix": args.prefix,\n            "tsv_sha256": sha256_file(args.tsv),\n            "prefix_sha256": sha256_file(args.prefix),\n            "tsv_bytes": os.path.getsize(args.tsv),\n            "prefix_bytes": os.path.getsize(args.prefix)}\n    os.makedirs(args.out_dir, exist_ok=True)\n    rows_path = os.path.join(args.out_dir, "spectral_rows.csv")\n    ctl_path = os.path.join(args.out_dir, "spectral_control_rows.csv")\n    sum_path = os.path.join(args.out_dir, "spectral_summary.json")\n\n    def flatten(rows):\n        flat = []\n        for r in rows:\n            f = dict(r)\n            h = f.pop("hits", {})\n            for arm in ARMS:\n                for k in (1, 3, 10):\n                    v = (h.get(arm, {}).get(k) if h else None)\n                    f[f"hit_{arm}_top{k}"] = v\n            flat.append(f)\n        return flat\n\n    flat_val, flat_ctl = flatten(val["rows"]), flatten(ctl["rows"])\n    for path, flat in ((rows_path, flat_val), (ctl_path, flat_ctl)):\n        # Union of fields across rows: mixed complete/exclusion schemas can\n        # never crash the writer, and every row keeps the same columns.\n        cols = sorted({c for f in flat for c in f})\n        with open(path, "w", encoding="utf-8", newline="") as handle:\n            writer = csv.DictWriter(handle, fieldnames=cols)\n            writer.writeheader()\n            for f in flat:\n                writer.writerow({c: f.get(c) for c in cols})\n    wall = time.perf_counter() - t0\n    cpu = time.process_time() - c0\n    peak_kb = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss\n    summary = {\n        "representation": {"bin_width": BIN_WIDTH, "mz_min": MZ_MIN,\n                           "mz_max": MZ_MAX, "n_bins": N_BINS,\n                           "aggregation": "per-bin max intensity",\n                           "similarity": "cosine on L2-normalized sparse "\n                                         "vectors, max over refs",\n                           "identity": "exact SMILES string (conservative "\n                                       "lower-bound coverage, not graph "\n                                       "canonicalization; no RDKit)",\n                           "shuffle": SHUFFLE_DOMAIN,\n                           "selection": "file-order prefix entries joining "\n                                        "fold rows; first row per SMILES",\n                           "fixed_a_priori": True,\n                           "train_calibration": "not applicable "\n                                                "(parameter-free abstention; "\n                                                "no thresholds fit)"},\n        "pins": pins,\n        "provenance": {"downloads_bytes": 0, "api_calls": 0,\n                       "test_fold": "streamed-but-unused: test-fold rows "\n                                    "pass through the shared TSV scanner "\n                                    "and are never used for fitting, "\n                                    "scoring, or selection"},\n        "params": {"max_queries": args.max_queries,\n                   "max_control": args.max_control},\n        "val": {k: v for k, v in val.items() if k != "rows"},\n        "control": {k: v for k, v in ctl.items() if k != "rows"},\n        "cost": {"wall_s": wall, "cpu_s": cpu,\n                 "peak_rss_kb": peak_kb,\n                 "note": "single-threaded CPU; stdlib only; timer covers "\n                         "experiment + sha256 verification + row CSV "\n                         "writes; only the summary-JSON write itself "\n                         "(ms-scale) falls outside"},\n        "outputs": {"rows": rows_path, "control_rows": ctl_path,\n                    "summary": sum_path,\n                    "rows_bytes": os.path.getsize(rows_path),\n                    "control_bytes": os.path.getsize(ctl_path),\n                    "summary_bytes_note": "stdout only: a file cannot "\n                                          "persist its own final size "\n                                          "before writing it"},\n    }\n    with open(sum_path, "w", encoding="utf-8") as handle:\n        json.dump(summary, handle, indent=2, default=str)\n        handle.write("\\n")\n    summary["outputs"]["summary_bytes"] = os.path.getsize(sum_path)\n    sys.stdout.write(json.dumps(summary, indent=2, default=str) + "\\n")\n\n\n# --------------------------------------------------------------------------\n# Tests.\n# --------------------------------------------------------------------------\n\nclass SpectrumParseTests(unittest.TestCase):\n    def test_valid(self):\n        peaks, err = parse_spectrum("100.0,200.5", "0.5,1.0")\n        self.assertIsNone(err)\n        self.assertEqual(peaks, [(100.0, 0.5), (200.5, 1.0)])\n\n    def test_empty(self):\n        for a, b in (("", ""), ("  ", "0.5"), ("100.0", ""),\n                     (None, "0.5"), ("100.0", None)):\n            _, err = parse_spectrum(a, b)\n            self.assertIsNotNone(err, (a, b))\n\n    def test_length_mismatch(self):\n        _, err = parse_spectrum("100.0,200.0", "0.5")\n        self.assertEqual(err, "length_mismatch")\n\n    def test_non_numeric(self):\n        _, err = parse_spectrum("100.0,abc", "0.5,1.0")\n        self.assertEqual(err, "non_numeric")\n\n    def test_non_finite(self):\n        _, err = parse_spectrum("100.0,nan", "0.5,1.0")\n        self.assertEqual(err, "non_finite")\n        _, err = parse_spectrum("100.0,inf", "0.5,1.0")\n        self.assertEqual(err, "non_finite")\n\n    def test_negative(self):\n        _, err = parse_spectrum("-5.0,100.0", "0.5,1.0")\n        self.assertEqual(err, "negative_value")\n        _, err = parse_spectrum("100.0,200.0", "0.5,-1.0")\n        self.assertEqual(err, "negative_value")\n\n    def test_zero_norm(self):\n        _, err = parse_spectrum("100.0,200.0", "0.0,0.0")\n        self.assertEqual(err, "zero_norm")\n\n\nclass BinCosineTests(unittest.TestCase):\n    def test_bin_edges(self):\n        vec, dropped = bin_spectrum([(0.0, 0.5), (0.05, 0.7), (1999.99, 1.0),\n                                     (2000.0, 1.0), (2500.0, 1.0)])\n        self.assertEqual(dropped, 2)  # upper edge + out of range\n        self.assertEqual(vec[0], 0.7)  # max aggregation within a bin\n        self.assertEqual(vec[N_BINS - 1], 1.0)\n\n    def test_identical_is_one(self):\n        vec, _ = bin_spectrum([(100.0, 0.5), (200.0, 1.0)])\n        n = vec_norm(vec)\n        self.assertAlmostEqual(cosine(vec, n, vec, n), 1.0)\n\n    def test_orthogonal_is_zero(self):\n        a, _ = bin_spectrum([(100.0, 1.0)])\n        b, _ = bin_spectrum([(300.0, 1.0)])\n        self.assertEqual(cosine(a, vec_norm(a), b, vec_norm(b)), 0.0)\n\n    def test_scale_invariant(self):\n        a, _ = bin_spectrum([(100.0, 0.5)])\n        b, _ = bin_spectrum([(100.0, 2.0)])\n        self.assertAlmostEqual(cosine(a, vec_norm(a), b, vec_norm(b)), 1.0)\n\n    def test_zero_vector_scores_zero(self):\n        a, dropped = bin_spectrum([(9999.0, 1.0)])\n        self.assertEqual(a, {})\n        self.assertEqual(dropped, 1)\n        b, _ = bin_spectrum([(100.0, 1.0)])\n        self.assertEqual(cosine(a, 0.0, b, vec_norm(b)), 0.0)\n        self.assertEqual(cosine(a, 0.0, a, 0.0), 0.0)\n\n    def test_partial_overlap_bounded(self):\n        a, _ = bin_spectrum([(100.0, 1.0), (200.0, 1.0)])\n        b, _ = bin_spectrum([(100.0, 1.0), (300.0, 1.0)])\n        s = cosine(a, vec_norm(a), b, vec_norm(b))\n        self.assertAlmostEqual(s, 0.5)\n\n\nclass RankBehaviorTests(unittest.TestCase):\n    def _scored(self):\n        return [\n            {"idx": 0, "smiles": "A", "score": 0.9, "n_refs": 2,\n             "best_ref": "r1"},\n            {"idx": 1, "smiles": "B", "score": 0.2, "n_refs": 1,\n             "best_ref": "r2"},\n            {"idx": 2, "smiles": "C", "score": None, "n_refs": 0,\n             "best_ref": None},\n            {"idx": 3, "smiles": "D", "score": None, "n_refs": 0,\n             "best_ref": None},\n        ]\n\n    def test_max_aggregation_picks_best_ref(self):\n        q = {10: 1.0}\n        refs = {"X": [("r1", {10: 0.1, 20: 1.0}, math.sqrt(1.01), 0, "", "",\n                      ()),\n                      ("r2", {10: 1.0}, 1.0, 0, "", "", ())]}\n        out = score_candidates(q, 1.0, ["X"], refs)\n        self.assertEqual(out[0]["n_refs"], 2)\n        self.assertAlmostEqual(out[0]["score"], 1.0)\n        self.assertEqual(out[0]["best_ref"], "r2")\n\n    def test_missing_refs_rank_last_but_retained(self):\n        scored = self._scored()\n        pos = seeded_positions("Q", len(scored))\n        order = rank_spectral(scored, pos)\n        self.assertEqual([scored[i]["smiles"] for i in order[:2]], ["A", "B"])\n        # Unreferenced candidates stay in the ranking (never dropped).\n        self.assertEqual(len(order), 4)\n        self.assertEqual(set(order), {0, 1, 2, 3})\n        tail = [scored[i]["smiles"] for i in order[2:]]\n        self.assertEqual(sorted(tail), ["C", "D"])\n\n    def test_ties_break_by_seeded_position(self):\n        scored = [\n            {"idx": 0, "smiles": "A", "score": 0.5, "n_refs": 1,\n             "best_ref": "r"},\n            {"idx": 1, "smiles": "B", "score": 0.5, "n_refs": 1,\n             "best_ref": "r"},\n        ]\n        o1 = rank_spectral(scored, seeded_positions("Q1", 2))\n        o2 = rank_spectral(scored, seeded_positions("Q1", 2))\n        self.assertEqual(o1, o2)  # deterministic per qid\n        # Order follows shuffled position, never ambient index order alone:\n        pos = seeded_positions("Q1", 2)\n        expect_first = 0 if pos[0] < pos[1] else 1\n        self.assertEqual(o1[0], expect_first)\n\n    def test_absent_target_ranks_none(self):\n        scored = self._scored()\n        pos = seeded_positions("Q", len(scored))\n        ev = evaluate_query("Q", scored, pos, [1.0, 2.0, 3.0, 4.0], "ZZZ")\n        self.assertFalse(ev["in_pool"])\n        self.assertIsNone(ev["ranks"]["spectral"])\n        self.assertIsNone(ev["hits"]["spectral"][1])\n        self.assertIsNone(ev["hits"]["uniform"][10])\n\n    def test_uniform_uses_shuffle_not_ambient(self):\n        scored = self._scored()\n        o = rank_uniform(scored, seeded_positions("Q7", len(scored)))\n        self.assertEqual(sorted(o), [0, 1, 2, 3])\n        # Seeded shuffle of 4 is overwhelmingly likely non-identity; the\n        # robust assertion is determinism + position-dependence instead:\n        self.assertEqual(o, rank_uniform(scored, seeded_positions("Q7", 4)))\n\n    def test_identity_is_exact_string(self):\n        # Stereo variants are DIFFERENT identities (conservative lower\n        # bound on coverage): \'C[C@H](N)O\' != \'C[C@@H](N)O\'.\n        self.assertNotEqual("C[C@H](N)O", "C[C@@H](N)O")\n        self.assertEqual(strip_stereo("C[C@H](N)O"),\n                         strip_stereo("C[C@@H](N)O"))\n\n    def test_massresid_unparseable_last(self):\n        scored = self._scored()\n        pos = seeded_positions("Q", len(scored))\n        order = rank_massresid(scored, [5.0, None, 0.1, None], pos)\n        self.assertEqual(scored[order[0]]["smiles"], "C")  # 0.1 ppm first\n        self.assertEqual(scored[order[1]]["smiles"], "A")  # 5.0 ppm next\n        # Unparseable (None) trail, retained.\n        self.assertEqual(len(order), 4)\n\n\nclass LeakageTests(unittest.TestCase):\n    def test_overlap_audit_detects(self):\n        ov_smi, ov_key = audit_split_disjointness(\n            {"A", "B"}, ["B", "C"], {"k1", "k2"}, {"k2", "k3"})\n        self.assertEqual(ov_smi, {"B"})\n        self.assertEqual(ov_key, {"k2"})\n\n    def test_no_oracle_query_features(self):\n        # score_candidates must not read target/is_target style fields.\n        import inspect\n        src = inspect.getsource(score_candidates)\n        self.assertNotIn("is_target", src)\n        self.assertNotIn("target_smiles", src)\n\n    def test_excluded_queries_never_scored(self):\n        # File-backed: a train row whose SMILES is in exclude_smiles is\n        # counted as a leak exclusion and never lands in refs.\n        import tempfile\n        header = "\\t".join(WANTED_COLUMNS)\n        rows = [\n            ["T1", "100.0", "1.0", "CCO", "K" * 14, "C2H6O", "C2H7O",\n             "46.0", "47.0", "[M+H]+", "QTOF", "20", "train"],\n            ["T2", "200.0", "1.0", "CCC", "J" * 14, "C3H8", "C3H9",\n             "44.0", "45.0", "[M+H]+", "QTOF", "20", "train"],\n        ]\n        with tempfile.NamedTemporaryFile("w", suffix=".tsv",\n                                         delete=False) as handle:\n            handle.write(header + "\\n")\n            for r in rows:\n                handle.write("\\t".join(r) + "\\n")\n            path = handle.name\n        try:\n            refs, info = collect_train_refs(path, {"CCO", "CCC"},\n                                            exclude_smiles={"CCO"})\n        finally:\n            os.unlink(path)\n        self.assertNotIn("CCO", refs)\n        self.assertIn("CCC", refs)\n        self.assertEqual(info["n_leak_excluded"], 1)\n\n    def test_duplicate_ids_first_wins(self):\n        import tempfile\n        header = "\\t".join(WANTED_COLUMNS)\n        rows = [\n            ["DUP", "100.0", "1.0", "CCO", "K" * 14, "C2H6O", "C2H7O",\n             "46.0", "47.0", "[M+H]+", "QTOF", "20", "train"],\n            ["DUP", "300.0", "1.0", "CCO", "K" * 14, "C2H6O", "C2H7O",\n             "46.0", "47.0", "[M+H]+", "QTOF", "20", "train"],\n        ]\n        with tempfile.NamedTemporaryFile("w", suffix=".tsv",\n                                         delete=False) as handle:\n            handle.write(header + "\\n")\n            for r in rows:\n                handle.write("\\t".join(r) + "\\n")\n            path = handle.name\n        try:\n            refs, info = collect_train_refs(path, {"CCO"})\n        finally:\n            os.unlink(path)\n        self.assertEqual(len(refs["CCO"]), 1)\n        self.assertEqual(info["n_duplicate_ids"], 1)\n        # First occurrence wins.\n        self.assertEqual(refs["CCO"][0][0], "DUP")\n        self.assertIn(1000, refs["CCO"][0][1])  # 100.0 Da bin\n\n\nclass ContentGuardTests(unittest.TestCase):\n    def test_fingerprint_equal_content(self):\n        self.assertEqual(content_fp([(100.0, 0.5), (200.0, 1.0)]),\n                         content_fp([(200.0, 1.0), (100.0, 0.5)]))\n        self.assertNotEqual(content_fp([(100.0, 0.5)]),\n                            content_fp([(100.05, 0.5)]))\n\n    def test_exclude_query_content_different_id(self):\n        fp_q = content_fp([(100.0, 1.0)])\n        refs = {"X": [("r1", {1000: 1.0}, 1.0, 0, "", "", fp_q),\n                      ("r2", {2000: 1.0}, 1.0, 0, "", "",\n                       content_fp([(200.0, 1.0)]))],\n                "Y": [("r3", {1000: 1.0}, 1.0, 0, "", "", fp_q)]}\n        kept, n_r, n_s = exclude_query_content(refs, fp_q)\n        self.assertEqual(n_r, 2)\n        self.assertEqual(n_s, 2)\n        self.assertEqual(kept, {"X": [refs["X"][1]]})\n\n    def test_collect_dedups_content_within_structure(self):\n        import tempfile\n        header = "\\t".join(WANTED_COLUMNS)\n        rows = [\n            ["A1", "100.0,200.0", "0.5,1.0", "CCO", "K" * 14, "C2H6O",\n             "C2H7O", "46.0", "47.0", "[M+H]+", "QTOF", "20", "train"],\n            ["A2", "100.0,200.0", "0.5,1.0", "CCO", "K" * 14, "C2H6O",\n             "C2H7O", "46.0", "47.0", "[M+H]+", "QTOF", "20", "train"],\n            ["A3", "150.0", "1.0", "CCO", "K" * 14, "C2H6O", "C2H7O",\n             "46.0", "47.0", "[M+H]+", "QTOF", "20", "train"],\n        ]\n        with tempfile.NamedTemporaryFile("w", suffix=".tsv",\n                                         delete=False) as handle:\n            handle.write(header + "\\n")\n            for r in rows:\n                handle.write("\\t".join(r) + "\\n")\n            path = handle.name\n        try:\n            refs, info = collect_train_refs(path, {"CCO"})\n        finally:\n            os.unlink(path)\n        self.assertEqual(len(refs["CCO"]), 2)  # A1 + A3; A2 deduped\n        self.assertEqual(info["n_duplicate_content"], 1)\n        self.assertEqual(info.get("n_duplicate_ids", 0), 0)\n\n\nclass CoverageBaselineTests(unittest.TestCase):\n    def test_referenced_first_no_scores(self):\n        scored = [\n            {"idx": 0, "smiles": "A", "score": 0.99, "n_refs": 0,\n             "best_ref": None},\n            {"idx": 1, "smiles": "B", "score": None, "n_refs": 0,\n             "best_ref": None},\n            {"idx": 2, "smiles": "C", "score": 0.01, "n_refs": 3,\n             "best_ref": "r"},\n        ]\n        pos = seeded_positions("QC", 3)\n        order = rank_coverage(scored, pos)\n        # Only referenced candidate first regardless of (low) score.\n        self.assertEqual(order[0], 2)\n        self.assertEqual(sorted(order), [0, 1, 2])\n        import inspect\n        src = inspect.getsource(rank_coverage)\n        self.assertNotIn(\'["score"]\', src)\n        self.assertNotIn("[\'score\']", src)\n\n    def test_coverage_arm_in_evaluate(self):\n        scored = [\n            {"idx": 0, "smiles": "A", "score": 0.9, "n_refs": 1,\n             "best_ref": "r"},\n            {"idx": 1, "smiles": "T", "score": 0.1, "n_refs": 1,\n             "best_ref": "r"},\n        ]\n        ev = evaluate_query("Q", scored, seeded_positions("Q", 2),\n                            [1.0, 1.0], "T")\n        # Spectral follows scores (A first); coverage follows shuffle among\n        # referenced (may or may not match) -- the recorded distinction is\n        # that both ranks exist on identical pools.\n        self.assertIn("coverage", ev["ranks"])\n        self.assertIn("coverage", ev["hits"])\n        self.assertIsNotNone(ev["ranks"]["coverage"])\n\n\nclass DenominatorTests(unittest.TestCase):\n    def _rows(self):\n        good = full_row("VAL-0000", "T", {"adduct": "a",\n                                             "instrument_type": "i",\n                                             "collision_energy": "10",\n                                             "parent_mass": "46.0"},\n                        ["T", "U"], ["T", "U"], "complete")\n        good.update({"n_ref": 1, "target_has_ref": False, "predicted": True,\n                     "hits": {"uniform": {1: False, 3: True, 10: True},\n                              "spectral": {1: False, 3: False, 10: True},\n                              "coverage": {1: False, 3: True, 10: True},\n                              "massresid": {1: True, 3: True, 10: True}}})\n        bad = full_row("VAL-0001", "T2", {"adduct": "a",\n                                              "instrument_type": "i",\n                                              "collision_energy": "10",\n                                              "parent_mass": "46.0"},\n                       ["T2", "U"], ["T2", "U"],\n                       "query_parse_excl:non_numeric")\n        bad.update({"n_ref": 1, "target_has_ref": False})\n        return [good, bad]\n\n    def test_all_covers_selected_excluded_in_denominators(self):\n        m = summarize(self._rows(), "t")\n        self.assertEqual(m["n_selected"], 2)\n        self.assertEqual(m["n_complete"], 1)\n        self.assertEqual(m["pool_recall_all"], 1.0)  # both targets in pools\n        # Coverage over ALL selected (excluded counts as abstention).\n        self.assertEqual(m["all"]["coverage"], 0.5)\n        # Top-k denominators count rankable rows only.\n        self.assertEqual(m["all"]["spectral@top1_den"], 1)\n        self.assertEqual(m["eligible_anyref"]["n"], 1)\n\n    def test_refcount_subgroups(self):\n        rows = self._rows()\n        rows[0]["n_ref"] = 2\n        m = summarize(rows, "t")\n        self.assertEqual(m["refcount_multi"]["n"], 1)\n        self.assertEqual(m["refcount_1"]["n"], 0)\n\n    def test_strip_stereo_documented_approximation(self):\n        import inspect\n        self.assertIn("APPROXIMATION",\n                      inspect.getdoc(strip_stereo).upper())\n\n\ndef _write_tsv(path, rows):\n    with open(path, "w", encoding="utf-8", newline="") as handle:\n        handle.write("\\t".join(WANTED_COLUMNS) + "\\n")\n        for r in rows:\n            handle.write("\\t".join(r) + "\\n")\n\n\ndef _row(ident, mzs, ints, smiles, key, fold, parent="46.041864"):\n    return [ident, mzs, ints, smiles, key, "C2H6O", "C2H7O", parent, "47.0",\n            "[M+H]+", "QTOF", "20", fold]\n\n\nclass EnforcementTests(unittest.TestCase):\n    def test_overlap_aborts(self):\n        import tempfile\n        with tempfile.TemporaryDirectory() as tmp:\n            tsv = os.path.join(tmp, "t.tsv")\n            pre = os.path.join(tmp, "p.json")\n            _write_tsv(tsv, [\n                _row("T1", "100.0", "1.0", "CCO", "K" * 14, "train"),\n                _row("V1", "200.0", "1.0", "CCO", "K" * 14, "val"),\n            ])\n            with open(pre, "w", encoding="utf-8") as handle:\n                json.dump({"CCO": ["CCO", "CCC"]}, handle)\n            with self.assertRaises(ValueError):\n                run_val_experiment(tsv, pre, 10)\n\n    def test_missing_key_excluded_not_scored(self):\n        import tempfile\n        with tempfile.TemporaryDirectory() as tmp:\n            tsv = os.path.join(tmp, "t.tsv")\n            pre = os.path.join(tmp, "p.json")\n            _write_tsv(tsv, [\n                _row("T1", "100.0", "1.0", "CCO", "K" * 14, "train"),\n                _row("V1", "200.0", "1.0", "CCN", "", "val"),\n            ])\n            with open(pre, "w", encoding="utf-8") as handle:\n                json.dump({"CCN": ["CCN", "CCO"]}, handle)\n            out = run_val_experiment(tsv, pre, 10)\n            self.assertEqual(len(out["rows"]), 1)\n            self.assertEqual(out["rows"][0]["status"],\n                             "query_excl:missing_connectivity_key")\n            self.assertEqual(out["ref_info"]["n_queries_missing_key"], 1)\n            self.assertEqual(out["metrics"]["n_selected"], 1)\n            self.assertEqual(out["metrics"]["n_complete"], 0)\n\n\nclass IntegrationTests(unittest.TestCase):\n    def test_malformed_first_and_later_full_write(self):\n        import tempfile\n        with tempfile.TemporaryDirectory() as tmp:\n            tsv = os.path.join(tmp, "t.tsv")\n            pre = os.path.join(tmp, "p.json")\n            out = os.path.join(tmp, "out")\n            _write_tsv(tsv, [\n                _row("T1", "100.0,200.0", "0.5,1.0", "CCO", "K" * 14,\n                     "train"),\n                _row("T2", "100.0,200.0", "0.5,1.0", "CCO", "K" * 14,\n                     "train"),\n                _row("T3", "150.0,250.0", "1.0,0.5", "CCO", "K" * 14,\n                     "train"),\n                _row("T4", "300.0", "1.0", "CCC", "J" * 14, "train"),\n                _row("Vbad1", "xx", "1.0", "BAD1", "B" * 14, "val"),\n                _row("Vq", "110.0,210.0", "0.6,0.9", "CCN", "N" * 14,\n                     "val"),\n                _row("Vbad2", "100.0", "", "BAD2", "C" * 14, "val"),\n            ])\n            with open(pre, "w", encoding="utf-8") as handle:\n                json.dump({"BAD1": ["CCO", "CCC"],\n                           "CCN": ["CCO", "CCC", "CCN"],\n                           "BAD2": ["CCO", "CCC"],\n                           "CCO": ["CCO", "CCC"]}, handle)\n            main(["--tsv", tsv, "--prefix", pre, "--max-queries", "3",\n                  "--max-control", "1", "--out-dir", out])\n            val_rows = list(csv.DictReader(\n                open(os.path.join(out, "spectral_rows.csv"))))\n            ctl_rows = list(csv.DictReader(\n                open(os.path.join(out, "spectral_control_rows.csv"))))\n            summary = json.load(\n                open(os.path.join(out, "spectral_summary.json")))\n            # Mixed complete/exclusion schemas share one column set.\n            self.assertEqual(len(val_rows), 3)\n            for r in val_rows:\n                self.assertEqual(set(r.keys()), set(val_rows[0].keys()))\n            for r in ctl_rows:\n                self.assertEqual(set(r.keys()), set(ctl_rows[0].keys()))\n            statuses = [r["status"] for r in val_rows]\n            self.assertEqual(statuses[0], "query_parse_excl:non_numeric")\n            self.assertEqual(statuses[1], "complete")\n            self.assertEqual(statuses[2], "query_parse_excl:empty_spectrum")\n            # Selected/complete/excluded accounting + pool recall on all.\n            m = summary["val"]["metrics"]\n            self.assertEqual(m["n_selected"], 3)\n            self.assertEqual(m["n_complete"], 1)\n            self.assertEqual(m["pool_recall_all"], 1 / 3)\n            # Abstention coverage denominator includes excluded spectra.\n            self.assertEqual(m["all"]["coverage"],\n                             m["all"]["predicted"] / 3)\n            # Machine-readable output accounting persisted.\n            self.assertIn("rows_bytes", summary["outputs"])\n            self.assertIn("control_bytes", summary["outputs"])\n            self.assertEqual(summary["provenance"]["api_calls"], 0)\n            self.assertEqual(summary["provenance"]["downloads_bytes"], 0)\n            # Content-dedup counted (T2 duplicates T1 content).\n            self.assertEqual(summary["val"]["ref_info"]\n                             ["n_duplicate_content"], 1)\n\n\nif __name__ == "__main__":\n    main(sys.argv[1:])\n', 'tools/ms2_database_retrieval.py': '"""Database-first molecular-completion retrieval harness (Experiments A/B).\n\nImplements docs/MOLECULAR_COMPLETION_DATABASE_EXPERIMENTS.md, first pass only:\noffline, stdlib-only, capped synthetic fixture corpus. No external dataset is\ndownloaded by the default run. Ingestion adapters for ChEBI / MassSpecGym /\nMassBank / GNPS / PubChem / QM9 are stubs that pin releases, record hashes and\nenforce license/throttle notes; they raise an informative error until the\noperator supplies a pinned local file.\n\nRun:   python3 tools/ms2_database_retrieval.py\nTest:  python3 -m unittest tools/ms2_database_retrieval.py\n\nConventions (from MOLECULAR_COMPLETION_DESIGN.md):\n- Parent-relative hydrogen counts: substructure atom types are\n  (element, parent H count, valence); never re-sanitized as capped molecules.\n- Three-valued mass verdict: accept / reject / boundary-ambiguous, plus\n  unavailable when precision is unknown. Integer arithmetic only.\n- Fingerprint is a SOUND rejection screen only; surviving hits always go\n  through exact typed graph matching.\n- Unknown-overlap queries never receive the known-correspondence oracle.\n- Zero candidates with target absent from the pool is reported as\n  `target_absent`, never as proof of constraint inconsistency.\n- Top-k is reported only when the target is present in the candidate pool.\n- Synthetic parent-subgraph queries are controlled completion tests, not\n  experimentally confirmed fragment structures.\n"""\nfrom __future__ import annotations\n\nimport csv\nimport hashlib\nimport io\nimport sys\nimport time\nimport unittest\nfrom collections import Counter\nfrom decimal import Decimal, ROUND_CEILING, ROUND_HALF_EVEN\nfrom itertools import combinations\n\n# --------------------------------------------------------------------------\n# Integer mass arithmetic (same constants/semantics as the pilot reference).\n# --------------------------------------------------------------------------\n\nEXACT = {\n    "C": "12",\n    "H": "1.00782503223",\n    "N": "14.00307400443",\n    "O": "15.99491461957",\n    "F": "18.99840316273",\n    "S": "31.9720711744",\n    "Cl": "34.968852682",\n    "Br": "78.9183376",\n    "I": "126.9044719",\n}\nSCALE = 1_000_000\nMASS = {e: int((Decimal(m) * SCALE).to_integral_value(rounding=ROUND_HALF_EVEN))\n        for e, m in EXACT.items()}\nERROR_NDA = {\n    e: int((abs(Decimal(m) * SCALE - MASS[e]) * 1000).to_integral_value(rounding=ROUND_CEILING))\n    for e, m in EXACT.items()\n}\n\n# V0 neutral closed-shell vocabulary used by this harness, plus the\n# max-hydride neutrals (methane/ammonia/water atom types), hydrogen\n# fluoride\'s F, monovalent halogens, divalent sulfur, and aromatic atom\n# types for RDKit-canonical SMILES (lowercase). Aromatic bonds carry order\n# code AROM_ORDER (4); ORDER_VALUE maps codes to valence sums, so one\n# uniform residual rule covers aliphatic and aromatic atoms. Bare aromatic\n# `n` with two aromatic-only connections follows the RDKit convention\n# (pyridine, H=0); pyrrolic NH must be written [nH]. This convention is\n# sound for RDKit-canonical corpora (e.g. MassSpecGym 1.5) and is recorded\n# as a corpus dependence, not a general SMILES rule.\n# (element, parent-relative H count, total valence)\nAROM_ORDER = 4\nORDER_VALUE = {1: 1, 2: 2, 3: 3, 4: 1}\nTYPES = (\n    ("C", 0, 4), ("C", 1, 4), ("C", 2, 4), ("C", 3, 4), ("C", 4, 4),\n    ("N", 0, 3), ("N", 1, 3), ("N", 2, 3), ("N", 3, 3),\n    ("O", 0, 2), ("O", 1, 2), ("O", 2, 2),\n    ("F", 0, 1), ("F", 1, 1),\n    ("Cl", 0, 1), ("Br", 0, 1), ("I", 0, 1),\n    ("Cl", 1, 1), ("Br", 1, 1), ("I", 1, 1),\n    ("S", 0, 2), ("S", 1, 2), ("S", 2, 2),\n    ("C", 0, 3), ("C", 1, 3), ("C", 2, 3),\n    ("N", 0, 2),\n)\nTYPE_SET = set(TYPES)\nC3 = ("C", 3, 4)\nC2 = ("C", 2, 4)\nC1 = ("C", 1, 4)\nN2 = ("N", 2, 3)\nN1 = ("N", 1, 3)\nO1 = ("O", 1, 2)\nO0 = ("O", 0, 2)\n\n\ndef formula_of(atom_types):\n    result = {e: 0 for e in DOMAIN_ELEMENTS}\n    for element, hydrogen, _ in atom_types:\n        result[element] += 1\n        result["H"] += hydrogen\n    return result\n\n\ndef neutral_mass(formula):\n    return sum(formula.get(e, 0) * MASS[e] for e in EXACT)\n\n\ndef mass_verdict(observed, formula, uncertainty=50, ppm_tenths=100):\n    """Three-valued neutral-mass decision. See design section on formulas."""\n    if uncertainty is None:\n        return "unavailable"\n    computed = neutral_mass(formula)\n    error = (sum(formula.get(e, 0) * ERROR_NDA[e] for e in EXACT) + 999) // 1000\n    error += uncertainty\n    tolerance = observed * ppm_tenths // 10_000_000\n    residual = abs(observed - computed)\n    if residual + error <= tolerance:\n        return "accept"\n    if residual > tolerance + error:\n        return "reject"\n    return "ambiguous"\n\n\n# --------------------------------------------------------------------------\n# Records, standardization, identity.\n# --------------------------------------------------------------------------\n\nDOMAIN_ELEMENTS = ("C", "H", "N", "O", "F", "S", "Cl", "Br", "I")\n\n\ndef standardize_record(raw):\n    """Validate a raw structure dict into a closed neutral record.\n\n    Returns (record, exclusion_reason). exclusion_reason is None on success.\n    Record keeps source id and original payload for provenance; identity is\n    connectivity-only (stereo stripped, tautomer not resolved -- recorded as\n    a limitation, not silently normalized).\n    Rejects: unknown atom types, nonzero charge, isotopic labels, salts or\n    disconnected graphs, open valences (DB stage is closed molecules only).\n    """\n    atom_types = tuple(raw.get("atom_types", ()))\n    edges = tuple(raw.get("edges", ()))\n    for t in atom_types:\n        if t not in TYPE_SET:\n            return None, f"unsupported_atom_type:{t}"\n    if raw.get("charge", 0) != 0:\n        return None, "unsupported_charge"\n    if raw.get("isotopes"):\n        return None, "unsupported_isotope"\n    n = len(atom_types)\n    if n == 0:\n        return None, "empty_graph"\n    # Connectedness (single component => no salt fragments).\n    seen = {0}\n    changed = True\n    emap = {}\n    for a, b, o in edges:\n        if o:\n            emap[tuple(sorted((a, b)))] = o\n    while changed:\n        changed = False\n        for a, b, o in edges:\n            if not o:\n                continue\n            if (a in seen) != (b in seen):\n                seen.update((a, b))\n                changed = True\n    if len(seen) != n:\n        return None, "disconnected_or_salt"\n    # Closed-shell: residual valence must be zero for every atom, using\n    # ORDER_VALUE so aromatic bonds (code 4) count one valence unit.\n    residual = [v - h for _, h, v in atom_types]\n    for a, b, o in edges:\n        try:\n            value = ORDER_VALUE[o]\n        except KeyError:\n            return None, f"unsupported_bond_type:{o}"\n        residual[a] -= value\n        residual[b] -= value\n    if any(r != 0 for r in residual):\n        return None, "open_valence"\n    formula = formula_of(atom_types)\n    record = {\n        "id": raw.get("id"),\n        "source": raw.get("source"),\n        "family": raw.get("family", "unspecified"),\n        "atom_types": atom_types,\n        "edges": edges,\n        "formula": formula,\n        "mass": neutral_mass(formula),\n        "charge": 0,\n        "heavy": sum(1 for e, _, _ in atom_types if e != "H"),\n        "original": dict(raw.get("original", {})),\n    }\n    return record, None\n\n\ndef canonical_key(atom_types, edges):\n    """Connectivity identity (no stereo). For fixture-scale graphs only."""\n    from itertools import permutations as _perm\n\n    n = len(atom_types)\n    edge_map = {tuple(sorted((a, b))): o for a, b, o in edges if o}\n    best = None\n    for order in _perm(range(n)):\n        labels = tuple(atom_types[i] for i in order)\n        bonds = tuple(edge_map.get(tuple(sorted((order[i], order[j]))), 0)\n                      for i, j in combinations(range(n), 2))\n        key = (labels, bonds)\n        if best is None or key < best:\n            best = key\n    return best\n\n\ndef skeleton_key(atom_types, edges):\n    """Coarse scaffold grouping: heavy-element sequence + bond multiset."""\n    heavy = tuple(sorted(e for e, _, _ in atom_types))\n    orders = tuple(sorted(o for _, _, o in edges if o))\n    return (heavy, orders)\n\n\n# --------------------------------------------------------------------------\n# Exact typed matching + sound fingerprint screen.\n# --------------------------------------------------------------------------\n\nclass WorkCounters:\n    def __init__(self, limit=None):\n        self.fingerprint_screens = 0\n        self.exact_matches = 0\n        self.embedding_nodes = 0\n        self.limit = limit\n\n    def tick(self):\n        self.embedding_nodes += 1\n        if self.limit is not None and self.embedding_nodes > self.limit:\n            raise BudgetExhausted("embedding_nodes")\n\n\nclass BudgetExhausted(Exception):\n    pass\n\n\ndef edge_fingerprint(atom_types, edges):\n    """Necessary-condition counters for typed containment.\n\n    fp = (atom-type Counter, unordered typed-edge Counter). If any pattern\n    counter exceeds the candidate\'s, no injective typed edge-preserving\n    embedding exists -> sound to reject. Never used to accept.\n    """\n    ac = Counter(atom_types)\n    ec = Counter()\n    for a, b, o in edges:\n        if not o:\n            continue\n        t = tuple(sorted((atom_types[a], atom_types[b])))\n        ec[(t[0], t[1], o)] += 1\n    return ac, ec\n\n\ndef fingerprint_screen(candidate_fp, pattern_fp):\n    cac, cec = candidate_fp\n    pac, pec = pattern_fp\n    for k, v in pac.items():\n        if cac.get(k, 0) < v:\n            return False\n    for k, v in pec.items():\n        if cec.get(k, 0) < v:\n            return False\n    return True\n\n\ndef pattern_fingerprint(pattern_types, pattern_edges):\n    return edge_fingerprint(pattern_types, [(a, b, o) for a, b, o in pattern_edges])\n\n\ndef prepare_target(atom_types, edges):\n    """Precompute once per candidate: neighbor maps and type positions.\n\n    Returns (nbr, pos_by_type). nbr[i] maps neighbor -> bond order;\n    pos_by_type[t] lists target atoms of exact type t. Both matchers iterate\n    only type-compatible atoms and check constraints via dict lookup\n    (no per-check tuple allocation or sorting).\n    """\n    nbr = [{} for _ in atom_types]\n    for a, b, o in edges:\n        if o:\n            nbr[a][b] = o\n            nbr[b][a] = o\n    pos = {}\n    for i, t in enumerate(atom_types):\n        pos.setdefault(t, []).append(i)\n    return nbr, pos\n\n\ndef _prepare_single(pattern_types, pattern_edges):\n    """Pattern-side prep, reusable across candidates.\n\n    Returns (order, cons) where order lists pattern atoms rarest-... (static\n    degree order; target rarity is applied at iteration via pos_by_type\n    candidate-list lengths) and cons[k] lists (earlier_position, order).\n    """\n    m = len(pattern_types)\n    deg = [0] * m\n    adj = [[] for _ in range(m)]\n    for a, b, o in pattern_edges:\n        deg[a] += 1\n        deg[b] += 1\n        adj[a].append((b, o))\n        adj[b].append((a, o))\n    order = sorted(range(m), key=lambda i: -deg[i])\n    rank = {atom: k for k, atom in enumerate(order)}\n    cons = []\n    for k, atom in enumerate(order):\n        cons.append(tuple(sorted(\n            (rank[nb], o) for nb, o in adj[atom] if rank[nb] < k)))\n    return order, cons\n\n\ndef count_embeddings_prep(nbr, pos, ptypes, order, cons, cap, counters=None):\n    """Count distinct embeddings of one pattern up to cap (feature use).\n\n    Same existence semantics as _contains_with_prep (result > 0 iff a\n    match exists); the count itself is a cheap multiplicity feature, not\n    a quality claim. Occupancy handling mirrors the matcher exactly.\n    """\n    total = 0\n    stop = False\n    n_target = len(nbr)\n    chosen = [0] * len(order)\n    occupied = [False] * n_target\n\n    def search(k):\n        nonlocal total, stop\n        if stop:\n            return\n        if k == len(order):\n            # No bulk reset here: each frame unsets its own atom after the\n            # recursive call returns, so ancestor assignments stay intact\n            # for the remaining branches (injectivity preserved while\n            # counting). Resetting `chosen` at the leaf would let later\n            # branches reuse ancestor atoms and inflate the count.\n            total += 1\n            if total >= cap:\n                stop = True\n            return\n        atom = order[k]\n        want = ptypes[atom]\n        for cand in pos.get(want, ()):\n            if stop:\n                return\n            if counters is not None:\n                counters.tick()\n            if occupied[cand]:\n                continue\n            row = nbr[cand]\n            ok = True\n            for l, o in cons[k]:\n                if row.get(chosen[l]) != o:\n                    ok = False\n                    break\n            if ok:\n                chosen[k] = cand\n                occupied[cand] = True\n                search(k + 1)\n                occupied[cand] = False\n\n    search(0)\n    return total\n\n\ndef _contains_with_prep(nbr, pos, ptypes, order, cons, occupied, counters):\n    # Occupancy is always clean on return: backtracking unsets on failure,\n    # and success resets the (small) chosen set before unwinding.\n    chosen = [0] * len(order)\n\n    def search(k):\n        if k == len(order):\n            for c in chosen:\n                occupied[c] = False\n            return True\n        atom = order[k]\n        want = ptypes[atom]\n        for cand in pos.get(want, ()):\n            if counters is not None:\n                counters.tick()\n            if occupied[cand]:\n                continue\n            row = nbr[cand]\n            ok = True\n            for l, o in cons[k]:\n                if row.get(chosen[l]) != o:\n                    ok = False\n                    break\n            if ok:\n                chosen[k] = cand\n                occupied[cand] = True\n                if search(k + 1):\n                    return True\n                occupied[cand] = False\n        return False\n\n    return search(0)\n\n\ndef contains_exact(atom_types, edges, pattern_types, pattern_edges, counters=None):\n    """Injective typed edge-preserving embedding; target may add edges."""\n    if len(pattern_types) > len(atom_types):\n        return False\n    nbr, pos = prepare_target(atom_types, edges)\n    order, cons = _prepare_single(pattern_types, pattern_edges)\n    return _contains_with_prep(nbr, pos, pattern_types, order, cons,\n                               [False] * len(atom_types), counters)\n\n\ndef _prepare_joint(patterns):\n    """Pattern-side prep for joint matching, reusable across candidates.\n\n    Returns (flat_types, flat_pat, flat_adj, degrees). flat_adj[i] lists\n    (j, order) pattern-edge neighbors of flat atom i.\n    """\n    flat_types, flat_pat = [], []\n    index_of = {}\n    for pi, (pt, pe) in enumerate(patterns):\n        for ai, t in enumerate(pt):\n            index_of[(pi, ai)] = len(flat_types)\n            flat_types.append(t)\n            flat_pat.append(pi)\n    flat_adj = [[] for _ in flat_types]\n    for pi, (pt, pe) in enumerate(patterns):\n        for a, b, o in pe:\n            i, j = index_of[(pi, a)], index_of[(pi, b)]\n            flat_adj[i].append((j, o))\n            flat_adj[j].append((i, o))\n    degrees = [len(v) for v in flat_adj]\n    return flat_types, flat_pat, flat_adj, degrees\n\n\ndef _joint_with_prep(nbr, pos, counts, flat_types, flat_pat, flat_adj,\n                     degrees, n_patterns, occupied_sets, counters):\n    order = sorted(range(len(flat_types)),\n                   key=lambda i: (counts.get(flat_types[i], 0), -degrees[i]))\n    assign = [None] * len(flat_types)\n\n    def search(k):\n        if k == len(order):\n            return True\n        fi = order[k]\n        want = flat_types[fi]\n        used = occupied_sets[flat_pat[fi]]\n        for cand in pos.get(want, ()):\n            if counters is not None:\n                counters.tick()\n            if cand in used:\n                continue\n            row = nbr[cand]\n            ok = True\n            for j, o in flat_adj[fi]:\n                other = assign[j]\n                if other is not None and row.get(other) != o:\n                    ok = False\n                    break\n            if ok:\n                assign[fi] = cand\n                used.add(cand)\n                if search(k + 1):\n                    return True\n                assign[fi] = None\n                used.discard(cand)\n        return False\n\n    return search(0)\n\n\ndef joint_contains(atom_types, edges, patterns, counters=None):\n    """Global overlap consistency across patterns.\n\n    Simultaneously embeds every pattern, injective within each pattern,\n    sharing allowed across patterns. Rejects quotients that collapse two\n    distinct atoms of one pattern or equate incompatible types. Pairwise\n    per-pattern success alone does not imply this returns True.\n    """\n    if not any(True for _ in patterns for _ in _[0]):\n        return True\n    flat_types, flat_pat, flat_adj, degrees = _prepare_joint(patterns)\n    nbr, pos = prepare_target(atom_types, edges)\n    from collections import Counter as _Counter\n\n    occupied_sets = [set() for _ in patterns]\n    return _joint_with_prep(nbr, pos, _Counter(atom_types),\n                            flat_types, flat_pat, flat_adj, degrees,\n                            len(patterns), occupied_sets, counters)\n\n\n# --------------------------------------------------------------------------\n# Fixture corpus (synthetic stand-ins; NOT ChEBI/MassBank records).\n# --------------------------------------------------------------------------\n\ndef _mol(mid, family, atom_types, edges):\n    return {"id": mid, "source": "synthetic-fixture", "family": family,\n            "atom_types": tuple(atom_types), "edges": tuple(edges),\n            "charge": 0, "original": {"note": "synthetic controlled-completion fixture"}}\n\n\ndef fixture_raw_records():\n    C, N, O = C3, N2, O1\n    recs = [\n        _mol("FIX-001", "alcohol", (C3, C2, O1), ((0, 1, 1), (1, 2, 1))),          # ethanol\n        _mol("FIX-002", "ether", (C3, O0, C3), ((0, 1, 1), (1, 2, 1))),            # dimethyl ether\n        _mol("FIX-003", "alcohol", (C3, C2, C2, O1),\n             ((0, 1, 1), (1, 2, 1), (2, 3, 1))),                                   # 1-propanol\n        _mol("FIX-004", "alcohol", (C3, C1, C3, O1),\n             ((0, 1, 1), (1, 2, 1), (1, 3, 1))),                                   # 2-propanol\n        _mol("FIX-005", "ether", (C3, O0, C2, C3), ((0, 1, 1), (1, 2, 1), (2, 3, 1))),\n        _mol("FIX-006", "amine", (C3, N2), ((0, 1, 1),)),                          # methylamine\n        _mol("FIX-007", "amide", (C1, O0, N2), ((0, 1, 2), (0, 2, 1))),            # formamide\n        _mol("FIX-008", "diol", (C2, C2, O1, O1),\n             ((0, 1, 1), (0, 2, 1), (1, 3, 1))),                                   # ethylene glycol\n        _mol("FIX-009", "cyclic-ether", (C2, C2, C2, O0),\n             ((0, 1, 1), (1, 2, 1), (2, 3, 1), (3, 0, 1))),                         # oxetane\n        _mol("FIX-010", "cyclic-amine", (C2, C2, N1),\n             ((0, 1, 1), (1, 2, 1), (2, 0, 1))),                                   # aziridine\n        _mol("FIX-011", "fluoro", (C3, C2, ("F", 0, 1)),\n             ((0, 1, 1), (1, 2, 1))),                                              # 1-fluoroethane\n        _mol("FIX-012", "carbonyl", (C3, C1, O0),\n             ((0, 1, 1), (1, 2, 2))),                                              # acetaldehyde\n    ]\n    return recs\n\n\nCH3_PAT = ((C3,), ())\nCH2OH_PAT = (((C2, O1)), ((0, 1, 1),))\nCH3CH2_PAT = (((C3, C2)), ((0, 1, 1),))\nCN_PAT = (((C3, N2)), ((0, 1, 1),))\nC1N_PAT = (((C1, N2)), ((0, 1, 1),))\nN_PAT = ((N2,), ())\n\n\ndef fixture_queries():\n    """(name, target_id, patterns, overlap, precursor_id).\n\n    overlap: \'na\' (no patterns), \'unknown\' (default condition), \'known\'\n    (oracle correspondence supplied separately, same filter plus provenance).\n    precursor: optional parent record id for stage-4 arm; None => not-evaluated.\n    """\n    return [\n        ("C2H6O_mass_only", "FIX-001", (), "na", None),\n        ("C2H6O_CH3_unknown", "FIX-001", (CH3_PAT,), "unknown", None),\n        ("C2H6O_CH2OH_unknown", "FIX-001", (CH2OH_PAT,), "unknown", None),\n        ("C2H6O_two_overlapping_unknown", "FIX-001", (CH3CH2_PAT, CH2OH_PAT), "unknown", None),\n        ("C2H6O_two_overlapping_known", "FIX-001", (CH3CH2_PAT, CH2OH_PAT), "known", None),\n        ("C3H8O_mass_only", "FIX-003", (), "na", None),\n        ("C3H8O_two_overlapping_unknown", "FIX-003", (CH3CH2_PAT, CH2OH_PAT), "unknown", None),\n        ("amine_CN_unknown", "FIX-006", (CN_PAT,), "unknown", None),\n        ("amide_C1N_unknown", "FIX-007", (C1N_PAT,), "unknown", None),\n        ("amide_C3N_incompatible", "FIX-007", (CN_PAT,), "unknown", None),\n        ("ring_mass_only", "FIX-009", (), "na", None),\n        ("fragment_completion_precursor", "FIX-001", (CH3_PAT,), "unknown", "FIX-003"),\n    ]\n\n\n# --------------------------------------------------------------------------\n# Retrieval index + staged filtering (Experiments A and B).\n# --------------------------------------------------------------------------\n\nclass DatabaseIndex:\n    def __init__(self, records):\n        self.records = records\n        self.by_id = {r["id"]: r for r in records}\n        self.by_formula = {}\n        self.fkeys = {}\n        for r in records:\n            key = formula_key(r["formula"])\n            self.by_formula.setdefault(key, []).append(r)\n            self.fkeys[r["id"]] = key\n        self.fps = {r["id"]: edge_fingerprint(r["atom_types"], r["edges"]) for r in records}\n        # NOTE: connectivity identities are NOT computed eagerly: canonical_key\n        # is factorial in atom count and hangs on drug-sized molecules. Use\n        # identity() for small graphs only.\n        self._identities = {}\n\n    def identity(self, rid, max_atoms=8):\n        """Canonical connectivity identity for small graphs; None above cap."""\n        if rid in self._identities:\n            return self._identities[rid]\n        r = self.by_id[rid]\n        if len(r["atom_types"]) > max_atoms:\n            return None\n        key = canonical_key(r["atom_types"], r["edges"])\n        self._identities[rid] = key\n        return key\n\n    def __len__(self):\n        return len(self.records)\n\n\ndef formula_key(formula):\n    return tuple(sorted((e, formula.get(e, 0)) for e in DOMAIN_ELEMENTS))\n\n\ndef run_query(index, target, patterns, overlap="unknown", precursor=None,\n              uncertainty=50, ppm_tenths=100, counters=None):\n    """Four staged candidate sets. Returns dict with counts/recall/statuses."""\n    counters = counters or WorkCounters()\n    observed = target["mass"]\n    # Stage 1: mass window (accept + ambiguous retained; reject dropped).\n    # Unknown precision ("unavailable") disables the mass decision: those\n    # candidates pass through and are counted separately, never rejected.\n    s1, n_accept, n_ambig, n_reject, n_unavail = [], 0, 0, 0, 0\n    for r in index.records:\n        v = mass_verdict(observed, r["formula"], uncertainty, ppm_tenths)\n        if v == "accept":\n            n_accept += 1\n            s1.append(r)\n        elif v == "ambiguous":\n            n_ambig += 1\n            s1.append(r)\n        elif v == "unavailable":\n            n_unavail += 1\n            s1.append(r)\n        else:\n            n_reject += 1\n    # Stage 2: exact formula + charge/element domain.\n    target_key = formula_key(target["formula"])\n    s2 = [r for r in s1 if index.fkeys.get(r["id"], formula_key(r["formula"])) == target_key\n          and r["charge"] == target["charge"]]\n    # Stage 3: subgraph containment + overlap consistency. Pattern-side prep\n    # is hoisted out of the per-candidate loop; per-candidate target prep is\n    # built once and reused across patterns.\n    pat_fps = [pattern_fingerprint(pt, pe) for pt, pe in patterns]\n    single_preps = [((pt, pe) + _prepare_single(pt, pe)) for pt, pe in patterns]\n    joint_prep = _prepare_joint(patterns) if len(patterns) > 1 else None\n    from collections import Counter as _Counter\n\n    s3 = []\n    truncated = False\n    try:\n        for r in s2:\n            cfp = index.fps[r["id"]]\n            counters.fingerprint_screens += 1\n            if not all(fingerprint_screen(cfp, pf) for pf in pat_fps):\n                continue\n            counters.exact_matches += 1\n            at, ed = r["atom_types"], r["edges"]\n            if any(len(pt) > len(at) for pt, _, _, _ in single_preps):\n                continue\n            nbr, pos = prepare_target(at, ed)\n            occupied = [False] * len(at)\n            ok = True\n            for pt, pe, order, cons in single_preps:\n                if not _contains_with_prep(nbr, pos, pt, order, cons,\n                                           occupied, counters):\n                    ok = False\n                    break\n            if not ok:\n                continue\n            if joint_prep is not None:\n                flat_types, flat_pat, flat_adj, degrees = joint_prep\n                occupied_sets = [set() for _ in patterns]\n                if not _joint_with_prep(nbr, pos, _Counter(at),\n                                        flat_types, flat_pat, flat_adj,\n                                        degrees, len(patterns),\n                                        occupied_sets, counters):\n                    continue\n            s3.append(r)\n    except BudgetExhausted:\n        truncated = True\n    # Stage 4: precursor evidence (heavy-atom conservation under the\n    # provisional target-fragment reading). No precursor => not-evaluated.\n    if precursor is None:\n        s4, precursor_status = s3, "not_evaluated"\n    else:\n        s4 = [r for r in s3 if all(\n            r["formula"].get(e, 0) <= precursor["formula"].get(e, 0) for e in DOMAIN_ELEMENTS)]\n        precursor_status = "evaluated"\n    in_pool = any(r["id"] == target["id"] for r in index.records)\n    recall = {}\n    for name, pool in (("s1", s1), ("s2", s2), ("s3", s3), ("s4", s4)):\n        recall[name] = (any(r["id"] == target["id"] for r in pool)\n                        if in_pool else None)\n    if s3:\n        zero_status = "nonempty"\n    elif not in_pool:\n        zero_status = "target_absent"\n    else:\n        zero_status = "target_filtered"\n    return {\n        "s1": s1, "s2": s2, "s3": s3, "s4": s4,\n        "n_accept": n_accept, "n_ambiguous": n_ambig, "n_reject": n_reject,\n        "n_unavailable": n_unavail,\n        "recall": recall, "in_pool": in_pool,\n        "precursor_status": precursor_status,\n        "overlap": overlap,  # provenance label; unknown path never sees oracle\n        "zero_status": zero_status,\n        "truncated": truncated,\n    }\n\n\ndef rank_baselines(pool, target_id, index):\n    """Ranking baselines at a fixed pool: uniform, provenance, fingerprint.\n\n    Spectral similarity is unavailable without measured spectra (marked, not\n    fabricated). Top-k reported only when target is in the pool.\n    """\n    ids = [r["id"] for r in pool]\n    uniform = list(ids)\n    provenance = sorted(ids, key=lambda i: (index.by_id[i]["source"],\n                                            index.by_id[i]["id"]))\n    # Fingerprint-similarity baseline: Tanimoto on typed-edge sets vs target.\n    target_fp = index.fps.get(target_id)\n    scored = []\n    for r in pool:\n        a = set(index.fps[r["id"]][1].elements())\n        b = set(target_fp[1].elements()) if target_fp else set()\n        inter = len(a & b)\n        union = len(a | b) or 1\n        scored.append((inter / union, r["id"]))\n    fingerprint = [i for _, i in sorted(scored, reverse=True)]\n    in_pool = target_id in ids\n    out = {"uniform": uniform, "provenance": provenance,\n           "fingerprint": fingerprint, "spectral": "unavailable_no_spectrum"}\n    if in_pool:\n        for k, v in list(out.items()):\n            if isinstance(v, list):\n                out[k + "@1"] = v[0] == target_id\n                out[k + "@3"] = target_id in v[:3]\n    return out, in_pool\n\n\nindex_global = None  # set by main/tests for ranking baseline access\n\n\n# --------------------------------------------------------------------------\n# Ingestion adapters (stubs: pin + hash + license, no download by default).\n# --------------------------------------------------------------------------\n\ndef _pin_error(source, url, note):\n    return FileNotFoundError(\n        f"{source} fixture not supplied. Pin a release from {url}, record its "\n        f"sha256, place the file under data/pinned/, and re-run. {note}")\n\n\ndef ingest_chebi_sdf(path, release, sha256):\n    raise _pin_error("ChEBI", "https://www.ebi.ac.uk/chebi/downloads",\n                     "3-star SDF; CC BY 4.0; standardize charge/isotopes/salts; "\n                     "compute mass from graph, not display values.")\n\n\ndef ingest_massspecgym_tsv(path, release, sha256):\n    raise _pin_error("MassSpecGym", "https://huggingface.co/datasets/roman-bushuiev/MassSpecGym",\n                     "Pin dataset revision; main TSV + needed candidate JSONs only; "\n                     "inspect split/structure duplication before pooling.")\n\n\ndef ingest_mgf(path, release, sha256, license_note):\n    raise _pin_error("MGF", "https://massbank.github.io/MassBank-documentation/about.html",\n                     f"Pinned record archive required. {license_note}")\n\n\ndef pubchem_query_cached(formula, cache, release, calls):\n    """Batched, throttled, cached PubChem lookup (stub).\n\n    Policy: <=5 req/s, cache by (formula, release), record truncation.\n    Never the sole ground truth for a reproducible benchmark.\n    """\n    key = (formula_key(formula), release)\n    if key in cache:\n        return cache[key], False\n    calls.append(formula)\n    raise _pin_error("PubChem", "https://pubchem.ncbi.nlm.nih.gov/docs/pug-rest",\n                     "Query only unresolved formulas; prefer bulk downloads at scale.")\n\n\ndef qm9_match(record, qm9_index):\n    """Restricted positive-control match into QM9 (stub).\n\n    Uses published geometries/frequencies only; no new DFT. Presence is not\n    a lifetime/solution-stability guarantee. Returns (matched, method_env).\n    """\n    if qm9_index is None:\n        return False, "qm9_not_loaded"\n    heavy = record["heavy"]\n    els = set(e for e, _, _ in record["atom_types"]) | {"H"}\n    if heavy <= 9 and els <= {"C", "H", "O", "N", "F"}:\n        return record["id"] in qm9_index, "qm9:b3lyp/6-31G(2df,p)//freq (published)"\n    return False, "outside_qm9_domain"\n\n\n# --------------------------------------------------------------------------\n# Experiment driver.\n# --------------------------------------------------------------------------\n\ndef residual_valence_sum(record):\n    return 0  # closed molecules by construction; kept for stratification key\n\n\ndef stratify_key(target, patterns):\n    return {\n        "heavy": target["heavy"],\n        "n_subgraphs": len(patterns),\n        "overlap": "overlap" if len(patterns) > 1 else ("single" if patterns else "none"),\n        "residual_valence": residual_valence_sum(target),\n        "family": target["family"],\n    }\n\n\ndef run_experiment(index, queries, out_of_pool_ids=(), uncertainty=50, ppm_tenths=100):\n    global index_global\n    index_global = index\n    rows = []\n    t0 = time.perf_counter()\n    c0 = time.process_time()\n    for name, tid, patterns, overlap, prec_id in queries:\n        sub = DatabaseIndex([r for r in index.records if r["id"] not in out_of_pool_ids])\n        index_global = sub\n        target = index.by_id[tid]\n        precursor = index.by_id.get(prec_id) if prec_id else None\n        counters = WorkCounters()\n        res = run_query(sub, target, patterns, overlap, precursor,\n                        uncertainty, ppm_tenths, counters)\n        rank, target_in_s3 = rank_baselines(res["s3"], tid, sub)\n        key = stratify_key(target, patterns)\n        rows.append({\n            "query": name, "target": tid, "overlap": overlap,\n            "in_pool": res["in_pool"], "target_in_s3": target_in_s3,\n            "precursor_status": res["precursor_status"],\n            "n_s1": len(res["s1"]), "n_s2": len(res["s2"]),\n            "n_s3": len(res["s3"]), "n_s4": len(res["s4"]),\n            "recall_s1": res["recall"]["s1"], "recall_s3": res["recall"]["s3"],\n            "accept": res["n_accept"], "ambiguous": res["n_ambiguous"],\n            "reject": res["n_reject"], "unavailable": res["n_unavailable"],\n            "zero_status": res["zero_status"],\n            "top1_uniform": rank.get("uniform@1"), "top1_fingerprint": rank.get("fingerprint@1"),\n            "spectral": rank["spectral"], **{f"strat_{k}": v for k, v in key.items()},\n            "embedding_nodes": counters.embedding_nodes,\n        })\n    wall = time.perf_counter() - t0\n    cpu = time.process_time() - c0\n    return rows, {"wall_s": wall, "cpu_s": cpu,\n                  "per_1000_queries_s": wall / max(len(queries), 1) * 1000}\n\n\ndef denominators(raw_records, standardized, index, rows):\n    parseable = sum(1 for _ in standardized)\n    total = len(raw_records)\n    in_domain = len(index)\n    recalls = [r for r in rows if r["in_pool"]]\n    pool_recall = (sum(1 for r in recalls if r["recall_s3"]) / len(recalls)) if recalls else None\n    amb = sum(r["ambiguous"] for r in rows)\n    # Scaffold overlap across corpus.\n    skels = Counter(skeleton_key(r["atom_types"], r["edges"]) for r in index.records)\n    dup_scaffolds = sum(1 for _, c in skels.items() if c > 1)\n    return {\n        "fraction_parseable": parseable / total if total else None,\n        "fraction_in_domain": in_domain / parseable if parseable else None,\n        "target_in_pool_recall_s3": pool_recall,\n        "n_queries": len(rows),\n        "n_in_pool": len(recalls),\n        "total_boundary_ambiguous_hits": amb,\n        "scaffolds_total": len(skels),\n        "scaffolds_shared": dup_scaffolds,\n        "physical_label_coverage": "0 (QM9 index not loaded; no new DFT per plan)",\n        "download_bytes": 0, "api_calls": 0,\n    }\n\n\ndef main():\n    raw = fixture_raw_records()\n    # Add two intentionally excluded records to publish denominators honestly.\n    raw = list(raw) + [\n        {"id": "FIX-BAD-CHARGE", "source": "synthetic-fixture", "family": "excluded",\n         "atom_types": (C3, N2), "edges": ((0, 1, 1),), "charge": 1,\n         "original": {"note": "charged; outside V0 neutral domain"}},\n        {"id": "FIX-BAD-SALT", "source": "synthetic-fixture", "family": "excluded",\n         "atom_types": (C3, C3), "edges": (), "charge": 0,\n         "original": {"note": "disconnected salt-like pair"}},\n    ]\n    standardized, excluded = [], []\n    for r in raw:\n        rec, reason = standardize_record(r)\n        if rec is None:\n            excluded.append((r["id"], reason))\n        else:\n            standardized.append(rec)\n    index = DatabaseIndex(standardized)\n    queries = fixture_queries()\n    rows, perf = run_experiment(index, queries)\n    # Out-of-pool slice: drop FIX-001 entirely, re-run one query.\n    oop_rows, _ = run_experiment(index, [q for q in queries if q[1] == "FIX-001"][:2],\n                                 out_of_pool_ids=("FIX-001", "FIX-002"))\n    den = denominators(raw, standardized, index, rows)\n    fields = ["query", "target", "overlap", "in_pool", "target_in_s3", "precursor_status",\n              "n_s1", "n_s2", "n_s3", "n_s4", "recall_s1", "recall_s3",\n              "accept", "ambiguous", "reject", "unavailable", "zero_status",\n              "top1_uniform", "top1_fingerprint", "spectral",\n              "strat_heavy", "strat_n_subgraphs", "strat_overlap",\n              "strat_residual_valence", "strat_family", "embedding_nodes"]\n    buf = io.StringIO()\n    w = csv.DictWriter(buf, fieldnames=fields, extrasaction="ignore")\n    w.writeheader()\n    for r in rows + [{**r, "query": r["query"] + "|out_of_pool_slice"} for r in oop_rows]:\n        w.writerow(r)\n    sys.stdout.write(buf.getvalue())\n    sys.stderr.write(f"# excluded: {excluded}\\n# perf: {perf}\\n# denominators: {den}\\n")\n\n\n# --------------------------------------------------------------------------\n# Tests.\n# --------------------------------------------------------------------------\n\nclass RetrievalTests(unittest.TestCase):\n    @classmethod\n    def setUpClass(cls):\n        recs = []\n        for raw in fixture_raw_records():\n            rec, reason = standardize_record(raw)\n            assert rec is not None, reason\n            recs.append(rec)\n        cls.index = DatabaseIndex(recs)\n        global index_global\n        index_global = cls.index\n\n    def test_mass_trichotomy_and_unavailable(self):\n        f = {"C": 2, "H": 6, "N": 0, "O": 1, "F": 0}\n        obs = neutral_mass(f)\n        self.assertEqual(mass_verdict(obs, f), "accept")\n        self.assertEqual(mass_verdict(obs, f, uncertainty=None), "unavailable")\n        tol = obs * 100 // 10_000_000\n        self.assertEqual(mass_verdict(obs + tol, f), "ambiguous")\n        self.assertEqual(mass_verdict(obs + 10 * tol + 10_000_000, f), "reject")\n\n    def test_standardization_rejects_charge_and_salt(self):\n        bad_c, r1 = standardize_record({"id": "x", "atom_types": (C3, N2),\n                                        "edges": ((0, 1, 1),), "charge": 1})\n        self.assertIsNone(bad_c)\n        self.assertIn("charge", r1)\n        bad_s, r2 = standardize_record({"id": "y", "atom_types": (C3, C3),\n                                        "edges": (), "charge": 0})\n        self.assertIsNone(bad_s)\n        self.assertIn("salt", r2)\n\n    def test_fingerprint_sound(self):\n        # Screen rejections must agree with exact matching (soundness), and\n        # every true embedding must pass the screen (no false rejection).\n        pats = [CH3_PAT, CH2OH_PAT, CH3CH2_PAT, CN_PAT]\n        for r in self.index.records:\n            cfp = self.index.fps[r["id"]]\n            for pt, pe in pats:\n                screen = fingerprint_screen(cfp, pattern_fingerprint(pt, pe))\n                exact = contains_exact(r["atom_types"], r["edges"], pt, pe)\n                if not screen:\n                    self.assertFalse(exact, (r["id"], pt))\n                if exact:\n                    self.assertTrue(screen, (r["id"], pt))\n\n    def test_monotonicity_across_stages(self):\n        target = self.index.by_id["FIX-001"]\n        res = run_query(self.index, target, (CH3CH2_PAT, CH2OH_PAT))\n        self.assertGreaterEqual(len(res["s1"]), len(res["s2"]))\n        self.assertGreaterEqual(len(res["s2"]), len(res["s3"]))\n        self.assertGreaterEqual(len(res["s3"]), len(res["s4"]))\n\n    def test_unknown_overlap_never_sees_oracle(self):\n        target = self.index.by_id["FIX-001"]\n        oracle = {(0, 0): 0}  # fabricated mapping object; unknown path takes none\n        a = run_query(self.index, target, (CH3CH2_PAT, CH2OH_PAT), overlap="unknown")\n        b = run_query(self.index, target, (CH3CH2_PAT, CH2OH_PAT), overlap="unknown",\n                      precursor=None)\n        _ = oracle\n        self.assertEqual([r["id"] for r in a["s3"]], [r["id"] for r in b["s3"]])\n\n    def test_zero_count_reports_target_absent(self):\n        sub = DatabaseIndex([r for r in self.index.records\n                              if r["id"] not in ("FIX-001", "FIX-002")])\n        target = self.index.by_id["FIX-001"]\n        res = run_query(sub, target, (CH3CH2_PAT, CH2OH_PAT))\n        self.assertFalse(res["in_pool"])\n        self.assertIsNone(res["recall"]["s3"])\n        self.assertIn(res["zero_status"], ("target_absent", "nonempty"))\n\n    def test_topk_gated_on_pool_membership(self):\n        target = self.index.by_id["FIX-001"]\n        res = run_query(self.index, target, ())\n        rank, in_pool = rank_baselines(res["s3"], "FIX-001", self.index)\n        self.assertTrue(in_pool)\n        self.assertIn("uniform@1", rank)\n        sub = DatabaseIndex([r for r in self.index.records if r["id"] != "FIX-001"])\n        global index_global\n        index_global = sub\n        res2 = run_query(sub, target, ())\n        rank2, in_pool2 = rank_baselines(res2["s3"], "FIX-001", sub)\n        self.assertFalse(in_pool2)\n        self.assertNotIn("uniform@1", rank2)\n        index_global = self.index\n\n    def test_joint_overlap_rejects_collapse(self):\n        # Two distinct single-atom patterns forced onto one atom by joint\n        # mapping are fine (sharing allowed), but an edge pattern plus an\n        # incompatible atom sharing must still satisfy edge constraints.\n        target = self.index.by_id["FIX-006"]  # methylamine\n        ok = joint_contains(target["atom_types"], target["edges"], (CH3_PAT, N_PAT))\n        self.assertTrue(ok)\n        impossible = (((C3, C3), ((0, 1, 1),)),)\n        self.assertFalse(joint_contains(target["atom_types"], target["edges"], impossible))\n\n    def test_count_triangle_path_is_six(self):\n        # Review regression: leaf bulk-reset overcounted (9 instead of 6)\n        # by letting later branches reuse ancestor atoms.\n        tri = ((C3, C3, C3), ((0, 1, 1), (1, 2, 1), (0, 2, 1)))\n        pat = ((C3, C3, C3), ((0, 1, 1), (1, 2, 1)))\n        nbr, pos = prepare_target(*tri)\n        order, cons = _prepare_single(*pat)\n        self.assertEqual(count_embeddings_prep(nbr, pos, pat[0], order, cons, 100), 6)\n        self.assertEqual(count_embeddings_prep(nbr, pos, pat[0], order, cons, 4), 4)\n\n    def test_unavailable_precision_passes_through(self):\n        # Review regression: unknown precision disabled the mass decision;\n        # it must not read as rejection.\n        target = self.index.by_id["FIX-001"]\n        res = run_query(self.index, target, (), "unknown", None, uncertainty=None)\n        self.assertEqual(len(res["s1"]), len(self.index))\n        self.assertEqual(res["n_unavailable"], len(self.index))\n        self.assertEqual(res["n_reject"], 0)\n        self.assertTrue(res["recall"]["s1"])\n\n    @staticmethod\n    def _all_injections(at, ed, pt, pe):\n        import itertools\n\n        emap = {tuple(sorted((a, b))): o for a, b, o in ed if o}\n        for perm in itertools.permutations(range(len(at)), len(pt)):\n            if any(at[perm[i]] != pt[i] for i in range(len(pt))):\n                continue\n            ok = True\n            for a, b, o in pe:\n                if emap.get(tuple(sorted((perm[a], perm[b])))) != o:\n                    ok = False\n                    break\n            if ok:\n                yield perm\n\n    def test_matchers_agree_with_brute_force(self):\n        # Optimized backtracking matchers vs an independent\n        # permutation-enumeration reference on randomized small graphs.\n        import itertools\n        import random\n\n        def brute_single(at, ed, pt, pe):\n            emap = {tuple(sorted((a, b))): o for a, b, o in ed if o}\n            for perm in itertools.permutations(range(len(at)), len(pt)):\n                if any(at[perm[i]] != pt[i] for i in range(len(pt))):\n                    continue\n                ok = True\n                for a, b, o in pe:\n                    if emap.get(tuple(sorted((perm[a], perm[b])))) != o:\n                        ok = False\n                        break\n                if ok:\n                    return True\n            return False\n\n        def brute_joint(at, ed, patterns):\n            emap = {tuple(sorted((a, b))): o for a, b, o in ed if o}\n            injs = []\n            for pt, pe in patterns:\n                found = []\n                for perm in itertools.permutations(range(len(at)), len(pt)):\n                    if any(at[perm[i]] != pt[i] for i in range(len(pt))):\n                        continue\n                    ok = True\n                    for a, b, o in pe:\n                        if emap.get(tuple(sorted((perm[a], perm[b])))) != o:\n                            ok = False\n                            break\n                    if ok:\n                        found.append(perm)\n                injs.append(found)\n            for combo in itertools.product(*injs):\n                return True  # sharing across patterns allowed; per-pattern\n                # injectivity already enforced by permutations\n            return False\n\n        rnd = random.Random(20261003)\n        pool = [C3, C2, C1, N2, N1, O1, O0]\n        for trial in range(300):\n            n = rnd.randint(1, 6)\n            at = tuple(rnd.choice(pool) for _ in range(n))\n            pairs = [(a, b) for a in range(n) for b in range(a + 1, n)]\n            rnd.shuffle(pairs)\n            ed = tuple((a, b, rnd.choice([1, 1, 2]))\n                       for a, b in pairs[:rnd.randint(0, min(len(pairs), n))])\n            m = rnd.randint(1, 3)\n            pt = tuple(rnd.choice(pool) for _ in range(m))\n            pp = [(a, b) for a in range(m) for b in range(a + 1, m)]\n            rnd.shuffle(pp)\n            pe = tuple((a, b, rnd.choice([1, 2]))\n                       for a, b in pp[:rnd.randint(0, len(pp))])\n            self.assertEqual(contains_exact(at, ed, pt, pe),\n                             brute_single(at, ed, pt, pe), (trial, at, ed, pt, pe))\n            if trial % 10 == 0:\n                # Capped counter agrees with exhaustive enumeration below cap\n                # and saturates at cap above it.\n                from tools.ms2_database_retrieval import (\n                    count_embeddings_prep, prepare_target, _prepare_single)\n                nbr, pos = prepare_target(at, ed)\n                order, cons = _prepare_single(pt, pe)\n                total = sum(1 for _ in self._all_injections(at, ed, pt, pe))\n                self.assertEqual(\n                    count_embeddings_prep(nbr, pos, pt, order, cons, 10_000),\n                    total, (trial, at, ed, pt, pe))\n                self.assertEqual(\n                    count_embeddings_prep(nbr, pos, pt, order, cons, 1),\n                    min(1, total))\n            if trial % 3 == 0:\n                m2 = rnd.randint(1, 2)\n                pt2 = tuple(rnd.choice(pool) for _ in range(m2))\n                pats = [(pt, pe), (pt2, ())]\n                self.assertEqual(joint_contains(at, ed, pats),\n                                 brute_joint(at, ed, pats), (trial, at, ed, pats))\n\n\nif __name__ == "__main__":\n    if len(sys.argv) > 1 and sys.argv[1] == "test":\n        unittest.main(argv=[sys.argv[0]])\n    else:\n        main()\n', 'tools/ms2_full_model.py': '"""Complete CHNO prototype: learned substructures, Mamba-3 graph actions and ranking.\n\nUses the repository\'s PyTorch Mamba-3 reference and MS2 Python grammar reference.\nThe domain and traversal are explicit experiment policies, not new frozen V0 APIs.\n"""\nimport itertools\nimport math\nfrom collections import Counter\nfrom dataclasses import dataclass\nfrom decimal import Decimal, ROUND_HALF_EVEN\nfrom functools import lru_cache\n\nimport numpy as np\nimport torch\nfrom torch import nn\nfrom torch.nn import functional as F\nfrom rdkit import Chem\nfrom rdkit.Chem.Scaffolds import MurckoScaffold\n\nfrom bench.torch_mamba3 import Block, RmsNorm\nfrom tools.ms2.ms2_reference import (Replay, ATOM_TYPES, TYPE_ID, MASS, RESIDUAL,\n                                    START, ADD, CLOSE, STOP, first_bfs_trace)\n\nMAX_ATOMS, MAX_CLOSURES, MAX_STEPS = 32, 8, 42\nELEMENTS = ("C", "H", "N", "O")\nADDUCT_SHIFT = {"[M+H]+": 1_007_276, "[M-H]-": -1_007_276,\n                "[M+Na]+": 22_989_221}\nADDUCT_IDS = {s: i + 1 for i, s in enumerate(ADDUCT_SHIFT)}\nDOMAIN = "neutral-CHNO-C1to32-N0to12-O0to16-2to32atoms-8cycles-connectivity-rdkit-bfs-v1"\nREPRESENTATION_VERSION = "continuous-forward-canonical-graph-v2"\n# Continuous random Fourier features at two mass resolutions complement coarse\n# bins without requiring a multi-million-bin spectrum prediction head.\nMASS_FREQUENCIES = np.concatenate([\n    np.random.default_rng(seed).normal(0, 1 / (2 * math.pi * sigma), 512)\n    for seed, sigma in ((71, 0.01), (72, 0.001))\n])\nSPECTRUM_DIM = 2000 + 2 * len(MASS_FREQUENCIES)\nCANONICAL_GRAPH_DIM = MAX_ATOMS * 21 + MAX_ATOMS * MAX_ATOMS * 5\n\n\n@dataclass(frozen=True)\nclass Graph:\n    types: tuple\n    edges: tuple\n    identity: str = ""\n    stereo_smiles: str = ""\n\n    @property\n    def counts(self):\n        counts = Counter()\n        for t in self.types:\n            element, hydrogens, _ = ATOM_TYPES[t]\n            counts[element] += 1\n            counts["H"] += hydrogens\n        return tuple(counts[e] for e in ELEMENTS)\n\n    def trace(self):\n        adjacency = {i: {} for i in range(len(self.types))}\n        for a, b, order in self.edges:\n            adjacency[a][b] = adjacency[b][a] = order\n        return first_bfs_trace(self.types, adjacency)\n\n\n@lru_cache(maxsize=8192)\ndef identity(smiles):\n    mol = Chem.MolFromSmiles(smiles)\n    if mol is None:\n        return "raw:" + smiles\n    return Chem.MolToSmiles(mol, canonical=True, isomericSmiles=False)\n\n\n@lru_cache(maxsize=8192)\ndef parse_graph(smiles):\n    mol = Chem.MolFromSmiles(smiles)\n    if mol is None:\n        return None, "smiles_parse"\n    # Canonical connectivity SMILES removes isotope labels. Validate the\n    # original molecule before that normalization can hide an excluded label.\n    excluded_label = any(a.GetFormalCharge() or a.GetIsotope() or a.GetNumRadicalElectrons() for a in mol.GetAtoms())\n    labelled = Chem.MolToSmiles(mol, canonical=True, isomericSmiles=True)\n    key = Chem.MolToSmiles(mol, canonical=True, isomericSmiles=False)\n    # Reparse canonical connectivity SMILES: a deterministic traversal independent\n    # of the supplier\'s atom labels, without an exponential canonical BFS search.\n    mol = Chem.MolFromSmiles(key)\n    if len(Chem.GetMolFrags(mol)) != 1:\n        return None, "disconnected"\n    if not 2 <= mol.GetNumAtoms() <= MAX_ATOMS:\n        return None, "atom_count"\n    if mol.GetNumBonds() - mol.GetNumAtoms() + 1 > MAX_CLOSURES:\n        return None, "cycle_count"\n    if any(a.GetSymbol() not in ("C", "N", "O") for a in mol.GetAtoms()):\n        return None, "element"\n    if excluded_label:\n        return None, "charged_isotopic_or_radical"\n    try:\n        Chem.Kekulize(mol, clearAromaticFlags=True)\n    except Chem.KekulizeException:\n        return None, "kekulization"\n    types = []\n    for a in mol.GetAtoms():\n        h = a.GetTotalNumHs()\n        valence = h + int(sum(b.GetBondTypeAsDouble() for b in a.GetBonds()))\n        t = TYPE_ID.get((a.GetSymbol(), h, valence))\n        if t is None or t > 9:\n            return None, "atom_type"\n        types.append(t)\n    edges = tuple(sorted((min(b.GetBeginAtomIdx(), b.GetEndAtomIdx()),\n                          max(b.GetBeginAtomIdx(), b.GetEndAtomIdx()),\n                          int(b.GetBondTypeAsDouble())) for b in mol.GetBonds()))\n    graph = Graph(tuple(types), edges, key, labelled)\n    c, _, n, o = graph.counts\n    if c < 1 or n > 12 or o > 16:\n        return None, "formula_table_domain"\n    return graph, None\n\n\ndef canonical_candidates(smiles):\n    """Deduplicate identities while validating the original candidate labels."""\n    result = {}\n    for raw in smiles:\n        key = identity(raw)\n        candidate, _ = parse_graph(raw)\n        if key not in result or result[key] is None:\n            result[key] = candidate\n    return result\n\n\n@lru_cache(maxsize=8192)\ndef scaffold(smiles):\n    mol = Chem.MolFromSmiles(smiles)\n    value = MurckoScaffold.MurckoScaffoldSmiles(mol=mol, includeChirality=False)\n    # Acyclic molecules have no Murcko scaffold; connectivity groups remain intact.\n    return "scaffold:" + value if value else "acyclic:" + identity(smiles)\n\n\nclass CompleteState(Replay):\n    def __init__(self, counts):\n        super().__init__(dict(zip(ELEMENTS, counts)))\n        self.edges = []\n\n    def add_options(self):\n        if not self.types or len(self.types) >= MAX_ATOMS:\n            return {}\n        options = {}\n        for t in range(1, 10):\n            _, h, valence = ATOM_TYPES[t]\n            if not self.type_fits(t):\n                continue\n            for bond in (1, 2, 3):\n                if bond > valence - h:\n                    continue\n                pointers = [p for p in range(self.last_parent, len(self.types)) if self.residual[p] >= bond]\n                if pointers:\n                    options.setdefault(t, {})[bond] = pointers\n        return options\n\n    def close_options(self):\n        if len(self.types) < 2 or self.closures >= MAX_CLOSURES:\n            return {}\n        newest = len(self.types) - 1\n        low = max(self.parent_of[newest], self.last_close) + 1\n        options = {}\n        for bond in (1, 2, 3):\n            if self.residual[newest] < bond:\n                continue\n            pointers = [p for p in range(low, newest) if self.residual[p] >= bond and (p, newest) not in self.bonded]\n            if pointers:\n                options[bond] = pointers\n        return options\n\n    def masks(self, token):\n        masks, legal = super().masks(token)\n        complete = self.used == Counter(self.budget) and not any(self.residual)\n        if not complete:\n            masks[0] &= ~(1 << STOP)\n            if token[0] == STOP:\n                legal = False\n        return masks, legal\n\n    def apply(self, token):\n        _, legal = self.masks(token)\n        if not legal:\n            raise ValueError(f"illegal complete-graph action at step {self.step}: {token}")\n        kind, atom, bond, pointer = token\n        if kind == ADD and self.types:\n            self.edges.append((pointer, len(self.types), bond))\n        elif kind == CLOSE:\n            self.edges.append((pointer, len(self.types) - 1, bond))\n        super().apply(token)\n\n    def snapshot(self):\n        types = np.zeros(MAX_ATOMS, dtype=np.int64)\n        residual = np.zeros(MAX_ATOMS, dtype=np.float32)\n        adjacency = np.zeros((MAX_ATOMS, MAX_ATOMS), dtype=np.float32)\n        types[:len(self.types)] = self.types\n        residual[:len(self.types)] = self.residual\n        for a, b, order in self.edges:\n            adjacency[a, b] = adjacency[b, a] = order\n        remaining = [(self.budget[e] - self.used[e]) / d for e, d in zip(ELEMENTS, (32, 66, 12, 16))]\n        summary = remaining + [sum(self.residual) / 128, len(self.types) / 32,\n                               self.closures / 8, self.last_parent / 32]\n        return types, residual, adjacency, np.asarray(summary, dtype=np.float32)\n\n    def graph(self):\n        if not self.stopped or any(self.residual) or self.used != Counter(self.budget):\n            raise ValueError("graph is incomplete")\n        graph = Graph(tuple(self.types), tuple(self.edges))\n        mol = Chem.RWMol()\n        for t in graph.types:\n            symbol, h, _ = ATOM_TYPES[t]\n            atom = Chem.Atom(symbol)\n            atom.SetNumExplicitHs(h)\n            atom.SetNoImplicit(True)\n            mol.AddAtom(atom)\n        for a, b, order in graph.edges:\n            mol.AddBond(a, b, (Chem.BondType.SINGLE, Chem.BondType.DOUBLE, Chem.BondType.TRIPLE)[order - 1])\n        try:\n            Chem.SanitizeMol(mol)\n        except (Chem.AtomValenceException, Chem.KekulizeException):\n            return None\n        key = Chem.MolToSmiles(mol, canonical=True, isomericSmiles=False)\n        parsed, _ = parse_graph(key)\n        return parsed if parsed is not None and parsed.counts == graph.counts else None\n\n\ndef motif_key(graph):\n    candidates = []\n    for order in itertools.permutations(range(len(graph.types))):\n        pos = {old: new for new, old in enumerate(order)}\n        edges = tuple(sorted((min(pos[a], pos[b]), max(pos[a], pos[b]), bnd) for a, b, bnd in graph.edges))\n        candidates.append((tuple(graph.types[i] for i in order), edges))\n    return min(candidates)\n\n\n@lru_cache(maxsize=8192)\ndef motifs(graph):\n    result = set()\n    for t in graph.types:\n        result.add(((t,), ()))\n    adjacency = [[] for _ in graph.types]\n    for a, b, bond in graph.edges:\n        result.add(motif_key(Graph((graph.types[a], graph.types[b]), ((0, 1, bond),))))\n        adjacency[a].append((b, bond))\n        adjacency[b].append((a, bond))\n    for center, neighbors in enumerate(adjacency):\n        for (a, ba), (b, bb) in itertools.combinations(neighbors, 2):\n            # Use induced bonds, including triangles; parent H counts stay fixed.\n            lookup = {tuple(sorted((x, y))): o for x, y, o in graph.edges}\n            edges = [(0, 1, ba), (1, 2, bb)]\n            if tuple(sorted((a, b))) in lookup:\n                edges.append((0, 2, lookup[tuple(sorted((a, b)))]))\n            result.add(motif_key(Graph((graph.types[a], graph.types[center], graph.types[b]), tuple(edges))))\n    return frozenset(result)\n\n\ndef vocabulary(records, cap=128):\n    counts = Counter(key for r in records for key in motifs(r["graph"]))\n    return sorted(counts, key=lambda k: (-counts[k], k))[:cap]\n\n\ndef prep_peaks(peaks, precursor):\n    if not math.isfinite(precursor) or precursor <= 0:\n        raise ValueError("precursor must be finite and positive")\n    if any(not math.isfinite(m) or not math.isfinite(i) or i < 0 for m, i in peaks):\n        raise ValueError("peaks must be finite with nonnegative intensities")\n    kept = [(m, i, p) for p, (m, i) in enumerate(peaks) if 0 < m <= precursor + 2 and i > 0]\n    maximum = max((i for _, i, _ in kept), default=0)\n    kept = [(m, i / maximum, p) for m, i, p in kept if i / maximum >= 1e-3]\n    kept = sorted(sorted(kept, key=lambda v: (-v[1], v[2]))[:160], key=lambda v: (v[0], v[2]))\n    features = np.zeros((160, 7), dtype=np.float32)\n    mask = np.zeros(160, dtype=np.float32)\n    bins = np.zeros(2000, dtype=np.float32)\n    for p, (m, intensity, _) in enumerate(kept):\n        root = math.sqrt(intensity)\n        features[p] = (m / 1000, (precursor - m) / 1000, root,\n                       math.sin(2 * math.pi * m), math.cos(2 * math.pi * m),\n                       math.sin(20 * math.pi * m), math.cos(20 * math.pi * m))\n        mask[p] = 1\n        if m < 2000:\n            bins[int(m)] = max(bins[int(m)], root)\n    phases = (2 * math.pi * np.asarray([m for m, _, _ in kept]))[:, None] * MASS_FREQUENCIES\n    weights = np.asarray([math.sqrt(i) for _, i, _ in kept])\n    fine = np.concatenate([np.einsum(\'i,ij->j\', weights, np.cos(phases)),\n                           np.einsum(\'i,ij->j\', weights, np.sin(phases))])\n    norm = np.linalg.norm(bins)\n    bins = bins / norm if norm else bins\n    fine_norm = np.linalg.norm(fine)\n    fine = fine / fine_norm if fine_norm else fine\n    target = np.concatenate([bins, fine]).astype(np.float32)\n    target_norm = np.linalg.norm(target)\n    return features, mask, target / target_norm if target_norm else target\n\n\ndef neutral_mass(row):\n    if row["adduct"] not in ADDUCT_SHIFT:\n        raise ValueError("unsupported adduct")\n    value = Decimal(row["precursor_mz"])\n    if not value.is_finite() or value <= 0:\n        raise ValueError("invalid precursor")\n    ion = int((value * 1_000_000).to_integral_value(rounding=ROUND_HALF_EVEN))\n    resolution = Decimal(10) ** value.as_tuple().exponent\n    rounding = int((resolution * 500_000).to_integral_value(rounding="ROUND_CEILING"))\n    return ion - ADDUCT_SHIFT[row["adduct"]], max(1, rounding)\n\n\nclass FormulaTable:\n    def __init__(self):\n        rows = []\n        for c in range(1, 33):\n            for n in range(min(12, 32 - c) + 1):\n                for o in range(min(16, 32 - c - n) + 1):\n                    if c + n + o < 2:\n                        continue\n                    for h in range((2 * c + 2 + n) % 2, 2 * c + n + 3, 2):\n                        counts = (c, h, n, o)\n                        mass = sum(MASS[e] * number for e, number in zip(ELEMENTS, counts))\n                        if mass <= 1_000_000_000:\n                            rows.append((mass, counts))\n        rows.sort()\n        self.mass = np.asarray([r[0] for r in rows], dtype=np.int64)\n        self.counts = np.asarray([r[1] for r in rows], dtype=np.int64)\n\n    def hypotheses(self, row):\n        observed, error = neutral_mass(row)\n        tolerance = max(100, int(abs(observed) * 20 / 1_000_000))\n        # First use a conservative superset; retain only numerical acceptance.\n        lo, hi = np.searchsorted(self.mass, [observed - tolerance - error - 100,\n                                            observed + tolerance + error + 100])\n        candidates = []\n        for mass, counts in zip(self.mass[lo:hi], self.counts[lo:hi]):\n            arithmetic = math.ceil(sum(RESIDUAL[e] * int(v) for e, v in zip(ELEMENTS, counts)) / 1000) + 2\n            if abs(int(mass) - observed) + error + arithmetic <= tolerance:\n                candidates.append(tuple(int(v) for v in counts))\n        return candidates\n\n\n@lru_cache(maxsize=8192)\ndef canonical_graph_features(graph):\n    """Full canonical connectivity and stereo labels, independent of atom order.\n\n    Connectivity identities remain the benchmark grouping key. Stereo labels\n    are retained separately so grouping cannot erase encoder input distinctions.\n    Generated graphs currently carry no stereo labels.\n    """\n    if graph.stereo_smiles:\n        mol = Chem.MolFromSmiles(graph.stereo_smiles)\n        Chem.Kekulize(mol, clearAromaticFlags=True)\n        for atom in mol.GetAtoms():\n            h = atom.GetTotalNumHs()\n            valence = h + int(sum(b.GetBondTypeAsDouble() for b in atom.GetBonds()))\n            atom.SetIsotope(100 + TYPE_ID[(atom.GetSymbol(), h, valence)])\n    else:\n        editable = Chem.RWMol()\n        for t in graph.types:\n            element, hydrogens, _ = ATOM_TYPES[t]\n            atom = Chem.Atom(element)\n            atom.SetNumExplicitHs(hydrogens)\n            atom.SetNoImplicit(True)\n            # Internal colors retain parent atom types for incomplete motifs.\n            # They are serialization labels, not chemical isotope inputs.\n            atom.SetIsotope(100 + t)\n            editable.AddAtom(atom)\n        for a, b, order in graph.edges:\n            editable.AddBond(a, b, (Chem.BondType.SINGLE, Chem.BondType.DOUBLE, Chem.BondType.TRIPLE)[order - 1])\n        mol = editable.GetMol()\n        Chem.SanitizeMol(mol)\n    mol = Chem.MolFromSmiles(Chem.MolToSmiles(mol, canonical=True, isomericSmiles=True))\n    Chem.AssignStereochemistry(mol, cleanIt=True, force=True)\n    atoms = np.zeros((MAX_ATOMS, 21), dtype=np.float32)\n    # Canonical local chiral parity and E/Z remain distinct after serialization.\n    Chem.Kekulize(mol, clearAromaticFlags=True)\n    edges = np.zeros((MAX_ATOMS, MAX_ATOMS, 5), dtype=np.float32)\n    for atom in mol.GetAtoms():\n        atoms[atom.GetIdx(), atom.GetIsotope() - 100] = 1\n        chirality = int(atom.GetChiralTag())\n        atoms[atom.GetIdx(), 18 + chirality] = 1\n    for bond in mol.GetBonds():\n        a, b = bond.GetBeginAtomIdx(), bond.GetEndAtomIdx()\n        edges[a, b, int(bond.GetBondTypeAsDouble()) - 1] = 1\n        stereo = bond.GetStereo()\n        if stereo in (Chem.BondStereo.STEREOE, Chem.BondStereo.STEREOTRANS):\n            edges[a, b, 3] = 1\n        elif stereo in (Chem.BondStereo.STEREOZ, Chem.BondStereo.STEREOCIS):\n            edges[a, b, 4] = 1\n        edges[b, a] = edges[a, b]\n    result = np.concatenate([atoms.ravel(), edges.ravel()])\n    result.setflags(write=False)\n    return result\n\n\ndef graph_tensors(graphs, device):\n    length = max(len(g.types) for g in graphs)\n    types = np.zeros((len(graphs), length), dtype=np.int64)\n    bonds = np.zeros((len(graphs), length, length), dtype=np.float32)\n    for i, g in enumerate(graphs):\n        types[i, :len(g.types)] = g.types\n        for a, b, order in g.edges:\n            bonds[i, a, b] = bonds[i, b, a] = order\n    canonical = np.stack([canonical_graph_features(g) for g in graphs])\n    return (torch.as_tensor(types, device=device), torch.as_tensor(bonds, device=device),\n            torch.as_tensor(canonical, device=device))\n\n\nclass GraphEncoder(nn.Module):\n    def __init__(self, width):\n        super().__init__()\n        self.atom = nn.Embedding(18, width, padding_idx=0)\n        self.own = nn.ModuleList(nn.Linear(width, width) for _ in range(3))\n        self.neighbor = nn.ModuleList(nn.Linear(width, width, bias=False) for _ in range(3))\n        self.output = nn.Linear(width * 2, width)\n        self.canonical = nn.Linear(CANONICAL_GRAPH_DIM, width, bias=False)\n\n    def forward(self, types, bonds, canonical):\n        mask = (types != 0).unsqueeze(-1)\n        h = self.atom(types)\n        for own, neighbor in zip(self.own, self.neighbor):\n            h = F.gelu(own(h) + neighbor(bonds @ h)) * mask\n        summed = h.sum(1)\n        return self.output(torch.cat([summed / mask.sum(1).clamp_min(1), summed / 8], -1)) + self.canonical(canonical)\n\n\ndef block(width):\n    return Block(d_model=width, n_heads=3, head_dim=32, d_state=8, chunk=16)\n\n\nclass SpectrumEncoder(nn.Module):\n    def __init__(self, width=96):\n        super().__init__()\n        self.peak = nn.Linear(7, width)\n        self.forward_layers = nn.ModuleList(block(width) for _ in range(2))\n        self.reverse_layers = nn.ModuleList(block(width) for _ in range(2))\n        self.adduct = nn.Embedding(4, 8)\n        self.meta = nn.Linear(13, width)\n        self.pool = nn.Linear(width * 2, width)\n\n    def forward(self, peaks, mask, meta, adduct):\n        original = self.peak(peaks) * mask.unsqueeze(-1)\n        forward, reverse = original, original.flip(1)\n        for layer in self.forward_layers:\n            forward = layer(forward) * mask.unsqueeze(-1)\n        for layer in self.reverse_layers:\n            reverse = layer(reverse) * mask.flip(1).unsqueeze(-1)\n        memory = (forward + reverse.flip(1)) * 0.5\n        average = (memory * mask.unsqueeze(-1)).sum(1) / mask.sum(1).clamp_min(1).unsqueeze(-1)\n        maximum = memory.masked_fill(~mask.bool().unsqueeze(-1), -1e4).max(1).values\n        maximum = torch.where(mask.sum(1, keepdim=True) > 0, maximum, torch.zeros_like(maximum))\n        context = self.pool(torch.cat([average, maximum], -1))\n        context = context + self.meta(torch.cat([meta, self.adduct(adduct)], -1))\n        return context, memory\n\n\nclass SubstructurePredictor(nn.Module):\n    def __init__(self, n_patterns):\n        super().__init__()\n        self.encoder = SpectrumEncoder()\n        self.head = nn.Linear(96, n_patterns)\n\n    def forward(self, batch):\n        context, _ = self.encoder(*batch[:4])\n        return self.head(context)\n\n\ndef batch_inputs(records, device):\n    return tuple(torch.as_tensor(np.stack([r[k] for r in records]), device=device)\n                 for k in ("peaks", "mask", "meta", "adduct", "bins"))\n\n\ndef substructure_context(model, records, device):\n    graphs, weights, owners = [], [], []\n    for i, r in enumerate(records):\n        for pattern, confidence in r.get("predicted", []):\n            graphs.append(Graph(pattern[0], pattern[1]))\n            weights.append(confidence)\n            owners.append(i)\n    result = torch.zeros(len(records), 96, device=device)\n    if graphs:\n        encoded = model.graph_encoder(*graph_tensors(graphs, device))\n        confidence = torch.tensor(weights, device=device).unsqueeze(-1)\n        owner = torch.tensor(owners, device=device)\n        result.index_add_(0, owner, encoded * confidence)\n        denominator = torch.zeros(len(records), 1, device=device)\n        denominator.index_add_(0, owner, confidence)\n        result = result / denominator.clamp_min(1)\n    return result\n\n\n@lru_cache(maxsize=8192)\ndef teacher_example(types, edges):\n    """Cache validated grammar data by connectivity, using compact exact integers.\n\n    The CPU profile found repeated replay across paired measurements/epochs.\n    Cache entries are immutable; batch collation owns its writable arrays.\n    """\n    graph = Graph(types, edges)\n    trace = graph.trace()\n    length = len(trace) - 1\n    snapshots = [np.zeros((length, MAX_ATOMS), dtype=np.uint8),\n                 np.zeros((length, MAX_ATOMS), dtype=np.uint8),\n                 np.zeros((length, MAX_ATOMS, MAX_ATOMS), dtype=np.uint8),\n                 np.zeros((length, 8), dtype=np.float32)]\n    masks = [np.zeros((length, n), dtype=bool) for n in (5,18,4,MAX_ATOMS)]\n    state = CompleteState(graph.counts)\n    for step, (previous, target) in enumerate(zip(trace, trace[1:])):\n        state.apply(previous)\n        legal_masks, legal = state.masks(target)\n        if not legal:\n            raise ValueError(f\'teacher trace illegal: {types}, step {step}, {target}\')\n        for output, value in zip(snapshots, state.snapshot()):\n            output[step] = value\n        for output, bitmask in zip(masks, legal_masks):\n            for j in range(output.shape[-1]):\n                output[step,j] = bool(bitmask & (1 << j))\n    state.apply(trace[-1])\n    for output in masks:\n        output[~output.any(-1),0] = True\n    tokens, targets = np.asarray(trace[:-1], dtype=np.uint8), np.asarray(trace[1:], dtype=np.uint8)\n    for array in [tokens, targets, *snapshots, *masks]:\n        array.setflags(write=False)\n    return tokens, targets, snapshots, masks\n\n\ndef teacher_batch(graphs, device):\n    examples = [teacher_example(g.types, g.edges) for g in graphs]\n    length = max(len(example[0]) for example in examples)\n    tokens = np.zeros((len(graphs), length, 4), dtype=np.int64)\n    targets = np.zeros_like(tokens)\n    valid = np.zeros((len(graphs), length), dtype=np.float32)\n    snapshots = [np.zeros((len(graphs), length, MAX_ATOMS), dtype=np.int64),\n                 np.zeros((len(graphs), length, MAX_ATOMS), dtype=np.float32),\n                 np.zeros((len(graphs), length, MAX_ATOMS, MAX_ATOMS), dtype=np.float32),\n                 np.zeros((len(graphs), length, 8), dtype=np.float32)]\n    masks = [np.zeros((len(graphs), length, n), dtype=bool) for n in (5, 18, 4, MAX_ATOMS)]\n    for output in masks:\n        output[:,:,0] = True\n    for b, (input_tokens, output_tokens, saved_states, saved_masks) in enumerate(examples):\n        count = len(input_tokens)\n        tokens[b,:count], targets[b,:count], valid[b,:count] = input_tokens, output_tokens, 1\n        for output, saved in zip(snapshots, saved_states):\n            output[b,:count] = saved\n        for output, saved in zip(masks, saved_masks):\n            output[b,:count] = saved\n    convert = lambda a: torch.as_tensor(a, device=device)\n    return convert(tokens), convert(targets), convert(valid), tuple(map(convert, snapshots)), tuple(map(convert, masks))\n\n\nclass CompletionModel(nn.Module):\n    def __init__(self):\n        super().__init__()\n        width = 96\n        self.spectrum_encoder = SpectrumEncoder(width)\n        self.graph_encoder = GraphEncoder(width)\n        self.formula = nn.Sequential(nn.Linear(4, width), nn.GELU(), nn.Linear(width, width))\n        self.formula_query = nn.Linear(width, width)\n        self.kind_emb = nn.Embedding(5, width, padding_idx=0)\n        self.type_emb = nn.Embedding(18, width, padding_idx=0)\n        self.bond_emb = nn.Embedding(4, width)\n        self.pointer_emb = nn.Embedding(MAX_ATOMS, width)\n        self.position = nn.Embedding(MAX_STEPS, width)\n        self.state_projection = nn.Linear(8, width)\n        self.residual_projection = nn.Linear(1, width)\n        self.neighbor_projection = nn.Linear(width, width, bias=False)\n        self.layers = nn.ModuleList(block(width) for _ in range(2))\n        self.cross = nn.MultiheadAttention(width, 4, batch_first=True)\n        self.norm = RmsNorm(width)\n        self.kind_head = nn.Linear(width, 5)\n        self.type_head = nn.Linear(width, 18)\n        self.bond_head = nn.Linear(width, 4)\n        self.pointer_query = nn.Linear(width, width)\n        # Fourier targets are signed; a nonnegative head would erase them.\n        self.forward_spectrum = nn.Sequential(nn.Linear(width + 13, width), nn.GELU(), nn.Linear(width, SPECTRUM_DIM))\n\n    def predict_spectrum(self, encoded, inputs):\n        conditions = torch.cat([inputs[2], self.spectrum_encoder.adduct(inputs[3])], -1)\n        return F.normalize(self.forward_spectrum(torch.cat([encoded, conditions], -1)), dim=-1)\n\n    def condition(self, records, device, conditional=True):\n        if not conditional:\n            return torch.zeros(len(records), 96, device=device), None, None\n        peaks, mask, meta, adduct, _ = batch_inputs(records, device)\n        context, memory = self.spectrum_encoder(peaks, mask, meta, adduct)\n        sub = substructure_context(self, records, device)\n        memory = torch.cat([memory, sub.unsqueeze(1)], 1)\n        padding = torch.cat([~mask.bool(), torch.zeros(len(records), 1, device=device, dtype=torch.bool)], 1)\n        return context + sub, memory, padding\n\n    def formula_embedding(self, counts):\n        return self.formula(counts / counts.new_tensor([32, 66, 12, 16]))\n\n    def hidden(self, tokens, snapshots, counts, context, memory, padding):\n        types, residual, adjacency, summary = snapshots\n        x = sum(embedding(tokens[..., i]) for i, embedding in enumerate((self.kind_emb, self.type_emb, self.bond_emb, self.pointer_emb)))\n        x = x + self.position(torch.arange(tokens.shape[1], device=tokens.device))\n        x = x + self.state_projection(summary)\n        x = x + self.formula_embedding(counts).unsqueeze(1) + context.unsqueeze(1)\n        for layer in self.layers:\n            x = layer(x)\n        if memory is not None:\n            x = x + self.cross(x, memory, memory, key_padding_mask=padding, need_weights=False)[0]\n        return self.norm(x)\n\n    def fields(self, hidden, chosen_types, chosen_bonds, snapshots):\n        types, residual, adjacency, _ = snapshots\n        atom_memory = self.type_emb(types)\n        atom_memory = atom_memory + self.neighbor_projection(adjacency @ atom_memory)\n        atom_memory = atom_memory + self.residual_projection(residual.unsqueeze(-1) / 4)\n        atom_memory = atom_memory + self.pointer_emb(torch.arange(MAX_ATOMS, device=hidden.device))\n        selected = hidden + self.type_emb(chosen_types)\n        pointer = self.pointer_query(selected + self.bond_emb(chosen_bonds))\n        return self.kind_head(hidden), self.type_head(hidden), self.bond_head(selected), (pointer.unsqueeze(-2) * atom_memory).sum(-1) / math.sqrt(96)\n\n    def likelihood(self, graphs, records, device, conditional=True):\n        tokens, targets, valid, snapshots, masks = teacher_batch(graphs, device)\n        counts = torch.tensor([g.counts for g in graphs], device=device, dtype=torch.float32)\n        context, memory, padding = self.condition(records, device, conditional)\n        hidden = self.hidden(tokens, snapshots, counts, context, memory, padding)\n        logits = self.fields(hidden, targets[..., 1], targets[..., 2], snapshots)\n        active = [valid, valid * (targets[..., 0] == ADD),\n                  valid * ((targets[..., 0] == ADD) | (targets[..., 0] == CLOSE)) * (snapshots[0].count_nonzero(-1) > 0),\n                  valid * ((targets[..., 0] == ADD) | (targets[..., 0] == CLOSE)) * (snapshots[0].count_nonzero(-1) > 0)]\n        total = torch.zeros_like(valid)\n        for field, (values, mask, weight) in enumerate(zip(logits, masks, active)):\n            masked = F.log_softmax(values.masked_fill(~mask, -1e4), -1)\n            total += masked.gather(-1, targets[..., field].unsqueeze(-1)).squeeze(-1) * weight\n        return total.sum(1) / valid.sum(1).clamp_min(1)\n\n\n@torch.no_grad()\ndef sample_graphs(model, record, formulas, device, trajectories=32, seed=42):\n    rng = torch.Generator(device=device).manual_seed(seed)\n    candidates, counters = {}, Counter()\n    for formula in formulas:\n        states = [CompleteState(formula) for _ in range(trajectories)]\n        traces = [[(START, 0, 0, 0)] for _ in states]\n        for state in states:\n            state.apply((START, 0, 0, 0))\n        histories = [[state.snapshot()] for state in states]\n        context, memory, padding = model.condition([record] * trajectories, device)\n        live = list(range(trajectories))\n        for step in range(MAX_STEPS - 1):\n            if not live:\n                break\n            # Retain exact replay snapshots; decoder prefixes remain unchanged.\n            tokens = torch.tensor([traces[i] for i in live], device=device)\n            snapshots = [histories[i] for i in live]\n            packed = tuple(torch.as_tensor(np.stack([[s[k] for s in row] for row in snapshots]), device=device) for k in range(4))\n            counts = torch.tensor([formula] * len(live), device=device, dtype=torch.float32)\n            h = model.hidden(tokens, packed, counts, context[live], memory[live], padding[live])[:, -1:]\n            current = tuple(x[:, -1:] for x in packed)\n            samples = np.zeros((len(live), 4), dtype=np.int64)\n            dead = np.zeros(len(live), dtype=bool)\n            # Batch each conditional action field to avoid a GPU synchronization\n            # and a complete pointer-head computation for every trajectory.\n            for field, size in enumerate((5, 18, 4, MAX_ATOMS)):\n                masks = np.zeros((len(live), size), dtype=bool)\n                for local, global_index in enumerate(live):\n                    state = states[global_index]\n                    kind, atom, bond = (int(v) for v in samples[local, :3])\n                    if field == 0:\n                        kind = ADD\n                    inactive = field and (kind == STOP or (kind == CLOSE and field == 1)\n                                          or (len(state.types) == 0 and field >= 2))\n                    bits = 1 if inactive or dead[local] else state.masks((kind, atom, bond, 0))[0][field]\n                    if not bits:\n                        dead[local] = True\n                        counters["dead_end"] += 1\n                        bits = 1\n                    masks[local] = [bool(bits & (1 << j)) for j in range(size)]\n                values = model.fields(h, torch.as_tensor(samples[:, 1:2], device=device),\n                                      torch.as_tensor(samples[:, 2:3], device=device), current)[field][:, 0]\n                mask = torch.as_tensor(masks, device=device)\n                probability = F.softmax(values.masked_fill(~mask, -1e4), -1)\n                samples[:, field] = torch.multinomial(probability, 1, generator=rng).flatten().cpu().numpy()\n            next_live = []\n            for local, global_index in enumerate(live):\n                state = states[global_index]\n                if dead[local]:\n                    continue\n                token = tuple(int(v) for v in samples[local])\n                state.apply(token)\n                traces[global_index].append(token)\n                if token[0] == STOP:\n                    graph = state.graph()\n                    if graph is not None:\n                        candidates[graph.identity] = graph\n                        counters["valid_finished"] += 1\n                    else:\n                        counters["sanitization_failed"] += 1\n                else:\n                    histories[global_index].append(state.snapshot())\n                    next_live.append(global_index)\n            live = next_live\n        counters["step_limit"] += len(live)\n    return list(candidates.values()), dict(counters)\n', 'tools/ms2_full_experiment.py': '"""Train and evaluate every neural component of the declared CHNO proposal."""\nimport argparse\nimport copy\nimport csv\nimport hashlib\nimport json\nimport math\nimport random\nimport sys\nimport time\nfrom collections import Counter, defaultdict\nfrom pathlib import Path\n\nimport numpy as np\nimport torch\nfrom torch import nn\nfrom torch.nn import functional as F\nfrom rdkit import Chem\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[1]))\nfrom tools.ms2_full_model import *\nfrom tools.ms2_neural_ranker import metadata, bootstrap_difference\nfrom tools.ms2_spectral_rank import parse_spectrum, content_fp, sha256_file, seeded_positions\nfrom tools.ms2_msgym_corpus import iter_json_entries\n\nDEVICE = torch.device(\'cpu\')\n\n\ndef seed_all(seed):\n    random.seed(seed)\n    np.random.seed(seed)\n    torch.manual_seed(seed)\n\n\ndef emit(message):\n    print(json.dumps(message, allow_nan=False), flush=True)\n\n\ndef make_record(row):\n    peaks, reason = parse_spectrum(row["mzs"], row["intensities"])\n    if reason:\n        return None, "peaks:" + reason\n    try:\n        precursor = float(row["precursor_mz"])\n        features, mask, bins = prep_peaks(peaks, precursor)\n        meta, _ = metadata(row, ADDUCT_IDS)\n        neutral_mass(row)\n    except (ValueError, ArithmeticError):\n        return None, "metadata"\n    if not mask.any():\n        return None, "empty_peaks"\n    graph, reason = parse_graph(row["smiles"])\n    record = {"row": row, "peaks": features, "mask": mask, "bins": bins,\n              "meta": meta, "adduct": ADDUCT_IDS[row["adduct"]], "graph": graph,\n              "identity": identity(row["smiles"]), "predicted": [],\n              "content": content_fp(peaks)}\n    return record, reason\n\n\ndef load_data(args, table):\n    train, val, test = {}, {}, {}\n    with open(args.tsv) as stream:\n        for row in csv.DictReader(stream, delimiter="\\t"):\n            bucket = {"train": train, "val": val, "test": test}.get(row["fold"])\n            if bucket is not None:\n                if row["smiles"] in bucket or bucket is not train or len(train) < args.max_train * 2:\n                    bucket.setdefault(row["smiles"], []).append(row)\n    queries = []\n    for smi, candidates in iter_json_entries(args.prefix, 1 << 30):\n        if smi in test and len(queries) < args.queries:\n            queries.append({"row": test[smi][0], "pool": list(dict.fromkeys(candidates)), "qid": f"TEST-{len(queries):04d}"})\n    if not queries:\n        raise ValueError("no test queries join the pinned prefix")\n    # Use the benchmark val fold only for checkpoint selection and calibration.\n    calibration_rows = [row for rows in list(val.values())[:args.calibration] for row in rows]\n    reserved_ids = {identity(q["row"]["smiles"]) for q in queries}\n    reserved_ids.update(identity(r["smiles"]) for r in calibration_rows)\n    reserved_scaffolds = {scaffold(r["smiles"]) for r in calibration_rows}\n    reserved_scaffolds.update(scaffold(q["row"]["smiles"]) for q in queries)\n    reserved_content = set()\n    for r in calibration_rows + [q["row"] for q in queries]:\n        peaks, error = parse_spectrum(r["mzs"], r["intensities"])\n        if error is None:\n            reserved_content.add(content_fp(peaks))\n    audit, fit, calibration, seen_ids, seen_measurements = Counter(), [], [], set(), set()\n    validated_graphs = set()\n    for row in (row for rows in train.values() for row in rows):\n        key = identity(row["smiles"])\n        if key not in seen_ids and len(seen_ids) >= args.max_train:\n            continue\n        group = scaffold(row["smiles"])\n        if key in reserved_ids or group in reserved_scaffolds:\n            audit["train_heldout_identity_or_scaffold"] += 1\n            continue\n        r, reason = make_record(row)\n        if r is None or reason:\n            audit["train:" + (reason or "unknown")] += 1\n            continue\n        measurement = (key, r["graph"].stereo_smiles, r["content"], r["adduct"],\n                       tuple(r["meta"]), float(row["precursor_mz"]))\n        if r["content"] in reserved_content or measurement in seen_measurements:\n            audit["train_duplicate"] += 1\n            continue\n        hypotheses = table.hypotheses(row)\n        if r["graph"].counts not in hypotheses:\n            audit["train_formula_outside_mass_or_table"] += 1\n            continue\n        r.update(scaffold=group, formula_hypotheses=hypotheses)\n        graph_key = (r[\'graph\'].types, r[\'graph\'].edges)\n        if graph_key not in validated_graphs:\n            teacher_batch([r["graph"]], "cpu")\n            validated_graphs.add(graph_key)\n        fit.append(r)\n        seen_ids.add(key)\n        seen_measurements.add(measurement)\n    for row in calibration_rows:\n        r, reason = make_record(row)\n        if r is None or reason:\n            audit["calibration:" + (reason or "unknown")] += 1\n            continue\n        hypotheses = table.hypotheses(row)\n        if r["graph"].counts not in hypotheses:\n            audit["calibration_formula_outside_mass_or_table"] += 1\n            continue\n        r.update(scaffold=scaffold(row["smiles"]), formula_hypotheses=hypotheses)\n        graph_key = (r[\'graph\'].types, r[\'graph\'].edges)\n        if graph_key not in validated_graphs:\n            teacher_batch([r["graph"]], "cpu")\n            validated_graphs.add(graph_key)\n        calibration.append(r)\n    fit_scaffolds = {r["scaffold"] for r in fit}\n    assert not fit_scaffolds.intersection(reserved_scaffolds)\n    assert not {r["identity"] for r in fit}.intersection(reserved_ids)\n    assert not {r["content"] for r in fit}.intersection(reserved_content)\n    return fit, calibration, queries, dict(audit), reserved_ids, reserved_scaffolds\n\n\ndef training_digest(records):\n    digest = hashlib.sha256()\n    for record in records:\n        if isinstance(record, dict):\n            value = (record.get(\'identity\'), record.get(\'content\'), record.get(\'row\'),\n                     record.get(\'predicted\'), [g.stereo_smiles or g.identity for g in record.get(\'pair_graphs\', [])])\n            digest.update(repr(value).encode())\n        else:\n            digest.update(np.asarray(record).tobytes())\n    return digest.hexdigest()\n\n\ndef molecule_records(records):\n    """The molecular prior/vocabulary counts structures, not measurements."""\n    unique = {}\n    for record in records:\n        unique.setdefault(record[\'identity\'], record)\n    return list(unique.values())\n\n\ndef atomic_checkpoint(value, path):\n    temporary = path.with_suffix(\'.partial\')\n    torch.save(value, temporary)\n    temporary.replace(path)\n\n\ndef fit_loop(model, fit, calibration, objective, epochs, batch_size, out, name, seed):\n    seed_all(seed)\n    optimizer = torch.optim.AdamW(model.parameters(), lr=3e-4, weight_decay=0.01)\n    history, best, minimum = [], None, math.inf\n    started = time.monotonic()\n    protocol = {\'epochs\': epochs, \'batch_size\': batch_size, \'seed\': seed,\n                \'fit\': training_digest(fit), \'calibration\': training_digest(calibration),\n                \'source\': hashlib.sha256(Path(__file__).read_bytes() +\n                          Path(__file__).with_name(\'ms2_full_model.py\').read_bytes()).hexdigest()}\n    completed, progress = out / f\'{name}.pt\', out / f\'{name}_progress.pt\'\n    if completed.exists():\n        checkpoint = torch.load(completed, map_location=DEVICE, weights_only=True)\n        if checkpoint.get(\'protocol\') != protocol or checkpoint.get(\'representation\') != REPRESENTATION_VERSION:\n            raise ValueError(f\'{completed}: training protocol changed; use a new results directory\')\n        model.load_state_dict(checkpoint[\'state\'])\n        emit({\'stage\': name, \'event\': \'restored_completed\'})\n        return model.eval()\n    first_epoch, prior_seconds = 0, 0\n    if progress.exists():\n        checkpoint = torch.load(progress, map_location=DEVICE, weights_only=True)\n        if checkpoint.get(\'protocol\') != protocol:\n            raise ValueError(f\'{progress}: training protocol changed; use a new results directory\')\n        model.load_state_dict(checkpoint[\'state\'])\n        optimizer.load_state_dict(checkpoint[\'optimizer\'])\n        history, best, minimum = checkpoint[\'history\'], checkpoint[\'best\'], checkpoint[\'minimum\']\n        first_epoch, prior_seconds = checkpoint[\'next_epoch\'], checkpoint[\'seconds\']\n        random.setstate(checkpoint[\'random_state\'])\n        state = checkpoint[\'numpy_state\']\n        np.random.set_state((state[0], np.asarray(state[1], dtype=np.uint32), *state[2:]))\n        torch.set_rng_state(checkpoint[\'torch_state\'].cpu())\n        if DEVICE.type == \'cuda\':\n            torch.cuda.set_rng_state_all([s.cpu() for s in checkpoint[\'cuda_state\']])\n        emit({\'stage\': name, \'event\': \'resumed\', \'next_epoch\': first_epoch + 1})\n    emit({"stage": name, "event": "start", "fit": len(fit), "calibration": len(calibration), "epochs": epochs})\n    for epoch in range(first_epoch, epochs):\n        model.train()\n        order = list(fit)\n        random.shuffle(order)\n        train_values = []\n        for start in range(0, len(order), batch_size):\n            batch = order[start:start + batch_size]\n            optimizer.zero_grad(set_to_none=True)\n            value = objective(model, batch)\n            if not torch.isfinite(value):\n                raise RuntimeError(f"{name}: nonfinite loss")\n            value.backward()\n            nn.utils.clip_grad_norm_(model.parameters(), 1)\n            optimizer.step()\n            train_values.append(value.item())\n            if len(train_values) % 64 == 0:\n                emit({"stage": name, "epoch": epoch + 1, "batch": len(train_values),\n                      "train_running": float(np.mean(train_values))})\n        model.eval()\n        with torch.no_grad():\n            valid = [objective(model, calibration[i:i + batch_size]).item() for i in range(0, len(calibration), batch_size)]\n        if not train_values or not valid or not all(math.isfinite(v) for v in valid):\n            raise ValueError(f"{name}: empty split or nonfinite calibration loss")\n        metric = float(np.mean(valid))\n        item = {"stage": name, "epoch": epoch + 1, "train": float(np.mean(train_values)), "calibration": metric}\n        history.append(item)\n        emit(item)\n        if metric < minimum:\n            minimum, best = metric, copy.deepcopy(model.state_dict())\n        numpy_state = np.random.get_state()\n        atomic_checkpoint({\'state\': model.state_dict(), \'optimizer\': optimizer.state_dict(),\n                           \'best\': best, \'minimum\': minimum, \'history\': history, \'next_epoch\': epoch + 1,\n                           \'protocol\': protocol, \'seconds\': prior_seconds + time.monotonic() - started,\n                           \'random_state\': random.getstate(),\n                           \'numpy_state\': (numpy_state[0], numpy_state[1].tolist(), *numpy_state[2:]),\n                           \'torch_state\': torch.get_rng_state(),\n                           \'cuda_state\': torch.cuda.get_rng_state_all() if DEVICE.type == \'cuda\' else []}, progress)\n        (out / f\'{name}_history.json\').write_text(json.dumps({\'history\': history,\n            \'seconds\': prior_seconds + time.monotonic() - started}, indent=2))\n    model.load_state_dict(best)\n    model.eval()\n    atomic_checkpoint({"state": model.cpu().state_dict(), "stage": name, "domain": DOMAIN,\n                "representation": REPRESENTATION_VERSION, "protocol": protocol}, completed)\n    model.to(DEVICE)\n    (out / f"{name}_history.json").write_text(json.dumps({"history": history, "seconds": prior_seconds + time.monotonic() - started}, indent=2))\n    progress.unlink(missing_ok=True)\n    return model\n\n\ndef upstream_objective(vocab):\n    def objective(model, records):\n        present = [motifs(r["graph"]) for r in records]\n        targets = torch.tensor([[key in keys for key in vocab] for keys in present], device=DEVICE, dtype=torch.float32)\n        return F.binary_cross_entropy_with_logits(model(batch_inputs(records, DEVICE)), targets)\n    return objective\n\n\n@torch.no_grad()\ndef predict_substructures(model, records, vocab, batch_size):\n    for start in range(0, len(records), batch_size):\n        batch = records[start:start + batch_size]\n        probabilities = model(batch_inputs(batch, DEVICE)).sigmoid().cpu().numpy()\n        for record, probability in zip(batch, probabilities):\n            selected = np.argsort(-probability)[:6]\n            record["predicted"] = [(vocab[i], float(probability[i])) for i in selected if probability[i] >= 0.2]\n\n\ndef train_upstream(fit, calibration, args, out):\n    folds = {r["scaffold"]: int(hashlib.sha256(r["scaffold"].encode()).hexdigest()[:8], 16) % 3 for r in fit}\n    audits = []\n    for fold in range(3):\n        training = [r for r in fit if folds[r["scaffold"]] != fold]\n        validation = [r for r in fit if folds[r["scaffold"]] == fold]\n        # Vocabulary is fold-train-only too, not mined from the predicted targets.\n        vocab = vocabulary(molecule_records(training))\n        model = SubstructurePredictor(len(vocab)).to(DEVICE)\n        fit_loop(model, training, calibration, upstream_objective(vocab), args.upstream_epochs, args.batch_size,\n                 out, f"upstream_fold{fold}", args.seed + fold)\n        predict_substructures(model, validation, vocab, args.batch_size)\n        audits.append({"fold": fold, "train": len(training), "predicted": len(validation),\n                       "scaffold_overlap": len({r["scaffold"] for r in training} & {r["scaffold"] for r in validation})})\n        torch.save({"patterns": vocab, "domain": DOMAIN}, out / f"upstream_fold{fold}_vocab.pt")\n    vocab = vocabulary(molecule_records(fit))\n    model = SubstructurePredictor(len(vocab)).to(DEVICE)\n    fit_loop(model, fit, calibration, upstream_objective(vocab), args.upstream_epochs,\n             args.batch_size, out, "upstream_final", args.seed)\n    predict_substructures(model, calibration, vocab, args.batch_size)\n    torch.save({"patterns": vocab, "domain": DOMAIN}, out / "upstream_final_vocab.pt")\n    (out / "upstream_crossfit_audit.json").write_text(json.dumps(audits, indent=2))\n    return model, vocab\n\n\ndef completion_objective(conditional, auxiliary):\n    def objective(model, records):\n        graphs = [r["graph"] for r in records]\n        likelihood = model.likelihood(graphs, records, DEVICE, conditional)\n        result = -likelihood.mean()\n        if conditional:\n            context, _, _ = model.condition(records, DEVICE)\n            query = model.formula_query(context)\n            logits, targets = [], []\n            maximum = max(len(r["formula_hypotheses"]) for r in records)\n            for i, record in enumerate(records):\n                counts = torch.tensor(record["formula_hypotheses"], device=DEVICE, dtype=torch.float32)\n                values = (model.formula_embedding(counts) * query[i]).sum(-1) / math.sqrt(96)\n                logits.append(F.pad(values, (0, maximum - len(values)), value=-1e4))\n                targets.append(record["formula_hypotheses"].index(record["graph"].counts))\n            result = result + F.cross_entropy(torch.stack(logits), torch.tensor(targets, device=DEVICE))\n            encoded = model.graph_encoder(*graph_tensors(graphs, DEVICE))\n            inputs = batch_inputs(records, DEVICE)\n            prediction = model.predict_spectrum(encoded, inputs)\n            result += auxiliary * (1 - (prediction * inputs[4]).sum(-1)).mean()\n            result += 0.2 * paired_candidate_loss(model, records)\n        return result\n    return objective\n\n\ndef paired_candidate_loss(model, records):\n    """Same-formula alternatives update both representations and the decoder."""\n    candidates, repeated, sizes = [], [], []\n    for record in records:\n        graphs = record.get("pair_graphs", [record["graph"]])\n        if len(graphs) < 2:\n            continue\n        if any(g.counts != graphs[0].counts for g in graphs):\n            raise ValueError("paired candidates must have identical molecular formulas")\n        candidates.extend(graphs)\n        repeated.extend([record] * len(graphs))\n        sizes.append(len(graphs))\n    if not candidates:\n        return next(model.parameters()).sum() * 0\n    # The profile showed repeated small encoder/decoder calls dominating this\n    # loss. Candidates are independent; batching preserves each query\'s CE group.\n    context, _, _ = model.condition(repeated, DEVICE)\n    encoded = model.graph_encoder(*graph_tensors(candidates, DEVICE))\n    alignment = (F.normalize(context, dim=-1) * F.normalize(encoded, dim=-1)).sum(-1) / 0.1\n    likelihood = model.likelihood(candidates, repeated, DEVICE)\n    target = torch.zeros(1, device=DEVICE, dtype=torch.long)\n    losses, offset = [], 0\n    for size in sizes:\n        losses.append(F.cross_entropy(alignment[offset:offset+size].unsqueeze(0), target) +\n                      F.cross_entropy(likelihood[offset:offset+size].unsqueeze(0), target))\n        offset += size\n    return torch.stack(losses).mean()\n\n\ndef prepare_pair_candidates(fit, calibration, forbidden, reserved_scaffolds, seed):\n    index = defaultdict(list)\n    for record in molecule_records(fit):\n        index[record["graph"].counts].append(record["graph"])\n    rng = random.Random(seed)\n    candidates = {}\n    for record in fit + calibration:\n        graph = record[\'graph\']\n        if graph not in candidates:\n            candidates[graph] = decoys(record, index, rng, forbidden, reserved_scaffolds)\n        record["pair_graphs"] = candidates[graph]\n\n\ndef decoys(record, index, rng, forbidden, forbidden_scaffolds):\n    graph = record["graph"]\n    result = {g.identity: g for g in index.get(graph.counts, []) if g.identity != graph.identity}\n    if len(result) < 4:\n        bonds = list(graph.edges)\n        for _ in range(60):\n            if len(bonds) < 2 or len(result) >= 4:\n                break\n            first, second = rng.sample(bonds, 2)\n            a, b, order = first\n            c, d, other = second\n            if order != other or len({a, b, c, d}) != 4:\n                continue\n            # Build from our graph ordering, not RDKit\'s post-kekulization order.\n            editable = Chem.RWMol()\n            for t in graph.types:\n                atom = Chem.Atom(ATOM_TYPES[t][0])\n                editable.AddAtom(atom)\n            for x, y, value in graph.edges:\n                editable.AddBond(x, y, (Chem.BondType.SINGLE, Chem.BondType.DOUBLE, Chem.BondType.TRIPLE)[value - 1])\n            editable.RemoveBond(a, b)\n            editable.RemoveBond(c, d)\n            new_edges = [(a, d), (b, c)] if rng.random() < 0.5 else [(a, c), (a, d)]\n            if any(editable.GetBondBetweenAtoms(x, y) for x, y in new_edges):\n                continue\n            for x, y in new_edges:\n                editable.AddBond(x, y, (Chem.BondType.SINGLE, Chem.BondType.DOUBLE, Chem.BondType.TRIPLE)[order - 1])\n            try:\n                Chem.SanitizeMol(editable)\n            except (Chem.AtomValenceException, Chem.KekulizeException):\n                continue\n            key = Chem.MolToSmiles(editable, canonical=True, isomericSmiles=False)\n            if key in forbidden or key == graph.identity or scaffold(key) in forbidden_scaffolds:\n                continue\n            candidate, _ = parse_graph(key)\n            if candidate is not None and candidate.counts == graph.counts:\n                result[key] = candidate\n    keys = sorted(result)\n    rng.shuffle(keys)\n    return [graph] + [result[k] for k in keys[:4]]\n\n\n@torch.no_grad()\ndef ranking_features(model, prior, graphs, record):\n    records = [record] * len(graphs)\n    context, _, _ = model.condition(records, DEVICE)\n    encoded = model.graph_encoder(*graph_tensors(graphs, DEVICE))\n    dot = (F.normalize(context, dim=-1) * F.normalize(encoded, dim=-1)).sum(-1)\n    conditional = model.likelihood(graphs, records, DEVICE)\n    prior_score = prior.likelihood(graphs, records, DEVICE, False)\n    inputs = batch_inputs(records, DEVICE)\n    predicted_spectrum = model.predict_spectrum(encoded, inputs)\n    similarity = (predicted_spectrum * inputs[4]).sum(-1)\n    support = []\n    for graph in graphs:\n        present = motifs(graph)\n        total = sum(confidence for _, confidence in record.get("predicted", []))\n        support.append(sum(confidence for key, confidence in record.get("predicted", []) if key in present) / max(total, 1e-6))\n    return torch.stack([dot, conditional, prior_score, similarity, torch.tensor(support, device=DEVICE)], -1).cpu().numpy()\n\n\nclass FeatureRanker(nn.Module):\n    def __init__(self, mean, scale):\n        super().__init__()\n        self.register_buffer("mean", torch.tensor(mean, dtype=torch.float32))\n        self.register_buffer("scale", torch.tensor(scale, dtype=torch.float32))\n        self.network = nn.Sequential(nn.Linear(5, 32), nn.GELU(), nn.Linear(32, 1))\n\n    def forward(self, features):\n        return self.network((features - self.mean) / self.scale).squeeze(-1)\n\n\ndef train_ranker(model, prior, fit, calibration, forbidden, reserved_scaffolds, args, out, name):\n    rng = random.Random(args.seed)\n    index = defaultdict(list)\n    for r in fit:\n        index[r["graph"].counts].append(r["graph"])\n    datasets = []\n    audit = {}\n    for split, records in (("fit", fit), ("calibration", calibration)):\n        dataset = []\n        selection = list(records)\n        if split == \'fit\':\n            rng.shuffle(selection)\n        for r in selection:\n            graphs = decoys(r, index, rng, forbidden, reserved_scaffolds)\n            if len(graphs) < 2:\n                continue\n            if split == "fit" and any(g.identity in forbidden for g in graphs):\n                raise RuntimeError("held-out identity in training ranker candidates")\n            features = ranking_features(model, prior, graphs, r)\n            dataset.append(features)\n            if len(dataset) >= args.rank_cap:\n                break\n        audit[split] = {"rankable": len(dataset), "examined_cap": args.rank_cap}\n        datasets.append(dataset)\n        emit({"stage": name + "_features", "split": split, "rankable": len(dataset)})\n    if not all(datasets):\n        raise ValueError("no same-formula negatives: ranker cannot be verified")\n    flattened = np.concatenate(datasets[0])\n    ranker = FeatureRanker(flattened.mean(0), flattened.std(0).clip(1e-3)).to(DEVICE)\n    # Independent fixed feature ablations test the reranking contributions.\n    def objective(ranker, batch):\n        maximum = max(len(x) for x in batch)\n        logits = []\n        for feature in batch:\n            scores = ranker(torch.tensor(feature, device=DEVICE))\n            logits.append(F.pad(scores, (0, maximum - len(scores)), value=-1e4))\n        return F.cross_entropy(torch.stack(logits), torch.zeros(len(batch), dtype=torch.long, device=DEVICE))\n    fit_loop(ranker, datasets[0], datasets[1], objective, args.rank_epochs, 32, out, name, args.seed)\n    (out / f"{name}_negative_audit.json").write_text(json.dumps(audit, indent=2))\n    return ranker\n\n\n@torch.no_grad()\ndef formula_predictions(model, record, table):\n    counts = table.hypotheses(record["row"])\n    if not counts:\n        return []\n    context, _, _ = model.condition([record], DEVICE)\n    query = model.formula_query(context)\n    values = torch.tensor(counts, device=DEVICE, dtype=torch.float32)\n    scores = (model.formula_embedding(values) * query).sum(-1)\n    order = scores.argsort(descending=True).cpu().tolist()\n    return [counts[i] for i in order[:4]]\n\n\n@torch.no_grad()\ndef retrieval_prediction(model, prior, ranker, query, record):\n    canonical_pool = canonical_candidates(query["pool"])\n    pool = list(canonical_pool)\n    scores = [None] * len(pool)\n    if record is not None:\n        supported = [(i, canonical_pool[s]) for i, s in enumerate(pool) if canonical_pool[s] is not None]\n        for start in range(0, len(supported), 32):\n            chunk = supported[start:start + 32]\n            features = ranking_features(model, prior, [g for _, g in chunk], record)\n            values = ranker(torch.tensor(features, device=DEVICE)).cpu().tolist()\n            for (index, _), value in zip(chunk, values):\n                scores[index] = value\n    positions = seeded_positions(query["qid"], len(pool))\n    order = sorted(range(len(pool)), key=lambda i: (scores[i] is None, -(scores[i] or 0), positions[i]))\n    target_identity = identity(query["row"]["smiles"])\n    target = pool.index(target_identity) if target_identity in pool else None\n    uniform = sorted(range(len(pool)), key=lambda i: positions[i])\n    return {"qid": query["qid"], "pool": len(pool), "scored": sum(v is not None for v in scores),\n            "rank": order.index(target) + 1 if target is not None else None,\n            "uniform_rank": uniform.index(target) + 1 if target is not None else None}\n\n\ndef evaluate_full(model, prior, ranker, upstream, vocab, queries, table, args, out):\n    predictions, generation = [], []\n    for query_index, query in enumerate(queries):\n        record, reason = make_record(query["row"])\n        row = {"qid": query["qid"], "status": "ok" if record is not None else reason, "generated": [], "rank": None,\n               "formula_recovered": False, "valid_candidates": 0, "query_identity": identity(query["row"]["smiles"])}\n        row["target_domain"] = reason or "supported"\n        if record is not None:\n            predict_substructures(upstream, [record], vocab, 1)\n            formulas = formula_predictions(model, record, table)\n            # Reference graph is used only for evaluation below, never generation.\n            row["formula_recovered"] = record["graph"] is not None and record["graph"].counts in formulas\n            generated, counters = sample_graphs(model, record, formulas, DEVICE, args.trajectories, args.seed + query_index)\n            row["work"] = counters\n            row["valid_candidates"] = len(generated)\n            if generated:\n                scored = []\n                for start in range(0, len(generated), 32):\n                    feature = ranking_features(model, prior, generated[start:start + 32], record)\n                    with torch.no_grad():\n                        scores = ranker(torch.tensor(feature, device=DEVICE)).cpu().tolist()\n                    scored.extend(scores)\n                ordered = sorted(zip(generated, scored), key=lambda x: (-x[1], x[0].identity))\n                row["generated"] = [g.identity for g, _ in ordered[:25]]\n                row["rank"] = next((i + 1 for i, (g, _) in enumerate(ordered) if g.identity == row["query_identity"]), None)\n            else:\n                row["status"] = "no_valid_generation"\n            actual = motifs(record["graph"]) if record["graph"] is not None else set()\n            row["predicted_patterns"] = [{"types": key[0], "edges": key[1], "confidence": confidence,\n                                           "correct": key in actual} for key, confidence in record["predicted"]]\n        generation.append(row)\n        # Retrieval diagnostic evaluates the same full conditional model on supplied\n        # pools; it cannot replace the primary de novo generation result.\n        predictions.append(retrieval_prediction(model, prior, ranker, query, record))\n        emit({"stage": "evaluation", "query": query_index + 1, "total": len(queries),\n              "generation_status": row["status"], "valid": row["valid_candidates"],\n              "generated_rank": row["rank"], "retrieval_rank": predictions[-1]["rank"]})\n        # Persist progress so Colab interruptions never erase completed queries.\n        (out / "generation_predictions.json").write_text(json.dumps(generation, indent=2))\n        (out / "retrieval_predictions.json").write_text(json.dumps(predictions, indent=2))\n    return generation, predictions\n\n\ndef main(args):\n    global DEVICE\n    DEVICE = torch.device(args.device)\n    if DEVICE.type == "cuda" and (not torch.cuda.is_available() or "T4" not in torch.cuda.get_device_name()):\n        raise RuntimeError("Colab Tesla T4 required")\n    seed_all(args.seed)\n    out = Path(args.out)\n    out.mkdir(parents=True, exist_ok=True)\n    (out / "plan.json").write_text(json.dumps(vars(args), indent=2))\n    table = FormulaTable()\n    fit, calibration, queries, audit, forbidden, reserved_scaffolds = load_data(args, table)\n    emit({"stage": "data", "fit": len(fit), "calibration": len(calibration), "test": len(queries), "audit": audit})\n    (out / "data_audit.json").write_text(json.dumps({"fit": len(fit), "calibration": len(calibration),\n        "test": len(queries), "exclusions": audit, "source_sha256": {"tsv": sha256_file(args.tsv), "prefix": sha256_file(args.prefix)},\n        "fit_identities": [r["identity"] for r in fit], "calibration_identities": [r["identity"] for r in calibration],\n        "test_identities": [identity(q["row"]["smiles"]) for q in queries]}, indent=2))\n    if len(fit) < 50 or len(calibration) < 10:\n        raise ValueError("insufficient domain examples after disjointness exclusions")\n    upstream, vocab = train_upstream(fit, calibration, args, out)\n    prior = CompletionModel().to(DEVICE)\n    fit_loop(prior, molecule_records(fit), molecule_records(calibration), completion_objective(False, 0), args.prior_epochs,\n             args.batch_size, out, "molecular_prior", args.seed)\n    model = CompletionModel().to(DEVICE)\n    model.load_state_dict(prior.state_dict())\n    model.spectrum_encoder.load_state_dict(upstream.encoder.state_dict())\n    prepare_pair_candidates(fit, calibration, forbidden, reserved_scaffolds, args.seed)\n    fit_loop(model, fit, calibration, completion_objective(True, 0.2), args.completion_epochs,\n             args.batch_size, out, "conditional_completion", args.seed)\n    ranker = train_ranker(model, prior, fit, calibration, forbidden, reserved_scaffolds, args, out, "same_formula_ranker")\n    generation, retrieval = evaluate_full(model, prior, ranker, upstream, vocab, queries, table, args, out)\n    hit = lambda row, k: row["rank"] is not None and row["rank"] <= k\n    summary = {"scope": "full declared CHNO neural pipeline; physical stability not evaluated",\n               "domain": DOMAIN, "config": vars(args), "fit": len(fit), "calibration": len(calibration),\n               "test": len(queries), "gpu": torch.cuda.get_device_name() if DEVICE.type == "cuda" else None,\n               "parameters": sum(p.numel() for p in model.parameters()),\n               "generation": {f"top{k}": sum(hit(r, k) for r in generation) / len(queries) for k in (1, 10, 25)},\n               "retrieval_diagnostic": {f"top{k}": sum(hit(r, k) for r in retrieval) / len(queries) for k in (1, 10, 25)},\n               "formula_top4_recovery": sum(r["formula_recovered"] for r in generation) / len(queries),\n               "generation_status": dict(Counter(r["status"] for r in generation)),\n               "mean_valid_candidates": float(np.mean([r["valid_candidates"] for r in generation])),\n               "limitations": ["physical stability labels absent", "single seed", "neutral CHNO domain",\n                               "unknown energy-count metadata", "connectivity identity excludes stereochemistry",\n                               "PyTorch Mamba-3 reference, not native Rust CUDA training"]}\n    (out / "summary.json").write_text(json.dumps(summary, indent=2))\n    emit(summary)\n\n\nif __name__ == "__main__":\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("--tsv", default="data/pinned/MassSpecGym1.5.tsv")\n    parser.add_argument("--prefix", default="data/pinned/msgym_candidates_formula_prefix64.json")\n    parser.add_argument("--out", default="experiments/molecular_completion/full_t4")\n    parser.add_argument("--device", choices=("cpu", "cuda"), default="cuda")\n    parser.add_argument("--max-train", type=int, default=6000)\n    parser.add_argument("--calibration", type=int, default=1000)\n    parser.add_argument("--queries", type=int, default=100)\n    parser.add_argument("--batch-size", type=int, default=16)\n    parser.add_argument("--upstream-epochs", type=int, default=8)\n    parser.add_argument("--prior-epochs", type=int, default=10)\n    parser.add_argument("--completion-epochs", type=int, default=15)\n    parser.add_argument("--rank-epochs", type=int, default=30)\n    parser.add_argument("--rank-cap", type=int, default=1500)\n    parser.add_argument("--trajectories", type=int, default=32)\n    parser.add_argument("--seed", type=int, default=42)\n    main(parser.parse_args())\n', 'tools/ms2_full_controls.py': '"""Matched decoder and substructure controls for the complete T4 pipeline.\n\nThe Transformer control replaces only the graph decoder. The spectrum encoder,\ntraining split, formula inference, molecular-prior pretraining, losses, ranking,\nand generation budget remain the same. Neither control evaluates physical\nstability. Run only after the full pipeline has completed.\n"""\nimport argparse\nimport hashlib\nimport json\nfrom pathlib import Path\nimport sys\n\nimport torch\nfrom torch import nn\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[1]))\nimport tools.ms2_full_experiment as experiment\nfrom tools.ms2_full_model import CompletionModel, FormulaTable, SubstructurePredictor\nfrom tools.ms2_neural_ranker import bootstrap_difference\n\n\nclass CausalTransformerBlock(nn.Module):\n    """One causal layer matched to two width-96 Mamba-3 decoder blocks."""\n    def __init__(self):\n        super().__init__()\n        self.layer = nn.TransformerEncoderLayer(96, 4, 166, dropout=0,\n            activation="gelu", batch_first=True, norm_first=True)\n\n    def forward(self, x):\n        mask = torch.ones(x.shape[1], x.shape[1], device=x.device, dtype=torch.bool).triu(1)\n        return self.layer(x, src_mask=mask)\n\n\nclass EmptyPredictor(nn.Module):\n    def forward(self, batch):\n        return batch[0].new_zeros(batch[0].shape[0], 0)\n\n\ndef completion_model(transformer=False):\n    model = CompletionModel()\n    if transformer:\n        model.layers = nn.ModuleList([CausalTransformerBlock()])\n    return model.to(experiment.DEVICE)\n\n\ndef restore(model, path):\n    checkpoint = torch.load(path, map_location=experiment.DEVICE, weights_only=True)\n    if checkpoint.get("representation") != experiment.REPRESENTATION_VERSION:\n        raise ValueError(f"{path}: incompatible representation; retrain with {experiment.REPRESENTATION_VERSION} "\n                         "or use the archived v1 sources to reproduce historical results")\n    model.load_state_dict(checkpoint["state"])\n    return model.eval()\n\n\ndef load_upstream(base, fit, calibration, batch_size):\n    # Reconstruct exactly the out-of-fold graph predictions used in completion\n    # training; the final predictor is reserved for the external validation/test.\n    for fold in range(3):\n        vocab = torch.load(base / f"upstream_fold{fold}_vocab.pt", weights_only=True)["patterns"]\n        model = restore(SubstructurePredictor(len(vocab)).to(experiment.DEVICE), base / f"upstream_fold{fold}.pt")\n        records = [r for r in fit if int(hashlib.sha256(r["scaffold"].encode()).hexdigest()[:8], 16) % 3 == fold]\n        experiment.predict_substructures(model, records, vocab, batch_size)\n    vocab = torch.load(base / "upstream_final_vocab.pt", weights_only=True)["patterns"]\n    model = restore(SubstructurePredictor(len(vocab)).to(experiment.DEVICE), base / "upstream_final.pt")\n    experiment.predict_substructures(model, calibration, vocab, batch_size)\n    return model, vocab\n\n\ndef metrics(generation, retrieval):\n    def hit(row, k):\n        return row["rank"] is not None and row["rank"] <= k\n    return {"generation": {f"top{k}": sum(hit(r, k) for r in generation) / len(generation) for k in (1, 10, 25)},\n            "retrieval": {f"top{k}": sum(hit(r, k) for r in retrieval) / len(retrieval) for k in (1, 10, 25)}}\n\n\ndef main(base):\n    args = argparse.Namespace(**json.loads((base / "plan.json").read_text()))\n    experiment.DEVICE = torch.device(args.device)\n    if args.device != "cuda" or "T4" not in torch.cuda.get_device_name():\n        raise RuntimeError("T4 required for matched controls")\n    original = json.loads((base / "summary.json").read_text())\n    table = FormulaTable()\n    fit, calibration, queries, audit, forbidden, reserved = experiment.load_data(args, table)\n    recorded = json.loads((base / "data_audit.json").read_text())\n    if [r["identity"] for r in fit] != recorded["fit_identities"] or len(queries) != original["test"]:\n        raise RuntimeError("control split differs from the full pipeline")\n    upstream, vocab = load_upstream(base, fit, calibration, args.batch_size)\n    results = {"full": {"generation": original["generation"], "retrieval": original["retrieval_diagnostic"],\n                        "parameters": original["parameters"]}}\n    full_generation = json.loads((base / "generation_predictions.json").read_text())\n    full_retrieval = json.loads((base / "retrieval_predictions.json").read_text())\n    controls = base / "controls"\n    controls.mkdir(exist_ok=True)\n    (controls / "plan.json").write_text(json.dumps({"arms": ["transformer_decoder", "no_substructures"],\n        "seed": args.seed, "epochs": {"prior": args.prior_epochs, "conditional": args.completion_epochs,\n        "ranker": args.rank_epochs}, "queries": len(queries), "trajectories_per_formula": args.trajectories,\n        "transformer": {"layers": 1, "width": 96, "heads": 4, "feedforward": 166},\n        "scope": "decoder and substructure ablations; physical stability not assessed"}, indent=2))\n    for arm in ("transformer_decoder", "no_substructures"):\n        experiment.seed_all(args.seed)\n        out = controls / arm\n        out.mkdir(exist_ok=True)\n        arm_fit = [{**r, "predicted": [] if arm == "no_substructures" else r["predicted"]} for r in fit]\n        arm_cal = [{**r, "predicted": [] if arm == "no_substructures" else r["predicted"]} for r in calibration]\n        if arm == "transformer_decoder":\n            prior = completion_model(True)\n            experiment.fit_loop(prior, experiment.molecule_records(arm_fit), experiment.molecule_records(arm_cal), experiment.completion_objective(False, 0),\n                args.prior_epochs, args.batch_size, out, "molecular_prior", args.seed)\n        else:\n            prior = restore(completion_model(), base / "molecular_prior.pt")\n        model = completion_model(arm == "transformer_decoder")\n        model.load_state_dict(prior.state_dict())\n        model.spectrum_encoder.load_state_dict(upstream.encoder.state_dict())\n        experiment.prepare_pair_candidates(arm_fit, arm_cal, forbidden, reserved, args.seed)\n        experiment.fit_loop(model, arm_fit, arm_cal, experiment.completion_objective(True, 0.2),\n            args.completion_epochs, args.batch_size, out, "conditional_completion", args.seed)\n        ranker = experiment.train_ranker(model, prior, arm_fit, arm_cal, forbidden, reserved, args, out, "same_formula_ranker")\n        predictor, patterns = (EmptyPredictor().to(experiment.DEVICE), []) if arm == "no_substructures" else (upstream, vocab)\n        generation, retrieval = experiment.evaluate_full(model, prior, ranker, predictor, patterns, queries, table, args, out)\n        result = metrics(generation, retrieval)\n        result["parameters"] = sum(p.numel() for p in model.parameters())\n        if arm == "transformer_decoder" and abs(result["parameters"] / original["parameters"] - 1) > 0.01:\n            raise RuntimeError("Transformer control parameter mismatch exceeds 1%")\n        hits = lambda rows: [r["rank"] is not None and r["rank"] <= 25 for r in rows]\n        result["generation_full_minus_control"] = bootstrap_difference(hits(full_generation), hits(generation), args.seed)\n        result["retrieval_full_minus_control"] = bootstrap_difference(hits(full_retrieval), hits(retrieval), args.seed)\n        results[arm] = result\n        (out / "summary.json").write_text(json.dumps(result, indent=2))\n        (controls / "summary.json").write_text(json.dumps(results, indent=2))\n        experiment.emit({"stage": "control_complete", "arm": arm, **result})\n\n\nif __name__ == "__main__":\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument("--base", type=Path, default=Path("experiments/molecular_completion/full_t4"))\n    main(parser.parse_args().base)\n', 'tools/ms2_full_diagnostics.py': '"""Independent component and generated-candidate checks for the full T4 run."""\nimport argparse\nimport json\nfrom collections import Counter\nfrom pathlib import Path\nimport sys\n\nimport numpy as np\nimport torch\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[1]))\nimport tools.ms2_full_experiment as experiment\nfrom tools.ms2_full_model import (CompletionModel, FormulaTable, SubstructurePredictor,\n    batch_inputs, graph_tensors, motifs, parse_graph)\nfrom tools.ms2_full_controls import restore\nfrom tools.ms2_neural_ranker import bootstrap_difference\n\n\ndef main(base):\n    args = argparse.Namespace(**json.loads((base / \'plan.json\').read_text()))\n    experiment.DEVICE = torch.device(args.device)\n    table = FormulaTable()\n    fit, calibration, queries, _, _, _ = experiment.load_data(args, table)\n    model = restore(CompletionModel().to(experiment.DEVICE), base / \'conditional_completion.pt\')\n    prior = restore(CompletionModel().to(experiment.DEVICE), base / \'molecular_prior.pt\')\n    vocab = torch.load(base / \'upstream_final_vocab.pt\', weights_only=True)[\'patterns\']\n    upstream = restore(SubstructurePredictor(len(vocab)).to(experiment.DEVICE), base / \'upstream_final.pt\')\n    template = np.mean(np.stack([r[\'bins\'] for r in fit]), axis=0)\n    template /= max(np.linalg.norm(template), 1e-12)\n    nll_prior, nll_full, nll_without_sub, forward, baseline, motif_scores = [], [], [], [], [], []\n    reasons = Counter()\n    for query in queries:\n        record, reason = experiment.make_record(query[\'row\'])\n        reasons[reason or \'supported\'] += 1\n        if record is None or record[\'graph\'] is None:\n            continue\n        experiment.predict_substructures(upstream, [record], vocab, 1)\n        graph = record[\'graph\']\n        present = motifs(graph)\n        motif_scores.extend((confidence, float(key in present)) for key, confidence in record[\'predicted\'])\n        with torch.no_grad():\n            nll_prior.append(float(-prior.likelihood([graph], [record], experiment.DEVICE, False)[0]))\n            nll_full.append(float(-model.likelihood([graph], [record], experiment.DEVICE)[0]))\n            nll_without_sub.append(float(-model.likelihood([graph], [{**record, \'predicted\':[]}], experiment.DEVICE)[0]))\n            encoded = model.graph_encoder(*graph_tensors([graph], experiment.DEVICE))\n            prediction = model.predict_spectrum(encoded, batch_inputs([record], experiment.DEVICE))[0].cpu().numpy()\n        forward.append(float(prediction @ record[\'bins\']))\n        baseline.append(float(template @ record[\'bins\']))\n    generation = json.loads((base / \'generation_predictions.json\').read_text())\n    retrieval = json.loads((base / \'retrieval_predictions.json\').read_text())\n    counts = Counter()\n    for row, query in zip(generation, queries):\n        counts.update(row.get(\'work\', {}))\n        accepted = set(table.hypotheses(query[\'row\'])) if experiment.make_record(query[\'row\'])[0] is not None else set()\n        for smiles in row[\'generated\']:\n            graph, reason = parse_graph(smiles)\n            if reason or graph is None or graph.counts not in accepted:\n                raise RuntimeError(f"invalid or mass-inconsistent generated candidate: {row[\'qid\']}")\n            counts[\'checked_returned_candidates\'] += 1\n        if len(row[\'generated\']) != len(set(row[\'generated\'])):\n            raise RuntimeError(\'duplicate generated connectivity\')\n    confidence = np.asarray([v[0] for v in motif_scores])\n    correct = np.asarray([v[1] for v in motif_scores])\n    ece = 0.0\n    calibration_bins = []\n    for low in np.arange(0, 1, 0.1):\n        mask = (confidence >= low) & (confidence < low + 0.1 + (1e-8 if low > 0.85 else 0))\n        if mask.any():\n            mean, accuracy = float(confidence[mask].mean()), float(correct[mask].mean())\n            ece += mask.mean() * abs(mean - accuracy)\n            calibration_bins.append({\'lower\':float(low), \'n\':int(mask.sum()), \'confidence\':mean,\'precision\':accuracy})\n    def mean(values):\n        return float(np.mean(values)) if values else None\n    hits = [r[\'rank\'] is not None and r[\'rank\'] <= 25 for r in retrieval]\n    uniform = [r[\'uniform_rank\'] is not None and r[\'uniform_rank\'] <= 25 for r in retrieval]\n    result = {\'test_queries\':len(queries), \'test_domain\':dict(reasons),\n        \'teacher_forced_supported_test\':{\'n\':len(nll_full), \'prior_nll_per_token\':mean(nll_prior),\n            \'conditional_nll_per_token\':mean(nll_full), \'conditional_without_subgraph_nll\':mean(nll_without_sub),\n            \'note\':\'Input perturbation without retraining; not a trained ablation or stability measure\'},\n        \'forward_spectrum\':{\'true_graph_cosine\':mean(forward),\'training_mean_spectrum_cosine\':mean(baseline)},\n        \'predicted_motifs\':{\'selected_predictions\':len(motif_scores),\'precision\':mean(correct.tolist()),\n            \'mean_confidence\':mean(confidence.tolist()),\'ece\':ece if len(motif_scores) else None,\'bins\':calibration_bins,\n            \'note\':\'Raw sigmoid scores; confidence has not been calibrated as physical stability\'},\n        \'generation_validity\':dict(counts),\n        \'retrieval_uniform\':{f\'top{k}\':sum(r[\'uniform_rank\'] is not None and r[\'uniform_rank\'] <= k for r in retrieval)/len(retrieval) for k in (1,10,25)},\n        \'retrieval_full_minus_uniform_top25\':bootstrap_difference(hits,uniform,args.seed),\n        \'scope\':\'Component/chemical-validity diagnostics; no physical-stability labels\'}\n    (base / \'component_diagnostics.json\').write_text(json.dumps(result,indent=2))\n    experiment.emit(result)\n\n\nif __name__ == \'__main__\':\n    parser=argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'--base\',type=Path,default=Path(\'experiments/molecular_completion/full_t4\'))\n    main(parser.parse_args().base)\n', 'tools/test_ms2_full_model.py': 'import json\nimport os\nimport subprocess\nimport unittest\n\nimport numpy as np\nimport torch\n\nfrom tools.ms2_full_model import *\n\n\nclass FullModelTests(unittest.TestCase):\n    def setUp(self):\n        torch.manual_seed(42)\n        torch.set_num_threads(1)\n\n    def test_roundtrip_closed_graph_and_early_stop(self):\n        for smiles in ("CC", "CCO", "c1ccccc1", "CC(=O)N", "C1CC1", "CCCCCCCCCCCCCCCCCC"):\n            graph, reason = parse_graph(smiles)\n            self.assertIsNone(reason)\n            state = CompleteState(graph.counts)\n            for index, token in enumerate(graph.trace()):\n                if index == 2:\n                    self.assertFalse(state.masks((STOP, 0, 0, 0))[1])\n                state.apply(token)\n            self.assertEqual(state.graph().identity, graph.identity)\n            self.assertFalse(any(state.residual))\n            teacher_batch([graph], "cpu")\n\n    def test_original_isotopes_charges_and_radicals_are_rejected(self):\n        for smiles in ("[13CH3]CO", "[NH3+]CC", "[CH2]C"):\n            graph, reason = parse_graph(smiles)\n            self.assertIsNone(graph)\n            self.assertEqual(reason, "charged_isotopic_or_radical")\n\n    def test_candidate_domain_checks_precede_identity_deduplication(self):\n        isotope_only = canonical_candidates(["[13CH3]CO"])\n        self.assertEqual(isotope_only, {"CCO": None})\n        both = canonical_candidates(["[13CH3]CO", "OCC"])\n        self.assertEqual(list(both), ["CCO"])\n        self.assertIsNotNone(both["CCO"])\n\n    def test_graph_encoder_invariant_and_parent_hydrogens(self):\n        graph, _ = parse_graph("CCO")\n        motifs_before = motifs(graph)\n        perm = [2, 0, 1]\n        position = {old: new for new, old in enumerate(perm)}\n        permuted = Graph(tuple(graph.types[i] for i in perm), tuple((position[a], position[b], o) for a,b,o in graph.edges))\n        self.assertEqual(motifs_before, motifs(permuted))\n        encoder = GraphEncoder(96).eval()\n        with torch.no_grad():\n            torch.testing.assert_close(encoder(*graph_tensors([graph], "cpu")), encoder(*graph_tensors([permuted], "cpu")))\n        self.assertIn(((9,), ()), motifs_before)  # Parent OH, not isolated water.\n\n    def test_mass_hypotheses_without_target_labels(self):\n        table = FormulaTable()\n        row = {"precursor_mz": "47.049141", "adduct": "[M+H]+"}\n        self.assertIn((2,6,0,1), table.hypotheses(row))\n        with self.assertRaises(ValueError):\n            table.hypotheses({"precursor_mz":"47", "adduct":"unknown"})\n\n    def test_mamba_causality_and_prefix_equivalence(self):\n        layer = block(96).eval()\n        x = torch.randn(2, 20, 96)\n        altered = x.clone()\n        altered[:, 12:] += 100\n        with torch.no_grad():\n            full = layer(x)\n            torch.testing.assert_close(full[:, :12], layer(altered)[:, :12], atol=1e-5, rtol=1e-5)\n            torch.testing.assert_close(full[:, :12], layer(x[:, :12]), atol=1e-5, rtol=1e-5)\n\n    def test_substructure_order_invariance(self):\n        model = CompletionModel().eval()\n        graph, _ = parse_graph("CCO")\n        patterns = [(key, 0.7) for key in sorted(motifs(graph))[:5]]\n        with torch.no_grad():\n            a = substructure_context(model, [{"predicted":patterns}], "cpu")\n            b = substructure_context(model, [{"predicted":patterns[::-1]}], "cpu")\n        torch.testing.assert_close(a,b)\n\n    def test_inference_condition_does_not_read_reference_graph(self):\n        features, mask, bins = prep_peaks([(20, 1)], 47.049141)\n        record = {"peaks": features, "mask": mask, "bins": bins,\n                  "meta": np.zeros(5, dtype=np.float32), "adduct": 1, "predicted": []}\n        model = CompletionModel().eval()\n        with torch.no_grad():\n            a = model.condition([{**record, "graph": parse_graph("CCO")[0]}], "cpu")\n            b = model.condition([{**record, "graph": None}], "cpu")\n        for left, right in zip(a, b):\n            torch.testing.assert_close(left, right)\n\n    def training_check(self, device):\n        graph, _ = parse_graph("CC")\n        model = CompletionModel().to(device)\n        optimizer = torch.optim.AdamW(model.parameters(), lr=0.003)\n        initial = -model.likelihood([graph], [{}], device, False).item()\n        for _ in range(25):\n            optimizer.zero_grad()\n            loss = -model.likelihood([graph], [{}], device, False).mean()\n            loss.backward()\n            optimizer.step()\n        final = -model.likelihood([graph], [{}], device, False).item()\n        self.assertLess(final, initial * 0.25)\n        features, mask, bins = prep_peaks([(20,1)], 31.05)\n        record = {"peaks":features, "mask":mask, "bins":bins, "meta":np.zeros(5,dtype=np.float32), "adduct":1, "predicted":[]}\n        # Only the prior is trained in this behavior test; condition is zeroed.\n        original = model.condition\n        model.condition = lambda records, dev, conditional=True: (torch.zeros(len(records),96,device=dev), torch.zeros(len(records),1,96,device=dev), torch.zeros(len(records),1,dtype=torch.bool,device=dev))\n        model.eval()\n        candidates, work = sample_graphs(model, record, [graph.counts], device, trajectories=2)\n        model.condition = original\n        self.assertTrue(candidates)\n        self.assertTrue(all(c.counts == graph.counts and c.identity == "CC" for c in candidates))\n\n    def test_cpu_training_and_generation(self):\n        self.training_check("cpu")\n\n    @unittest.skipUnless(torch.cuda.is_available(), "CUDA unavailable locally")\n    def test_cuda_training_and_cpu_gpu_parity(self):\n        self.training_check("cuda")\n        cpu = CompletionModel().eval()\n        gpu = CompletionModel().cuda().eval()\n        gpu.load_state_dict(cpu.state_dict())\n        graphs = [parse_graph("CCO")[0], parse_graph("c1ccccc1")[0]]\n        with torch.no_grad():\n            a = cpu.likelihood(graphs, [{},{}], "cpu", False)\n            b = gpu.likelihood(graphs, [{},{}], "cuda", False).cpu()\n        torch.testing.assert_close(a,b,atol=2e-4,rtol=2e-4)\n        features, mask, bins = prep_peaks([(20, 1), (31, 0.5)], 47.049141)\n        record = {"peaks": features, "mask": mask, "bins": bins,\n                  "meta": np.zeros(5, dtype=np.float32), "adduct": 1,\n                  "predicted": [(key, 0.7) for key in sorted(motifs(graphs[0]))[:3]]}\n        with torch.no_grad():\n            a = cpu.likelihood(graphs, [record, record], "cpu")\n            b = gpu.likelihood(graphs, [record, record], "cuda").cpu()\n            torch.testing.assert_close(a, b, atol=3e-4, rtol=3e-4)\n            encoded_cpu = cpu.graph_encoder(*graph_tensors(graphs, "cpu"))\n            encoded_gpu = gpu.graph_encoder(*graph_tensors(graphs, "cuda"))\n            a = cpu.predict_spectrum(encoded_cpu, batch_inputs([record, record], "cpu"))\n            b = gpu.predict_spectrum(encoded_gpu, batch_inputs([record, record], "cuda")).cpu()\n            torch.testing.assert_close(a, b, atol=3e-4, rtol=3e-4)\n\n    @unittest.skipUnless(os.environ.get("MS2_RUST_PARITY_BIN"), "Rust parity executable not configured")\n    def test_rust_python_grammar_parity(self):\n        cases, expected = [], []\n        for smiles in ("CC", "CCO", "c1ccccc1", "CC(=O)N", "C1CC1", "CCCCCCCCCCCCCCCCCC"):\n            graph, _ = parse_graph(smiles)\n            state = CompleteState(graph.counts)\n            masks=[]\n            for token in graph.trace():\n                masks.append(state.masks(token)[0])\n                state.apply(token)\n            cases.append({"counts":graph.counts,"trace":graph.trace()})\n            expected.append({"masks":masks,"residual":state.residual})\n        process = subprocess.run([os.environ["MS2_RUST_PARITY_BIN"]], input=json.dumps(cases), capture_output=True,text=True,check=True)\n        self.assertEqual(json.loads(process.stdout), expected)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'tools/test_ms2_full_controls.py': '"""Observable behavior and capacity checks for the full-pipeline controls."""\nimport unittest\nimport torch\n\nfrom tools.ms2_full_model import CompletionModel, batch_inputs, prep_peaks\nfrom tools.ms2_full_controls import CausalTransformerBlock, EmptyPredictor\nimport tools.ms2_full_experiment as experiment\nimport numpy as np\n\n\nclass FullControlTests(unittest.TestCase):\n    def setUp(self):\n        torch.manual_seed(42)\n        torch.set_num_threads(1)\n\n    def test_transformer_capacity_and_causal_prefix(self):\n        model = CompletionModel()\n        layer = CausalTransformerBlock().eval()\n        difference = abs(sum(p.numel() for p in model.layers.parameters()) - sum(p.numel() for p in layer.parameters()))\n        self.assertLess(difference / sum(p.numel() for p in model.parameters()), 0.01)\n        x = torch.randn(2, 20, 96)\n        changed = x.clone()\n        changed[:, 12:] += 100\n        with torch.no_grad():\n            torch.testing.assert_close(layer(x)[:, :12], layer(changed)[:, :12], atol=1e-5, rtol=1e-5)\n            torch.testing.assert_close(layer(x)[:, :12], layer(x[:, :12]), atol=1e-5, rtol=1e-5)\n\n    def test_empty_predictor_returns_no_patterns(self):\n        features, mask, bins = prep_peaks([(20, 1)], 47.049141)\n        record = {"peaks":features, "mask":mask, "bins":bins, "meta":[0]*5, "adduct":1}\n        result = EmptyPredictor()(batch_inputs([record], "cpu"))\n        self.assertEqual(tuple(result.shape), (1, 0))\n\n    def test_retrieval_leaves_isotope_only_identity_unscored(self):\n        experiment.DEVICE = torch.device("cpu")\n        model, prior = CompletionModel().eval(), CompletionModel().eval()\n        ranker = experiment.FeatureRanker(np.zeros(5), np.ones(5)).eval()\n        features, mask, bins = prep_peaks([(20, 1)], 47.049141)\n        record = {"peaks":features, "mask":mask, "bins":bins,\n                  "meta":np.zeros(5, dtype=np.float32), "adduct":1, "predicted":[]}\n        query = {"qid":"isotope-regression", "pool":["[13CH3]CO", "COC"], "row":{"smiles":"CCO"}}\n        row = experiment.retrieval_prediction(model, prior, ranker, query, record)\n        self.assertEqual(row["pool"], 2)\n        self.assertEqual(row["scored"], 1)\n        self.assertEqual(row["rank"], 2)\n\n\nif __name__ == "__main__":\n    unittest.main()\n', 'bench/torch_mamba3.py': '"""Mamba-3 in PyTorch, as the reference the Rust/CubeCL implementation is measured against.\n\nThis is a direct port of `src/models/mamba3.rs` and `src/ssm/scan.rs`: the same fused\ninput projection, the same depthwise causal convolution, the same B/C bias + RMS norm,\nthe same learned-trapezoidal weights, the same rotating frame, and the same chunked SSD\nscan written out of the same primitives. Nothing here is fused by hand, which is exactly\nthe point — both sides compose the scan from ordinary tensor ops, so the comparison is\nbetween two implementations of one algorithm rather than between two algorithms.\n\nRun:\n    python bench/torch_mamba3.py                       # eager\n    python bench/torch_mamba3.py --compile             # torch.compile\nShape knobs mirror examples/bench_train.rs and come from the same environment variables.\n"""\n\nimport argparse\nimport math\nimport os\nimport time\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\nLOG_DECAY_FLOOR = -60.0\n\n\ndef env(name, default):\n    return int(os.environ.get(name, default))\n\n\nclass RmsNorm(nn.Module):\n    def __init__(self, dim, eps=1e-5):\n        super().__init__()\n        self.weight = nn.Parameter(torch.ones(dim))\n        self.eps = eps\n\n    def forward(self, x):\n        scale = torch.rsqrt(x.pow(2).mean(-1, keepdim=True) + self.eps)\n        return x * scale * self.weight\n\n\ndef cumsum_exclusive(x, dim):\n    return x.cumsum(dim) - x\n\n\ndef ssd_chunked(x, b, c, a, g, w, chunk):\n    """The scan of `src/ssm/scan.rs::ssd_chunked`.\n\n    x [B,T,H,P]; b, c [B,T,H,N]; a, g, w [B,T,H]. Returns y [B,T,H,P].\n    """\n    B, T, H, P = x.shape\n    N = b.shape[-1]\n    pad = (chunk - T % chunk) % chunk\n    if pad:\n        x = F.pad(x, (0, 0, 0, 0, 0, pad))\n        b = F.pad(b, (0, 0, 0, 0, 0, pad))\n        c = F.pad(c, (0, 0, 0, 0, 0, pad))\n        a = F.pad(a, (0, 0, 0, pad))\n        g = F.pad(g, (0, 0, 0, pad))\n        w = F.pad(w, (0, 0, 0, pad))\n    L = T + pad\n    C = L // chunk\n\n    x = x.reshape(B, C, chunk, H, P)\n    b = b.reshape(B, C, chunk, H, N)\n    c = c.reshape(B, C, chunk, H, N)\n    a = a.reshape(B, C, chunk, H)\n    g = g.reshape(B, C, chunk, H)\n    w = w.reshape(B, C, chunk, H)\n\n    acum = a.cumsum(2)\n\n    # ---- 1. intra-chunk ----\n    diff = acum.unsqueeze(3) - acum.unsqueeze(2)              # [B,C,t,s,H]\n    causal = torch.tril(torch.ones(chunk, chunk, device=x.device, dtype=x.dtype))\n    decay = diff.clamp(LOG_DECAY_FLOOR, 0.0).exp() * causal.view(1, 1, chunk, chunk, 1)\n    strict = torch.tril(\n        torch.ones(chunk, chunk, device=x.device, dtype=x.dtype), diagonal=-1\n    ).view(1, 1, chunk, chunk, 1)\n    eye = torch.eye(chunk, device=x.device, dtype=x.dtype).view(1, 1, chunk, chunk, 1)\n    weight = w.unsqueeze(2) * strict + g.unsqueeze(2) * eye\n\n    def heads_first(v, last):\n        return v.permute(0, 1, 3, 2, 4).reshape(B * C * H, chunk, last)\n\n    c_flat = heads_first(c, N)\n    b_flat = heads_first(b, N)\n    x_flat = heads_first(x, P)\n\n    cb = (c_flat @ b_flat.transpose(-1, -2)).reshape(B, C, H, chunk, chunk).permute(\n        0, 1, 3, 4, 2\n    )\n    mixing = cb * decay * weight\n    mixing_flat = mixing.permute(0, 1, 4, 2, 3).reshape(B * C * H, chunk, chunk)\n    y_diag = (mixing_flat @ x_flat).reshape(B, C, H, chunk, P).permute(0, 1, 3, 2, 4)\n\n    # ---- 2. chunk summaries ----\n    last_acum = acum[:, :, chunk - 1 : chunk]\n    decay_to_end = (last_acum - acum).clamp(LOG_DECAY_FLOOR, 0.0).exp()\n    weighted_x = x * (decay_to_end * w).unsqueeze(4)\n    chunk_state = (\n        weighted_x.permute(0, 1, 3, 4, 2).reshape(B * C * H, P, chunk) @ b_flat\n    ).reshape(B, C, H, P, N)\n\n    # ---- 3. inter-chunk recurrence ----\n    chunk_decay = last_acum.reshape(B, C, H)\n    before = cumsum_exclusive(chunk_decay, 1)\n    through = chunk_decay.cumsum(1)\n    strict_chunks = torch.tril(\n        torch.ones(C, C, device=x.device, dtype=x.dtype), diagonal=-1\n    ).view(1, C, C, 1)\n    transfer = (before.unsqueeze(2) - through.unsqueeze(1)).clamp(\n        LOG_DECAY_FLOOR, 0.0\n    ).exp() * strict_chunks\n    carry_in = (\n        transfer.permute(0, 3, 1, 2).reshape(B * H, C, C)\n        @ chunk_state.permute(0, 2, 1, 3, 4).reshape(B * H, C, P * N)\n    ).reshape(B, H, C, P, N).permute(0, 2, 1, 3, 4)\n\n    # ---- 4. carry-in contribution ----\n    c_decayed = c * acum.clamp(LOG_DECAY_FLOOR, 0.0).exp().unsqueeze(4)\n    y_off = (\n        heads_first(c_decayed, N)\n        @ carry_in.permute(0, 1, 2, 4, 3).reshape(B * C * H, N, P)\n    ).reshape(B, C, H, chunk, P).permute(0, 1, 3, 2, 4)\n\n    y = (y_diag + y_off).reshape(B, L, H, P)\n    return y[:, :T] if pad else y\n\n\ndef rotate_halves(v, phi):\n    """Rotate the two halves of the trailing axis by `-phi`, matching `rotate_by_angle`."""\n    cos, sin = torch.cos(phi), torch.sin(phi)\n    d = v.shape[-1] // 2\n    lo, hi = v[..., :d], v[..., d:]\n    return torch.cat([lo * cos + hi * sin, hi * cos - lo * sin], dim=-1)\n\n\nclass Mamba3Mixer(nn.Module):\n    def __init__(self, d_model, n_heads, head_dim, d_state, chunk, conv_kernel=4):\n        super().__init__()\n        self.d_model = d_model\n        self.h = n_heads\n        self.p = head_dim\n        self.n = d_state\n        self.chunk = chunk\n        self.d_inner = n_heads * head_dim\n        self.bc = n_heads * d_state          # n_groups == n_heads\n        width = 2 * self.d_inner + 2 * self.bc + n_heads + n_heads + n_heads * d_state // 2\n        self.in_proj = nn.Linear(d_model, width, bias=False)\n        self.out_proj = nn.Linear(self.d_inner, d_model, bias=False)\n        conv_ch = self.d_inner + 2 * self.bc\n        self.conv = nn.Conv1d(\n            conv_ch, conv_ch, conv_kernel, groups=conv_ch, padding=conv_kernel - 1\n        )\n        self.conv_kernel = conv_kernel\n        self.dt_bias = nn.Parameter(torch.zeros(n_heads))\n        self.a_log = nn.Parameter(torch.zeros(n_heads))\n        self.d_skip = nn.Parameter(torch.ones(n_heads))\n        self.b_bias = nn.Parameter(torch.zeros(n_heads, d_state))\n        self.c_bias = nn.Parameter(torch.zeros(n_heads, d_state))\n        self.bc_norm = RmsNorm(d_state)\n\n    def forward(self, u):\n        B, T, _ = u.shape\n        H, P, N = self.h, self.p, self.n\n        proj = self.in_proj(u)\n        z, xbc, dt_raw, lam_raw, theta_raw = torch.split(\n            proj,\n            [self.d_inner, self.d_inner + 2 * self.bc, H, H, H * N // 2],\n            dim=-1,\n        )\n        # Depthwise causal convolution over x, B and C together.\n        xbc = self.conv(xbc.transpose(1, 2))[..., :T].transpose(1, 2)\n        xbc = F.silu(xbc)\n        x, b_flat, c_flat = torch.split(\n            xbc, [self.d_inner, self.bc, self.bc], dim=-1\n        )\n\n        b = b_flat.reshape(B, T, H, N) + self.b_bias\n        c = c_flat.reshape(B, T, H, N) + self.c_bias\n        b = self.bc_norm(b)\n        c = self.bc_norm(c)\n        x = x.reshape(B, T, H, P)\n\n        dt = F.softplus(dt_raw + self.dt_bias)\n        lam = torch.sigmoid(lam_raw)\n        theta = theta_raw.reshape(B, T, H, N // 2)\n\n        a = dt * (-torch.exp(self.a_log))\n        g = lam * dt\n        nxt = (1.0 - lam) * dt\n        f = torch.cat([nxt[:, 1:], torch.zeros_like(nxt[:, :1])], dim=1)\n        w = g + f\n\n        # Rotating frame: cumulative angle, wrapped into [-pi, pi].\n        phi = (dt.unsqueeze(3) * theta).cumsum(1)\n        two_pi = 2.0 * math.pi\n        phi = phi - (torch.round(phi / two_pi) * two_pi).detach()\n        b = rotate_halves(b, phi)\n        c = rotate_halves(c, phi)\n\n        y = ssd_chunked(x, b, c, a, g, w, self.chunk)\n        y = y + x * self.d_skip.view(1, 1, H, 1)\n        y = y.reshape(B, T, self.d_inner) * F.silu(z)\n        return self.out_proj(y)\n\n\nclass Block(nn.Module):\n    def __init__(self, **kw):\n        super().__init__()\n        self.norm = RmsNorm(kw["d_model"])\n        self.mixer = Mamba3Mixer(**kw)\n\n    def forward(self, x):\n        return x + self.mixer(self.norm(x))\n\n\nclass Mamba3Lm(nn.Module):\n    def __init__(self, vocab, d_model, n_layers, **kw):\n        super().__init__()\n        self.embed = nn.Embedding(vocab, d_model)\n        self.layers = nn.ModuleList(\n            [Block(d_model=d_model, **kw) for _ in range(n_layers)]\n        )\n        self.norm = RmsNorm(d_model)\n        self.head = nn.Linear(d_model, vocab, bias=False)\n\n    def forward(self, ids):\n        x = self.embed(ids)\n        for layer in self.layers:\n            x = layer(x)\n        return self.head(self.norm(x))\n\n\ndef main():\n    ap = argparse.ArgumentParser()\n    ap.add_argument("--compile", action="store_true")\n    ap.add_argument("--dtype", default="fp32", choices=["fp32", "bf16"])\n    args = ap.parse_args()\n\n    vocab = env("VOCAB", 8192)\n    d_model = env("D_MODEL", 512)\n    n_layers = env("LAYERS", 8)\n    n_heads = env("HEADS", 16)\n    head_dim = env("HEAD_DIM", 64)\n    d_state = env("D_STATE", 64)\n    chunk = env("CHUNK", 64)\n    seq = env("SEQ", 512)\n    batch = env("BATCH", 4)\n    iters = env("ITERS", 10)\n\n    dev = "cuda"\n    torch.manual_seed(1234)\n    model = Mamba3Lm(\n        vocab,\n        d_model,\n        n_layers,\n        n_heads=n_heads,\n        head_dim=head_dim,\n        d_state=d_state,\n        chunk=chunk,\n    ).to(dev)\n    params = sum(p.numel() for p in model.parameters())\n    print(f"torch   {torch.__version__}  {torch.cuda.get_device_name(0)}")\n    print(\n        f"model   d_model {d_model} layers {n_layers} heads {n_heads}x{head_dim} "\n        f"state {d_state} chunk {chunk} vocab {vocab}"\n    )\n    print(f"batch   {batch} x {seq} tokens = {batch * seq} tokens/step")\n    print(f"params  {params / 1e6:.2f} M")\n\n    fwd = model\n    if args.compile:\n        fwd = torch.compile(model)\n\n    opt = torch.optim.AdamW(model.parameters(), lr=1e-3, fused=False)\n    ids = torch.randint(0, vocab, (batch, seq), device=dev)\n    targets = torch.randint(0, vocab, (batch, seq), device=dev)\n\n    autocast = (\n        torch.autocast("cuda", dtype=torch.bfloat16)\n        if args.dtype == "bf16"\n        else torch.autocast("cuda", enabled=False)\n    )\n\n    def step():\n        opt.zero_grad(set_to_none=True)\n        with autocast:\n            logits = fwd(ids)\n            loss = F.cross_entropy(logits.reshape(-1, vocab), targets.reshape(-1))\n        loss.backward()\n        torch.nn.utils.clip_grad_norm_(model.parameters(), 1.0)\n        opt.step()\n        return loss\n\n    t = time.perf_counter()\n    step()\n    torch.cuda.synchronize()\n    print(f"warmup  {time.perf_counter() - t:9.2f}s")\n\n    # Phase split, each phase synchronised.\n    opt.zero_grad(set_to_none=True)\n    torch.cuda.synchronize()\n    t = time.perf_counter()\n    with autocast:\n        logits = fwd(ids)\n        loss = F.cross_entropy(logits.reshape(-1, vocab), targets.reshape(-1))\n    torch.cuda.synchronize()\n    f_ms = (time.perf_counter() - t) * 1e3\n    t = time.perf_counter()\n    loss.backward()\n    torch.cuda.synchronize()\n    b_ms = (time.perf_counter() - t) * 1e3\n    print(f"forward {f_ms:9.2f}ms")\n    print(f"backward{b_ms:9.2f}ms")\n\n    # Best and median rather than mean, for the same reason the Rust benchmark uses\n    # them: this GPU shares its bandwidth with the rest of the machine.\n    times = []\n    for _ in range(iters):\n        torch.cuda.synchronize()\n        t = time.perf_counter()\n        step()\n        torch.cuda.synchronize()\n        times.append(time.perf_counter() - t)\n    times.sort()\n    best, median = times[0], times[len(times) // 2]\n    print(f"step    best {best * 1e3:9.2f}ms  median {median * 1e3:9.2f}ms")\n    print(\n        f"tokens/s best {batch * seq / best:7.0f}  median {batch * seq / median:7.0f}"\n        f"   peak {torch.cuda.max_memory_allocated() / 2**20:.0f} MiB"\n    )\n\n\nif __name__ == "__main__":\n    main()\n', 'tools/ms2/ms2_reference.py': '"""Python reference of docs/MS2_CONTRACTS.md, shared by the MS2 tools.\n\nThe chemistry domain (section 4), the integer mass arithmetic (section 5), the\ngraph-action grammar and canonical traversal (sections 4.4 and 7.4) and the\npseudo-label recipe `q-cut-v1` (section 7.2), written from the contract with\nRDKit and Python integers. `make_fixtures.py` turns it into the fixture the Rust\nreference is tested against; `audit_casmi.py` and `pilot_targets.py` apply it to\nthe CASMI data. Nothing here is derived from Rust output.\n"""\nfrom __future__ import annotations\n\nimport itertools\nfrom collections import Counter\nfrom decimal import ROUND_HALF_EVEN, Decimal\nfrom fractions import Fraction\nfrom rdkit import Chem, RDLogger\nfrom rdkit.Chem import Descriptors\n\nRDLogger.DisableLog("rdApp.*")\n\nSCALE = 1_000_000\n# docs/MS2_CONTRACTS.md section 4.1 (NIST / AME2016).\nEXACT = {\n    "H": "1.00782503223", "C": "12", "N": "14.00307400443", "O": "15.99491461957",\n    "F": "18.99840316273", "P": "30.97376199842", "S": "31.9720711744",\n    "Cl": "34.968852682", "Br": "78.9183376", "I": "126.9044719",\n}\nELECTRON_EXACT = "0.000548579909065"\nELEMENT_ORDER = ["C", "H", "N", "O", "F", "P", "S", "Cl", "Br", "I"]\n\n\ndef to_int(decimal_text: str) -> int:\n    return int((Decimal(decimal_text) * SCALE).to_integral_value(rounding=ROUND_HALF_EVEN))\n\n\ndef residual_nda(decimal_text: str) -> int:\n    """Absolute rounding residual in nano-dalton, rounded up."""\n    exact = Decimal(decimal_text) * SCALE\n    return int((abs(exact - to_int(decimal_text)) * 1000).to_integral_value(rounding="ROUND_CEILING"))\n\n\nMASS = {e: to_int(v) for e, v in EXACT.items()}\nRESIDUAL = {e: residual_nda(v) for e, v in EXACT.items()}\nELECTRON = to_int(ELECTRON_EXACT)\nELECTRON_RESIDUAL = residual_nda(ELECTRON_EXACT)\n\n# docs/MS2_CONTRACTS.md section 4.2: id -> (element, parent hydrogens, valence).\nATOM_TYPES = {\n    1: ("C", 0, 4), 2: ("C", 1, 4), 3: ("C", 2, 4), 4: ("C", 3, 4),\n    5: ("N", 0, 3), 6: ("N", 1, 3), 7: ("N", 2, 3),\n    8: ("O", 0, 2), 9: ("O", 1, 2),\n    10: ("F", 0, 1), 11: ("Cl", 0, 1), 12: ("Br", 0, 1),\n    13: ("S", 0, 2), 14: ("S", 1, 2), 15: ("S", 0, 6),\n    16: ("P", 0, 5), 17: ("I", 0, 1),\n}\nTYPE_ID = {v: k for k, v in ATOM_TYPES.items()}\nADDUCTS = {1: ("[M+H]+", +1, +1), 2: ("[M-H]-", -1, -1)}  # id -> (name, hydrogens, charge)\n\nU32_MAX = 2**32 - 1\nUNKNOWN_UNCERTAINTY = U32_MAX\n# Integer weights (contract section 7.2 step 5): intensities in units of 2^-20, and\n# a split factor divisible by every count up to 16 (4096 * lcm(1..16)).\nINTENSITY_UNITS = 1 << 20\nSPLIT_UNITS = 4096 * 720720\nMAX_ATOMS, MIN_ATOMS, MAX_CLOSURES, MAX_CUTS, MAX_SHIFT, MAX_TARGETS = 16, 3, 4, 2, 2, 16\nPAD, START, ADD, CLOSE, STOP = 0, 1, 2, 3, 4\n\ndef raw_atoms(mol):\n    out = []\n    for a in mol.GetAtoms():\n        order = int(sum(b.GetBondTypeAsDouble() for b in a.GetBonds()))\n        out.append({\n            "element": a.GetSymbol(), "charge": a.GetFormalCharge(), "hydrogens": a.GetTotalNumHs(),\n            "isotope": a.GetIsotope(), "radical_electrons": a.GetNumRadicalElectrons(),\n            "valence": a.GetTotalNumHs() + order,\n        })\n    return out\n\n\ndef classify(mol):\n    """Every reason the molecule is outside the V0 structure domain (sorted).\n\n    `unsupported_atom_type` is reported for an atom that has none of the other\n    per-atom defects and still is not in the vocabulary.\n    """\n    reasons = set()\n    if len(Chem.GetMolFrags(mol)) != 1:\n        reasons.add("disconnected")\n    for a in raw_atoms(mol):\n        own = set()\n        if a["element"] not in MASS or a["element"] == "H":\n            own.add("element_outside_domain")\n        if a["charge"] != 0:\n            own.add("formal_charge")\n        if a["isotope"] != 0:\n            own.add("isotope_label")\n        if a["radical_electrons"] != 0:\n            own.add("radical")\n        if not own and (a["element"], a["hydrogens"], a["valence"]) not in TYPE_ID:\n            own.add("unsupported_atom_type")\n        reasons |= own\n    return sorted(reasons)\n\n\ndef kekulized(smiles):\n    mol = Chem.MolFromSmiles(smiles)\n    assert mol is not None, smiles\n    Chem.Kekulize(mol, clearAromaticFlags=True)\n    return mol\n\n\ndef graph_of(mol):\n    atoms = [TYPE_ID[(a["element"], a["hydrogens"], a["valence"])] for a in raw_atoms(mol)]\n    bonds = sorted(\n        (min(b.GetBeginAtomIdx(), b.GetEndAtomIdx()), max(b.GetBeginAtomIdx(), b.GetEndAtomIdx()),\n         int(b.GetBondTypeAsDouble()))\n        for b in mol.GetBonds())\n    return atoms, [list(b) for b in bonds]\n\n\ndef composition(atoms):\n    c = Counter()\n    for t in atoms:\n        element, h, _ = ATOM_TYPES[t]\n        c[element] += 1\n        c["H"] += h\n    return c\n\n\ndef mass_of(counts) -> int:\n    return sum(MASS[e] * n for e, n in counts.items())\n\n\ndef error_nda(counts) -> int:\n    """Representation error bound of a neutral composition, nano-dalton."""\n    return sum(RESIDUAL[e] * n for e, n in counts.items())\n\n\ndef enumerate_subgraphs(atoms, bonds):\n    """{sorted atom tuple: smallest boundary count} for the contract\'s bond-cut recipe."""\n    n = len(atoms)\n    found = {}\n    for k in range(0, MAX_CUTS + 1):\n        for cut in itertools.combinations(range(len(bonds)), k):\n            comp = list(range(n))\n\n            def find(x):\n                while comp[x] != x:\n                    x = comp[x]\n                return x\n\n            for i, (a, b, _) in enumerate(bonds):\n                if i not in cut:\n                    ra, rb = find(a), find(b)\n                    if ra != rb:\n                        comp[ra] = rb\n            roots = [find(i) for i in range(n)]\n            if any(roots[bonds[i][0]] == roots[bonds[i][1]] for i in cut):\n                continue\n            groups = {}\n            for i, r in enumerate(roots):\n                groups.setdefault(r, []).append(i)\n            for r, members in groups.items():\n                boundary = sum((roots[bonds[i][0]] == r) + (roots[bonds[i][1]] == r) for i in cut)\n                inside = set(members)\n                closures = sum(1 for a, b, _ in bonds if a in inside and b in inside) - (len(members) - 1)\n                if MIN_ATOMS <= len(members) <= MAX_ATOMS and closures <= MAX_CLOSURES:\n                    key = tuple(members)\n                    if key not in found or boundary < found[key][0]:\n                        found[key] = (boundary, closures)\n    return found\n\n\ndef fragment_smiles(mol, atoms_types, members):\n    """RDKit canonical SMILES of the fragment with each atom tagged by its type id."""\n    tagged = Chem.RWMol(mol)\n    # Identity is atom type and bond order only (contract section 7.4): drop the\n    # parent\'s stereo marks, which an isomeric SMILES would otherwise keep.\n    Chem.RemoveStereochemistry(tagged)\n    for i in members:\n        tagged.GetAtomWithIdx(i).SetIsotope(atoms_types[i])\n    inside = set(members)\n    bond_ids = [b.GetIdx() for b in tagged.GetBonds()\n                if b.GetBeginAtomIdx() in inside and b.GetEndAtomIdx() in inside]\n    return Chem.MolFragmentToSmiles(tagged, atomsToUse=list(members), bondsToUse=bond_ids, canonical=True,\n                                    kekuleSmiles=True, allHsExplicit=True, isomericSmiles=True)\n\n\n# ---- grammar: traversal, canonical trace and legality, written from the contract ----\n\ndef sub_adjacency(members, bonds):\n    index = {a: i for i, a in enumerate(members)}\n    adj = {i: {} for i in range(len(members))}\n    for a, b, order in bonds:\n        if a in index and b in index:\n            adj[index[a]][index[b]] = order\n            adj[index[b]][index[a]] = order\n    return adj\n\n\ndef all_bfs_traces(types, adj):\n    """Every breadth-first trace of a connected labeled graph (exhaustive)."""\n    n = len(types)\n    out = []\n\n    def extend(order, head, tokens):\n        if len(order) == n:\n            out.append(tokens + [(STOP, 0, 0, 0)])\n            return\n        placed = {a: i for i, a in enumerate(order)}\n        while head < len(order):\n            u = order[head]\n            fresh = [v for v in adj[u] if v not in placed]\n            if fresh:\n                break\n            head += 1\n        else:\n            return  # disconnected: not reachable for the fixtures\n        for v in fresh:\n            block = [(ADD, types[v], adj[u][v], head)]\n            closing = sorted(placed[w] for w in adj[v] if w in placed and w != u)\n            block += [(CLOSE, 0, adj[v][order[p]], p) for p in closing]\n            extend(order + [v], head, tokens + block)\n\n    for root in range(n):\n        extend([root], 0, [(START, 0, 0, 0), (ADD, types[root], 0, 0)])\n    return out\n\n\ndef canonical_trace(types, adj):\n    """Exhaustive minimum over every breadth-first traversal: for small graphs only.\n\n    This is the unpruned check of the contract\'s definition; it has no work limit,\n    so the fixture uses it up to 9 atoms. The bounded search is the Rust reference.\n    """\n    closures = sum(len(n) for n in adj.values()) // 2 - (len(types) - 1)\n    if not 1 <= len(types) <= MAX_ATOMS or closures > MAX_CLOSURES:\n        raise ValueError("graph outside the grammar limits")\n    return min(all_bfs_traces(types, adj))\n\n\ndef first_bfs_trace(types, adj, root=0):\n    """One breadth-first trace: neighbours discovered in increasing atom index.\n\n    Not canonical. It gives large graphs a legal trace whose legality masks can be\n    written down without the exhaustive search.\n    """\n    order, placed = [root], {root: 0}\n    tokens = [(START, 0, 0, 0), (ADD, types[root], 0, 0)]\n    head = 0\n    while head < len(order):\n        u = order[head]\n        for v in sorted(adj[u]):\n            if v in placed:\n                continue\n            tokens.append((ADD, types[v], adj[u][v], head))\n            closing = sorted(placed[w] for w in adj[v] if w in placed and w != u)\n            tokens += [(CLOSE, 0, adj[v][order[p]], p) for p in closing]\n            placed[v] = len(order)\n            order.append(v)\n        head += 1\n    return tokens + [(STOP, 0, 0, 0)]\n\n\nclass Replay:\n    """Grammar state of a trace prefix: the legality rules of contract section 4.4."""\n\n    def __init__(self, budget):\n        self.budget = budget  # parent composition (element -> count, H included), or None\n        self.types, self.residual, self.parent_of, self.bonded = [], [], [], set()\n        self.last_parent, self.last_close, self.closures = 0, -1, 0\n        self.used = Counter()\n        self.step = 0\n        self.stopped = False\n\n    def type_fits(self, t):\n        if self.budget is None:\n            return True\n        element, h, _ = ATOM_TYPES[t]\n        return (self.used[element] + 1 <= self.budget.get(element, 0)\n                and self.used["H"] + h <= self.budget.get("H", 0))\n\n    def add_options(self):\n        """{type: {bond: [pointers]}} for a non-root ADD_ATOM."""\n        opts = {}\n        if not self.types or len(self.types) >= MAX_ATOMS:\n            return opts\n        for t, (_, h, valence) in ATOM_TYPES.items():\n            if not self.type_fits(t):\n                continue\n            for b in (1, 2, 3):\n                if b > valence - h:\n                    continue\n                ptrs = [p for p in range(self.last_parent, len(self.types)) if self.residual[p] >= b]\n                if ptrs:\n                    opts.setdefault(t, {})[b] = ptrs\n        return opts\n\n    def close_options(self):\n        """{bond: [pointers]} for a CLOSE_RING on the newest atom."""\n        opts = {}\n        if len(self.types) < 2 or self.closures >= MAX_CLOSURES:\n            return opts\n        newest = len(self.types) - 1\n        lo = max(self.parent_of[newest], self.last_close) + 1\n        for b in (1, 2, 3):\n            if self.residual[newest] < b:\n                continue\n            ptrs = [p for p in range(lo, newest) if self.residual[p] >= b and (p, newest) not in self.bonded]\n            if ptrs:\n                opts[b] = ptrs\n        return opts\n\n    def masks(self, token):\n        """(kind, type, bond, pointer) masks at this step, conditioned on `token`\'s\n        earlier fields, and whether `token` itself is legal."""\n        kind, t, b, p = token\n        if self.stopped:\n            return [0, 0, 0, 0], False\n        if self.step == 0:\n            return [1 << START, 0, 0, 0], token == (START, 0, 0, 0)\n        if self.step == 1:\n            # The root ADD_ATOM is legal only if some atom type fits the budget.\n            type_mask = sum(1 << x for x in ATOM_TYPES if self.type_fits(x))\n            ok = kind == ADD and t in ATOM_TYPES and bool(type_mask >> t & 1) and b == 0 and p == 0\n            return [(1 << ADD) if type_mask else 0, type_mask, 0, 0], ok\n        adds, closes = self.add_options(), self.close_options()\n        kind_mask = (1 << STOP) | ((1 << ADD) if adds else 0) | ((1 << CLOSE) if closes else 0)\n        if kind == ADD and adds:\n            type_mask = sum(1 << x for x in adds)\n            bond_mask = sum(1 << x for x in adds.get(t, {}))\n            ptr_mask = sum(1 << x for x in adds.get(t, {}).get(b, []))\n            return [kind_mask, type_mask, bond_mask, ptr_mask], p in adds.get(t, {}).get(b, [])\n        if kind == CLOSE and closes:\n            bond_mask = sum(1 << x for x in closes)\n            ptr_mask = sum(1 << x for x in closes.get(b, []))\n            return [kind_mask, 0, bond_mask, ptr_mask], t == 0 and p in closes.get(b, [])\n        if kind == STOP:\n            return [kind_mask, 0, 0, 0], (t, b, p) == (0, 0, 0)\n        return [kind_mask, 0, 0, 0], False\n\n    def apply(self, token):\n        kind, t, b, p = token\n        if kind == ADD:\n            element, h, valence = ATOM_TYPES[t]\n            self.used[element] += 1\n            self.used["H"] += h\n            self.types.append(t)\n            self.residual.append(valence - h)\n            if self.step == 1:\n                self.parent_of.append(-1)\n            else:\n                self.residual[p] -= b\n                self.residual[-1] -= b\n                self.parent_of.append(p)\n                self.bonded.add((p, len(self.types) - 1))\n                self.last_parent = p\n            self.last_close = -1\n        elif kind == CLOSE:\n            newest = len(self.types) - 1\n            self.residual[p] -= b\n            self.residual[newest] -= b\n            self.bonded.add((p, newest))\n            self.last_close = p\n            self.closures += 1\n        elif kind == STOP:\n            self.stopped = True\n        self.step += 1\n\n\ndef legality_masks(trace, budget):\n    """Per-step masks of a legal trace, and the residual valences at its end."""\n    state = Replay(budget)\n    out = []\n    for token in trace:\n        masks, ok = state.masks(tuple(token))\n        assert ok, (state.step, token)\n        out.append(masks)\n        state.apply(tuple(token))\n    return out, state.residual\n\n\ndef first_illegal_step(trace, budget=None):\n    """Index of the first token the grammar forbids, or None for a legal trace."""\n    state = Replay(budget)\n    for i, token in enumerate(trace):\n        _, ok = state.masks(tuple(token))\n        if not ok:\n            return i\n        state.apply(tuple(token))\n    return None\n\n\nS0, STOP_T = (START, 0, 0, 0), (STOP, 0, 0, 0)\nINVALID_TRACES = [\n    ("missing START", [(ADD, 1, 0, 0), STOP_T]),\n    ("root carries a bond", [S0, (ADD, 1, 1, 0), STOP_T]),\n    ("STOP before any atom", [S0, STOP_T]),\n    ("bond above the new atom\'s capacity", [S0, (ADD, 1, 0, 0), (ADD, 4, 2, 0), STOP_T]),\n    ("bond above the parent\'s residual valence", [S0, (ADD, 9, 0, 0), (ADD, 1, 2, 0), STOP_T]),\n    ("pointer to an atom that does not exist", [S0, (ADD, 1, 0, 0), (ADD, 1, 1, 1), STOP_T]),\n    ("parent pointer decreases", [S0, (ADD, 1, 0, 0), (ADD, 1, 1, 0), (ADD, 1, 1, 1), (ADD, 1, 1, 0), STOP_T]),\n    ("ring closure right after the root", [S0, (ADD, 1, 0, 0), (CLOSE, 0, 1, 0), STOP_T]),\n    ("ring closure onto the parent", [S0, (ADD, 1, 0, 0), (ADD, 1, 1, 0), (CLOSE, 0, 1, 0), STOP_T]),\n    ("ring closure pointers not increasing",\n     [S0, (ADD, 1, 0, 0), (ADD, 1, 1, 0), (ADD, 1, 1, 0), (ADD, 1, 1, 1), (CLOSE, 0, 1, 2), (CLOSE, 0, 1, 2), STOP_T]),\n    ("ring closure onto itself", [S0, (ADD, 1, 0, 0), (ADD, 1, 1, 0), (ADD, 1, 1, 0), (CLOSE, 0, 1, 2), STOP_T]),\n    ("unknown atom type", [S0, (ADD, 18, 0, 0), STOP_T]),\n    ("bond order zero", [S0, (ADD, 1, 0, 0), (ADD, 1, 0, 0), STOP_T]),\n    ("token after STOP", [S0, (ADD, 1, 0, 0), STOP_T, (ADD, 1, 1, 0)]),\n    ("PAD inside the trace", [S0, (ADD, 1, 0, 0), (PAD, 0, 0, 0), STOP_T]),\n    ("halogen cannot take a second bond", [S0, (ADD, 10, 0, 0), (ADD, 1, 1, 0), (ADD, 1, 1, 0), STOP_T]),\n    ("seventeenth atom", [S0, (ADD, 1, 0, 0)] + [(ADD, 3, 1, i) for i in range(16)] + [STOP_T]),\n    ("STOP with fields set", [S0, (ADD, 1, 0, 0), (STOP, 0, 0, 1)]),\n]\n\n\n# ---- ions and pseudo-labels ----\n\ndef tolerance(mz: int, ppm_tenths: int) -> int:\n    return mz * ppm_tenths // 10_000_000\n\n\ndef ion(counts, adduct_id, shift):\n    """(m/z, error bound in micro-dalton rounded up) of ion hypothesis (g, s), or None."""\n    if adduct_id not in ADDUCTS:\n        raise ValueError(f"unsupported_adduct: {adduct_id}")\n    _, h_a, z = ADDUCTS[adduct_id]\n    extra_h = h_a + shift\n    if counts["H"] + extra_h < 0:\n        return None\n    mz = mass_of(counts) + extra_h * MASS["H"] - z * ELECTRON\n    if not 0 <= mz <= U32_MAX:\n        raise ValueError(f"mass_overflow: ion m/z {mz}")\n    # The ion\'s own composition: the subgraph\'s atoms with the net hydrogen count.\n    nda = error_nda(counts) + extra_h * RESIDUAL["H"] + ELECTRON_RESIDUAL\n    return mz, -(-nda // 1000)\n\n\ndef decide(observed: int, computed: int, error: int, tol: int) -> str:\n    r = abs(observed - computed)\n    if r + error <= tol:\n        return "accept"\n    if r > tol + error:\n        return "reject"\n    return "ambiguous"\n\n\ndef hypotheses(g, adduct_id):\n    """Every supported ion of subgraph `g`: [(shift, (m/z, arithmetic error bound))], cached on `g`."""\n    key = ("ions", adduct_id)\n    if key not in g:\n        limit = min(g["boundary"], MAX_SHIFT)\n        found = [(s, ion(g["counts"], adduct_id, s)) for s in range(-limit, limit + 1)]\n        g[key] = [(s, hyp) for s, hyp in found if hyp is not None]\n    return g[key]\n\n\ndef intensity_units(relative: float) -> int:\n    """A relative intensity in integer units of 2^-20, rounded half up."""\n    return int(relative * INTENSITY_UNITS + 0.5)\n\n\ndef targets(peaks, subgraphs, adduct_id, ppm_tenths, uncertainty=0, ids=None):\n    """Recipe q-cut-v1 before the top-16 cut, in integer weights.\n\n    `peaks`: (m/z, linear relative intensity); `ids`: their `peak_id`s (positions\n    when omitted). `subgraphs`: dicts with `counts`, `boundary` and `class` (graph\n    identity); several embeddings may share a class, and a peak is explained by a\n    class when any embedding accepts it at any allowed shift. `uncertainty` is the\n    observation half-width added to every ion\'s arithmetic bound; the unknown\n    sentinel disables exact-mass decisions, so nothing is matched or counted.\n    A peak with integer intensity I explained by n classes gives each\n    `I * SPLIT_UNITS // n`. Returns (weight per class, anchors per class as\n    [peak id, shift], ambiguous (peak, embedding, shift) count, explained peak ids).\n    """\n    weight = Counter()\n    anchors = {}\n    ambiguous = 0\n    explained = set()\n    if uncertainty == UNKNOWN_UNCERTAINTY:\n        return weight, anchors, ambiguous, explained\n    for index, (mz, intensity) in enumerate(peaks):\n        peak_id = index if ids is None else ids[index]\n        tol = tolerance(mz, ppm_tenths)\n        hit = {}\n        for g in subgraphs:\n            for s, hyp in hypotheses(g, adduct_id):\n                verdict = decide(mz, hyp[0], hyp[1] + uncertainty, tol)\n                if verdict == "accept":\n                    hit.setdefault(g["class"], set()).add(s)\n                elif verdict == "ambiguous":\n                    ambiguous += 1\n        if hit:\n            explained.add(peak_id)\n        share = intensity_units(intensity) * SPLIT_UNITS // len(hit) if hit else 0\n        for cls, shifts in hit.items():\n            weight[cls] += share\n            anchors.setdefault(cls, []).extend([peak_id, s] for s in sorted(shifts))\n    return weight, anchors, ambiguous, explained\n\n\ndef retain(weight, order_key=None, max_targets=None):\n    """Top `max_targets` classes by integer weight (ties by `order_key(class)`).\n\n    Returns ({class: q}, dropped weight fraction), `q` normalised over the kept.\n    """\n    total = sum(weight.values())\n    if not total:\n        return {}, 0.0\n    limit = MAX_TARGETS if max_targets is None else max_targets\n    key = order_key or (lambda cls: cls)\n    ranked = sorted(weight, key=lambda cls: (-weight[cls], key(cls)))\n    kept = ranked[:limit]\n    kept_total = sum(weight[c] for c in kept)\n    return {c: weight[c] / kept_total for c in kept}, 1.0 - kept_total / total\n\n\ndef filter_peaks(mz, intensity, precursor_mz):\n    """Contract section 2 without the cap: (indices kept, linear relative intensity).\n\n    Intensities must already be finite and non-negative (request validation,\n    contract section 3.1, rejects anything else before this point).\n    """\n    for value in intensity:\n        if not (value == value and 0 <= value < float("inf")):\n            raise ValueError(f"invalid intensity {value!r}: validate the request first")\n    keep = [i for i, m in enumerate(mz) if 0 < m <= precursor_mz + 2 * SCALE]\n    if not keep:\n        return [], []\n    top = max(intensity[i] for i in keep)\n    if top <= 0:\n        return [], []\n    keep = [i for i in keep if intensity[i] / top >= 1e-3]\n    return keep, [intensity[i] / top for i in keep]\n\n\ndef mz_uncertainty(decimals: int) -> int:\n    """Half the last stored digit, in integer units, rounded up (at least 1)."""\n    if decimals >= 6:\n        return 1\n    return -(-(10 ** (6 - decimals)) // 2)\n\n\ndef stored_decimals(values) -> int:\n    """Decimals needed to write every value exactly, capped at 6."""\n    need = 0\n    for v in values:\n        for d in range(need, 7):\n            if abs(round(v, d) - v) < 1e-9:\n                need = d\n                break\n        else:\n            return 6\n    return need\n', 'examples/ms2_full_grammar_parity.rs': '//! Check the Python completion experiment against the authoritative Rust grammar.\nuse std::io::{self, Read};\nuse mamba3::models::ms2::{Composition, Limits, Token, TraceState, atom_type, HYDROGEN, STOP};\nuse serde::{Deserialize, Serialize};\n\n#[derive(Deserialize)]\nstruct Case { counts: [u16; 4], trace: Vec<[u8; 4]> }\n#[derive(Serialize)]\nstruct Report { masks: Vec<[u32; 4]>, residual: Vec<u8> }\n\nfn main() -> Result<(), Box<dyn std::error::Error>> {\n    let mut input = String::new();\n    io::stdin().read_to_string(&mut input)?;\n    let cases: Vec<Case> = serde_json::from_str(&input)?;\n    let mut reports = Vec::new();\n    for case in cases {\n        let mut budget: Composition = [0; 10];\n        // Both composition tables begin C,H,N,O.\n        budget[0] = case.counts[0];\n        budget[HYDROGEN] = case.counts[1];\n        budget[2] = case.counts[2];\n        budget[3] = case.counts[3];\n        let mut state = TraceState::new(Limits::new(32, 8)?, Some(budget));\n        let mut used: Composition = [0; 10];\n        let mut masks = Vec::new();\n        for fields in case.trace {\n            let token = Token { kind: fields[0], atom_type: fields[1], bond: fields[2], pointer: fields[3] };\n            let legal = state.masks(token);\n            let mut kinds = legal.kinds;\n            if used != budget || state.residual_valence().iter().any(|r| *r != 0) {\n                kinds &= !(1u32 << STOP);\n            }\n            if kinds & (1u32 << token.kind) == 0 {\n                return Err("incomplete STOP or illegal kind".into());\n            }\n            masks.push([kinds, legal.atom_types, legal.bonds, legal.pointers]);\n            state.apply(token)?;\n            if token.kind == mamba3::models::ms2::ADD_ATOM {\n                let atom = atom_type(token.atom_type).ok_or("unknown atom type")?;\n                used[atom.element] += 1;\n                used[HYDROGEN] += u16::from(atom.hydrogens);\n            }\n        }\n        if used != budget || state.residual_valence().iter().any(|r| *r != 0) {\n            return Err("completed graph is not closed under exact composition".into());\n        }\n        reports.push(Report { masks, residual: state.residual_valence().to_vec() });\n    }\n    println!("{}", serde_json::to_string(&reports)?);\n    Ok(())\n}\n', 'tools/ms2_full_report.py': '"""Aggregate archived full-pipeline results with connectivity-cluster intervals."""\nimport argparse\nimport json\nfrom collections import defaultdict\nfrom pathlib import Path\n\nimport numpy as np\n\n\ndef clustered_difference(a, b, identities, seed=42, repeats=5000):\n    if len(a) != len(b) or len(a) != len(identities) or not a:\n        raise ValueError(\'paired nonempty query lists and identities required\')\n    groups = defaultdict(list)\n    for left, right, key in zip(a, b, identities):\n        groups[key].append(float(left) - float(right))\n    values = list(groups.values())\n    sums = np.asarray([sum(v) for v in values])\n    counts = np.asarray([len(v) for v in values])\n    samples = np.random.default_rng(seed).integers(len(groups), size=(repeats, len(groups)))\n    means = sums[samples].sum(1) / counts[samples].sum(1)\n    return {\'difference\':float((np.asarray(a,dtype=float)-np.asarray(b,dtype=float)).mean()),\n            \'ci95\':np.quantile(means,[0.025,0.975]).tolist(),\'connectivity_groups\':len(groups),\n            \'unit\':\'query-weighted difference; bootstrap resamples connectivity groups\'}\n\n\ndef main(base):\n    audit=json.loads((base/\'data_audit.json\').read_text())\n    identities=audit[\'test_identities\']\n    paths={\'full\':base,\'transformer_decoder\':base/\'controls/transformer_decoder\',\n           \'no_substructures\':base/\'controls/no_substructures\'}\n    predictions={}\n    result={\'queries\':len(identities),\'distinct_connectivities\':len(set(identities)),\n            \'calibration_queries\':audit[\'calibration\'],\n            \'calibration_distinct_connectivities\':len(set(audit[\'calibration_identities\'])),\n            \'physical_stability_evaluated\':False,\'single_seed\':42,\'arms\':{},\'clustered_comparisons\':{}}\n    hit=lambda rows,k:[r[\'rank\'] is not None and r[\'rank\']<=k for r in rows]\n    for arm,path in paths.items():\n        generation=json.loads((path/\'generation_predictions.json\').read_text())\n        retrieval=json.loads((path/\'retrieval_predictions.json\').read_text())\n        if len(generation)!=len(identities) or len(retrieval)!=len(identities):\n            raise ValueError(\'incomplete arm predictions\')\n        if [r[\'query_identity\'] for r in generation]!=identities:\n            raise ValueError(\'query ordering/identity mismatch\')\n        predictions[arm]=(generation,retrieval)\n        result[\'arms\'][arm]={\n            \'generation\':{f\'top{k}\':float(np.mean(hit(generation,k))) for k in (1,10,25)},\n            \'retrieval\':{f\'top{k}\':float(np.mean(hit(retrieval,k))) for k in (1,10,25)},\n            \'queries_with_completed_graphs\':sum(r[\'valid_candidates\']>0 for r in generation),\n            \'distinct_candidates_per_query_total\':sum(r[\'valid_candidates\'] for r in generation)}\n    uniform=[r[\'uniform_rank\'] is not None and r[\'uniform_rank\']<=25 for r in predictions[\'full\'][1]]\n    result[\'retrieval_uniform_top25\']=float(np.mean(uniform))\n    result[\'clustered_comparisons\'][\'retrieval_full_minus_uniform\']=clustered_difference(hit(predictions[\'full\'][1],25),uniform,identities)\n    for arm in (\'transformer_decoder\',\'no_substructures\'):\n        for index,name in enumerate((\'generation\',\'retrieval\')):\n            result[\'clustered_comparisons\'][name+\'_full_minus_\'+arm]=clustered_difference(\n                hit(predictions[\'full\'][index],25),hit(predictions[arm][index],25),identities)\n    (base/\'verification_report.json\').write_text(json.dumps(result,indent=2))\n    print(json.dumps(result),flush=True)\n\n\nif __name__==\'__main__\':\n    parser=argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'--base\',type=Path,default=Path(\'experiments/molecular_completion/full_t4\'))\n    main(parser.parse_args().base)\n', 'tools/test_ms2_full_report.py': "import unittest\nfrom tools.ms2_full_report import clustered_difference\n\n\nclass ClusteredReportTests(unittest.TestCase):\n    def test_duplicate_queries_preserve_point_estimate_and_clusters(self):\n        report=clustered_difference([1,1,0],[0,0,0],['same','same','other'],repeats=100)\n        self.assertEqual(report['connectivity_groups'],2)\n        self.assertAlmostEqual(report['difference'],2/3)\n        self.assertTrue(report['ci95'][0]<=2/3<=report['ci95'][1])\n\n    def test_mismatched_inputs_are_rejected(self):\n        with self.assertRaises(ValueError):\n            clustered_difference([1],[],['a'])\n\n\nif __name__=='__main__':\n    unittest.main()\n", 'tools/ms2_full_retrieval_audit.py': '"""Recheck retrieval eligibility with fixed isotope validation and frozen weights.\n\nPreserves the original diagnostic predictions. Generation and trained weights\nare never modified. Run after both controls complete.\n"""\nimport argparse\nimport json\nfrom pathlib import Path\nimport shutil\nimport sys\n\nimport numpy as np\nimport torch\n\nsys.path.insert(0,str(Path(__file__).resolve().parents[1]))\nimport tools.ms2_full_experiment as experiment\nfrom tools.ms2_full_model import FormulaTable, SubstructurePredictor\nfrom tools.ms2_full_controls import completion_model, restore, EmptyPredictor\n\n\ndef main(base):\n    args=argparse.Namespace(**json.loads((base/\'plan.json\').read_text()))\n    experiment.DEVICE=torch.device(args.device)\n    fit,calibration,queries,*_=experiment.load_data(args,FormulaTable())\n    vocab=torch.load(base/\'upstream_final_vocab.pt\',weights_only=True)[\'patterns\']\n    upstream=restore(SubstructurePredictor(len(vocab)).to(experiment.DEVICE),base/\'upstream_final.pt\')\n    paths={\'full\':base,\'transformer_decoder\':base/\'controls/transformer_decoder\',\n           \'no_substructures\':base/\'controls/no_substructures\'}\n    audit={}\n    for arm,out in paths.items():\n        model=restore(completion_model(arm==\'transformer_decoder\'),out/\'conditional_completion.pt\')\n        prior_out=base if arm==\'no_substructures\' else out\n        prior=restore(completion_model(arm==\'transformer_decoder\'),prior_out/\'molecular_prior.pt\')\n        ranker=restore(experiment.FeatureRanker(np.zeros(5),np.ones(5)).to(experiment.DEVICE),out/\'same_formula_ranker.pt\')\n        predictor,patterns=(EmptyPredictor().to(experiment.DEVICE),[]) if arm==\'no_substructures\' else (upstream,vocab)\n        original_path=out/\'retrieval_predictions_before_isotope_audit.json\'\n        if not original_path.exists():\n            shutil.copyfile(out/\'retrieval_predictions.json\',original_path)\n        original=json.loads(original_path.read_text())\n        rows=[]\n        for query in queries:\n            record,_=experiment.make_record(query[\'row\'])\n            if record is not None:\n                experiment.predict_substructures(predictor,[record],patterns,1)\n            rows.append(experiment.retrieval_prediction(model,prior,ranker,query,record))\n        (out/\'retrieval_predictions.json\').write_text(json.dumps(rows,indent=2))\n        changed=[b[\'qid\'] for a,b in zip(original,rows) if a[\'rank\']!=b[\'rank\'] or a[\'scored\']!=b[\'scored\']]\n        metric={f\'top{k}\':sum(r[\'rank\'] is not None and r[\'rank\']<=k for r in rows)/len(rows) for k in (1,10,25)}\n        audit[arm]={\'changed_queries\':changed,\'retrieval\':metric,\'generation_unchanged\':True,\'weights_unchanged\':True}\n        experiment.emit({\'stage\':\'retrieval_isotope_audit\',\'arm\':arm,**audit[arm]})\n    (base/\'retrieval_eligibility_audit.json\').write_text(json.dumps(audit,indent=2))\n\n\nif __name__==\'__main__\':\n    parser=argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'--base\',type=Path,default=Path(\'experiments/molecular_completion/full_t4\'))\n    main(parser.parse_args().base)\n', 'tools/test_ms2_representation.py': '"""Regression checks for distinctions lost by the original MS2 representation."""\nimport csv\nimport tempfile\nimport unittest\nfrom pathlib import Path\nfrom types import SimpleNamespace\nfrom unittest.mock import patch\n\nimport numpy as np\nimport torch\n\nfrom tools import ms2_full_experiment as experiment\nfrom tools.ms2_full_model import *\n\n\nclass RepresentationTests(unittest.TestCase):\n    def setUp(self):\n        torch.manual_seed(42)\n        torch.set_num_threads(1)\n\n    def test_subdalton_forward_targets_remain_distinct(self):\n        a = prep_peaks([(20.101, 1)], 50)[2]\n        b = prep_peaks([(20.109, 1)], 50)[2]\n        np.testing.assert_array_equal(a[:2000], b[:2000])\n        self.assertLess(float(a @ b), 0.8)\n        np.testing.assert_array_equal(a, prep_peaks([(20.101, 10)], 50)[2])\n        self.assertEqual(len(a), SPECTRUM_DIM)\n        with self.assertRaisesRegex(ValueError, \'finite\'):\n            prep_peaks([(20, float(\'nan\'))], 50)\n\n    def test_vectorized_mass_features_match_peakwise_definition_and_caches_are_immutable(self):\n        peaks = [(20.101,1), (20.109,.5), (31.02,.3)]\n        target = prep_peaks(peaks, 50)[2]\n        fine = np.zeros(2*len(MASS_FREQUENCIES))\n        coarse = np.zeros(2000)\n        for mass,intensity in peaks:\n            phase = 2*math.pi*mass*MASS_FREQUENCIES\n            fine += math.sqrt(intensity)*np.concatenate([np.cos(phase),np.sin(phase)])\n            coarse[int(mass)] = max(coarse[int(mass)],math.sqrt(intensity))\n        expected = np.concatenate([coarse/np.linalg.norm(coarse),fine/np.linalg.norm(fine)])\n        expected /= np.linalg.norm(expected)\n        np.testing.assert_allclose(target, expected, atol=1e-7, rtol=1e-6)\n        cached = canonical_graph_features(parse_graph(\'CCO\')[0])\n        with self.assertRaises(ValueError):\n            cached[0] = 99\n        self.assertEqual(canonical_graph_features.cache_info().maxsize,8192)\n\n    def test_regular_graphs_with_identical_local_messages_remain_distinct(self):\n        # Triangular prism and K3,3: same six C-H atoms, degree and bond counts.\n        carbon = TYPE_ID[(\'C\', 1, 4)]\n        prism = Graph((carbon,) * 6, ((0,1,1),(1,2,1),(0,2,1),\n                      (3,4,1),(4,5,1),(3,5,1),(0,3,1),(1,4,1),(2,5,1)))\n        bipartite = Graph((carbon,) * 6, tuple((a,b,1) for a in range(3) for b in range(3,6)))\n        tensors = graph_tensors([prism, bipartite], \'cpu\')\n        encoder = GraphEncoder(96).eval()\n        with torch.no_grad():\n            encoded = encoder(*tensors)\n            # Original pooled branch gives exactly the same representation.\n            pooled = encoded - encoder.canonical(tensors[2])\n            torch.testing.assert_close(pooled[0], pooled[1], atol=1e-5, rtol=1e-5)\n        self.assertFalse(torch.allclose(encoded[0], encoded[1]))\n        permutation = [5,2,4,0,3,1]\n        index = {old:new for new,old in enumerate(permutation)}\n        moved = Graph(tuple(prism.types[i] for i in permutation),\n                      tuple((index[a],index[b],o) for a,b,o in prism.edges))\n        np.testing.assert_array_equal(canonical_graph_features(prism), canonical_graph_features(moved))\n\n    def test_stereo_annotations_survive_connectivity_grouping(self):\n        for left, right in [(\'C[C@H](O)C(=O)O\', \'C[C@@H](O)C(=O)O\'),\n                            (\'C/C=C/C\', \'C/C=C\\\\C\')]:\n            a, reason = parse_graph(left)\n            b, other = parse_graph(right)\n            self.assertIsNone(reason)\n            self.assertIsNone(other)\n            self.assertEqual(a.identity, b.identity)\n            self.assertNotEqual(a.stereo_smiles, b.stereo_smiles)\n            self.assertFalse(np.array_equal(canonical_graph_features(a), canonical_graph_features(b)))\n            encoder = GraphEncoder(96).eval()\n            with torch.no_grad():\n                encoded = encoder(*graph_tensors([a,b], \'cpu\'))\n            self.assertFalse(torch.allclose(encoded[0], encoded[1]))\n\n    def test_distinct_measurement_conditions_retained_without_identity_leakage(self):\n        fields = [\'fold\',\'smiles\',\'mzs\',\'intensities\',\'precursor_mz\',\'adduct\',\'collision_energy\']\n        def row(fold, smiles, peak, energy):\n            return dict(zip(fields, [fold,smiles,str(peak),\'1\',\'47.049141\',\'[M+H]+\',energy]))\n        rows = [row(\'train\',\'CCO\',20,\'10\'), row(\'train\',\'CCO\',20,\'20\'),\n                row(\'train\',\'CCO\',20,\'20\'), row(\'train\',\'COC\',21,\'10\'),\n                row(\'val\',\'CCN\',22,\'10\'), row(\'test\',\'CCC\',23,\'10\')]\n        table = SimpleNamespace(hypotheses=lambda r: [parse_graph(r[\'smiles\'])[0].counts])\n        with tempfile.TemporaryDirectory() as temp:\n            path = Path(temp) / \'data.tsv\'\n            with path.open(\'w\') as stream:\n                writer = csv.DictWriter(stream, fields, delimiter=\'\\t\')\n                writer.writeheader()\n                writer.writerows(rows)\n            args = SimpleNamespace(tsv=str(path), prefix=\'unused\', max_train=2, calibration=1, queries=1)\n            with patch.object(experiment, \'iter_json_entries\', return_value=iter([(\'CCC\',[\'CCC\'])])):\n                fit, calibration, queries, audit, forbidden, _ = experiment.load_data(args, table)\n        self.assertEqual(len(fit), 3)\n        self.assertEqual(sum(r[\'identity\']==\'CCO\' for r in fit), 2)\n        self.assertEqual(audit[\'train_duplicate\'], 1)\n        self.assertFalse({r[\'identity\'] for r in fit} & forbidden)\n\n    def test_prior_and_negative_candidates_count_molecules_once(self):\n        a,b = parse_graph(\'CCO\')[0],parse_graph(\'COC\')[0]\n        records = [{\'identity\':a.identity,\'graph\':a}, {\'identity\':a.identity,\'graph\':a},\n                   {\'identity\':b.identity,\'graph\':b}]\n        self.assertEqual(len(experiment.molecule_records(records)),2)\n        with patch.object(experiment,\'decoys\',side_effect=lambda r,*_: [r[\'graph\'],b if r[\'graph\']==a else a]) as mocked:\n            experiment.prepare_pair_candidates(records,[],set(),set(),42)\n        self.assertEqual(mocked.call_count,2)\n        self.assertIs(records[0][\'pair_graphs\'],records[1][\'pair_graphs\'])\n\n    def test_spectral_substitution_retains_target_conditions_and_recomputes_losses(self):\n        from tools.ms2_full_pairing_audit import substitute_peaks\n        target = {\'row\':{\'precursor_mz\':\'50\'}, \'meta\':np.array([1,2,3]),\n                  \'adduct\':1, \'predicted\':[(\'old\',1)], \'graph\':parse_graph(\'CCO\')[0]}\n        donor = {\'row\':{\'mzs\':\'20.109\', \'intensities\':\'1\', \'precursor_mz\':\'99\'}}\n        replaced = substitute_peaks(target, donor)\n        np.testing.assert_array_equal(replaced[\'meta\'], target[\'meta\'])\n        self.assertEqual(replaced[\'adduct\'], target[\'adduct\'])\n        self.assertIs(replaced[\'graph\'], target[\'graph\'])\n        self.assertEqual(replaced[\'predicted\'], [])\n        self.assertAlmostEqual(float(replaced[\'peaks\'][0,1]), (50-20.109)/1000, places=7)\n\n    def paired_training_check(self, device):\n        previous_device = experiment.DEVICE\n        self.addCleanup(setattr, experiment, \'DEVICE\', previous_device)\n        experiment.DEVICE = torch.device(device)\n        a, _ = parse_graph(\'CCO\')\n        b, _ = parse_graph(\'COC\')\n        peaks, mask, target = prep_peaks([(20.101,1),(31.02,.5)], 47.049141)\n        record = dict(graph=a, pair_graphs=[a,b], peaks=peaks, mask=mask, bins=target,\n                      meta=np.zeros(5,dtype=np.float32), adduct=1, predicted=[])\n        model = CompletionModel().to(device)\n        optimizer = torch.optim.AdamW(model.parameters(), lr=0.001)\n        initial = experiment.paired_candidate_loss(model, [record])\n        initial.backward()\n        for module in (model.spectrum_encoder, model.graph_encoder, model.layers):\n            self.assertGreater(sum(p.grad.abs().sum().item() for p in module.parameters()\n                                   if p.grad is not None), 0)\n        before = initial.item()\n        optimizer.step()\n        for _ in range(11):\n            optimizer.zero_grad()\n            loss = experiment.paired_candidate_loss(model, [record])\n            loss.backward()\n            optimizer.step()\n        self.assertLess(experiment.paired_candidate_loss(model, [record]).item(), before * .5)\n\n    def test_cpu_same_formula_training_updates_both_encoders_and_decoder(self):\n        self.paired_training_check(\'cpu\')\n\n    def test_batched_pairing_preserves_query_losses_and_gradients(self):\n        previous_device = experiment.DEVICE\n        self.addCleanup(setattr, experiment, \'DEVICE\', previous_device)\n        experiment.DEVICE = torch.device(\'cpu\')\n        a, b = parse_graph(\'CCO\')[0], parse_graph(\'COC\')[0]\n        c, d = parse_graph(\'CCCC\')[0], parse_graph(\'CC(C)C\')[0]\n        p,m,t = prep_peaks([(20,1)], 60)\n        records = [dict(graph=g, pair_graphs=group, peaks=p, mask=m, bins=t,\n                        meta=np.zeros(5,dtype=np.float32), adduct=1, predicted=[])\n                   for g,group in ((a,[a,b]),(c,[c,d,d]))]\n        model = CompletionModel().eval()\n        batched = experiment.paired_candidate_loss(model, records)\n        expected = torch.stack([experiment.paired_candidate_loss(model, [r]) for r in records]).mean()\n        torch.testing.assert_close(batched, expected, atol=1e-5, rtol=1e-5)\n        actual_grad = torch.autograd.grad(batched, tuple(model.parameters()), allow_unused=True)\n        expected_grad = torch.autograd.grad(expected, tuple(model.parameters()), allow_unused=True)\n        for actual, reference in zip(actual_grad, expected_grad):\n            if reference is None:\n                self.assertIsNone(actual)\n            else:\n                torch.testing.assert_close(actual, reference, atol=1e-5, rtol=1e-4)\n\n    def test_old_checkpoints_require_explicit_retraining(self):\n        from tools.ms2_full_controls import restore\n        with tempfile.TemporaryDirectory() as temp:\n            path = Path(temp) / \'old.pt\'\n            torch.save({\'state\': {}}, path)\n            with self.assertRaisesRegex(ValueError, \'incompatible representation; retrain\'):\n                restore(GraphEncoder(96), path)\n\n    def test_interrupted_epoch_resumes_exactly_and_completed_stage_is_reused(self):\n        previous_device = experiment.DEVICE\n        self.addCleanup(setattr, experiment, \'DEVICE\', previous_device)\n        experiment.DEVICE = torch.device(\'cpu\')\n        initial = torch.nn.Linear(1, 1).state_dict()\n        def objective(model, batch):\n            x = torch.tensor(batch, dtype=torch.float32).reshape(-1, 1)\n            return ((model(x) - 2*x + torch.rand_like(x)*.01)**2).mean()\n        with tempfile.TemporaryDirectory() as temp:\n            base = Path(temp)\n            uninterrupted, resumed = base/\'uninterrupted\', base/\'resumed\'\n            uninterrupted.mkdir()\n            resumed.mkdir()\n            reference = torch.nn.Linear(1,1)\n            reference.load_state_dict(initial)\n            experiment.fit_loop(reference, [1.,2.], [3.], objective, 2, 1, uninterrupted, \'toy\', 42)\n            partial = torch.nn.Linear(1,1)\n            partial.load_state_dict(initial)\n            calls = 0\n            def interrupted(model, batch):\n                nonlocal calls\n                calls += 1\n                if calls == 4:\n                    raise RuntimeError(\'simulated interruption\')\n                return objective(model, batch)\n            with self.assertRaisesRegex(RuntimeError, \'simulated interruption\'):\n                experiment.fit_loop(partial, [1.,2.], [3.], interrupted, 2, 1, resumed, \'toy\', 42)\n            recovered = torch.nn.Linear(1,1)\n            experiment.fit_loop(recovered, [1.,2.], [3.], objective, 2, 1, resumed, \'toy\', 42)\n            for key in reference.state_dict():\n                torch.testing.assert_close(reference.state_dict()[key], recovered.state_dict()[key], atol=0, rtol=0)\n            with patch.object(experiment, \'emit\'):\n                experiment.fit_loop(recovered, [1.,2.], [3.],\n                    lambda *_: self.fail(\'completed stage must not train again\'), 2, 1, resumed, \'toy\', 42)\n            with self.assertRaisesRegex(ValueError, \'protocol changed\'):\n                experiment.fit_loop(recovered, [1.,2.], [4.], objective, 2, 1, resumed, \'toy\', 42)\n\n    @unittest.skipUnless(torch.cuda.is_available(), \'CUDA unavailable locally\')\n    def test_cuda_same_formula_training_updates_both_encoders_and_decoder(self):\n        self.paired_training_check(\'cuda\')\n\n\nif __name__ == \'__main__\':\n    unittest.main()\n', 'tools/ms2_full_pairing_audit.py': '"""Held-out correct-spectrum versus substituted-spectrum intervention.\n\nSame-formula donors are preferred. Unmatched-formula substitutions are reported\nseparately and are not evidence of same-formula discrimination. Weights are frozen.\n"""\nimport argparse\nimport json\nfrom pathlib import Path\nimport sys\n\nimport numpy as np\nimport torch\n\nsys.path.insert(0, str(Path(__file__).resolve().parents[1]))\nfrom tools import ms2_full_experiment as experiment\nfrom tools.ms2_full_model import CompletionModel, FormulaTable, SubstructurePredictor, prep_peaks\nfrom tools.ms2_full_controls import restore\nfrom tools.ms2_spectral_rank import parse_spectrum\n\n\ndef substitute_peaks(target, donor):\n    peaks, reason = parse_spectrum(donor[\'row\'][\'mzs\'], donor[\'row\'][\'intensities\'])\n    if reason:\n        raise ValueError(f\'invalid donor peaks: {reason}\')\n    features, mask, bins = prep_peaks(peaks, float(target[\'row\'][\'precursor_mz\']))\n    return {**target, \'peaks\': features, \'mask\': mask, \'bins\': bins, \'predicted\': []}\n\n\ndef main(base):\n    args = argparse.Namespace(**json.loads((base/\'plan.json\').read_text()))\n    experiment.DEVICE = torch.device(args.device)\n    _, _, queries, *_ = experiment.load_data(args, FormulaTable())\n    model = restore(CompletionModel().to(experiment.DEVICE), base/\'conditional_completion.pt\')\n    prior = restore(CompletionModel().to(experiment.DEVICE), base/\'molecular_prior.pt\')\n    vocab = torch.load(base/\'upstream_final_vocab.pt\', weights_only=True)[\'patterns\']\n    upstream = restore(SubstructurePredictor(len(vocab)).to(experiment.DEVICE), base/\'upstream_final.pt\')\n    ranker = restore(experiment.FeatureRanker(np.zeros(5), np.ones(5)).to(experiment.DEVICE),\n                     base/\'same_formula_ranker.pt\')\n    records = []\n    for query in queries:\n        record, reason = experiment.make_record(query[\'row\'])\n        if record is not None and reason is None:\n            records.append((query, record))\n    rows = []\n    for query, record in records:\n        donors = [(q,r) for q,r in records if r[\'identity\'] != record[\'identity\']]\n        matched = [(q,r) for q,r in donors if r[\'graph\'].counts == record[\'graph\'].counts]\n        if not donors:\n            continue\n        donor_query, donor = min(matched or donors,\n            key=lambda pair: (abs(float(pair[1][\'row\'][\'precursor_mz\'])-float(record[\'row\'][\'precursor_mz\'])), pair[0][\'qid\']))\n        wrong = substitute_peaks(record, donor)\n        if not wrong[\'mask\'].any():\n            rows.append({\'qid\':query[\'qid\'], \'donor\':donor_query[\'qid\'], \'status\':\'empty_after_precursor_filter\'})\n            continue\n        experiment.predict_substructures(upstream, [record, wrong], vocab, 2)\n        with torch.no_grad():\n            correct_nll = float(-model.likelihood([record[\'graph\']], [record], experiment.DEVICE)[0])\n            wrong_nll = float(-model.likelihood([record[\'graph\']], [wrong], experiment.DEVICE)[0])\n            correct_rank = experiment.retrieval_prediction(model, prior, ranker, query, record)[\'rank\']\n            wrong_rank = experiment.retrieval_prediction(model, prior, ranker, query, wrong)[\'rank\']\n        rows.append({\'qid\':query[\'qid\'], \'donor\':donor_query[\'qid\'], \'status\':\'ok\',\n            \'query_identity\':record[\'identity\'], \'same_formula_donor\':bool(matched),\n            \'correct_nll\':correct_nll, \'substituted_nll\':wrong_nll,\n            \'nll_increase\':wrong_nll-correct_nll, \'correct_rank\':correct_rank, \'substituted_rank\':wrong_rank})\n    summary = {}\n    for matched, name in ((True,\'same_formula\'), (False,\'unmatched_formula\')):\n        group = [r for r in rows if r[\'status\']==\'ok\' and r[\'same_formula_donor\']==matched]\n        summary[name] = {\'queries\':len(group),\n            \'mean_nll_increase\':float(np.mean([r[\'nll_increase\'] for r in group])) if group else None,\n            \'fraction_correct_spectrum_lower_nll\':float(np.mean([r[\'nll_increase\']>0 for r in group])) if group else None}\n    result = {\'scope\':\'frozen held-out spectral substitution; target metadata retained; motifs recomputed\',\n              \'rows\':rows, \'summary\':summary}\n    (base/\'paired_spectrum_audit.json\').write_text(json.dumps(result,indent=2))\n    print(json.dumps(summary), flush=True)\n\n\nif __name__ == \'__main__\':\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'--base\', type=Path, required=True)\n    main(parser.parse_args().base)\n', 'tools/ms2_full_supervisor.py': '"""Run the full T4 verification with logs, stage markers and atomic status."""\nimport argparse\nimport hashlib\nimport json\nimport os\nfrom pathlib import Path\nimport platform\nimport shutil\nimport subprocess\nimport sys\nimport time\n\nimport torch\n\n\ndef write_json(path, value):\n    temporary = path.with_suffix(\'.partial\')\n    temporary.write_text(json.dumps(value, indent=2))\n    temporary.replace(path)\n\n\ndef main(base):\n    base.mkdir(parents=True, exist_ok=True)\n    if not torch.cuda.is_available() or \'T4\' not in torch.cuda.get_device_name():\n        raise RuntimeError(\'Actual CUDA Tesla T4 required\')\n    status_path = base/\'run_status.json\'\n    start = time.monotonic()\n    # Preflight is a separate process; wait without occupying the notebook kernel.\n    while not (base/\'preflight_complete.json\').exists():\n        write_json(status_path, {\'state\':\'waiting_preflight\',\'supervisor_pid\':os.getpid(),\n                                \'elapsed_seconds\':time.monotonic()-start})\n        if time.monotonic()-start > 1800:\n            raise TimeoutError(\'Preflight did not complete within 30 minutes; inspect preflight.log\')\n        time.sleep(5)\n    stages = [\n        (\'gpu_tests\', [\'-m\',\'unittest\',\'tools.test_ms2_full_model\',\'tools.test_ms2_full_controls\',\n                       \'tools.test_ms2_full_report\',\'tools.test_ms2_representation\',\'-v\']),\n        (\'training\', [\'-u\',\'tools/ms2_full_experiment.py\',\'--out\',str(base)]),\n        (\'diagnostics\', [\'-u\',\'tools/ms2_full_diagnostics.py\',\'--base\',str(base)]),\n        (\'paired_spectrum_audit\', [\'-u\',\'tools/ms2_full_pairing_audit.py\',\'--base\',str(base)]),\n        (\'controls\', [\'-u\',\'tools/ms2_full_controls.py\',\'--base\',str(base)]),\n        (\'retrieval_audit\', [\'-u\',\'tools/ms2_full_retrieval_audit.py\',\'--base\',str(base)]),\n        (\'report\', [\'-u\',\'tools/ms2_full_report.py\',\'--base\',str(base)]),\n    ]\n    for name, arguments in stages:\n        marker = base/(name+\'_stage_complete.json\')\n        if marker.exists():\n            print(\'Restored completed stage\',name,flush=True)\n            continue\n        print(\'Starting stage\',name,flush=True)\n        stage_start = time.monotonic()\n        # Append preserves previous failure evidence; model epoch checkpoints\n        # restore training progress when a stage needs to run again.\n        with (base/(name+\'.log\')).open(\'a\') as log:\n            log.write(\'\\nSUPERVISOR_STAGE_START \'+name+\'\\n\');log.flush()\n            process = subprocess.Popen([sys.executable,*arguments],stdout=log,stderr=subprocess.STDOUT)\n            while process.poll() is None:\n                write_json(status_path, {\'state\':\'running\',\'stage\':name,\'pid\':process.pid,\n                    \'supervisor_pid\':os.getpid(),\'stage_seconds\':time.monotonic()-stage_start,\n                    \'elapsed_seconds\':time.monotonic()-start})\n                if time.monotonic()-stage_start > 24*3600:\n                    process.terminate()\n                    try:\n                        process.wait(timeout=30)\n                    except subprocess.TimeoutExpired:\n                        process.kill();process.wait()\n                    raise TimeoutError(f\'{name}: 24-hour stage limit reached; epoch checkpoints retained\')\n                time.sleep(5)\n        if process.returncode:\n            write_json(status_path, {\'state\':\'failed\',\'stage\':name,\'exit_code\':process.returncode,\n                                    \'elapsed_seconds\':time.monotonic()-start})\n            raise RuntimeError(f\'{name} exited {process.returncode}; see {base/(name+".log")}\')\n        write_json(marker, {\'stage\':name,\'seconds\':time.monotonic()-stage_start})\n    import numpy, scipy, sklearn, rdkit\n    write_json(base/\'environment.json\', {\'python\':platform.python_version(),\'torch\':torch.__version__,\n        \'numpy\':numpy.__version__,\'scipy\':scipy.__version__,\'sklearn\':sklearn.__version__,\n        \'rdkit\':rdkit.__version__,\'gpu\':torch.cuda.get_device_name(),\n        \'revision\':\'d2e86d0c3bd905a6d578c0dd6053ed2bd41f9c2a\'})\n    write_json(status_path, {\'state\':\'complete\',\'elapsed_seconds\':time.monotonic()-start})\n    manifest = {str(p.relative_to(base)):hashlib.sha256(p.read_bytes()).hexdigest()\n                for p in base.rglob(\'*\') if p.is_file() and p.name not in (\'manifest.json\',\'supervisor.log\')}\n    write_json(base/\'manifest.json\',manifest)\n    archive = Path(shutil.make_archive(str(base.parent/\'representation_v2_full_t4_results\'),\'zip\',base))\n    write_json(base.parent/\'representation_v2_archive.json\',\n        {\'path\':str(archive),\'bytes\':archive.stat().st_size,\'sha256\':hashlib.sha256(archive.read_bytes()).hexdigest()})\n    print(\'Full verification complete:\',archive,flush=True)\n\n\nif __name__ == \'__main__\':\n    parser = argparse.ArgumentParser(description=__doc__)\n    parser.add_argument(\'--base\',type=Path,required=True)\n    args=parser.parse_args()\n    try:\n        main(args.base.resolve())\n    except Exception as error:\n        status=args.base/\'run_status.json\'\n        if not status.exists() or json.loads(status.read_text()).get(\'state\')!=\'failed\':\n            write_json(status, {\'state\':\'failed\',\'error\':str(error)})\n        raise\n'}
