import hashlib, time, requests
REVISION = 'd2e86d0c3bd905a6d578c0dd6053ed2bd41f9c2a'
BASE = f'https://huggingface.co/datasets/roman-bushuiev/MassSpecGym/resolve/{REVISION}/'

def digest(path):
    h = hashlib.sha256()
    with path.open('rb') as stream:
        for chunk in iter(lambda: stream.read(1024 * 1024), b''):
            h.update(chunk)
    return h.hexdigest()

def download(remote, local, expected_hash, size, prefix=False):
    path = WORK / local
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists() and digest(path) == expected_hash:
        print('Verified cached', local)
        return
    temporary = path.with_suffix('.partial')
    for attempt in range(3):
        try:
            headers = {'Range': f'bytes=0-{size - 1}'} if prefix else {}
            with requests.get(BASE + remote, headers=headers, stream=True, timeout=(20, 60)) as response:
                response.raise_for_status()
                if prefix and response.status_code == 206 and not response.headers.get('Content-Range', '').startswith('bytes 0-'):
                    raise ValueError('Server returned an unexpected range')
                written = 0
                with temporary.open('wb') as output:
                    for chunk in response.iter_content(1024 * 1024):
                        if not chunk:
                            continue
                        if prefix:
                            chunk = chunk[:size - written]
                        output.write(chunk)
                        written += len(chunk)
                        if prefix and written == size:
                            break
            if written != size or digest(temporary) != expected_hash:
                raise ValueError(f'Pinned size/hash mismatch for {local}')
            temporary.replace(path)
            print('Downloaded and verified', local)
            return
        except (requests.RequestException, ValueError):
            temporary.unlink(missing_ok=True)
            if attempt == 2:
                raise
            time.sleep(2 ** attempt)

download('data/MassSpecGym1.5.tsv', 'data/pinned/MassSpecGym1.5.tsv',
         '50cfdd1d22f79543c59555f9ce43c6893bd788a19a42b21fb4e2e3a54673c06a', 261197365)
download('data/molecules/MassSpecGym1.5_retrieval_candidates_formula.json',
         'data/pinned/msgym_candidates_formula_prefix64.json',
         '6066de3b1f2a5c013a6d37959b0c6f2f8a4867dc2fdef07fdbe3eaceaa9a6864',
         67108864, prefix=True)

import platform, numpy, scipy, sklearn, rdkit, time, signal, subprocess
(RUN_LOG_DIR/'environment.json').write_text(json.dumps({'platform':'Kaggle','python':platform.python_version(),'torch':torch.__version__,'gpu':torch.cuda.get_device_name(),'numpy':numpy.__version__,'scipy':scipy.__version__,'sklearn':sklearn.__version__,'rdkit':rdkit.__version__,'revision':REVISION},indent=2))
(RUN_LOG_DIR/'preflight_complete.json').write_text(json.dumps({'gpu':torch.cuda.get_device_name(),'pinned_data_verified':True}))
# End before the platform's session limit so Kaggle can persist epoch checkpoints.
started = time.monotonic()
with (RUN_LOG_DIR/'supervisor.log').open('a') as log:
    process = subprocess.Popen([sys.executable,'-u','tools/ms2_full_supervisor.py','--base',str(RUN_LOG_DIR)], stdout=log, stderr=subprocess.STDOUT, start_new_session=True)
    offsets = {}
    while process.poll() is None:
        for path in sorted(RUN_LOG_DIR.glob('*.log')):
            with path.open() as stream:
                stream.seek(offsets.get(str(path),0))
                chunk = stream.read()
                offsets[str(path)] = stream.tell()
            if chunk:
                print(path.name+': '+chunk, flush=True)
        if time.monotonic()-started > 10.5*3600:
            os.killpg(process.pid, signal.SIGTERM)
            try:
                process.wait(timeout=30)
            except subprocess.TimeoutExpired:
                os.killpg(process.pid, signal.SIGKILL)
                process.wait()
            status_path = RUN_LOG_DIR/'run_status.json'
            status = json.loads(status_path.read_text())
            status.update(state='segment_complete', reason='Kaggle time budget; resume saved epoch checkpoints')
            status_path.write_text(json.dumps(status,indent=2))
            break
        time.sleep(15)
print((RUN_LOG_DIR/'run_status.json').read_text(),flush=True)
